window.YC_MORE_QBANKS=window.YC_MORE_QBANKS||[];window.YC_MORE_QBANKS.push([{"id":"pdn01205","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「协同治理」是指区级牵头部门通过建立常态化联络与移交规则，使跨界问题不再悬空的工作机制。\n\n按照上述界定，下列情形可认定为「协同治理」的是：","options":["由上级部门包办到底，后续也未按上述机制推进。","区级牵头部门在信息通报共享中，建立常态化联络与移交规则，但边界地带的问题仍在部门之间来回流转。","区级牵头部门在跨界事项梳理中，建立常态化联络与移交规则，跨界问题不再悬空。","区级牵头部门在联合排班安排中，各自按本部门旧流程办理，最终边界地带的问题仍在部门之间来回流转。"],"answer":2,"explanation":"「协同治理」的构成要件为：①主体为区级牵头部门；②通过建立常态化联络与移交规则；③使跨界问题不再悬空。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01206","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「增值评价」是指任课教师团队通过随堂记录并及时反馈调整，使学习过程而非仅结果被看见的工作机制。\n\n根据上述定义，下列不属于「增值评价」的是：","options":["任课教师团队在作业反馈整理中，随堂记录并及时反馈调整，学习过程而非仅结果被看见。","任课教师团队在实验课程组织中，随堂记录并及时反馈调整，学习过程而非仅结果被看见。","任课教师团队在实验课程组织中，只以期末一次分数定结论，最终教学安排并未因数据而作任何调整。","任课教师团队在单元教学设计中，随堂记录并及时反馈调整，学习过程而非仅结果被看见。"],"answer":2,"explanation":"「增值评价」的构成要件为：①主体为任课教师团队；②通过随堂记录并及时反馈调整；③使学习过程而非仅结果被看见。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（只以期末一次分数定结论），因此不符合构成要件。故选C。"},{"id":"pdn01207","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「按需配置」是指就业服务窗口通过依据使用频次动态增减项目，使资源不再平均摊薄的工作机制。\n\n依据上述定义，以下哪一项符合「按需配置」的构成要件：","options":["就业服务窗口在服务事项梳理中，依据使用频次动态增减项目，资源不再平均摊薄。","由供应商单方决定目录，后续也未按上述机制推进。","就业服务窗口在服务清单编制中，依据使用频次动态增减项目，但大量项目无人使用而真实诉求仍被搁置。","就业服务窗口在对象需求摸排中，按编制人数而不是实际用量分配，最终大量项目无人使用而真实诉求仍被搁置。"],"answer":0,"explanation":"「按需配置」的构成要件为：①主体为就业服务窗口；②通过依据使用频次动态增减项目；③使资源不再平均摊薄。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01208","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「数据校验」是指项目评审委员会通过用对照组剔除同期其他影响，使判断建立在可核验的依据上的工作机制。\n\n按照上述界定，下列情形不应认定为「数据校验」的是：","options":["项目评审委员会在抽样数据核查中，用对照组剔除同期其他影响，判断建立在可核验的依据上。","项目评审委员会在年度计划编制中，用对照组剔除同期其他影响，判断建立在可核验的依据上。","项目评审委员会在政策效果评估中，以主观感受替代实测数据，最终结论无法由所引数据支撑。","项目评审委员会在政策效果评估中，用对照组剔除同期其他影响，判断建立在可核验的依据上。"],"answer":2,"explanation":"「数据校验」的构成要件为：①主体为项目评审委员会；②通过用对照组剔除同期其他影响；③使判断建立在可核验的依据上。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（以主观感受替代实测数据），因此不符合构成要件。故选C。"},{"id":"pdn01209","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「多元共治」是指跨部门工作专班通过一次会商形成分工清单，使跨界问题不再悬空的工作机制。\n\n根据上述定义，下列属于「多元共治」的是：","options":["跨部门工作专班在联合排班安排中，各自按本部门旧流程办理，最终边界地带的问题仍在部门之间来回流转。","跨部门工作专班在跨界事项梳理中，一次会商形成分工清单，跨界问题不再悬空。","由上级部门包办到底，后续也未按上述机制推进。","跨部门工作专班在信息通报共享中，一次会商形成分工清单，但边界地带的问题仍在部门之间来回流转。"],"answer":1,"explanation":"「多元共治」的构成要件为：①主体为跨部门工作专班；②通过一次会商形成分工清单；③使跨界问题不再悬空。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01210","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「全过程追溯」是指农产品质量检测站通过关键节点双人签认留档，使台账与实物始终一致的工作机制。\n\n依据上述定义，以下哪一项不符合「全过程追溯」的构成要件：","options":["农产品质量检测站在批次交接记录中，只在最终出库时记一笔总账，最终出现问题时无法定位到具体环节。","农产品质量检测站在进货环节核验中，关键节点双人签认留档，台账与实物始终一致。","农产品质量检测站在批次交接记录中，关键节点双人签认留档，台账与实物始终一致。","农产品质量检测站在储运环节温控中，关键节点双人签认留档，台账与实物始终一致。"],"answer":0,"explanation":"「全过程追溯」的构成要件为：①主体为农产品质量检测站；②通过关键节点双人签认留档；③使台账与实物始终一致。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（只在最终出库时记一笔总账），因此不符合构成要件。故选A。"},{"id":"pdn01211","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「灰度验证」是指产品迭代小组通过设置观察期并保留回退通道，使后续推广更贴合一线实际的工作机制。\n\n按照上述界定，下列情形可认定为「灰度验证」的是：","options":["产品迭代小组在新流程上线中，设置观察期并保留回退通道，后续推广更贴合一线实际。","产品迭代小组在新工具推广中，试运行期间禁止任何修改，最终同类偏差在扩面后被成倍放大。","产品迭代小组在新机制落地中，设置观察期并保留回退通道，但同类偏差在扩面后被成倍放大。","由外部团队一次性交付即结束，后续也未按上述机制推进。"],"answer":0,"explanation":"「灰度验证」的构成要件为：①主体为产品迭代小组；②通过设置观察期并保留回退通道；③使后续推广更贴合一线实际。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01212","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「脆弱性评估」是指应急指挥中心通过关键节点保留备用通道，使核心功能在异常下仍可维持的工作机制。\n\n根据上述定义，下列不属于「脆弱性评估」的是：","options":["应急指挥中心在关键节点值守中，关键节点保留备用通道，核心功能在异常下仍可维持。","应急指挥中心在响应动作预置中，关键节点保留备用通道，核心功能在异常下仍可维持。","应急指挥中心在响应动作预置中，预案长期封存不随风险更新，最终异常发生时无预设动作可依。","应急指挥中心在风险等级研判中，关键节点保留备用通道，核心功能在异常下仍可维持。"],"answer":2,"explanation":"「脆弱性评估」的构成要件为：①主体为应急指挥中心；②通过关键节点保留备用通道；③使核心功能在异常下仍可维持。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（预案长期封存不随风险更新），因此不符合构成要件。故选C。"},{"id":"pdn01213","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「分级诊疗」是指乡镇卫生院通过建立电子档案并定期回访，使重复检查明显减少的工作机制。\n\n依据上述定义，以下哪一项符合「分级诊疗」的构成要件：","options":["乡镇卫生院在重点人群筛查中，建立电子档案并定期回访，但各环节彼此脱节、患者仍需多次重复排队。","乡镇卫生院在慢病随访安排中，建立电子档案并定期回访，重复检查明显减少。","由商业体检机构独立出具结论，后续也未按上述机制推进。","乡镇卫生院在康复跟踪记录中，待病情加重后再启动会诊，最终各环节彼此脱节、患者仍需多次重复排队。"],"answer":1,"explanation":"「分级诊疗」的构成要件为：①主体为乡镇卫生院；②通过建立电子档案并定期回访；③使重复检查明显减少。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01214","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「形成性评价」是指任课教师团队通过先摸清起点再设定分层目标，使学生的薄弱点被及时识别的工作机制。\n\n按照上述界定，下列情形不应认定为「形成性评价」的是：","options":["任课教师团队在实验课程组织中，先摸清起点再设定分层目标，学生的薄弱点被及时识别。","任课教师团队在单元教学设计中，先摸清起点再设定分层目标，学生的薄弱点被及时识别。","任课教师团队在作业反馈整理中，先摸清起点再设定分层目标，学生的薄弱点被及时识别。","任课教师团队在实验课程组织中，只以期末一次分数定结论，最终教学安排并未因数据而作任何调整。"],"answer":3,"explanation":"「形成性评价」的构成要件为：①主体为任课教师团队；②通过先摸清起点再设定分层目标；③使学生的薄弱点被及时识别。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（只以期末一次分数定结论），因此不符合构成要件。故选D。"},{"id":"pdn01215","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「诊断性测评」是指区域教研中心通过按阶段采集学情数据再修正教学，使教学策略得以动态优化的工作机制。\n\n根据上述定义，下列属于「诊断性测评」的是：","options":["区域教研中心在实验课程组织中，全程不作任何反馈、结束后才公布，最终教学安排并未因数据而作任何调整。","区域教研中心在作业反馈整理中，按阶段采集学情数据再修正教学，但教学安排并未因数据而作任何调整。","区域教研中心在单元教学设计中，按阶段采集学情数据再修正教学，教学策略得以动态优化。","由家长自行报送成绩，后续也未按上述机制推进。"],"answer":2,"explanation":"「诊断性测评」的构成要件为：①主体为区域教研中心；②通过按阶段采集学情数据再修正教学；③使教学策略得以动态优化。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01216","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「容错纠偏」是指改革推进专班通过设置观察期并保留回退通道，使后续推广更贴合一线实际的工作机制。\n\n依据上述定义，以下哪一项不符合「容错纠偏」的构成要件：","options":["改革推进专班在新工具推广中，只记录成功案例不分析偏差，最终同类偏差在扩面后被成倍放大。","改革推进专班在新机制落地中，设置观察期并保留回退通道，后续推广更贴合一线实际。","改革推进专班在新工具推广中，设置观察期并保留回退通道，后续推广更贴合一线实际。","改革推进专班在新流程上线中，设置观察期并保留回退通道，后续推广更贴合一线实际。"],"answer":0,"explanation":"「容错纠偏」的构成要件为：①主体为改革推进专班；②通过设置观察期并保留回退通道；③使后续推广更贴合一线实际。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（只记录成功案例不分析偏差），因此不符合构成要件。故选A。"},{"id":"pdn01217","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「协同会商」是指社区网格站通过依托网格员常态化走访摸排，使重复投诉明显下降的工作机制。\n\n按照上述界定，下列情形可认定为「协同会商」的是：","options":["社区网格站在便民事项办理中，依托网格员常态化走访摸排，但问题仍反复出现且未形成稳定机制。","社区网格站在邻里纠纷调解中，各口径分头办理、彼此不通气，最终问题仍反复出现且未形成稳定机制。","由服务对象自行申报后不再跟进，后续也未按上述机制推进。","社区网格站在老旧小区改造中，依托网格员常态化走访摸排，重复投诉明显下降。"],"answer":3,"explanation":"「协同会商」的构成要件为：①主体为社区网格站；②通过依托网格员常态化走访摸排；③使重复投诉明显下降。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01218","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「阈值预警」是指自然保护区管理局通过按监测指标分档调整措施，使管控成本保持在合理区间的工作机制。\n\n根据上述定义，下列不属于「阈值预警」的是：","options":["自然保护区管理局在栖息环境变化中，全年沿用同一套固定配额，最终指标已越界而措施仍维持不变。","自然保护区管理局在监测指标波动中，按监测指标分档调整措施，管控成本保持在合理区间。","自然保护区管理局在外来因素扩散中，按监测指标分档调整措施，管控成本保持在合理区间。","自然保护区管理局在栖息环境变化中，按监测指标分档调整措施，管控成本保持在合理区间。"],"answer":0,"explanation":"「阈值预警」的构成要件为：①主体为自然保护区管理局；②通过按监测指标分档调整措施；③使管控成本保持在合理区间。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（全年沿用同一套固定配额），因此不符合构成要件。故选A。"},{"id":"pdn01219","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「形成性评价」是指学校教研组通过先摸清起点再设定分层目标，使学生的薄弱点被及时识别的工作机制。\n\n依据上述定义，以下哪一项符合「形成性评价」的构成要件：","options":["由家长自行报送成绩，后续也未按上述机制推进。","学校教研组在作业反馈整理中，先摸清起点再设定分层目标，但教学安排并未因数据而作任何调整。","学校教研组在实验课程组织中，全程不作任何反馈、结束后才公布，最终教学安排并未因数据而作任何调整。","学校教研组在单元教学设计中，先摸清起点再设定分层目标，学生的薄弱点被及时识别。"],"answer":3,"explanation":"「形成性评价」的构成要件为：①主体为学校教研组；②通过先摸清起点再设定分层目标；③使学生的薄弱点被及时识别。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01220","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「共创工作坊」是指社区营造团队通过先做可体验原型再收集反馈，使方案贴合真实使用习惯的工作机制。\n\n按照上述界定，下列情形不应认定为「共创工作坊」的是：","options":["社区营造团队在公共界面优化中，先做可体验原型再收集反馈，方案贴合真实使用习惯。","社区营造团队在使用路径排查中，先做可体验原型再收集反馈，方案贴合真实使用习惯。","社区营造团队在服务流程梳理中，先做可体验原型再收集反馈，方案贴合真实使用习惯。","社区营造团队在公共界面优化中，照搬其他地区成品，最终上线后仍频发与习惯不符的障碍。"],"answer":3,"explanation":"「共创工作坊」的构成要件为：①主体为社区营造团队；②通过先做可体验原型再收集反馈；③使方案贴合真实使用习惯。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（照搬其他地区成品），因此不符合构成要件。故选D。"},{"id":"pdn01221","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「分区管控」是指自然保护区管理局通过随季节数据滚动修订方案，使核心栖息地得到有效避让的工作机制。\n\n根据上述定义，下列属于「分区管控」的是：","options":["自然保护区管理局在外来因素扩散中，随季节数据滚动修订方案，但指标已越界而措施仍维持不变。","由游客反馈临时决定，后续也未按上述机制推进。","自然保护区管理局在栖息环境变化中，等出现明显损害后再启动处置，最终指标已越界而措施仍维持不变。","自然保护区管理局在监测指标波动中，随季节数据滚动修订方案，核心栖息地得到有效避让。"],"answer":3,"explanation":"「分区管控」的构成要件为：①主体为自然保护区管理局；②通过随季节数据滚动修订方案；③使核心栖息地得到有效避让。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01222","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「多元共治」是指跨部门工作专班通过建立常态化联络与移交规则，使处置效率整体提升的工作机制。\n\n依据上述定义，以下哪一项不符合「多元共治」的构成要件：","options":["跨部门工作专班在跨界事项梳理中，建立常态化联络与移交规则，处置效率整体提升。","跨部门工作专班在联合排班安排中，建立常态化联络与移交规则，处置效率整体提升。","跨部门工作专班在信息通报共享中，建立常态化联络与移交规则，处置效率整体提升。","跨部门工作专班在联合排班安排中，各部门分头进场、结果互不通报，最终边界地带的问题仍在部门之间来回流转。"],"answer":3,"explanation":"「多元共治」的构成要件为：①主体为跨部门工作专班；②通过建立常态化联络与移交规则；③使处置效率整体提升。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（各部门分头进场、结果互不通报），因此不符合构成要件。故选D。"},{"id":"pdn01223","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「弹性调控」是指自然保护区管理局通过随季节数据滚动修订方案，使干预强度与实际风险相匹配的工作机制。\n\n按照上述界定，下列情形可认定为「弹性调控」的是：","options":["自然保护区管理局在外来因素扩散中，随季节数据滚动修订方案，但指标已越界而措施仍维持不变。","自然保护区管理局在栖息环境变化中，指标超标后仍不调整，最终指标已越界而措施仍维持不变。","由邻近地区照抄方案，后续也未按上述机制推进。","自然保护区管理局在监测指标波动中，随季节数据滚动修订方案，干预强度与实际风险相匹配。"],"answer":3,"explanation":"「弹性调控」的构成要件为：①主体为自然保护区管理局；②通过随季节数据滚动修订方案；③使干预强度与实际风险相匹配。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01224","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「试错迭代」是指政策试点工作组通过分批次扩面而非一次铺开，使风险被限制在可控范围的工作机制。\n\n根据上述定义，下列不属于「试错迭代」的是：","options":["政策试点工作组在新工具推广中，只记录成功案例不分析偏差，最终同类偏差在扩面后被成倍放大。","政策试点工作组在新机制落地中，分批次扩面而非一次铺开，风险被限制在可控范围。","政策试点工作组在新流程上线中，分批次扩面而非一次铺开，风险被限制在可控范围。","政策试点工作组在新工具推广中，分批次扩面而非一次铺开，风险被限制在可控范围。"],"answer":0,"explanation":"「试错迭代」的构成要件为：①主体为政策试点工作组；②通过分批次扩面而非一次铺开；③使风险被限制在可控范围。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（只记录成功案例不分析偏差），因此不符合构成要件。故选A。"},{"id":"pdn01225","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「增值评价」是指课程组通过先摸清起点再设定分层目标，使后续目标更贴合实际起点的工作机制。\n\n依据上述定义，以下哪一项符合「增值评价」的构成要件：","options":["课程组在作业反馈整理中，先摸清起点再设定分层目标，但教学安排并未因数据而作任何调整。","课程组在单元教学设计中，先摸清起点再设定分层目标，后续目标更贴合实际起点。","由学生互评后不再复核，后续也未按上述机制推进。","课程组在实验课程组织中，按固定名次划线且不追溯变化，最终教学安排并未因数据而作任何调整。"],"answer":1,"explanation":"「增值评价」的构成要件为：①主体为课程组；②通过先摸清起点再设定分层目标；③使后续目标更贴合实际起点。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01226","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「形成性评价」是指学校教研组通过随堂记录并及时反馈调整，使后续目标更贴合实际起点的工作机制。\n\n按照上述界定，下列情形不应认定为「形成性评价」的是：","options":["学校教研组在作业反馈整理中，随堂记录并及时反馈调整，后续目标更贴合实际起点。","学校教研组在实验课程组织中，只以期末一次分数定结论，最终教学安排并未因数据而作任何调整。","学校教研组在实验课程组织中，随堂记录并及时反馈调整，后续目标更贴合实际起点。","学校教研组在单元教学设计中，随堂记录并及时反馈调整，后续目标更贴合实际起点。"],"answer":1,"explanation":"「形成性评价」的构成要件为：①主体为学校教研组；②通过随堂记录并及时反馈调整；③使后续目标更贴合实际起点。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（只以期末一次分数定结论），因此不符合构成要件。故选B。"},{"id":"pdn01227","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「连续照护」是指乡镇卫生院通过建立电子档案并定期回访，使病情变化能被尽早发现的工作机制。\n\n根据上述定义，下列属于「连续照护」的是：","options":["仅由三甲医院单方建档，后续也未按上述机制推进。","乡镇卫生院在慢病随访安排中，建立电子档案并定期回访，病情变化能被尽早发现。","乡镇卫生院在康复跟踪记录中，只做一次性检查不作后续跟踪，最终各环节彼此脱节、患者仍需多次重复排队。","乡镇卫生院在重点人群筛查中，建立电子档案并定期回访，但各环节彼此脱节、患者仍需多次重复排队。"],"answer":1,"explanation":"「连续照护」的构成要件为：①主体为乡镇卫生院；②通过建立电子档案并定期回访；③使病情变化能被尽早发现。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01228","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「循证施策」是指统计调查队通过对关键指标作独立复核，使结论不易被个别异常值带偏的工作机制。\n\n依据上述定义，以下哪一项不符合「循证施策」的构成要件：","options":["统计调查队在年度计划编制中，对关键指标作独立复核，结论不易被个别异常值带偏。","统计调查队在抽样数据核查中，对关键指标作独立复核，结论不易被个别异常值带偏。","统计调查队在政策效果评估中，以主观感受替代实测数据，最终结论无法由所引数据支撑。","统计调查队在政策效果评估中，对关键指标作独立复核，结论不易被个别异常值带偏。"],"answer":2,"explanation":"「循证施策」的构成要件为：①主体为统计调查队；②通过对关键指标作独立复核；③使结论不易被个别异常值带偏。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（以主观感受替代实测数据），因此不符合构成要件。故选C。"},{"id":"pdn01229","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「风险前置」是指应急指挥中心通过设定触发条件并提前布防，使次生影响被压到最小的工作机制。\n\n按照上述界定，下列情形可认定为「风险前置」的是：","options":["由外部单位事后支援，后续也未按上述机制推进。","应急指挥中心在响应动作预置中，只在事发后补充记录，最终异常发生时无预设动作可依。","应急指挥中心在风险等级研判中，设定触发条件并提前布防，次生影响被压到最小。","应急指挥中心在关键节点值守中，设定触发条件并提前布防，但异常发生时无预设动作可依。"],"answer":2,"explanation":"「风险前置」的构成要件为：①主体为应急指挥中心；②通过设定触发条件并提前布防；③使次生影响被压到最小。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01230","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「预案触发」是指数据中心运维组通过关键节点保留备用通道，使核心功能在异常下仍可维持的工作机制。\n\n根据上述定义，下列不属于「预案触发」的是：","options":["数据中心运维组在风险等级研判中，关键节点保留备用通道，核心功能在异常下仍可维持。","数据中心运维组在关键节点值守中，关键节点保留备用通道，核心功能在异常下仍可维持。","数据中心运维组在响应动作预置中，等指标越限后才临时研究方案，最终异常发生时无预设动作可依。","数据中心运维组在响应动作预置中，关键节点保留备用通道，核心功能在异常下仍可维持。"],"answer":2,"explanation":"「预案触发」的构成要件为：①主体为数据中心运维组；②通过关键节点保留备用通道；③使核心功能在异常下仍可维持。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（等指标越限后才临时研究方案），因此不符合构成要件。故选C。"},{"id":"pdn01231","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「协同会商」是指社区网格站通过建立台账逐项限时销号，使诉求在前端得到化解的工作机制。\n\n依据上述定义，以下哪一项符合「协同会商」的构成要件：","options":["由临时志愿队自行接管，后续也未按上述机制推进。","社区网格站在便民事项办理中，建立台账逐项限时销号，但问题仍反复出现且未形成稳定机制。","社区网格站在老旧小区改造中，建立台账逐项限时销号，诉求在前端得到化解。","社区网格站在邻里纠纷调解中，等群众上门反映后再统一研究，最终问题仍反复出现且未形成稳定机制。"],"answer":2,"explanation":"「协同会商」的构成要件为：①主体为社区网格站；②通过建立台账逐项限时销号；③使诉求在前端得到化解。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01232","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「联勤联动」是指街道与职能站所通过一次会商形成分工清单，使重复检查与推诿明显减少的工作机制。\n\n按照上述界定，下列情形不应认定为「联勤联动」的是：","options":["街道与职能站所在联合排班安排中，遇跨界事项互相等待，最终边界地带的问题仍在部门之间来回流转。","街道与职能站所在信息通报共享中，一次会商形成分工清单，重复检查与推诿明显减少。","街道与职能站所在跨界事项梳理中，一次会商形成分工清单，重复检查与推诿明显减少。","街道与职能站所在联合排班安排中，一次会商形成分工清单，重复检查与推诿明显减少。"],"answer":0,"explanation":"「联勤联动」的构成要件为：①主体为街道与职能站所；②通过一次会商形成分工清单；③使重复检查与推诿明显减少。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（遇跨界事项互相等待），因此不符合构成要件。故选A。"},{"id":"pdn01233","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「共创工作坊」是指公共服务设计组通过先做可体验原型再收集反馈，使隐蔽障碍在使用前被暴露的工作机制。\n\n根据上述定义，下列属于「共创工作坊」的是：","options":["由外部专家远程定稿，后续也未按上述机制推进。","公共服务设计组在公共界面优化中，一次性定稿不再接收反馈，最终上线后仍频发与习惯不符的障碍。","公共服务设计组在服务流程梳理中，先做可体验原型再收集反馈，隐蔽障碍在使用前被暴露。","公共服务设计组在使用路径排查中，先做可体验原型再收集反馈，但上线后仍频发与习惯不符的障碍。"],"answer":2,"explanation":"「共创工作坊」的构成要件为：①主体为公共服务设计组；②通过先做可体验原型再收集反馈；③使隐蔽障碍在使用前被暴露。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01234","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「分区管控」是指生态环境监测站通过按监测指标分档调整措施，使干预强度与实际风险相匹配的工作机制。\n\n依据上述定义，以下哪一项不符合「分区管控」的构成要件：","options":["生态环境监测站在栖息环境变化中，全年沿用同一套固定配额，最终指标已越界而措施仍维持不变。","生态环境监测站在监测指标波动中，按监测指标分档调整措施，干预强度与实际风险相匹配。","生态环境监测站在栖息环境变化中，按监测指标分档调整措施，干预强度与实际风险相匹配。","生态环境监测站在外来因素扩散中，按监测指标分档调整措施，干预强度与实际风险相匹配。"],"answer":0,"explanation":"「分区管控」的构成要件为：①主体为生态环境监测站；②通过按监测指标分档调整措施；③使干预强度与实际风险相匹配。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（全年沿用同一套固定配额），因此不符合构成要件。故选A。"},{"id":"pdn01235","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「留存限期」是指公共服务窗口通过到期自动清理并留清理记录，使敏感字段仅在授权场景可见的工作机制。\n\n按照上述界定，下列情形可认定为「留存限期」的是：","options":["公共服务窗口在数据调阅留痕中，到期自动清理并留清理记录，但与办理目的无关的字段仍被长期留存。","由外包人员全量导出，后续也未按上述机制推进。","公共服务窗口在字段权限配置中，所有岗位开放同一份全量清单，最终与办理目的无关的字段仍被长期留存。","公共服务窗口在信息采集登记中，到期自动清理并留清理记录，敏感字段仅在授权场景可见。"],"answer":3,"explanation":"「留存限期」的构成要件为：①主体为公共服务窗口；②通过到期自动清理并留清理记录；③使敏感字段仅在授权场景可见。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01236","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「联合响应」是指跨部门工作专班通过一次会商形成分工清单，使重复检查与推诿明显减少的工作机制。\n\n根据上述定义，下列不属于「联合响应」的是：","options":["跨部门工作专班在联合排班安排中，一次会商形成分工清单，重复检查与推诿明显减少。","跨部门工作专班在跨界事项梳理中，一次会商形成分工清单，重复检查与推诿明显减少。","跨部门工作专班在信息通报共享中，一次会商形成分工清单，重复检查与推诿明显减少。","跨部门工作专班在联合排班安排中，遇跨界事项互相等待，最终边界地带的问题仍在部门之间来回流转。"],"answer":3,"explanation":"「联合响应」的构成要件为：①主体为跨部门工作专班；②通过一次会商形成分工清单；③使重复检查与推诿明显减少。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（遇跨界事项互相等待），因此不符合构成要件。故选D。"},{"id":"pdn01237","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「最小必要采集」是指医院信息科通过对外提供前作去标识化处理，使历史数据不再无限期堆积的工作机制。\n\n依据上述定义，以下哪一项符合「最小必要采集」的构成要件：","options":["医院信息科在字段权限配置中，超过期限仍不作清理，最终与办理目的无关的字段仍被长期留存。","由系统默认长期全量保留，后续也未按上述机制推进。","医院信息科在信息采集登记中，对外提供前作去标识化处理，历史数据不再无限期堆积。","医院信息科在数据调阅留痕中，对外提供前作去标识化处理，但与办理目的无关的字段仍被长期留存。"],"answer":2,"explanation":"「最小必要采集」的构成要件为：①主体为医院信息科；②通过对外提供前作去标识化处理；③使历史数据不再无限期堆积。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01238","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「形成性评价」是指课程组通过随堂记录并及时反馈调整，使后续目标更贴合实际起点的工作机制。\n\n按照上述界定，下列情形不应认定为「形成性评价」的是：","options":["课程组在实验课程组织中，只以期末一次分数定结论，最终教学安排并未因数据而作任何调整。","课程组在实验课程组织中，随堂记录并及时反馈调整，后续目标更贴合实际起点。","课程组在单元教学设计中，随堂记录并及时反馈调整，后续目标更贴合实际起点。","课程组在作业反馈整理中，随堂记录并及时反馈调整，后续目标更贴合实际起点。"],"answer":0,"explanation":"「形成性评价」的构成要件为：①主体为课程组；②通过随堂记录并及时反馈调整；③使后续目标更贴合实际起点。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（只以期末一次分数定结论），因此不符合构成要件。故选A。"},{"id":"pdn01239","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「留痕管理」是指农产品质量检测站通过按批号串联台账与检验记录，使召回范围精确到具体批次的工作机制。\n\n根据上述定义，下列属于「留痕管理」的是：","options":["农产品质量检测站在储运环节温控中，按批号串联台账与检验记录，但出现问题时无法定位到具体环节。","由终端门店自行补记，后续也未按上述机制推进。","农产品质量检测站在进货环节核验中，按批号串联台账与检验记录，召回范围精确到具体批次。","农产品质量检测站在批次交接记录中，各环节各自记录且互不关联，最终出现问题时无法定位到具体环节。"],"answer":2,"explanation":"「留痕管理」的构成要件为：①主体为农产品质量检测站；②通过按批号串联台账与检验记录；③使召回范围精确到具体批次。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01240","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「协同治理」是指街道与职能站所通过共享信息并同步排班，使重复检查与推诿明显减少的工作机制。\n\n依据上述定义，以下哪一项不符合「协同治理」的构成要件：","options":["街道与职能站所在跨界事项梳理中，共享信息并同步排班，重复检查与推诿明显减少。","街道与职能站所在信息通报共享中，共享信息并同步排班，重复检查与推诿明显减少。","街道与职能站所在联合排班安排中，共享信息并同步排班，重复检查与推诿明显减少。","街道与职能站所在联合排班安排中，遇跨界事项互相等待，最终边界地带的问题仍在部门之间来回流转。"],"answer":3,"explanation":"「协同治理」的构成要件为：①主体为街道与职能站所；②通过共享信息并同步排班；③使重复检查与推诿明显减少。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（遇跨界事项互相等待），因此不符合构成要件。故选D。"},{"id":"pdn01241","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「协同会商」是指村委会通过提前公示并逐户征询意见，使重复投诉明显下降的工作机制。\n\n按照上述界定，下列情形可认定为「协同会商」的是：","options":["村委会在便民事项办理中，提前公示并逐户征询意见，但问题仍反复出现且未形成稳定机制。","村委会在邻里纠纷调解中，各口径分头办理、彼此不通气，最终问题仍反复出现且未形成稳定机制。","由服务对象自行申报后不再跟进，后续也未按上述机制推进。","村委会在老旧小区改造中，提前公示并逐户征询意见，重复投诉明显下降。"],"answer":3,"explanation":"「协同会商」的构成要件为：①主体为村委会；②通过提前公示并逐户征询意见；③使重复投诉明显下降。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01242","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「脱敏处理」是指公共服务窗口通过对外提供前作去标识化处理，使共享环节不泄露可识别信息的工作机制。\n\n根据上述定义，下列不属于「脱敏处理」的是：","options":["公共服务窗口在数据调阅留痕中，对外提供前作去标识化处理，共享环节不泄露可识别信息。","公共服务窗口在字段权限配置中，为方便起见一次性收齐全部字段，最终与办理目的无关的字段仍被长期留存。","公共服务窗口在信息采集登记中，对外提供前作去标识化处理，共享环节不泄露可识别信息。","公共服务窗口在字段权限配置中，对外提供前作去标识化处理，共享环节不泄露可识别信息。"],"answer":1,"explanation":"「脱敏处理」的构成要件为：①主体为公共服务窗口；②通过对外提供前作去标识化处理；③使共享环节不泄露可识别信息。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（为方便起见一次性收齐全部字段），因此不符合构成要件。故选B。"},{"id":"pdn01243","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「留痕管理」是指冷链运营方通过每一节点登记并关联上下游凭证，使召回范围精确到具体批次的工作机制。\n\n依据上述定义，以下哪一项符合「留痕管理」的构成要件：","options":["冷链运营方在进货环节核验中，每一节点登记并关联上下游凭证，召回范围精确到具体批次。","冷链运营方在储运环节温控中，每一节点登记并关联上下游凭证，但出现问题时无法定位到具体环节。","由终端门店自行补记，后续也未按上述机制推进。","冷链运营方在批次交接记录中，各环节各自记录且互不关联，最终出现问题时无法定位到具体环节。"],"answer":0,"explanation":"「留痕管理」的构成要件为：①主体为冷链运营方；②通过每一节点登记并关联上下游凭证；③使召回范围精确到具体批次。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01244","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「网格代办」是指村委会通过建立台账逐项限时销号，使诉求在前端得到化解的工作机制。\n\n按照上述界定，下列情形不应认定为「网格代办」的是：","options":["村委会在邻里纠纷调解中，只在事后补录台账，最终问题仍反复出现且未形成稳定机制。","村委会在邻里纠纷调解中，建立台账逐项限时销号，诉求在前端得到化解。","村委会在老旧小区改造中，建立台账逐项限时销号，诉求在前端得到化解。","村委会在便民事项办理中，建立台账逐项限时销号，诉求在前端得到化解。"],"answer":0,"explanation":"「网格代办」的构成要件为：①主体为村委会；②通过建立台账逐项限时销号；③使诉求在前端得到化解。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（只在事后补录台账），因此不符合构成要件。故选A。"},{"id":"pdn01245","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「协同治理」是指跨部门工作专班通过明确牵头与配合边界后统一行动，使重复检查与推诿明显减少的工作机制。\n\n根据上述定义，下列属于「协同治理」的是：","options":["跨部门工作专班在信息通报共享中，明确牵头与配合边界后统一行动，但边界地带的问题仍在部门之间来回流转。","跨部门工作专班在跨界事项梳理中，明确牵头与配合边界后统一行动，重复检查与推诿明显减少。","跨部门工作专班在联合排班安排中，各自按本部门旧流程办理，最终边界地带的问题仍在部门之间来回流转。","由上级部门包办到底，后续也未按上述机制推进。"],"answer":1,"explanation":"「协同治理」的构成要件为：①主体为跨部门工作专班；②通过明确牵头与配合边界后统一行动；③使重复检查与推诿明显减少。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01246","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「需求导向供给」是指养老服务站点通过按对象条件分档配置资源，使冷门项目被及时替换的工作机制。\n\n依据上述定义，以下哪一项不符合「需求导向供给」的构成要件：","options":["养老服务站点在对象需求摸排中，按对象条件分档配置资源，冷门项目被及时替换。","养老服务站点在服务事项梳理中，按对象条件分档配置资源，冷门项目被及时替换。","养老服务站点在对象需求摸排中，所有对象发放完全相同的固定包，最终大量项目无人使用而真实诉求仍被搁置。","养老服务站点在服务清单编制中，按对象条件分档配置资源，冷门项目被及时替换。"],"answer":2,"explanation":"「需求导向供给」的构成要件为：①主体为养老服务站点；②通过按对象条件分档配置资源；③使冷门项目被及时替换。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（所有对象发放完全相同的固定包），因此不符合构成要件。故选C。"},{"id":"pdn01247","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「共创工作坊」是指社区营造团队通过多轮共创后收敛为最终版本，使隐蔽障碍在使用前被暴露的工作机制。\n\n按照上述界定，下列情形可认定为「共创工作坊」的是：","options":["社区营造团队在使用路径排查中，多轮共创后收敛为最终版本，但上线后仍频发与习惯不符的障碍。","由供应商提供标准模板，后续也未按上述机制推进。","社区营造团队在服务流程梳理中，多轮共创后收敛为最终版本，隐蔽障碍在使用前被暴露。","社区营造团队在公共界面优化中，只做内部评审不接触使用者，最终上线后仍频发与习惯不符的障碍。"],"answer":2,"explanation":"「共创工作坊」的构成要件为：①主体为社区营造团队；②通过多轮共创后收敛为最终版本；③使隐蔽障碍在使用前被暴露。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01248","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「留痕管理」是指冷链运营方通过每一节点登记并关联上下游凭证，使责任环节清晰可查的工作机制。\n\n根据上述定义，下列不属于「留痕管理」的是：","options":["冷链运营方在批次交接记录中，每一节点登记并关联上下游凭证，责任环节清晰可查。","冷链运营方在进货环节核验中，每一节点登记并关联上下游凭证，责任环节清晰可查。","冷链运营方在批次交接记录中，事后一次性补全整本台账，最终出现问题时无法定位到具体环节。","冷链运营方在储运环节温控中，每一节点登记并关联上下游凭证，责任环节清晰可查。"],"answer":2,"explanation":"「留痕管理」的构成要件为：①主体为冷链运营方；②通过每一节点登记并关联上下游凭证；③使责任环节清晰可查。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（事后一次性补全整本台账），因此不符合构成要件。故选C。"},{"id":"pdn01249","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「跨界协作」是指流域联席会议通过建立常态化联络与移交规则，使跨界问题不再悬空的工作机制。\n\n依据上述定义，以下哪一项符合「跨界协作」的构成要件：","options":["流域联席会议在联合排班安排中，各自按本部门旧流程办理，最终边界地带的问题仍在部门之间来回流转。","流域联席会议在信息通报共享中，建立常态化联络与移交规则，但边界地带的问题仍在部门之间来回流转。","由上级部门包办到底，后续也未按上述机制推进。","流域联席会议在跨界事项梳理中，建立常态化联络与移交规则，跨界问题不再悬空。"],"answer":3,"explanation":"「跨界协作」的构成要件为：①主体为流域联席会议；②通过建立常态化联络与移交规则；③使跨界问题不再悬空。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01250","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「差异化供给」是指公共文化服务中心通过按对象条件分档配置资源，使供给与实际需求更加贴合的工作机制。\n\n按照上述界定，下列情形不应认定为「差异化供给」的是：","options":["公共文化服务中心在服务清单编制中，按对象条件分档配置资源，供给与实际需求更加贴合。","公共文化服务中心在服务事项梳理中，按对象条件分档配置资源，供给与实际需求更加贴合。","公共文化服务中心在对象需求摸排中，所有对象发放完全相同的固定包，最终大量项目无人使用而真实诉求仍被搁置。","公共文化服务中心在对象需求摸排中，按对象条件分档配置资源，供给与实际需求更加贴合。"],"answer":2,"explanation":"「差异化供给」的构成要件为：①主体为公共文化服务中心；②通过按对象条件分档配置资源；③使供给与实际需求更加贴合。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（所有对象发放完全相同的固定包），因此不符合构成要件。故选C。"},{"id":"pdn01251","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「循证施策」是指政策评估小组通过用对照组剔除同期其他影响，使后续调整有据可依的工作机制。\n\n根据上述定义，下列属于「循证施策」的是：","options":["政策评估小组在政策效果评估中，用总量变化直接归因、不作对照，最终结论无法由所引数据支撑。","政策评估小组在年度计划编制中，用对照组剔除同期其他影响，后续调整有据可依。","由申报方自行填报不作核实，后续也未按上述机制推进。","政策评估小组在抽样数据核查中，用对照组剔除同期其他影响，但结论无法由所引数据支撑。"],"answer":1,"explanation":"「循证施策」的构成要件为：①主体为政策评估小组；②通过用对照组剔除同期其他影响；③使后续调整有据可依。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01252","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「容错纠偏」是指改革推进专班通过先在小范围试运行再按反馈调整，使方案随实际反馈逐步完善的工作机制。\n\n依据上述定义，以下哪一项不符合「容错纠偏」的构成要件：","options":["改革推进专班在新流程上线中，先在小范围试运行再按反馈调整，方案随实际反馈逐步完善。","改革推进专班在新工具推广中，只记录成功案例不分析偏差，最终同类偏差在扩面后被成倍放大。","改革推进专班在新机制落地中，先在小范围试运行再按反馈调整，方案随实际反馈逐步完善。","改革推进专班在新工具推广中，先在小范围试运行再按反馈调整，方案随实际反馈逐步完善。"],"answer":1,"explanation":"「容错纠偏」的构成要件为：①主体为改革推进专班；②通过先在小范围试运行再按反馈调整；③使方案随实际反馈逐步完善。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（只记录成功案例不分析偏差），因此不符合构成要件。故选B。"},{"id":"pdn01253","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「目的限定」是指学校学籍管理系统通过到期自动清理并留清理记录，使历史数据不再无限期堆积的工作机制。\n\n按照上述界定，下列情形可认定为「目的限定」的是：","options":["学校学籍管理系统在信息采集登记中，到期自动清理并留清理记录，历史数据不再无限期堆积。","学校学籍管理系统在字段权限配置中，超过期限仍不作清理，最终与办理目的无关的字段仍被长期留存。","学校学籍管理系统在数据调阅留痕中，到期自动清理并留清理记录，但与办理目的无关的字段仍被长期留存。","由系统默认长期全量保留，后续也未按上述机制推进。"],"answer":0,"explanation":"「目的限定」的构成要件为：①主体为学校学籍管理系统；②通过到期自动清理并留清理记录；③使历史数据不再无限期堆积。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01254","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「复盘改进」是指政策试点工作组通过每轮结束后复盘并修订下一轮，使后续推广更贴合一线实际的工作机制。\n\n根据上述定义，下列不属于「复盘改进」的是：","options":["政策试点工作组在新机制落地中，每轮结束后复盘并修订下一轮，后续推广更贴合一线实际。","政策试点工作组在新工具推广中，不经试点直接全面强制推开，最终同类偏差在扩面后被成倍放大。","政策试点工作组在新工具推广中，每轮结束后复盘并修订下一轮，后续推广更贴合一线实际。","政策试点工作组在新流程上线中，每轮结束后复盘并修订下一轮，后续推广更贴合一线实际。"],"answer":1,"explanation":"「复盘改进」的构成要件为：①主体为政策试点工作组；②通过每轮结束后复盘并修订下一轮；③使后续推广更贴合一线实际。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（不经试点直接全面强制推开），因此不符合构成要件。故选B。"},{"id":"pdn01255","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「协同会商」是指村委会通过联合多方现场会商后再定方案，使居民满意度稳步提升的工作机制。\n\n依据上述定义，以下哪一项符合「协同会商」的构成要件：","options":["村委会在邻里纠纷调解中，等群众上门反映后再统一研究，最终问题仍反复出现且未形成稳定机制。","由临时志愿队自行接管，后续也未按上述机制推进。","村委会在便民事项办理中，联合多方现场会商后再定方案，但问题仍反复出现且未形成稳定机制。","村委会在老旧小区改造中，联合多方现场会商后再定方案，居民满意度稳步提升。"],"answer":3,"explanation":"「协同会商」的构成要件为：①主体为村委会；②通过联合多方现场会商后再定方案；③使居民满意度稳步提升。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01256","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「风险前置」是指数据中心运维组通过关键节点保留备用通道，使险情初起即进入有序处置的工作机制。\n\n按照上述界定，下列情形不应认定为「风险前置」的是：","options":["数据中心运维组在风险等级研判中，关键节点保留备用通道，险情初起即进入有序处置。","数据中心运维组在响应动作预置中，预案长期封存不随风险更新，最终异常发生时无预设动作可依。","数据中心运维组在关键节点值守中，关键节点保留备用通道，险情初起即进入有序处置。","数据中心运维组在响应动作预置中，关键节点保留备用通道，险情初起即进入有序处置。"],"answer":1,"explanation":"「风险前置」的构成要件为：①主体为数据中心运维组；②通过关键节点保留备用通道；③使险情初起即进入有序处置。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（预案长期封存不随风险更新），因此不符合构成要件。故选B。"},{"id":"pdn01257","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「分区管控」是指生态环境监测站通过随季节数据滚动修订方案，使管控成本保持在合理区间的工作机制。\n\n根据上述定义，下列属于「分区管控」的是：","options":["生态环境监测站在监测指标波动中，随季节数据滚动修订方案，管控成本保持在合理区间。","由游客反馈临时决定，后续也未按上述机制推进。","生态环境监测站在栖息环境变化中，等出现明显损害后再启动处置，最终指标已越界而措施仍维持不变。","生态环境监测站在外来因素扩散中，随季节数据滚动修订方案，但指标已越界而措施仍维持不变。"],"answer":0,"explanation":"「分区管控」的构成要件为：①主体为生态环境监测站；②通过随季节数据滚动修订方案；③使管控成本保持在合理区间。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01258","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「精准匹配」是指农技推广站通过先摸清不同群体诉求再分类提供，使资源不再平均摊薄的工作机制。\n\n依据上述定义，以下哪一项不符合「精准匹配」的构成要件：","options":["农技推广站在服务清单编制中，先摸清不同群体诉求再分类提供，资源不再平均摊薄。","农技推广站在对象需求摸排中，先摸清不同群体诉求再分类提供，资源不再平均摊薄。","农技推广站在对象需求摸排中，所有对象发放完全相同的固定包，最终大量项目无人使用而真实诉求仍被搁置。","农技推广站在服务事项梳理中，先摸清不同群体诉求再分类提供，资源不再平均摊薄。"],"answer":2,"explanation":"「精准匹配」的构成要件为：①主体为农技推广站；②通过先摸清不同群体诉求再分类提供；③使资源不再平均摊薄。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（所有对象发放完全相同的固定包），因此不符合构成要件。故选C。"},{"id":"pdn01259","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「预案触发」是指应急指挥中心通过设定触发条件并提前布防，使核心功能在异常下仍可维持的工作机制。\n\n按照上述界定，下列情形可认定为「预案触发」的是：","options":["应急指挥中心在风险等级研判中，设定触发条件并提前布防，核心功能在异常下仍可维持。","应急指挥中心在响应动作预置中，仅保留一份无备用的关键设备，最终异常发生时无预设动作可依。","应急指挥中心在关键节点值守中，设定触发条件并提前布防，但异常发生时无预设动作可依。","由上级在事后统一追认，后续也未按上述机制推进。"],"answer":0,"explanation":"「预案触发」的构成要件为：①主体为应急指挥中心；②通过设定触发条件并提前布防；③使核心功能在异常下仍可维持。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01260","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「闭环处置」是指街道办通过依托网格员常态化走访摸排，使诉求在前端得到化解的工作机制。\n\n根据上述定义，下列不属于「闭环处置」的是：","options":["街道办在老旧小区改造中，依托网格员常态化走访摸排，诉求在前端得到化解。","街道办在便民事项办理中，依托网格员常态化走访摸排，诉求在前端得到化解。","街道办在邻里纠纷调解中，只在事后补录台账，最终问题仍反复出现且未形成稳定机制。","街道办在邻里纠纷调解中，依托网格员常态化走访摸排，诉求在前端得到化解。"],"answer":2,"explanation":"「闭环处置」的构成要件为：①主体为街道办；②通过依托网格员常态化走访摸排；③使诉求在前端得到化解。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（只在事后补录台账），因此不符合构成要件。故选C。"},{"id":"pdn01261","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「过程性考核」是指课程组通过结合真实任务表现打分，使后续目标更贴合实际起点的工作机制。\n\n依据上述定义，以下哪一项符合「过程性考核」的构成要件：","options":["由学生互评后不再复核，后续也未按上述机制推进。","课程组在单元教学设计中，结合真实任务表现打分，后续目标更贴合实际起点。","课程组在实验课程组织中，按固定名次划线且不追溯变化，最终教学安排并未因数据而作任何调整。","课程组在作业反馈整理中，结合真实任务表现打分，但教学安排并未因数据而作任何调整。"],"answer":1,"explanation":"「过程性考核」的构成要件为：①主体为课程组；②通过结合真实任务表现打分；③使后续目标更贴合实际起点。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01262","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「诊断性测评」是指课程组通过按阶段采集学情数据再修正教学，使后续目标更贴合实际起点的工作机制。\n\n按照上述界定，下列情形不应认定为「诊断性测评」的是：","options":["课程组在实验课程组织中，只以期末一次分数定结论，最终教学安排并未因数据而作任何调整。","课程组在实验课程组织中，按阶段采集学情数据再修正教学，后续目标更贴合实际起点。","课程组在作业反馈整理中，按阶段采集学情数据再修正教学，后续目标更贴合实际起点。","课程组在单元教学设计中，按阶段采集学情数据再修正教学，后续目标更贴合实际起点。"],"answer":0,"explanation":"「诊断性测评」的构成要件为：①主体为课程组；②通过按阶段采集学情数据再修正教学；③使后续目标更贴合实际起点。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（只以期末一次分数定结论），因此不符合构成要件。故选A。"},{"id":"pdn01263","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「预案触发」是指数据中心运维组通过按风险等级预置响应动作，使次生影响被压到最小的工作机制。\n\n根据上述定义，下列属于「预案触发」的是：","options":["数据中心运维组在风险等级研判中，按风险等级预置响应动作，次生影响被压到最小。","由上级在事后统一追认，后续也未按上述机制推进。","数据中心运维组在响应动作预置中，仅保留一份无备用的关键设备，最终异常发生时无预设动作可依。","数据中心运维组在关键节点值守中，按风险等级预置响应动作，但异常发生时无预设动作可依。"],"answer":0,"explanation":"「预案触发」的构成要件为：①主体为数据中心运维组；②通过按风险等级预置响应动作；③使次生影响被压到最小。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01264","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「预案触发」是指城市运行管理平台通过按风险等级预置响应动作，使险情初起即进入有序处置的工作机制。\n\n依据上述定义，以下哪一项不符合「预案触发」的构成要件：","options":["城市运行管理平台在响应动作预置中，预案长期封存不随风险更新，最终异常发生时无预设动作可依。","城市运行管理平台在关键节点值守中，按风险等级预置响应动作，险情初起即进入有序处置。","城市运行管理平台在风险等级研判中，按风险等级预置响应动作，险情初起即进入有序处置。","城市运行管理平台在响应动作预置中，按风险等级预置响应动作，险情初起即进入有序处置。"],"answer":0,"explanation":"「预案触发」的构成要件为：①主体为城市运行管理平台；②通过按风险等级预置响应动作；③使险情初起即进入有序处置。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（预案长期封存不随风险更新），因此不符合构成要件。故选A。"},{"id":"pdn01265","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「全过程追溯」是指冷链运营方通过每一节点登记并关联上下游凭证，使台账与实物始终一致的工作机制。\n\n按照上述界定，下列情形可认定为「全过程追溯」的是：","options":["冷链运营方在进货环节核验中，每一节点登记并关联上下游凭证，台账与实物始终一致。","冷链运营方在批次交接记录中，仅保留汇总数不留明细，最终出现问题时无法定位到具体环节。","冷链运营方在储运环节温控中，每一节点登记并关联上下游凭证，但出现问题时无法定位到具体环节。","由消费者事后反馈倒查，后续也未按上述机制推进。"],"answer":0,"explanation":"「全过程追溯」的构成要件为：①主体为冷链运营方；②通过每一节点登记并关联上下游凭证；③使台账与实物始终一致。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01266","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「预案触发」是指数据中心运维组通过识别薄弱环节并预先加固，使人员与物资提前就位的工作机制。\n\n根据上述定义，下列不属于「预案触发」的是：","options":["数据中心运维组在风险等级研判中，识别薄弱环节并预先加固，人员与物资提前就位。","数据中心运维组在响应动作预置中，等指标越限后才临时研究方案，最终异常发生时无预设动作可依。","数据中心运维组在关键节点值守中，识别薄弱环节并预先加固，人员与物资提前就位。","数据中心运维组在响应动作预置中，识别薄弱环节并预先加固，人员与物资提前就位。"],"answer":1,"explanation":"「预案触发」的构成要件为：①主体为数据中心运维组；②通过识别薄弱环节并预先加固；③使人员与物资提前就位。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（等指标越限后才临时研究方案），因此不符合构成要件。故选B。"},{"id":"pdn01267","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「分级预警」是指水利工程调度处通过按风险等级预置响应动作，使险情初起即进入有序处置的工作机制。\n\n依据上述定义，以下哪一项符合「分级预警」的构成要件：","options":["由上级在事后统一追认，后续也未按上述机制推进。","水利工程调度处在关键节点值守中，按风险等级预置响应动作，但异常发生时无预设动作可依。","水利工程调度处在响应动作预置中，仅保留一份无备用的关键设备，最终异常发生时无预设动作可依。","水利工程调度处在风险等级研判中，按风险等级预置响应动作，险情初起即进入有序处置。"],"answer":3,"explanation":"「分级预警」的构成要件为：①主体为水利工程调度处；②通过按风险等级预置响应动作；③使险情初起即进入有序处置。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01268","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「最小必要采集」是指学校学籍管理系统通过按岗位授予最小可见范围，使敏感字段仅在授权场景可见的工作机制。\n\n按照上述界定，下列情形不应认定为「最小必要采集」的是：","options":["学校学籍管理系统在数据调阅留痕中，按岗位授予最小可见范围，敏感字段仅在授权场景可见。","学校学籍管理系统在字段权限配置中，共享时直接提供原始明细，最终与办理目的无关的字段仍被长期留存。","学校学籍管理系统在信息采集登记中，按岗位授予最小可见范围，敏感字段仅在授权场景可见。","学校学籍管理系统在字段权限配置中，按岗位授予最小可见范围，敏感字段仅在授权场景可见。"],"answer":1,"explanation":"「最小必要采集」的构成要件为：①主体为学校学籍管理系统；②通过按岗位授予最小可见范围；③使敏感字段仅在授权场景可见。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（共享时直接提供原始明细），因此不符合构成要件。故选B。"},{"id":"pdn01269","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「可回溯核查」是指冷链运营方通过每一节点登记并关联上下游凭证，使问题批次能被快速定位的工作机制。\n\n根据上述定义，下列属于「可回溯核查」的是：","options":["由消费者事后反馈倒查，后续也未按上述机制推进。","冷链运营方在批次交接记录中，仅保留汇总数不留明细，最终出现问题时无法定位到具体环节。","冷链运营方在进货环节核验中，每一节点登记并关联上下游凭证，问题批次能被快速定位。","冷链运营方在储运环节温控中，每一节点登记并关联上下游凭证，但出现问题时无法定位到具体环节。"],"answer":2,"explanation":"「可回溯核查」的构成要件为：①主体为冷链运营方；②通过每一节点登记并关联上下游凭证；③使问题批次能被快速定位。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01270","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「参与式设计」是指产品体验小组通过邀请使用者全程参与方案打磨，使返工与投诉明显减少的工作机制。\n\n依据上述定义，以下哪一项不符合「参与式设计」的构成要件：","options":["产品体验小组在服务流程梳理中，邀请使用者全程参与方案打磨，返工与投诉明显减少。","产品体验小组在公共界面优化中，仅在完工后征求意见，最终上线后仍频发与习惯不符的障碍。","产品体验小组在公共界面优化中，邀请使用者全程参与方案打磨，返工与投诉明显减少。","产品体验小组在使用路径排查中，邀请使用者全程参与方案打磨，返工与投诉明显减少。"],"answer":1,"explanation":"「参与式设计」的构成要件为：①主体为产品体验小组；②通过邀请使用者全程参与方案打磨；③使返工与投诉明显减少。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（仅在完工后征求意见），因此不符合构成要件。故选B。"},{"id":"pdn01271","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「跨界协作」是指跨部门工作专班通过共享信息并同步排班，使重复检查与推诿明显减少的工作机制。\n\n按照上述界定，下列情形可认定为「跨界协作」的是：","options":["跨部门工作专班在信息通报共享中，共享信息并同步排班，但边界地带的问题仍在部门之间来回流转。","由各区各自为政，后续也未按上述机制推进。","跨部门工作专班在联合排班安排中，只开会不落责任清单，最终边界地带的问题仍在部门之间来回流转。","跨部门工作专班在跨界事项梳理中，共享信息并同步排班，重复检查与推诿明显减少。"],"answer":3,"explanation":"「跨界协作」的构成要件为：①主体为跨部门工作专班；②通过共享信息并同步排班；③使重复检查与推诿明显减少。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01272","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「动态监测」是指流域管理机构通过随季节数据滚动修订方案，使核心栖息地得到有效避让的工作机制。\n\n根据上述定义，下列不属于「动态监测」的是：","options":["流域管理机构在栖息环境变化中，只看年度均值忽略峰值，最终指标已越界而措施仍维持不变。","流域管理机构在外来因素扩散中，随季节数据滚动修订方案，核心栖息地得到有效避让。","流域管理机构在栖息环境变化中，随季节数据滚动修订方案，核心栖息地得到有效避让。","流域管理机构在监测指标波动中，随季节数据滚动修订方案，核心栖息地得到有效避让。"],"answer":0,"explanation":"「动态监测」的构成要件为：①主体为流域管理机构；②通过随季节数据滚动修订方案；③使核心栖息地得到有效避让。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（只看年度均值忽略峰值），因此不符合构成要件。故选A。"},{"id":"pdn01273","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「多元共治」是指区级牵头部门通过建立常态化联络与移交规则，使重复检查与推诿明显减少的工作机制。\n\n依据上述定义，以下哪一项符合「多元共治」的构成要件：","options":["区级牵头部门在跨界事项梳理中，建立常态化联络与移交规则，重复检查与推诿明显减少。","区级牵头部门在信息通报共享中，建立常态化联络与移交规则，但边界地带的问题仍在部门之间来回流转。","区级牵头部门在联合排班安排中，各自按本部门旧流程办理，最终边界地带的问题仍在部门之间来回流转。","由上级部门包办到底，后续也未按上述机制推进。"],"answer":0,"explanation":"「多元共治」的构成要件为：①主体为区级牵头部门；②通过建立常态化联络与移交规则；③使重复检查与推诿明显减少。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01274","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「分级诊疗」是指社区卫生服务中心通过建立电子档案并定期回访，使重复检查明显减少的工作机制。\n\n按照上述界定，下列情形不应认定为「分级诊疗」的是：","options":["社区卫生服务中心在慢病随访安排中，建立电子档案并定期回访，重复检查明显减少。","社区卫生服务中心在重点人群筛查中，建立电子档案并定期回访，重复检查明显减少。","社区卫生服务中心在康复跟踪记录中，一律先安排住院再评估，最终各环节彼此脱节、患者仍需多次重复排队。","社区卫生服务中心在康复跟踪记录中，建立电子档案并定期回访，重复检查明显减少。"],"answer":2,"explanation":"「分级诊疗」的构成要件为：①主体为社区卫生服务中心；②通过建立电子档案并定期回访；③使重复检查明显减少。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（一律先安排住院再评估），因此不符合构成要件。故选C。"},{"id":"pdn01275","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「前置筛查」是指乡镇卫生院通过按病情轻重分流并约定转诊路径，使重复检查明显减少的工作机制。\n\n根据上述定义，下列属于「前置筛查」的是：","options":["乡镇卫生院在重点人群筛查中，按病情轻重分流并约定转诊路径，但各环节彼此脱节、患者仍需多次重复排队。","乡镇卫生院在康复跟踪记录中，只做一次性检查不作后续跟踪，最终各环节彼此脱节、患者仍需多次重复排队。","仅由三甲医院单方建档，后续也未按上述机制推进。","乡镇卫生院在慢病随访安排中，按病情轻重分流并约定转诊路径，重复检查明显减少。"],"answer":3,"explanation":"「前置筛查」的构成要件为：①主体为乡镇卫生院；②通过按病情轻重分流并约定转诊路径；③使重复检查明显减少。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01276","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「用户旅程映射」是指公共服务设计组通过邀请使用者全程参与方案打磨，使隐蔽障碍在使用前被暴露的工作机制。\n\n依据上述定义，以下哪一项不符合「用户旅程映射」的构成要件：","options":["公共服务设计组在使用路径排查中，邀请使用者全程参与方案打磨，隐蔽障碍在使用前被暴露。","公共服务设计组在公共界面优化中，照搬其他地区成品，最终上线后仍频发与习惯不符的障碍。","公共服务设计组在服务流程梳理中，邀请使用者全程参与方案打磨，隐蔽障碍在使用前被暴露。","公共服务设计组在公共界面优化中，邀请使用者全程参与方案打磨，隐蔽障碍在使用前被暴露。"],"answer":1,"explanation":"「用户旅程映射」的构成要件为：①主体为公共服务设计组；②通过邀请使用者全程参与方案打磨；③使隐蔽障碍在使用前被暴露。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（照搬其他地区成品），因此不符合构成要件。故选B。"},{"id":"pdn01277","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「小步试点」是指数字化转型办公室通过先在小范围试运行再按反馈调整，使偏差在放大前被修正的工作机制。\n\n按照上述界定，下列情形可认定为「小步试点」的是：","options":["数字化转型办公室在新工具推广中，一次上线后即固化不再迭代，最终同类偏差在扩面后被成倍放大。","数字化转型办公室在新机制落地中，先在小范围试运行再按反馈调整，但同类偏差在扩面后被成倍放大。","由用户自行摸索不作收集，后续也未按上述机制推进。","数字化转型办公室在新流程上线中，先在小范围试运行再按反馈调整，偏差在放大前被修正。"],"answer":3,"explanation":"「小步试点」的构成要件为：①主体为数字化转型办公室；②通过先在小范围试运行再按反馈调整；③使偏差在放大前被修正。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01278","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「灰度验证」是指政策试点工作组通过先在小范围试运行再按反馈调整，使风险被限制在可控范围的工作机制。\n\n根据上述定义，下列不属于「灰度验证」的是：","options":["政策试点工作组在新机制落地中，先在小范围试运行再按反馈调整，风险被限制在可控范围。","政策试点工作组在新工具推广中，先在小范围试运行再按反馈调整，风险被限制在可控范围。","政策试点工作组在新工具推广中，不经试点直接全面强制推开，最终同类偏差在扩面后被成倍放大。","政策试点工作组在新流程上线中，先在小范围试运行再按反馈调整，风险被限制在可控范围。"],"answer":2,"explanation":"「灰度验证」的构成要件为：①主体为政策试点工作组；②通过先在小范围试运行再按反馈调整；③使风险被限制在可控范围。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（不经试点直接全面强制推开），因此不符合构成要件。故选C。"},{"id":"pdn01279","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「容错纠偏」是指产品迭代小组通过设置观察期并保留回退通道，使偏差在放大前被修正的工作机制。\n\n依据上述定义，以下哪一项符合「容错纠偏」的构成要件：","options":["产品迭代小组在新流程上线中，设置观察期并保留回退通道，偏差在放大前被修正。","产品迭代小组在新机制落地中，设置观察期并保留回退通道，但同类偏差在扩面后被成倍放大。","由外部团队一次性交付即结束，后续也未按上述机制推进。","产品迭代小组在新工具推广中，试运行期间禁止任何修改，最终同类偏差在扩面后被成倍放大。"],"answer":0,"explanation":"「容错纠偏」的构成要件为：①主体为产品迭代小组；②通过设置观察期并保留回退通道；③使偏差在放大前被修正。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01280","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「留痕管理」是指药品批发企业质控部通过关键节点双人签认留档，使问题批次能被快速定位的工作机制。\n\n按照上述界定，下列情形不应认定为「留痕管理」的是：","options":["药品批发企业质控部在批次交接记录中，事后一次性补全整本台账，最终出现问题时无法定位到具体环节。","药品批发企业质控部在储运环节温控中，关键节点双人签认留档，问题批次能被快速定位。","药品批发企业质控部在进货环节核验中，关键节点双人签认留档，问题批次能被快速定位。","药品批发企业质控部在批次交接记录中，关键节点双人签认留档，问题批次能被快速定位。"],"answer":0,"explanation":"「留痕管理」的构成要件为：①主体为药品批发企业质控部；②通过关键节点双人签认留档；③使问题批次能被快速定位。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（事后一次性补全整本台账），因此不符合构成要件。故选A。"},{"id":"pdn01281","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「证据本位决策」是指统计调查队通过以多源数据交叉校验结论，使结论不易被个别异常值带偏的工作机制。\n\n根据上述定义，下列属于「证据本位决策」的是：","options":["统计调查队在政策效果评估中，指标口径中途变更却不说明，最终结论无法由所引数据支撑。","由第三方直接给结论不附依据，后续也未按上述机制推进。","统计调查队在年度计划编制中，以多源数据交叉校验结论，结论不易被个别异常值带偏。","统计调查队在抽样数据核查中，以多源数据交叉校验结论，但结论无法由所引数据支撑。"],"answer":2,"explanation":"「证据本位决策」的构成要件为：①主体为统计调查队；②通过以多源数据交叉校验结论；③使结论不易被个别异常值带偏。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01282","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「闭环处置」是指街道办通过建立台账逐项限时销号，使平均处置周期缩短的工作机制。\n\n依据上述定义，以下哪一项不符合「闭环处置」的构成要件：","options":["街道办在老旧小区改造中，建立台账逐项限时销号，平均处置周期缩短。","街道办在邻里纠纷调解中，直接照搬既有方案、未作任何征询，最终问题仍反复出现且未形成稳定机制。","街道办在邻里纠纷调解中，建立台账逐项限时销号，平均处置周期缩短。","街道办在便民事项办理中，建立台账逐项限时销号，平均处置周期缩短。"],"answer":1,"explanation":"「闭环处置」的构成要件为：①主体为街道办；②通过建立台账逐项限时销号；③使平均处置周期缩短。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（直接照搬既有方案、未作任何征询），因此不符合构成要件。故选B。"},{"id":"pdn01283","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「需求导向供给」是指农技推广站通过先摸清不同群体诉求再分类提供，使不同群体各取所需的工作机制。\n\n按照上述界定，下列情形可认定为「需求导向供给」的是：","options":["农技推广站在服务事项梳理中，先摸清不同群体诉求再分类提供，不同群体各取所需。","农技推广站在对象需求摸排中，按编制人数而不是实际用量分配，最终大量项目无人使用而真实诉求仍被搁置。","由供应商单方决定目录，后续也未按上述机制推进。","农技推广站在服务清单编制中，先摸清不同群体诉求再分类提供，但大量项目无人使用而真实诉求仍被搁置。"],"answer":0,"explanation":"「需求导向供给」的构成要件为：①主体为农技推广站；②通过先摸清不同群体诉求再分类提供；③使不同群体各取所需。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01284","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「预案触发」是指数据中心运维组通过设定触发条件并提前布防，使险情初起即进入有序处置的工作机制。\n\n根据上述定义，下列不属于「预案触发」的是：","options":["数据中心运维组在风险等级研判中，设定触发条件并提前布防，险情初起即进入有序处置。","数据中心运维组在响应动作预置中，设定触发条件并提前布防，险情初起即进入有序处置。","数据中心运维组在关键节点值守中，设定触发条件并提前布防，险情初起即进入有序处置。","数据中心运维组在响应动作预置中，预案长期封存不随风险更新，最终异常发生时无预设动作可依。"],"answer":3,"explanation":"「预案触发」的构成要件为：①主体为数据中心运维组；②通过设定触发条件并提前布防；③使险情初起即进入有序处置。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（预案长期封存不随风险更新），因此不符合构成要件。故选D。"},{"id":"pdn01285","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「形成性评价」是指区域教研中心通过结合真实任务表现打分，使后续目标更贴合实际起点的工作机制。\n\n依据上述定义，以下哪一项符合「形成性评价」的构成要件：","options":["由学生互评后不再复核，后续也未按上述机制推进。","区域教研中心在实验课程组织中，按固定名次划线且不追溯变化，最终教学安排并未因数据而作任何调整。","区域教研中心在单元教学设计中，结合真实任务表现打分，后续目标更贴合实际起点。","区域教研中心在作业反馈整理中，结合真实任务表现打分，但教学安排并未因数据而作任何调整。"],"answer":2,"explanation":"「形成性评价」的构成要件为：①主体为区域教研中心；②通过结合真实任务表现打分；③使后续目标更贴合实际起点。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01286","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「闭环处置」是指乡镇便民中心通过建立台账逐项限时销号，使诉求在前端得到化解的工作机制。\n\n按照上述界定，下列情形不应认定为「闭环处置」的是：","options":["乡镇便民中心在邻里纠纷调解中，建立台账逐项限时销号，诉求在前端得到化解。","乡镇便民中心在老旧小区改造中，建立台账逐项限时销号，诉求在前端得到化解。","乡镇便民中心在便民事项办理中，建立台账逐项限时销号，诉求在前端得到化解。","乡镇便民中心在邻里纠纷调解中，直接照搬既有方案、未作任何征询，最终问题仍反复出现且未形成稳定机制。"],"answer":3,"explanation":"「闭环处置」的构成要件为：①主体为乡镇便民中心；②通过建立台账逐项限时销号；③使诉求在前端得到化解。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（直接照搬既有方案、未作任何征询），因此不符合构成要件。故选D。"},{"id":"pdn01287","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「数据校验」是指规划编制组通过对关键指标作独立复核，使后续调整有据可依的工作机制。\n\n根据上述定义，下列属于「数据校验」的是：","options":["由申报方自行填报不作核实，后续也未按上述机制推进。","规划编制组在政策效果评估中，用总量变化直接归因、不作对照，最终结论无法由所引数据支撑。","规划编制组在抽样数据核查中，对关键指标作独立复核，但结论无法由所引数据支撑。","规划编制组在年度计划编制中，对关键指标作独立复核，后续调整有据可依。"],"answer":3,"explanation":"「数据校验」的构成要件为：①主体为规划编制组；②通过对关键指标作独立复核；③使后续调整有据可依。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01288","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「弹性调控」是指流域管理机构通过按监测指标分档调整措施，使异常苗头被尽早识别的工作机制。\n\n依据上述定义，以下哪一项不符合「弹性调控」的构成要件：","options":["流域管理机构在监测指标波动中，按监测指标分档调整措施，异常苗头被尽早识别。","流域管理机构在栖息环境变化中，只看年度均值忽略峰值，最终指标已越界而措施仍维持不变。","流域管理机构在栖息环境变化中，按监测指标分档调整措施，异常苗头被尽早识别。","流域管理机构在外来因素扩散中，按监测指标分档调整措施，异常苗头被尽早识别。"],"answer":1,"explanation":"「弹性调控」的构成要件为：①主体为流域管理机构；②通过按监测指标分档调整措施；③使异常苗头被尽早识别。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（只看年度均值忽略峰值），因此不符合构成要件。故选B。"},{"id":"pdn01289","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「小步试点」是指政策试点工作组通过设置观察期并保留回退通道，使偏差在放大前被修正的工作机制。\n\n按照上述界定，下列情形可认定为「小步试点」的是：","options":["政策试点工作组在新机制落地中，设置观察期并保留回退通道，但同类偏差在扩面后被成倍放大。","政策试点工作组在新工具推广中，一次上线后即固化不再迭代，最终同类偏差在扩面后被成倍放大。","由用户自行摸索不作收集，后续也未按上述机制推进。","政策试点工作组在新流程上线中，设置观察期并保留回退通道，偏差在放大前被修正。"],"answer":3,"explanation":"「小步试点」的构成要件为：①主体为政策试点工作组；②通过设置观察期并保留回退通道；③使偏差在放大前被修正。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01290","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「容错纠偏」是指改革推进专班通过先在小范围试运行再按反馈调整，使后续推广更贴合一线实际的工作机制。\n\n根据上述定义，下列不属于「容错纠偏」的是：","options":["改革推进专班在新机制落地中，先在小范围试运行再按反馈调整，后续推广更贴合一线实际。","改革推进专班在新工具推广中，先在小范围试运行再按反馈调整，后续推广更贴合一线实际。","改革推进专班在新工具推广中，不经试点直接全面强制推开，最终同类偏差在扩面后被成倍放大。","改革推进专班在新流程上线中，先在小范围试运行再按反馈调整，后续推广更贴合一线实际。"],"answer":2,"explanation":"「容错纠偏」的构成要件为：①主体为改革推进专班；②通过先在小范围试运行再按反馈调整；③使后续推广更贴合一线实际。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（不经试点直接全面强制推开），因此不符合构成要件。故选C。"},{"id":"pdn01291","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「前置响应」是指街道办通过依托网格员常态化走访摸排，使平均处置周期缩短的工作机制。\n\n依据上述定义，以下哪一项符合「前置响应」的构成要件：","options":["街道办在便民事项办理中，依托网格员常态化走访摸排，但问题仍反复出现且未形成稳定机制。","由临时志愿队自行接管，后续也未按上述机制推进。","街道办在老旧小区改造中，依托网格员常态化走访摸排，平均处置周期缩短。","街道办在邻里纠纷调解中，等群众上门反映后再统一研究，最终问题仍反复出现且未形成稳定机制。"],"answer":2,"explanation":"「前置响应」的构成要件为：①主体为街道办；②通过依托网格员常态化走访摸排；③使平均处置周期缩短。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01292","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「容错纠偏」是指数字化转型办公室通过分批次扩面而非一次铺开，使后续推广更贴合一线实际的工作机制。\n\n按照上述界定，下列情形不应认定为「容错纠偏」的是：","options":["数字化转型办公室在新机制落地中，分批次扩面而非一次铺开，后续推广更贴合一线实际。","数字化转型办公室在新流程上线中，分批次扩面而非一次铺开，后续推广更贴合一线实际。","数字化转型办公室在新工具推广中，只记录成功案例不分析偏差，最终同类偏差在扩面后被成倍放大。","数字化转型办公室在新工具推广中，分批次扩面而非一次铺开，后续推广更贴合一线实际。"],"answer":2,"explanation":"「容错纠偏」的构成要件为：①主体为数字化转型办公室；②通过分批次扩面而非一次铺开；③使后续推广更贴合一线实际。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（只记录成功案例不分析偏差），因此不符合构成要件。故选C。"},{"id":"pdn01293","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「多元共治」是指区级牵头部门通过一次会商形成分工清单，使响应口径保持一致的工作机制。\n\n根据上述定义，下列属于「多元共治」的是：","options":["区级牵头部门在信息通报共享中，一次会商形成分工清单，但边界地带的问题仍在部门之间来回流转。","区级牵头部门在跨界事项梳理中，一次会商形成分工清单，响应口径保持一致。","由上级部门包办到底，后续也未按上述机制推进。","区级牵头部门在联合排班安排中，各自按本部门旧流程办理，最终边界地带的问题仍在部门之间来回流转。"],"answer":1,"explanation":"「多元共治」的构成要件为：①主体为区级牵头部门；②通过一次会商形成分工清单；③使响应口径保持一致。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01294","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「证据本位决策」是指统计调查队通过先确立基线再对照前后变化，使成效与措施之间的对应更清楚的工作机制。\n\n依据上述定义，以下哪一项不符合「证据本位决策」的构成要件：","options":["统计调查队在抽样数据核查中，先确立基线再对照前后变化，成效与措施之间的对应更清楚。","统计调查队在政策效果评估中，先确立基线再对照前后变化，成效与措施之间的对应更清楚。","统计调查队在年度计划编制中，先确立基线再对照前后变化，成效与措施之间的对应更清楚。","统计调查队在政策效果评估中，只选取有利样本作展示，最终结论无法由所引数据支撑。"],"answer":3,"explanation":"「证据本位决策」的构成要件为：①主体为统计调查队；②通过先确立基线再对照前后变化；③使成效与措施之间的对应更清楚。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（只选取有利样本作展示），因此不符合构成要件。故选D。"},{"id":"pdn01295","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「指标复核」是指统计调查队通过用对照组剔除同期其他影响，使后续调整有据可依的工作机制。\n\n按照上述界定，下列情形可认定为「指标复核」的是：","options":["由申报方自行填报不作核实，后续也未按上述机制推进。","统计调查队在抽样数据核查中，用对照组剔除同期其他影响，但结论无法由所引数据支撑。","统计调查队在年度计划编制中，用对照组剔除同期其他影响，后续调整有据可依。","统计调查队在政策效果评估中，用总量变化直接归因、不作对照，最终结论无法由所引数据支撑。"],"answer":2,"explanation":"「指标复核」的构成要件为：①主体为统计调查队；②通过用对照组剔除同期其他影响；③使后续调整有据可依。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01296","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「联合响应」是指跨部门工作专班通过共享信息并同步排班，使处置效率整体提升的工作机制。\n\n根据上述定义，下列不属于「联合响应」的是：","options":["跨部门工作专班在联合排班安排中，共享信息并同步排班，处置效率整体提升。","跨部门工作专班在信息通报共享中，共享信息并同步排班，处置效率整体提升。","跨部门工作专班在跨界事项梳理中，共享信息并同步排班，处置效率整体提升。","跨部门工作专班在联合排班安排中，遇跨界事项互相等待，最终边界地带的问题仍在部门之间来回流转。"],"answer":3,"explanation":"「联合响应」的构成要件为：①主体为跨部门工作专班；②通过共享信息并同步排班；③使处置效率整体提升。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（遇跨界事项互相等待），因此不符合构成要件。故选D。"},{"id":"pdn01297","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「全过程追溯」是指冷链运营方通过异常批次可一键回溯全链路，使台账与实物始终一致的工作机制。\n\n依据上述定义，以下哪一项符合「全过程追溯」的构成要件：","options":["由消费者事后反馈倒查，后续也未按上述机制推进。","冷链运营方在进货环节核验中，异常批次可一键回溯全链路，台账与实物始终一致。","冷链运营方在储运环节温控中，异常批次可一键回溯全链路，但出现问题时无法定位到具体环节。","冷链运营方在批次交接记录中，仅保留汇总数不留明细，最终出现问题时无法定位到具体环节。"],"answer":1,"explanation":"「全过程追溯」的构成要件为：①主体为冷链运营方；②通过异常批次可一键回溯全链路；③使台账与实物始终一致。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01298","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「前置响应」是指街道办通过联合多方现场会商后再定方案，使平均处置周期缩短的工作机制。\n\n按照上述界定，下列情形不应认定为「前置响应」的是：","options":["街道办在便民事项办理中，联合多方现场会商后再定方案，平均处置周期缩短。","街道办在老旧小区改造中，联合多方现场会商后再定方案，平均处置周期缩短。","街道办在邻里纠纷调解中，联合多方现场会商后再定方案，平均处置周期缩短。","街道办在邻里纠纷调解中，直接照搬既有方案、未作任何征询，最终问题仍反复出现且未形成稳定机制。"],"answer":3,"explanation":"「前置响应」的构成要件为：①主体为街道办；②通过联合多方现场会商后再定方案；③使平均处置周期缩短。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（直接照搬既有方案、未作任何征询），因此不符合构成要件。故选D。"},{"id":"pdn01299","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「参与式设计」是指公共服务设计组通过先做可体验原型再收集反馈，使改动获得使用者认同的工作机制。\n\n根据上述定义，下列属于「参与式设计」的是：","options":["公共服务设计组在公共界面优化中，只做内部评审不接触使用者，最终上线后仍频发与习惯不符的障碍。","由供应商提供标准模板，后续也未按上述机制推进。","公共服务设计组在使用路径排查中，先做可体验原型再收集反馈，但上线后仍频发与习惯不符的障碍。","公共服务设计组在服务流程梳理中，先做可体验原型再收集反馈，改动获得使用者认同。"],"answer":3,"explanation":"「参与式设计」的构成要件为：①主体为公共服务设计组；②通过先做可体验原型再收集反馈；③使改动获得使用者认同。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01300","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「节点责任制」是指药品批发企业质控部通过关键节点双人签认留档，使台账与实物始终一致的工作机制。\n\n依据上述定义，以下哪一项不符合「节点责任制」的构成要件：","options":["药品批发企业质控部在批次交接记录中，关键节点双人签认留档，台账与实物始终一致。","药品批发企业质控部在进货环节核验中，关键节点双人签认留档，台账与实物始终一致。","药品批发企业质控部在批次交接记录中，事后一次性补全整本台账，最终出现问题时无法定位到具体环节。","药品批发企业质控部在储运环节温控中，关键节点双人签认留档，台账与实物始终一致。"],"answer":2,"explanation":"「节点责任制」的构成要件为：①主体为药品批发企业质控部；②通过关键节点双人签认留档；③使台账与实物始终一致。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（事后一次性补全整本台账），因此不符合构成要件。故选C。"},{"id":"pdn01301","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「复盘改进」是指改革推进专班通过设置观察期并保留回退通道，使后续推广更贴合一线实际的工作机制。\n\n按照上述界定，下列情形可认定为「复盘改进」的是：","options":["改革推进专班在新机制落地中，设置观察期并保留回退通道，但同类偏差在扩面后被成倍放大。","改革推进专班在新工具推广中，一次上线后即固化不再迭代，最终同类偏差在扩面后被成倍放大。","由用户自行摸索不作收集，后续也未按上述机制推进。","改革推进专班在新流程上线中，设置观察期并保留回退通道，后续推广更贴合一线实际。"],"answer":3,"explanation":"「复盘改进」的构成要件为：①主体为改革推进专班；②通过设置观察期并保留回退通道；③使后续推广更贴合一线实际。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01302","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「共创工作坊」是指社区营造团队通过邀请使用者全程参与方案打磨，使方案贴合真实使用习惯的工作机制。\n\n根据上述定义，下列不属于「共创工作坊」的是：","options":["社区营造团队在公共界面优化中，仅在完工后征求意见，最终上线后仍频发与习惯不符的障碍。","社区营造团队在服务流程梳理中，邀请使用者全程参与方案打磨，方案贴合真实使用习惯。","社区营造团队在公共界面优化中，邀请使用者全程参与方案打磨，方案贴合真实使用习惯。","社区营造团队在使用路径排查中，邀请使用者全程参与方案打磨，方案贴合真实使用习惯。"],"answer":0,"explanation":"「共创工作坊」的构成要件为：①主体为社区营造团队；②通过邀请使用者全程参与方案打磨；③使方案贴合真实使用习惯。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（仅在完工后征求意见），因此不符合构成要件。故选A。"},{"id":"pdn01303","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「循证施策」是指政策评估小组通过用对照组剔除同期其他影响，使判断建立在可核验的依据上的工作机制。\n\n依据上述定义，以下哪一项符合「循证施策」的构成要件：","options":["由申报方自行填报不作核实，后续也未按上述机制推进。","政策评估小组在抽样数据核查中，用对照组剔除同期其他影响，但结论无法由所引数据支撑。","政策评估小组在年度计划编制中，用对照组剔除同期其他影响，判断建立在可核验的依据上。","政策评估小组在政策效果评估中，用总量变化直接归因、不作对照，最终结论无法由所引数据支撑。"],"answer":2,"explanation":"「循证施策」的构成要件为：①主体为政策评估小组；②通过用对照组剔除同期其他影响；③使判断建立在可核验的依据上。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01304","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「最小必要采集」是指医院信息科通过只采集完成本事项所必需的字段，使历史数据不再无限期堆积的工作机制。\n\n按照上述界定，下列情形不应认定为「最小必要采集」的是：","options":["医院信息科在信息采集登记中，只采集完成本事项所必需的字段，历史数据不再无限期堆积。","医院信息科在字段权限配置中，只采集完成本事项所必需的字段，历史数据不再无限期堆积。","医院信息科在字段权限配置中，共享时直接提供原始明细，最终与办理目的无关的字段仍被长期留存。","医院信息科在数据调阅留痕中，只采集完成本事项所必需的字段，历史数据不再无限期堆积。"],"answer":2,"explanation":"「最小必要采集」的构成要件为：①主体为医院信息科；②通过只采集完成本事项所必需的字段；③使历史数据不再无限期堆积。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（共享时直接提供原始明细），因此不符合构成要件。故选C。"},{"id":"pdn01305","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「多元共治」是指街道与职能站所通过一次会商形成分工清单，使处置效率整体提升的工作机制。\n\n根据上述定义，下列属于「多元共治」的是：","options":["街道与职能站所在信息通报共享中，一次会商形成分工清单，但边界地带的问题仍在部门之间来回流转。","由上级部门包办到底，后续也未按上述机制推进。","街道与职能站所在联合排班安排中，各自按本部门旧流程办理，最终边界地带的问题仍在部门之间来回流转。","街道与职能站所在跨界事项梳理中，一次会商形成分工清单，处置效率整体提升。"],"answer":3,"explanation":"「多元共治」的构成要件为：①主体为街道与职能站所；②通过一次会商形成分工清单；③使处置效率整体提升。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01306","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「多元共治」是指区级牵头部门通过建立常态化联络与移交规则，使跨界问题不再悬空的工作机制。\n\n依据上述定义，以下哪一项不符合「多元共治」的构成要件：","options":["区级牵头部门在联合排班安排中，各部门分头进场、结果互不通报，最终边界地带的问题仍在部门之间来回流转。","区级牵头部门在信息通报共享中，建立常态化联络与移交规则，跨界问题不再悬空。","区级牵头部门在联合排班安排中，建立常态化联络与移交规则，跨界问题不再悬空。","区级牵头部门在跨界事项梳理中，建立常态化联络与移交规则，跨界问题不再悬空。"],"answer":0,"explanation":"「多元共治」的构成要件为：①主体为区级牵头部门；②通过建立常态化联络与移交规则；③使跨界问题不再悬空。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（各部门分头进场、结果互不通报），因此不符合构成要件。故选A。"},{"id":"pdn01307","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「复盘改进」是指数字化转型办公室通过分批次扩面而非一次铺开，使风险被限制在可控范围的工作机制。\n\n按照上述界定，下列情形可认定为「复盘改进」的是：","options":["数字化转型办公室在新工具推广中，试运行期间禁止任何修改，最终同类偏差在扩面后被成倍放大。","数字化转型办公室在新流程上线中，分批次扩面而非一次铺开，风险被限制在可控范围。","数字化转型办公室在新机制落地中，分批次扩面而非一次铺开，但同类偏差在扩面后被成倍放大。","由外部团队一次性交付即结束，后续也未按上述机制推进。"],"answer":1,"explanation":"「复盘改进」的构成要件为：①主体为数字化转型办公室；②通过分批次扩面而非一次铺开；③使风险被限制在可控范围。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01308","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「联勤联动」是指街道与职能站所通过一次会商形成分工清单，使处置效率整体提升的工作机制。\n\n根据上述定义，下列不属于「联勤联动」的是：","options":["街道与职能站所在信息通报共享中，一次会商形成分工清单，处置效率整体提升。","街道与职能站所在联合排班安排中，一次会商形成分工清单，处置效率整体提升。","街道与职能站所在跨界事项梳理中，一次会商形成分工清单，处置效率整体提升。","街道与职能站所在联合排班安排中，遇跨界事项互相等待，最终边界地带的问题仍在部门之间来回流转。"],"answer":3,"explanation":"「联勤联动」的构成要件为：①主体为街道与职能站所；②通过一次会商形成分工清单；③使处置效率整体提升。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（遇跨界事项互相等待），因此不符合构成要件。故选D。"},{"id":"pdn01309","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「精准匹配」是指就业服务窗口通过按对象条件分档配置资源，使资源不再平均摊薄的工作机制。\n\n依据上述定义，以下哪一项符合「精准匹配」的构成要件：","options":["由服务对象自行寻找渠道，后续也未按上述机制推进。","就业服务窗口在服务事项梳理中，按对象条件分档配置资源，资源不再平均摊薄。","就业服务窗口在服务清单编制中，按对象条件分档配置资源，但大量项目无人使用而真实诉求仍被搁置。","就业服务窗口在对象需求摸排中，沿用上一年清单不作修订，最终大量项目无人使用而真实诉求仍被搁置。"],"answer":1,"explanation":"「精准匹配」的构成要件为：①主体为就业服务窗口；②通过按对象条件分档配置资源；③使资源不再平均摊薄。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01310","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「可回溯核查」是指农产品质量检测站通过按批号串联台账与检验记录，使责任环节清晰可查的工作机制。\n\n按照上述界定，下列情形不应认定为「可回溯核查」的是：","options":["农产品质量检测站在储运环节温控中，按批号串联台账与检验记录，责任环节清晰可查。","农产品质量检测站在批次交接记录中，只在最终出库时记一笔总账，最终出现问题时无法定位到具体环节。","农产品质量检测站在批次交接记录中，按批号串联台账与检验记录，责任环节清晰可查。","农产品质量检测站在进货环节核验中，按批号串联台账与检验记录，责任环节清晰可查。"],"answer":1,"explanation":"「可回溯核查」的构成要件为：①主体为农产品质量检测站；②通过按批号串联台账与检验记录；③使责任环节清晰可查。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（只在最终出库时记一笔总账），因此不符合构成要件。故选B。"},{"id":"pdn01311","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「动态监测」是指湿地管护中心通过划分区块实行差异化管护，使核心栖息地得到有效避让的工作机制。\n\n根据上述定义，下列属于「动态监测」的是：","options":["湿地管护中心在栖息环境变化中，指标超标后仍不调整，最终指标已越界而措施仍维持不变。","湿地管护中心在监测指标波动中，划分区块实行差异化管护，核心栖息地得到有效避让。","由邻近地区照抄方案，后续也未按上述机制推进。","湿地管护中心在外来因素扩散中，划分区块实行差异化管护，但指标已越界而措施仍维持不变。"],"answer":1,"explanation":"「动态监测」的构成要件为：①主体为湿地管护中心；②通过划分区块实行差异化管护；③使核心栖息地得到有效避让。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01312","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「连续照护」是指乡镇卫生院通过建立电子档案并定期回访，使患者往返成本下降的工作机制。\n\n依据上述定义，以下哪一项不符合「连续照护」的构成要件：","options":["乡镇卫生院在康复跟踪记录中，建立电子档案并定期回访，患者往返成本下降。","乡镇卫生院在重点人群筛查中，建立电子档案并定期回访，患者往返成本下降。","乡镇卫生院在康复跟踪记录中，各机构各自重复开单，最终各环节彼此脱节、患者仍需多次重复排队。","乡镇卫生院在慢病随访安排中，建立电子档案并定期回访，患者往返成本下降。"],"answer":2,"explanation":"「连续照护」的构成要件为：①主体为乡镇卫生院；②通过建立电子档案并定期回访；③使患者往返成本下降。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（各机构各自重复开单），因此不符合构成要件。故选C。"},{"id":"pdn01313","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「协同会商」是指村委会通过提前公示并逐户征询意见，使平均处置周期缩短的工作机制。\n\n按照上述界定，下列情形可认定为「协同会商」的是：","options":["村委会在老旧小区改造中，提前公示并逐户征询意见，平均处置周期缩短。","由服务对象自行申报后不再跟进，后续也未按上述机制推进。","村委会在便民事项办理中，提前公示并逐户征询意见，但问题仍反复出现且未形成稳定机制。","村委会在邻里纠纷调解中，各口径分头办理、彼此不通气，最终问题仍反复出现且未形成稳定机制。"],"answer":0,"explanation":"「协同会商」的构成要件为：①主体为村委会；②通过提前公示并逐户征询意见；③使平均处置周期缩短。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01314","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「联合响应」是指跨部门工作专班通过一次会商形成分工清单，使处置效率整体提升的工作机制。\n\n根据上述定义，下列不属于「联合响应」的是：","options":["跨部门工作专班在联合排班安排中，一次会商形成分工清单，处置效率整体提升。","跨部门工作专班在联合排班安排中，各部门分头进场、结果互不通报，最终边界地带的问题仍在部门之间来回流转。","跨部门工作专班在信息通报共享中，一次会商形成分工清单，处置效率整体提升。","跨部门工作专班在跨界事项梳理中，一次会商形成分工清单，处置效率整体提升。"],"answer":1,"explanation":"「联合响应」的构成要件为：①主体为跨部门工作专班；②通过一次会商形成分工清单；③使处置效率整体提升。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（各部门分头进场、结果互不通报），因此不符合构成要件。故选B。"},{"id":"pdn01315","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「协同治理」是指跨部门工作专班通过共享信息并同步排班，使跨界问题不再悬空的工作机制。\n\n依据上述定义，以下哪一项符合「协同治理」的构成要件：","options":["跨部门工作专班在信息通报共享中，共享信息并同步排班，但边界地带的问题仍在部门之间来回流转。","跨部门工作专班在跨界事项梳理中，共享信息并同步排班，跨界问题不再悬空。","跨部门工作专班在联合排班安排中，只开会不落责任清单，最终边界地带的问题仍在部门之间来回流转。","由各区各自为政，后续也未按上述机制推进。"],"answer":1,"explanation":"「协同治理」的构成要件为：①主体为跨部门工作专班；②通过共享信息并同步排班；③使跨界问题不再悬空。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01316","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「协同治理」是指区级牵头部门通过一次会商形成分工清单，使处置效率整体提升的工作机制。\n\n按照上述界定，下列情形不应认定为「协同治理」的是：","options":["区级牵头部门在跨界事项梳理中，一次会商形成分工清单，处置效率整体提升。","区级牵头部门在联合排班安排中，一次会商形成分工清单，处置效率整体提升。","区级牵头部门在联合排班安排中，遇跨界事项互相等待，最终边界地带的问题仍在部门之间来回流转。","区级牵头部门在信息通报共享中，一次会商形成分工清单，处置效率整体提升。"],"answer":2,"explanation":"「协同治理」的构成要件为：①主体为区级牵头部门；②通过一次会商形成分工清单；③使处置效率整体提升。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（遇跨界事项互相等待），因此不符合构成要件。故选C。"},{"id":"pdn01317","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「按需配置」是指养老服务站点通过按对象条件分档配置资源，使冷门项目被及时替换的工作机制。\n\n根据上述定义，下列属于「按需配置」的是：","options":["养老服务站点在服务清单编制中，按对象条件分档配置资源，但大量项目无人使用而真实诉求仍被搁置。","由服务对象自行寻找渠道，后续也未按上述机制推进。","养老服务站点在服务事项梳理中，按对象条件分档配置资源，冷门项目被及时替换。","养老服务站点在对象需求摸排中，沿用上一年清单不作修订，最终大量项目无人使用而真实诉求仍被搁置。"],"answer":2,"explanation":"「按需配置」的构成要件为：①主体为养老服务站点；②通过按对象条件分档配置资源；③使冷门项目被及时替换。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01318","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「联勤联动」是指流域联席会议通过明确牵头与配合边界后统一行动，使跨界问题不再悬空的工作机制。\n\n依据上述定义，以下哪一项不符合「联勤联动」的构成要件：","options":["流域联席会议在联合排班安排中，各部门分头进场、结果互不通报，最终边界地带的问题仍在部门之间来回流转。","流域联席会议在信息通报共享中，明确牵头与配合边界后统一行动，跨界问题不再悬空。","流域联席会议在联合排班安排中，明确牵头与配合边界后统一行动，跨界问题不再悬空。","流域联席会议在跨界事项梳理中，明确牵头与配合边界后统一行动，跨界问题不再悬空。"],"answer":0,"explanation":"「联勤联动」的构成要件为：①主体为流域联席会议；②通过明确牵头与配合边界后统一行动；③使跨界问题不再悬空。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（各部门分头进场、结果互不通报），因此不符合构成要件。故选A。"},{"id":"pdn01319","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「灰度验证」是指改革推进专班通过每轮结束后复盘并修订下一轮，使方案随实际反馈逐步完善的工作机制。\n\n按照上述界定，下列情形可认定为「灰度验证」的是：","options":["改革推进专班在新工具推广中，试运行期间禁止任何修改，最终同类偏差在扩面后被成倍放大。","改革推进专班在新机制落地中，每轮结束后复盘并修订下一轮，但同类偏差在扩面后被成倍放大。","改革推进专班在新流程上线中，每轮结束后复盘并修订下一轮，方案随实际反馈逐步完善。","由外部团队一次性交付即结束，后续也未按上述机制推进。"],"answer":2,"explanation":"「灰度验证」的构成要件为：①主体为改革推进专班；②通过每轮结束后复盘并修订下一轮；③使方案随实际反馈逐步完善。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01320","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「循证施策」是指项目评审委员会通过对关键指标作独立复核，使结论不易被个别异常值带偏的工作机制。\n\n根据上述定义，下列不属于「循证施策」的是：","options":["项目评审委员会在年度计划编制中，对关键指标作独立复核，结论不易被个别异常值带偏。","项目评审委员会在政策效果评估中，以主观感受替代实测数据，最终结论无法由所引数据支撑。","项目评审委员会在政策效果评估中，对关键指标作独立复核，结论不易被个别异常值带偏。","项目评审委员会在抽样数据核查中，对关键指标作独立复核，结论不易被个别异常值带偏。"],"answer":1,"explanation":"「循证施策」的构成要件为：①主体为项目评审委员会；②通过对关键指标作独立复核；③使结论不易被个别异常值带偏。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（以主观感受替代实测数据），因此不符合构成要件。故选B。"},{"id":"pdn01321","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「精准匹配」是指农技推广站通过先摸清不同群体诉求再分类提供，使冷门项目被及时替换的工作机制。\n\n依据上述定义，以下哪一项符合「精准匹配」的构成要件：","options":["农技推广站在服务事项梳理中，先摸清不同群体诉求再分类提供，冷门项目被及时替换。","农技推广站在服务清单编制中，先摸清不同群体诉求再分类提供，但大量项目无人使用而真实诉求仍被搁置。","由服务对象自行寻找渠道，后续也未按上述机制推进。","农技推广站在对象需求摸排中，沿用上一年清单不作修订，最终大量项目无人使用而真实诉求仍被搁置。"],"answer":0,"explanation":"「精准匹配」的构成要件为：①主体为农技推广站；②通过先摸清不同群体诉求再分类提供；③使冷门项目被及时替换。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01322","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「最小必要采集」是指公共服务窗口通过按岗位授予最小可见范围，使敏感字段仅在授权场景可见的工作机制。\n\n按照上述界定，下列情形不应认定为「最小必要采集」的是：","options":["公共服务窗口在数据调阅留痕中，按岗位授予最小可见范围，敏感字段仅在授权场景可见。","公共服务窗口在字段权限配置中，为方便起见一次性收齐全部字段，最终与办理目的无关的字段仍被长期留存。","公共服务窗口在信息采集登记中，按岗位授予最小可见范围，敏感字段仅在授权场景可见。","公共服务窗口在字段权限配置中，按岗位授予最小可见范围，敏感字段仅在授权场景可见。"],"answer":1,"explanation":"「最小必要采集」的构成要件为：①主体为公共服务窗口；②通过按岗位授予最小可见范围；③使敏感字段仅在授权场景可见。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（为方便起见一次性收齐全部字段），因此不符合构成要件。故选B。"},{"id":"pdn01323","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「过程性考核」是指区域教研中心通过按阶段采集学情数据再修正教学，使后续目标更贴合实际起点的工作机制。\n\n根据上述定义，下列属于「过程性考核」的是：","options":["由家长自行报送成绩，后续也未按上述机制推进。","区域教研中心在单元教学设计中，按阶段采集学情数据再修正教学，后续目标更贴合实际起点。","区域教研中心在实验课程组织中，全程不作任何反馈、结束后才公布，最终教学安排并未因数据而作任何调整。","区域教研中心在作业反馈整理中，按阶段采集学情数据再修正教学，但教学安排并未因数据而作任何调整。"],"answer":1,"explanation":"「过程性考核」的构成要件为：①主体为区域教研中心；②通过按阶段采集学情数据再修正教学；③使后续目标更贴合实际起点。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01324","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「差异化供给」是指农技推广站通过依据使用频次动态增减项目，使冷门项目被及时替换的工作机制。\n\n依据上述定义，以下哪一项不符合「差异化供给」的构成要件：","options":["农技推广站在服务事项梳理中，依据使用频次动态增减项目，冷门项目被及时替换。","农技推广站在服务清单编制中，依据使用频次动态增减项目，冷门项目被及时替换。","农技推广站在对象需求摸排中，依据使用频次动态增减项目，冷门项目被及时替换。","农技推广站在对象需求摸排中，先采购再询问是否需要，最终大量项目无人使用而真实诉求仍被搁置。"],"answer":3,"explanation":"「差异化供给」的构成要件为：①主体为农技推广站；②通过依据使用频次动态增减项目；③使冷门项目被及时替换。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（先采购再询问是否需要），因此不符合构成要件。故选D。"},{"id":"pdn01325","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「前置筛查」是指家庭医生团队通过建立电子档案并定期回访，使病情变化能被尽早发现的工作机制。\n\n按照上述界定，下列情形可认定为「前置筛查」的是：","options":["由商业体检机构独立出具结论，后续也未按上述机制推进。","家庭医生团队在重点人群筛查中，建立电子档案并定期回访，但各环节彼此脱节、患者仍需多次重复排队。","家庭医生团队在慢病随访安排中，建立电子档案并定期回访，病情变化能被尽早发现。","家庭医生团队在康复跟踪记录中，待病情加重后再启动会诊，最终各环节彼此脱节、患者仍需多次重复排队。"],"answer":2,"explanation":"「前置筛查」的构成要件为：①主体为家庭医生团队；②通过建立电子档案并定期回访；③使病情变化能被尽早发现。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01326","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「全过程追溯」是指食品药品监管所通过按批号串联台账与检验记录，使问题批次能被快速定位的工作机制。\n\n根据上述定义，下列不属于「全过程追溯」的是：","options":["食品药品监管所在批次交接记录中，按批号串联台账与检验记录，问题批次能被快速定位。","食品药品监管所在储运环节温控中，按批号串联台账与检验记录，问题批次能被快速定位。","食品药品监管所在批次交接记录中，只在最终出库时记一笔总账，最终出现问题时无法定位到具体环节。","食品药品监管所在进货环节核验中，按批号串联台账与检验记录，问题批次能被快速定位。"],"answer":2,"explanation":"「全过程追溯」的构成要件为：①主体为食品药品监管所；②通过按批号串联台账与检验记录；③使问题批次能被快速定位。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（只在最终出库时记一笔总账），因此不符合构成要件。故选C。"},{"id":"pdn01327","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「双向转诊」是指乡镇卫生院通过建立电子档案并定期回访，使重复检查明显减少的工作机制。\n\n依据上述定义，以下哪一项符合「双向转诊」的构成要件：","options":["乡镇卫生院在重点人群筛查中，建立电子档案并定期回访，但各环节彼此脱节、患者仍需多次重复排队。","乡镇卫生院在康复跟踪记录中，只做一次性检查不作后续跟踪，最终各环节彼此脱节、患者仍需多次重复排队。","乡镇卫生院在慢病随访安排中，建立电子档案并定期回访，重复检查明显减少。","仅由三甲医院单方建档，后续也未按上述机制推进。"],"answer":2,"explanation":"「双向转诊」的构成要件为：①主体为乡镇卫生院；②通过建立电子档案并定期回访；③使重复检查明显减少。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01328","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「增值评价」是指任课教师团队通过结合真实任务表现打分，使学习过程而非仅结果被看见的工作机制。\n\n按照上述界定，下列情形不应认定为「增值评价」的是：","options":["任课教师团队在单元教学设计中，结合真实任务表现打分，学习过程而非仅结果被看见。","任课教师团队在实验课程组织中，照搬统一答案不看作答过程，最终教学安排并未因数据而作任何调整。","任课教师团队在作业反馈整理中，结合真实任务表现打分，学习过程而非仅结果被看见。","任课教师团队在实验课程组织中，结合真实任务表现打分，学习过程而非仅结果被看见。"],"answer":1,"explanation":"「增值评价」的构成要件为：①主体为任课教师团队；②通过结合真实任务表现打分；③使学习过程而非仅结果被看见。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（照搬统一答案不看作答过程），因此不符合构成要件。故选B。"},{"id":"pdn01329","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「适应性管理」是指流域管理机构通过随季节数据滚动修订方案，使管控成本保持在合理区间的工作机制。\n\n根据上述定义，下列属于「适应性管理」的是：","options":["流域管理机构在栖息环境变化中，等出现明显损害后再启动处置，最终指标已越界而措施仍维持不变。","流域管理机构在监测指标波动中，随季节数据滚动修订方案，管控成本保持在合理区间。","由游客反馈临时决定，后续也未按上述机制推进。","流域管理机构在外来因素扩散中，随季节数据滚动修订方案，但指标已越界而措施仍维持不变。"],"answer":1,"explanation":"「适应性管理」的构成要件为：①主体为流域管理机构；②通过随季节数据滚动修订方案；③使管控成本保持在合理区间。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01330","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「连续照护」是指社区卫生服务中心通过建立电子档案并定期回访，使轻症在基层得到及时处置的工作机制。\n\n依据上述定义，以下哪一项不符合「连续照护」的构成要件：","options":["社区卫生服务中心在康复跟踪记录中，一律先安排住院再评估，最终各环节彼此脱节、患者仍需多次重复排队。","社区卫生服务中心在慢病随访安排中，建立电子档案并定期回访，轻症在基层得到及时处置。","社区卫生服务中心在重点人群筛查中，建立电子档案并定期回访，轻症在基层得到及时处置。","社区卫生服务中心在康复跟踪记录中，建立电子档案并定期回访，轻症在基层得到及时处置。"],"answer":0,"explanation":"「连续照护」的构成要件为：①主体为社区卫生服务中心；②通过建立电子档案并定期回访；③使轻症在基层得到及时处置。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（一律先安排住院再评估），因此不符合构成要件。故选A。"},{"id":"pdn01331","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「跨界协作」是指跨部门工作专班通过明确牵头与配合边界后统一行动，使响应口径保持一致的工作机制。\n\n按照上述界定，下列情形可认定为「跨界协作」的是：","options":["跨部门工作专班在跨界事项梳理中，明确牵头与配合边界后统一行动，响应口径保持一致。","跨部门工作专班在联合排班安排中，只开会不落责任清单，最终边界地带的问题仍在部门之间来回流转。","由各区各自为政，后续也未按上述机制推进。","跨部门工作专班在信息通报共享中，明确牵头与配合边界后统一行动，但边界地带的问题仍在部门之间来回流转。"],"answer":0,"explanation":"「跨界协作」的构成要件为：①主体为跨部门工作专班；②通过明确牵头与配合边界后统一行动；③使响应口径保持一致。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01332","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「表现性评价」是指课程组通过随堂记录并及时反馈调整，使教学策略得以动态优化的工作机制。\n\n根据上述定义，下列不属于「表现性评价」的是：","options":["课程组在单元教学设计中，随堂记录并及时反馈调整，教学策略得以动态优化。","课程组在实验课程组织中，随堂记录并及时反馈调整，教学策略得以动态优化。","课程组在作业反馈整理中，随堂记录并及时反馈调整，教学策略得以动态优化。","课程组在实验课程组织中，照搬统一答案不看作答过程，最终教学安排并未因数据而作任何调整。"],"answer":3,"explanation":"「表现性评价」的构成要件为：①主体为课程组；②通过随堂记录并及时反馈调整；③使教学策略得以动态优化。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（照搬统一答案不看作答过程），因此不符合构成要件。故选D。"},{"id":"pdn01333","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「基线比对」是指项目评审委员会通过以多源数据交叉校验结论，使结论不易被个别异常值带偏的工作机制。\n\n依据上述定义，以下哪一项符合「基线比对」的构成要件：","options":["项目评审委员会在年度计划编制中，以多源数据交叉校验结论，结论不易被个别异常值带偏。","由第三方直接给结论不附依据，后续也未按上述机制推进。","项目评审委员会在抽样数据核查中，以多源数据交叉校验结论，但结论无法由所引数据支撑。","项目评审委员会在政策效果评估中，指标口径中途变更却不说明，最终结论无法由所引数据支撑。"],"answer":0,"explanation":"「基线比对」的构成要件为：①主体为项目评审委员会；②通过以多源数据交叉校验结论；③使结论不易被个别异常值带偏。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01334","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「全过程追溯」是指食品药品监管所通过每一节点登记并关联上下游凭证，使召回范围精确到具体批次的工作机制。\n\n按照上述界定，下列情形不应认定为「全过程追溯」的是：","options":["食品药品监管所在批次交接记录中，只在最终出库时记一笔总账，最终出现问题时无法定位到具体环节。","食品药品监管所在储运环节温控中，每一节点登记并关联上下游凭证，召回范围精确到具体批次。","食品药品监管所在批次交接记录中，每一节点登记并关联上下游凭证，召回范围精确到具体批次。","食品药品监管所在进货环节核验中，每一节点登记并关联上下游凭证，召回范围精确到具体批次。"],"answer":0,"explanation":"「全过程追溯」的构成要件为：①主体为食品药品监管所；②通过每一节点登记并关联上下游凭证；③使召回范围精确到具体批次。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（只在最终出库时记一笔总账），因此不符合构成要件。故选A。"},{"id":"pdn01335","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「阈值预警」是指自然保护区管理局通过随季节数据滚动修订方案，使干预强度与实际风险相匹配的工作机制。\n\n根据上述定义，下列属于「阈值预警」的是：","options":["自然保护区管理局在栖息环境变化中，指标超标后仍不调整，最终指标已越界而措施仍维持不变。","自然保护区管理局在监测指标波动中，随季节数据滚动修订方案，干预强度与实际风险相匹配。","自然保护区管理局在外来因素扩散中，随季节数据滚动修订方案，但指标已越界而措施仍维持不变。","由邻近地区照抄方案，后续也未按上述机制推进。"],"answer":1,"explanation":"「阈值预警」的构成要件为：①主体为自然保护区管理局；②通过随季节数据滚动修订方案；③使干预强度与实际风险相匹配。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01336","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「跨界协作」是指区级牵头部门通过建立常态化联络与移交规则，使重复检查与推诿明显减少的工作机制。\n\n依据上述定义，以下哪一项不符合「跨界协作」的构成要件：","options":["区级牵头部门在联合排班安排中，遇跨界事项互相等待，最终边界地带的问题仍在部门之间来回流转。","区级牵头部门在联合排班安排中，建立常态化联络与移交规则，重复检查与推诿明显减少。","区级牵头部门在信息通报共享中，建立常态化联络与移交规则，重复检查与推诿明显减少。","区级牵头部门在跨界事项梳理中，建立常态化联络与移交规则，重复检查与推诿明显减少。"],"answer":0,"explanation":"「跨界协作」的构成要件为：①主体为区级牵头部门；②通过建立常态化联络与移交规则；③使重复检查与推诿明显减少。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（遇跨界事项互相等待），因此不符合构成要件。故选A。"},{"id":"pdn01337","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「协同治理」是指跨部门工作专班通过建立常态化联络与移交规则，使处置效率整体提升的工作机制。\n\n按照上述界定，下列情形可认定为「协同治理」的是：","options":["跨部门工作专班在联合排班安排中，各自按本部门旧流程办理，最终边界地带的问题仍在部门之间来回流转。","由上级部门包办到底，后续也未按上述机制推进。","跨部门工作专班在信息通报共享中，建立常态化联络与移交规则，但边界地带的问题仍在部门之间来回流转。","跨部门工作专班在跨界事项梳理中，建立常态化联络与移交规则，处置效率整体提升。"],"answer":3,"explanation":"「协同治理」的构成要件为：①主体为跨部门工作专班；②通过建立常态化联络与移交规则；③使处置效率整体提升。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01338","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「闭环处置」是指街道办通过建立台账逐项限时销号，使重复投诉明显下降的工作机制。\n\n根据上述定义，下列不属于「闭环处置」的是：","options":["街道办在便民事项办理中，建立台账逐项限时销号，重复投诉明显下降。","街道办在老旧小区改造中，建立台账逐项限时销号，重复投诉明显下降。","街道办在邻里纠纷调解中，建立台账逐项限时销号，重复投诉明显下降。","街道办在邻里纠纷调解中，直接照搬既有方案、未作任何征询，最终问题仍反复出现且未形成稳定机制。"],"answer":3,"explanation":"「闭环处置」的构成要件为：①主体为街道办；②通过建立台账逐项限时销号；③使重复投诉明显下降。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（直接照搬既有方案、未作任何征询），因此不符合构成要件。故选D。"},{"id":"pdn01339","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「表现性评价」是指学校教研组通过先摸清起点再设定分层目标，使后续目标更贴合实际起点的工作机制。\n\n依据上述定义，以下哪一项符合「表现性评价」的构成要件：","options":["学校教研组在实验课程组织中，全程不作任何反馈、结束后才公布，最终教学安排并未因数据而作任何调整。","由家长自行报送成绩，后续也未按上述机制推进。","学校教研组在单元教学设计中，先摸清起点再设定分层目标，后续目标更贴合实际起点。","学校教研组在作业反馈整理中，先摸清起点再设定分层目标，但教学安排并未因数据而作任何调整。"],"answer":2,"explanation":"「表现性评价」的构成要件为：①主体为学校教研组；②通过先摸清起点再设定分层目标；③使后续目标更贴合实际起点。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01340","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「分区管控」是指生态环境监测站通过按监测指标分档调整措施，使异常苗头被尽早识别的工作机制。\n\n按照上述界定，下列情形不应认定为「分区管控」的是：","options":["生态环境监测站在监测指标波动中，按监测指标分档调整措施，异常苗头被尽早识别。","生态环境监测站在栖息环境变化中，只看年度均值忽略峰值，最终指标已越界而措施仍维持不变。","生态环境监测站在栖息环境变化中，按监测指标分档调整措施，异常苗头被尽早识别。","生态环境监测站在外来因素扩散中，按监测指标分档调整措施，异常苗头被尽早识别。"],"answer":1,"explanation":"「分区管控」的构成要件为：①主体为生态环境监测站；②通过按监测指标分档调整措施；③使异常苗头被尽早识别。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（只看年度均值忽略峰值），因此不符合构成要件。故选B。"},{"id":"pdn01341","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「留存限期」是指医院信息科通过到期自动清理并留清理记录，使共享环节不泄露可识别信息的工作机制。\n\n根据上述定义，下列属于「留存限期」的是：","options":["医院信息科在数据调阅留痕中，到期自动清理并留清理记录，但与办理目的无关的字段仍被长期留存。","医院信息科在字段权限配置中，超过期限仍不作清理，最终与办理目的无关的字段仍被长期留存。","由系统默认长期全量保留，后续也未按上述机制推进。","医院信息科在信息采集登记中，到期自动清理并留清理记录，共享环节不泄露可识别信息。"],"answer":3,"explanation":"「留存限期」的构成要件为：①主体为医院信息科；②通过到期自动清理并留清理记录；③使共享环节不泄露可识别信息。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01342","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「按需配置」是指养老服务站点通过依据使用频次动态增减项目，使不同群体各取所需的工作机制。\n\n依据上述定义，以下哪一项不符合「按需配置」的构成要件：","options":["养老服务站点在服务事项梳理中，依据使用频次动态增减项目，不同群体各取所需。","养老服务站点在对象需求摸排中，依据使用频次动态增减项目，不同群体各取所需。","养老服务站点在服务清单编制中，依据使用频次动态增减项目，不同群体各取所需。","养老服务站点在对象需求摸排中，所有对象发放完全相同的固定包，最终大量项目无人使用而真实诉求仍被搁置。"],"answer":3,"explanation":"「按需配置」的构成要件为：①主体为养老服务站点；②通过依据使用频次动态增减项目；③使不同群体各取所需。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（所有对象发放完全相同的固定包），因此不符合构成要件。故选D。"},{"id":"pdn01343","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「联勤联动」是指区级牵头部门通过共享信息并同步排班，使处置效率整体提升的工作机制。\n\n按照上述界定，下列情形可认定为「联勤联动」的是：","options":["区级牵头部门在信息通报共享中，共享信息并同步排班，但边界地带的问题仍在部门之间来回流转。","区级牵头部门在联合排班安排中，只开会不落责任清单，最终边界地带的问题仍在部门之间来回流转。","由各区各自为政，后续也未按上述机制推进。","区级牵头部门在跨界事项梳理中，共享信息并同步排班，处置效率整体提升。"],"answer":3,"explanation":"「联勤联动」的构成要件为：①主体为区级牵头部门；②通过共享信息并同步排班；③使处置效率整体提升。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01344","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「差异化供给」是指公共文化服务中心通过依据使用频次动态增减项目，使资源不再平均摊薄的工作机制。\n\n根据上述定义，下列不属于「差异化供给」的是：","options":["公共文化服务中心在对象需求摸排中，先采购再询问是否需要，最终大量项目无人使用而真实诉求仍被搁置。","公共文化服务中心在服务清单编制中，依据使用频次动态增减项目，资源不再平均摊薄。","公共文化服务中心在对象需求摸排中，依据使用频次动态增减项目，资源不再平均摊薄。","公共文化服务中心在服务事项梳理中，依据使用频次动态增减项目，资源不再平均摊薄。"],"answer":0,"explanation":"「差异化供给」的构成要件为：①主体为公共文化服务中心；②通过依据使用频次动态增减项目；③使资源不再平均摊薄。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（先采购再询问是否需要），因此不符合构成要件。故选A。"},{"id":"pdn01345","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「基线比对」是指统计调查队通过先确立基线再对照前后变化，使结论不易被个别异常值带偏的工作机制。\n\n依据上述定义，以下哪一项符合「基线比对」的构成要件：","options":["统计调查队在政策效果评估中，指标口径中途变更却不说明，最终结论无法由所引数据支撑。","统计调查队在年度计划编制中，先确立基线再对照前后变化，结论不易被个别异常值带偏。","由第三方直接给结论不附依据，后续也未按上述机制推进。","统计调查队在抽样数据核查中，先确立基线再对照前后变化，但结论无法由所引数据支撑。"],"answer":1,"explanation":"「基线比对」的构成要件为：①主体为统计调查队；②通过先确立基线再对照前后变化；③使结论不易被个别异常值带偏。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01346","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「复盘改进」是指数字化转型办公室通过设置观察期并保留回退通道，使方案随实际反馈逐步完善的工作机制。\n\n按照上述界定，下列情形不应认定为「复盘改进」的是：","options":["数字化转型办公室在新机制落地中，设置观察期并保留回退通道，方案随实际反馈逐步完善。","数字化转型办公室在新工具推广中，不经试点直接全面强制推开，最终同类偏差在扩面后被成倍放大。","数字化转型办公室在新流程上线中，设置观察期并保留回退通道，方案随实际反馈逐步完善。","数字化转型办公室在新工具推广中，设置观察期并保留回退通道，方案随实际反馈逐步完善。"],"answer":1,"explanation":"「复盘改进」的构成要件为：①主体为数字化转型办公室；②通过设置观察期并保留回退通道；③使方案随实际反馈逐步完善。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（不经试点直接全面强制推开），因此不符合构成要件。故选B。"},{"id":"pdn01347","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「分区管控」是指自然保护区管理局通过按监测指标分档调整措施，使干预强度与实际风险相匹配的工作机制。\n\n根据上述定义，下列属于「分区管控」的是：","options":["自然保护区管理局在监测指标波动中，按监测指标分档调整措施，干预强度与实际风险相匹配。","自然保护区管理局在栖息环境变化中，指标超标后仍不调整，最终指标已越界而措施仍维持不变。","自然保护区管理局在外来因素扩散中，按监测指标分档调整措施，但指标已越界而措施仍维持不变。","由邻近地区照抄方案，后续也未按上述机制推进。"],"answer":0,"explanation":"「分区管控」的构成要件为：①主体为自然保护区管理局；②通过按监测指标分档调整措施；③使干预强度与实际风险相匹配。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01348","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「协同会商」是指街道办通过建立台账逐项限时销号，使重复投诉明显下降的工作机制。\n\n依据上述定义，以下哪一项不符合「协同会商」的构成要件：","options":["街道办在邻里纠纷调解中，建立台账逐项限时销号，重复投诉明显下降。","街道办在便民事项办理中，建立台账逐项限时销号，重复投诉明显下降。","街道办在邻里纠纷调解中，只在事后补录台账，最终问题仍反复出现且未形成稳定机制。","街道办在老旧小区改造中，建立台账逐项限时销号，重复投诉明显下降。"],"answer":2,"explanation":"「协同会商」的构成要件为：①主体为街道办；②通过建立台账逐项限时销号；③使重复投诉明显下降。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（只在事后补录台账），因此不符合构成要件。故选C。"},{"id":"pdn01349","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「双向转诊」是指社区卫生服务中心通过与上级医院共享检查结果，使病情变化能被尽早发现的工作机制。\n\n按照上述界定，下列情形可认定为「双向转诊」的是：","options":["社区卫生服务中心在慢病随访安排中，与上级医院共享检查结果，病情变化能被尽早发现。","社区卫生服务中心在康复跟踪记录中，待病情加重后再启动会诊，最终各环节彼此脱节、患者仍需多次重复排队。","社区卫生服务中心在重点人群筛查中，与上级医院共享检查结果，但各环节彼此脱节、患者仍需多次重复排队。","由商业体检机构独立出具结论，后续也未按上述机制推进。"],"answer":0,"explanation":"「双向转诊」的构成要件为：①主体为社区卫生服务中心；②通过与上级医院共享检查结果；③使病情变化能被尽早发现。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01350","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「前置筛查」是指社区卫生服务中心通过与上级医院共享检查结果，使重复检查明显减少的工作机制。\n\n根据上述定义，下列不属于「前置筛查」的是：","options":["社区卫生服务中心在慢病随访安排中，与上级医院共享检查结果，重复检查明显减少。","社区卫生服务中心在康复跟踪记录中，与上级医院共享检查结果，重复检查明显减少。","社区卫生服务中心在康复跟踪记录中，一律先安排住院再评估，最终各环节彼此脱节、患者仍需多次重复排队。","社区卫生服务中心在重点人群筛查中，与上级医院共享检查结果，重复检查明显减少。"],"answer":2,"explanation":"「前置筛查」的构成要件为：①主体为社区卫生服务中心；②通过与上级医院共享检查结果；③使重复检查明显减少。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（一律先安排住院再评估），因此不符合构成要件。故选C。"},{"id":"pdn01351","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「分级诊疗」是指乡镇卫生院通过先由基层评估再决定是否上转，使病情变化能被尽早发现的工作机制。\n\n依据上述定义，以下哪一项符合「分级诊疗」的构成要件：","options":["乡镇卫生院在康复跟踪记录中，只做一次性检查不作后续跟踪，最终各环节彼此脱节、患者仍需多次重复排队。","乡镇卫生院在慢病随访安排中，先由基层评估再决定是否上转，病情变化能被尽早发现。","仅由三甲医院单方建档，后续也未按上述机制推进。","乡镇卫生院在重点人群筛查中，先由基层评估再决定是否上转，但各环节彼此脱节、患者仍需多次重复排队。"],"answer":1,"explanation":"「分级诊疗」的构成要件为：①主体为乡镇卫生院；②通过先由基层评估再决定是否上转；③使病情变化能被尽早发现。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01352","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「前置筛查」是指社区卫生服务中心通过按病情轻重分流并约定转诊路径，使轻症在基层得到及时处置的工作机制。\n\n按照上述界定，下列情形不应认定为「前置筛查」的是：","options":["社区卫生服务中心在重点人群筛查中，按病情轻重分流并约定转诊路径，轻症在基层得到及时处置。","社区卫生服务中心在慢病随访安排中，按病情轻重分流并约定转诊路径，轻症在基层得到及时处置。","社区卫生服务中心在康复跟踪记录中，各机构各自重复开单，最终各环节彼此脱节、患者仍需多次重复排队。","社区卫生服务中心在康复跟踪记录中，按病情轻重分流并约定转诊路径，轻症在基层得到及时处置。"],"answer":2,"explanation":"「前置筛查」的构成要件为：①主体为社区卫生服务中心；②通过按病情轻重分流并约定转诊路径；③使轻症在基层得到及时处置。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（各机构各自重复开单），因此不符合构成要件。故选C。"},{"id":"pdn01353","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「证据本位决策」是指项目评审委员会通过对关键指标作独立复核，使成效与措施之间的对应更清楚的工作机制。\n\n根据上述定义，下列属于「证据本位决策」的是：","options":["项目评审委员会在政策效果评估中，指标口径中途变更却不说明，最终结论无法由所引数据支撑。","由第三方直接给结论不附依据，后续也未按上述机制推进。","项目评审委员会在抽样数据核查中，对关键指标作独立复核，但结论无法由所引数据支撑。","项目评审委员会在年度计划编制中，对关键指标作独立复核，成效与措施之间的对应更清楚。"],"answer":3,"explanation":"「证据本位决策」的构成要件为：①主体为项目评审委员会；②通过对关键指标作独立复核；③使成效与措施之间的对应更清楚。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01354","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「容错纠偏」是指政策试点工作组通过先在小范围试运行再按反馈调整，使风险被限制在可控范围的工作机制。\n\n依据上述定义，以下哪一项不符合「容错纠偏」的构成要件：","options":["政策试点工作组在新流程上线中，先在小范围试运行再按反馈调整，风险被限制在可控范围。","政策试点工作组在新工具推广中，先在小范围试运行再按反馈调整，风险被限制在可控范围。","政策试点工作组在新工具推广中，不经试点直接全面强制推开，最终同类偏差在扩面后被成倍放大。","政策试点工作组在新机制落地中，先在小范围试运行再按反馈调整，风险被限制在可控范围。"],"answer":2,"explanation":"「容错纠偏」的构成要件为：①主体为政策试点工作组；②通过先在小范围试运行再按反馈调整；③使风险被限制在可控范围。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（不经试点直接全面强制推开），因此不符合构成要件。故选C。"},{"id":"pdn01355","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「双向转诊」是指乡镇卫生院通过按病情轻重分流并约定转诊路径，使重复检查明显减少的工作机制。\n\n按照上述界定，下列情形可认定为「双向转诊」的是：","options":["乡镇卫生院在慢病随访安排中，按病情轻重分流并约定转诊路径，重复检查明显减少。","仅由三甲医院单方建档，后续也未按上述机制推进。","乡镇卫生院在康复跟踪记录中，只做一次性检查不作后续跟踪，最终各环节彼此脱节、患者仍需多次重复排队。","乡镇卫生院在重点人群筛查中，按病情轻重分流并约定转诊路径，但各环节彼此脱节、患者仍需多次重复排队。"],"answer":0,"explanation":"「双向转诊」的构成要件为：①主体为乡镇卫生院；②通过按病情轻重分流并约定转诊路径；③使重复检查明显减少。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01356","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「风险前置」是指数据中心运维组通过识别薄弱环节并预先加固，使人员与物资提前就位的工作机制。\n\n根据上述定义，下列不属于「风险前置」的是：","options":["数据中心运维组在关键节点值守中，识别薄弱环节并预先加固，人员与物资提前就位。","数据中心运维组在响应动作预置中，预案长期封存不随风险更新，最终异常发生时无预设动作可依。","数据中心运维组在响应动作预置中，识别薄弱环节并预先加固，人员与物资提前就位。","数据中心运维组在风险等级研判中，识别薄弱环节并预先加固，人员与物资提前就位。"],"answer":1,"explanation":"「风险前置」的构成要件为：①主体为数据中心运维组；②通过识别薄弱环节并预先加固；③使人员与物资提前就位。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（预案长期封存不随风险更新），因此不符合构成要件。故选B。"},{"id":"pdn01357","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「最小必要采集」是指公共服务窗口通过按岗位授予最小可见范围，使历史数据不再无限期堆积的工作机制。\n\n依据上述定义，以下哪一项符合「最小必要采集」的构成要件：","options":["公共服务窗口在信息采集登记中，按岗位授予最小可见范围，历史数据不再无限期堆积。","公共服务窗口在数据调阅留痕中，按岗位授予最小可见范围，但与办理目的无关的字段仍被长期留存。","由系统默认长期全量保留，后续也未按上述机制推进。","公共服务窗口在字段权限配置中，超过期限仍不作清理，最终与办理目的无关的字段仍被长期留存。"],"answer":0,"explanation":"「最小必要采集」的构成要件为：①主体为公共服务窗口；②通过按岗位授予最小可见范围；③使历史数据不再无限期堆积。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01358","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「跨界协作」是指区级牵头部门通过共享信息并同步排班，使处置效率整体提升的工作机制。\n\n按照上述界定，下列情形不应认定为「跨界协作」的是：","options":["区级牵头部门在信息通报共享中，共享信息并同步排班，处置效率整体提升。","区级牵头部门在联合排班安排中，共享信息并同步排班，处置效率整体提升。","区级牵头部门在联合排班安排中，各部门分头进场、结果互不通报，最终边界地带的问题仍在部门之间来回流转。","区级牵头部门在跨界事项梳理中，共享信息并同步排班，处置效率整体提升。"],"answer":2,"explanation":"「跨界协作」的构成要件为：①主体为区级牵头部门；②通过共享信息并同步排班；③使处置效率整体提升。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（各部门分头进场、结果互不通报），因此不符合构成要件。故选C。"},{"id":"pdn01359","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「弹性调控」是指生态环境监测站通过划分区块实行差异化管护，使异常苗头被尽早识别的工作机制。\n\n根据上述定义，下列属于「弹性调控」的是：","options":["生态环境监测站在外来因素扩散中，划分区块实行差异化管护，但指标已越界而措施仍维持不变。","生态环境监测站在栖息环境变化中，指标超标后仍不调整，最终指标已越界而措施仍维持不变。","由邻近地区照抄方案，后续也未按上述机制推进。","生态环境监测站在监测指标波动中，划分区块实行差异化管护，异常苗头被尽早识别。"],"answer":3,"explanation":"「弹性调控」的构成要件为：①主体为生态环境监测站；②通过划分区块实行差异化管护；③使异常苗头被尽早识别。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01360","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「菜单式服务」是指公共文化服务中心通过按对象条件分档配置资源，使冷门项目被及时替换的工作机制。\n\n依据上述定义，以下哪一项不符合「菜单式服务」的构成要件：","options":["公共文化服务中心在服务事项梳理中，按对象条件分档配置资源，冷门项目被及时替换。","公共文化服务中心在对象需求摸排中，按对象条件分档配置资源，冷门项目被及时替换。","公共文化服务中心在对象需求摸排中，先采购再询问是否需要，最终大量项目无人使用而真实诉求仍被搁置。","公共文化服务中心在服务清单编制中，按对象条件分档配置资源，冷门项目被及时替换。"],"answer":2,"explanation":"「菜单式服务」的构成要件为：①主体为公共文化服务中心；②通过按对象条件分档配置资源；③使冷门项目被及时替换。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（先采购再询问是否需要），因此不符合构成要件。故选C。"},{"id":"pdn01361","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「闭环处置」是指乡镇便民中心通过依托网格员常态化走访摸排，使诉求在前端得到化解的工作机制。\n\n按照上述界定，下列情形可认定为「闭环处置」的是：","options":["由服务对象自行申报后不再跟进，后续也未按上述机制推进。","乡镇便民中心在邻里纠纷调解中，各口径分头办理、彼此不通气，最终问题仍反复出现且未形成稳定机制。","乡镇便民中心在老旧小区改造中，依托网格员常态化走访摸排，诉求在前端得到化解。","乡镇便民中心在便民事项办理中，依托网格员常态化走访摸排，但问题仍反复出现且未形成稳定机制。"],"answer":2,"explanation":"「闭环处置」的构成要件为：①主体为乡镇便民中心；②通过依托网格员常态化走访摸排；③使诉求在前端得到化解。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01362","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「预案触发」是指应急指挥中心通过按风险等级预置响应动作，使次生影响被压到最小的工作机制。\n\n根据上述定义，下列不属于「预案触发」的是：","options":["应急指挥中心在响应动作预置中，等指标越限后才临时研究方案，最终异常发生时无预设动作可依。","应急指挥中心在风险等级研判中，按风险等级预置响应动作，次生影响被压到最小。","应急指挥中心在关键节点值守中，按风险等级预置响应动作，次生影响被压到最小。","应急指挥中心在响应动作预置中，按风险等级预置响应动作，次生影响被压到最小。"],"answer":0,"explanation":"「预案触发」的构成要件为：①主体为应急指挥中心；②通过按风险等级预置响应动作；③使次生影响被压到最小。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（等指标越限后才临时研究方案），因此不符合构成要件。故选A。"},{"id":"pdn01363","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「跨界协作」是指流域联席会议通过一次会商形成分工清单，使响应口径保持一致的工作机制。\n\n依据上述定义，以下哪一项符合「跨界协作」的构成要件：","options":["流域联席会议在跨界事项梳理中，一次会商形成分工清单，响应口径保持一致。","流域联席会议在信息通报共享中，一次会商形成分工清单，但边界地带的问题仍在部门之间来回流转。","流域联席会议在联合排班安排中，只开会不落责任清单，最终边界地带的问题仍在部门之间来回流转。","由各区各自为政，后续也未按上述机制推进。"],"answer":0,"explanation":"「跨界协作」的构成要件为：①主体为流域联席会议；②通过一次会商形成分工清单；③使响应口径保持一致。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01364","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「联勤联动」是指区级牵头部门通过一次会商形成分工清单，使重复检查与推诿明显减少的工作机制。\n\n按照上述界定，下列情形不应认定为「联勤联动」的是：","options":["区级牵头部门在联合排班安排中，一次会商形成分工清单，重复检查与推诿明显减少。","区级牵头部门在联合排班安排中，遇跨界事项互相等待，最终边界地带的问题仍在部门之间来回流转。","区级牵头部门在信息通报共享中，一次会商形成分工清单，重复检查与推诿明显减少。","区级牵头部门在跨界事项梳理中，一次会商形成分工清单，重复检查与推诿明显减少。"],"answer":1,"explanation":"「联勤联动」的构成要件为：①主体为区级牵头部门；②通过一次会商形成分工清单；③使重复检查与推诿明显减少。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（遇跨界事项互相等待），因此不符合构成要件。故选B。"},{"id":"pdn01365","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「菜单式服务」是指就业服务窗口通过依据使用频次动态增减项目，使资源不再平均摊薄的工作机制。\n\n根据上述定义，下列属于「菜单式服务」的是：","options":["就业服务窗口在服务清单编制中，依据使用频次动态增减项目，但大量项目无人使用而真实诉求仍被搁置。","就业服务窗口在服务事项梳理中，依据使用频次动态增减项目，资源不再平均摊薄。","由服务对象自行寻找渠道，后续也未按上述机制推进。","就业服务窗口在对象需求摸排中，沿用上一年清单不作修订，最终大量项目无人使用而真实诉求仍被搁置。"],"answer":1,"explanation":"「菜单式服务」的构成要件为：①主体为就业服务窗口；②通过依据使用频次动态增减项目；③使资源不再平均摊薄。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01366","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「预案触发」是指数据中心运维组通过关键节点保留备用通道，使险情初起即进入有序处置的工作机制。\n\n依据上述定义，以下哪一项不符合「预案触发」的构成要件：","options":["数据中心运维组在响应动作预置中，关键节点保留备用通道，险情初起即进入有序处置。","数据中心运维组在响应动作预置中，等指标越限后才临时研究方案，最终异常发生时无预设动作可依。","数据中心运维组在关键节点值守中，关键节点保留备用通道，险情初起即进入有序处置。","数据中心运维组在风险等级研判中，关键节点保留备用通道，险情初起即进入有序处置。"],"answer":1,"explanation":"「预案触发」的构成要件为：①主体为数据中心运维组；②通过关键节点保留备用通道；③使险情初起即进入有序处置。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（等指标越限后才临时研究方案），因此不符合构成要件。故选B。"},{"id":"pdn01367","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「协同治理」是指流域联席会议通过建立常态化联络与移交规则，使重复检查与推诿明显减少的工作机制。\n\n按照上述界定，下列情形可认定为「协同治理」的是：","options":["流域联席会议在信息通报共享中，建立常态化联络与移交规则，但边界地带的问题仍在部门之间来回流转。","流域联席会议在联合排班安排中，只开会不落责任清单，最终边界地带的问题仍在部门之间来回流转。","流域联席会议在跨界事项梳理中，建立常态化联络与移交规则，重复检查与推诿明显减少。","由各区各自为政，后续也未按上述机制推进。"],"answer":2,"explanation":"「协同治理」的构成要件为：①主体为流域联席会议；②通过建立常态化联络与移交规则；③使重复检查与推诿明显减少。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01368","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「过程性考核」是指课程组通过随堂记录并及时反馈调整，使教学策略得以动态优化的工作机制。\n\n根据上述定义，下列不属于「过程性考核」的是：","options":["课程组在作业反馈整理中，随堂记录并及时反馈调整，教学策略得以动态优化。","课程组在实验课程组织中，照搬统一答案不看作答过程，最终教学安排并未因数据而作任何调整。","课程组在实验课程组织中，随堂记录并及时反馈调整，教学策略得以动态优化。","课程组在单元教学设计中，随堂记录并及时反馈调整，教学策略得以动态优化。"],"answer":1,"explanation":"「过程性考核」的构成要件为：①主体为课程组；②通过随堂记录并及时反馈调整；③使教学策略得以动态优化。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（照搬统一答案不看作答过程），因此不符合构成要件。故选B。"},{"id":"pdn01369","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「基线比对」是指规划编制组通过对关键指标作独立复核，使结论不易被个别异常值带偏的工作机制。\n\n依据上述定义，以下哪一项符合「基线比对」的构成要件：","options":["规划编制组在年度计划编制中，对关键指标作独立复核，结论不易被个别异常值带偏。","由第三方直接给结论不附依据，后续也未按上述机制推进。","规划编制组在政策效果评估中，指标口径中途变更却不说明，最终结论无法由所引数据支撑。","规划编制组在抽样数据核查中，对关键指标作独立复核，但结论无法由所引数据支撑。"],"answer":0,"explanation":"「基线比对」的构成要件为：①主体为规划编制组；②通过对关键指标作独立复核；③使结论不易被个别异常值带偏。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01370","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「共创工作坊」是指公共服务设计组通过邀请使用者全程参与方案打磨，使改动获得使用者认同的工作机制。\n\n按照上述界定，下列情形不应认定为「共创工作坊」的是：","options":["公共服务设计组在公共界面优化中，邀请使用者全程参与方案打磨，改动获得使用者认同。","公共服务设计组在使用路径排查中，邀请使用者全程参与方案打磨，改动获得使用者认同。","公共服务设计组在服务流程梳理中，邀请使用者全程参与方案打磨，改动获得使用者认同。","公共服务设计组在公共界面优化中，仅在完工后征求意见，最终上线后仍频发与习惯不符的障碍。"],"answer":3,"explanation":"「共创工作坊」的构成要件为：①主体为公共服务设计组；②通过邀请使用者全程参与方案打磨；③使改动获得使用者认同。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（仅在完工后征求意见），因此不符合构成要件。故选D。"},{"id":"pdn01371","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「增值评价」是指任课教师团队通过结合真实任务表现打分，使后续目标更贴合实际起点的工作机制。\n\n根据上述定义，下列属于「增值评价」的是：","options":["任课教师团队在单元教学设计中，结合真实任务表现打分，后续目标更贴合实际起点。","任课教师团队在作业反馈整理中，结合真实任务表现打分，但教学安排并未因数据而作任何调整。","任课教师团队在实验课程组织中，全程不作任何反馈、结束后才公布，最终教学安排并未因数据而作任何调整。","由家长自行报送成绩，后续也未按上述机制推进。"],"answer":0,"explanation":"「增值评价」的构成要件为：①主体为任课教师团队；②通过结合真实任务表现打分；③使后续目标更贴合实际起点。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01372","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「阈值预警」是指湿地管护中心通过划分区块实行差异化管护，使干预强度与实际风险相匹配的工作机制。\n\n依据上述定义，以下哪一项不符合「阈值预警」的构成要件：","options":["湿地管护中心在栖息环境变化中，划分区块实行差异化管护，干预强度与实际风险相匹配。","湿地管护中心在监测指标波动中，划分区块实行差异化管护，干预强度与实际风险相匹配。","湿地管护中心在栖息环境变化中，只看年度均值忽略峰值，最终指标已越界而措施仍维持不变。","湿地管护中心在外来因素扩散中，划分区块实行差异化管护，干预强度与实际风险相匹配。"],"answer":2,"explanation":"「阈值预警」的构成要件为：①主体为湿地管护中心；②通过划分区块实行差异化管护；③使干预强度与实际风险相匹配。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（只看年度均值忽略峰值），因此不符合构成要件。故选C。"},{"id":"pdn01373","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「弹性调控」是指湿地管护中心通过设定阈值并触发分级响应，使核心栖息地得到有效避让的工作机制。\n\n按照上述界定，下列情形可认定为「弹性调控」的是：","options":["湿地管护中心在栖息环境变化中，等出现明显损害后再启动处置，最终指标已越界而措施仍维持不变。","湿地管护中心在外来因素扩散中，设定阈值并触发分级响应，但指标已越界而措施仍维持不变。","湿地管护中心在监测指标波动中，设定阈值并触发分级响应，核心栖息地得到有效避让。","由游客反馈临时决定，后续也未按上述机制推进。"],"answer":2,"explanation":"「弹性调控」的构成要件为：①主体为湿地管护中心；②通过设定阈值并触发分级响应；③使核心栖息地得到有效避让。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01374","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「证据本位决策」是指项目评审委员会通过以多源数据交叉校验结论，使后续调整有据可依的工作机制。\n\n根据上述定义，下列不属于「证据本位决策」的是：","options":["项目评审委员会在政策效果评估中，以多源数据交叉校验结论，后续调整有据可依。","项目评审委员会在政策效果评估中，只选取有利样本作展示，最终结论无法由所引数据支撑。","项目评审委员会在年度计划编制中，以多源数据交叉校验结论，后续调整有据可依。","项目评审委员会在抽样数据核查中，以多源数据交叉校验结论，后续调整有据可依。"],"answer":1,"explanation":"「证据本位决策」的构成要件为：①主体为项目评审委员会；②通过以多源数据交叉校验结论；③使后续调整有据可依。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（只选取有利样本作展示），因此不符合构成要件。故选B。"},{"id":"pdn01375","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「风险前置」是指水利工程调度处通过识别薄弱环节并预先加固，使核心功能在异常下仍可维持的工作机制。\n\n依据上述定义，以下哪一项符合「风险前置」的构成要件：","options":["水利工程调度处在响应动作预置中，仅保留一份无备用的关键设备，最终异常发生时无预设动作可依。","水利工程调度处在关键节点值守中，识别薄弱环节并预先加固，但异常发生时无预设动作可依。","由上级在事后统一追认，后续也未按上述机制推进。","水利工程调度处在风险等级研判中，识别薄弱环节并预先加固，核心功能在异常下仍可维持。"],"answer":3,"explanation":"「风险前置」的构成要件为：①主体为水利工程调度处；②通过识别薄弱环节并预先加固；③使核心功能在异常下仍可维持。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01376","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「阈值预警」是指湿地管护中心通过设定阈值并触发分级响应，使管控成本保持在合理区间的工作机制。\n\n按照上述界定，下列情形不应认定为「阈值预警」的是：","options":["湿地管护中心在栖息环境变化中，设定阈值并触发分级响应，管控成本保持在合理区间。","湿地管护中心在栖息环境变化中，只看年度均值忽略峰值，最终指标已越界而措施仍维持不变。","湿地管护中心在外来因素扩散中，设定阈值并触发分级响应，管控成本保持在合理区间。","湿地管护中心在监测指标波动中，设定阈值并触发分级响应，管控成本保持在合理区间。"],"answer":1,"explanation":"「阈值预警」的构成要件为：①主体为湿地管护中心；②通过设定阈值并触发分级响应；③使管控成本保持在合理区间。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（只看年度均值忽略峰值），因此不符合构成要件。故选B。"},{"id":"pdn01377","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「证据本位决策」是指统计调查队通过先确立基线再对照前后变化，使后续调整有据可依的工作机制。\n\n根据上述定义，下列属于「证据本位决策」的是：","options":["统计调查队在抽样数据核查中，先确立基线再对照前后变化，但结论无法由所引数据支撑。","统计调查队在年度计划编制中，先确立基线再对照前后变化，后续调整有据可依。","由第三方直接给结论不附依据，后续也未按上述机制推进。","统计调查队在政策效果评估中，指标口径中途变更却不说明，最终结论无法由所引数据支撑。"],"answer":1,"explanation":"「证据本位决策」的构成要件为：①主体为统计调查队；②通过先确立基线再对照前后变化；③使后续调整有据可依。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01378","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「前置筛查」是指社区卫生服务中心通过建立电子档案并定期回访，使轻症在基层得到及时处置的工作机制。\n\n依据上述定义，以下哪一项不符合「前置筛查」的构成要件：","options":["社区卫生服务中心在重点人群筛查中，建立电子档案并定期回访，轻症在基层得到及时处置。","社区卫生服务中心在慢病随访安排中，建立电子档案并定期回访，轻症在基层得到及时处置。","社区卫生服务中心在康复跟踪记录中，建立电子档案并定期回访，轻症在基层得到及时处置。","社区卫生服务中心在康复跟踪记录中，一律先安排住院再评估，最终各环节彼此脱节、患者仍需多次重复排队。"],"answer":3,"explanation":"「前置筛查」的构成要件为：①主体为社区卫生服务中心；②通过建立电子档案并定期回访；③使轻症在基层得到及时处置。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（一律先安排住院再评估），因此不符合构成要件。故选D。"},{"id":"pdn01379","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「随访管理」是指社区卫生服务中心通过按病情轻重分流并约定转诊路径，使患者往返成本下降的工作机制。\n\n按照上述界定，下列情形可认定为「随访管理」的是：","options":["社区卫生服务中心在重点人群筛查中，按病情轻重分流并约定转诊路径，但各环节彼此脱节、患者仍需多次重复排队。","社区卫生服务中心在康复跟踪记录中，只做一次性检查不作后续跟踪，最终各环节彼此脱节、患者仍需多次重复排队。","仅由三甲医院单方建档，后续也未按上述机制推进。","社区卫生服务中心在慢病随访安排中，按病情轻重分流并约定转诊路径，患者往返成本下降。"],"answer":3,"explanation":"「随访管理」的构成要件为：①主体为社区卫生服务中心；②通过按病情轻重分流并约定转诊路径；③使患者往返成本下降。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01380","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「协同治理」是指街道与职能站所通过建立常态化联络与移交规则，使重复检查与推诿明显减少的工作机制。\n\n根据上述定义，下列不属于「协同治理」的是：","options":["街道与职能站所在跨界事项梳理中，建立常态化联络与移交规则，重复检查与推诿明显减少。","街道与职能站所在联合排班安排中，遇跨界事项互相等待，最终边界地带的问题仍在部门之间来回流转。","街道与职能站所在联合排班安排中，建立常态化联络与移交规则，重复检查与推诿明显减少。","街道与职能站所在信息通报共享中，建立常态化联络与移交规则，重复检查与推诿明显减少。"],"answer":1,"explanation":"「协同治理」的构成要件为：①主体为街道与职能站所；②通过建立常态化联络与移交规则；③使重复检查与推诿明显减少。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（遇跨界事项互相等待），因此不符合构成要件。故选B。"},{"id":"pdn01381","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「原型共创」是指无障碍改造专班通过按真实使用路径逐点排查痛点，使改动获得使用者认同的工作机制。\n\n依据上述定义，以下哪一项符合「原型共创」的构成要件：","options":["由外部专家远程定稿，后续也未按上述机制推进。","无障碍改造专班在服务流程梳理中，按真实使用路径逐点排查痛点，改动获得使用者认同。","无障碍改造专班在公共界面优化中，一次性定稿不再接收反馈，最终上线后仍频发与习惯不符的障碍。","无障碍改造专班在使用路径排查中，按真实使用路径逐点排查痛点，但上线后仍频发与习惯不符的障碍。"],"answer":1,"explanation":"「原型共创」的构成要件为：①主体为无障碍改造专班；②通过按真实使用路径逐点排查痛点；③使改动获得使用者认同。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01382","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「多元共治」是指区级牵头部门通过明确牵头与配合边界后统一行动，使处置效率整体提升的工作机制。\n\n按照上述界定，下列情形不应认定为「多元共治」的是：","options":["区级牵头部门在联合排班安排中，明确牵头与配合边界后统一行动，处置效率整体提升。","区级牵头部门在跨界事项梳理中，明确牵头与配合边界后统一行动，处置效率整体提升。","区级牵头部门在信息通报共享中，明确牵头与配合边界后统一行动，处置效率整体提升。","区级牵头部门在联合排班安排中，各部门分头进场、结果互不通报，最终边界地带的问题仍在部门之间来回流转。"],"answer":3,"explanation":"「多元共治」的构成要件为：①主体为区级牵头部门；②通过明确牵头与配合边界后统一行动；③使处置效率整体提升。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（各部门分头进场、结果互不通报），因此不符合构成要件。故选D。"},{"id":"pdn01383","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「菜单式服务」是指就业服务窗口通过先摸清不同群体诉求再分类提供，使冷门项目被及时替换的工作机制。\n\n根据上述定义，下列属于「菜单式服务」的是：","options":["由供应商单方决定目录，后续也未按上述机制推进。","就业服务窗口在服务清单编制中，先摸清不同群体诉求再分类提供，但大量项目无人使用而真实诉求仍被搁置。","就业服务窗口在对象需求摸排中，按编制人数而不是实际用量分配，最终大量项目无人使用而真实诉求仍被搁置。","就业服务窗口在服务事项梳理中，先摸清不同群体诉求再分类提供，冷门项目被及时替换。"],"answer":3,"explanation":"「菜单式服务」的构成要件为：①主体为就业服务窗口；②通过先摸清不同群体诉求再分类提供；③使冷门项目被及时替换。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01384","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「分级办理」是指街道办通过建立台账逐项限时销号，使诉求在前端得到化解的工作机制。\n\n依据上述定义，以下哪一项不符合「分级办理」的构成要件：","options":["街道办在便民事项办理中，建立台账逐项限时销号，诉求在前端得到化解。","街道办在邻里纠纷调解中，建立台账逐项限时销号，诉求在前端得到化解。","街道办在老旧小区改造中，建立台账逐项限时销号，诉求在前端得到化解。","街道办在邻里纠纷调解中，只在事后补录台账，最终问题仍反复出现且未形成稳定机制。"],"answer":3,"explanation":"「分级办理」的构成要件为：①主体为街道办；②通过建立台账逐项限时销号；③使诉求在前端得到化解。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（只在事后补录台账），因此不符合构成要件。故选D。"},{"id":"pdn01385","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「需求导向供给」是指公共文化服务中心通过依据使用频次动态增减项目，使供给与实际需求更加贴合的工作机制。\n\n按照上述界定，下列情形可认定为「需求导向供给」的是：","options":["公共文化服务中心在对象需求摸排中，沿用上一年清单不作修订，最终大量项目无人使用而真实诉求仍被搁置。","公共文化服务中心在服务事项梳理中，依据使用频次动态增减项目，供给与实际需求更加贴合。","公共文化服务中心在服务清单编制中，依据使用频次动态增减项目，但大量项目无人使用而真实诉求仍被搁置。","由服务对象自行寻找渠道，后续也未按上述机制推进。"],"answer":1,"explanation":"「需求导向供给」的构成要件为：①主体为公共文化服务中心；②通过依据使用频次动态增减项目；③使供给与实际需求更加贴合。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01386","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「分级授权」是指公共服务窗口通过只采集完成本事项所必需的字段，使共享环节不泄露可识别信息的工作机制。\n\n根据上述定义，下列不属于「分级授权」的是：","options":["公共服务窗口在数据调阅留痕中，只采集完成本事项所必需的字段，共享环节不泄露可识别信息。","公共服务窗口在信息采集登记中，只采集完成本事项所必需的字段，共享环节不泄露可识别信息。","公共服务窗口在字段权限配置中，为方便起见一次性收齐全部字段，最终与办理目的无关的字段仍被长期留存。","公共服务窗口在字段权限配置中，只采集完成本事项所必需的字段，共享环节不泄露可识别信息。"],"answer":2,"explanation":"「分级授权」的构成要件为：①主体为公共服务窗口；②通过只采集完成本事项所必需的字段；③使共享环节不泄露可识别信息。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（为方便起见一次性收齐全部字段），因此不符合构成要件。故选C。"},{"id":"pdn01387","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「协同会商」是指社区网格站通过依托网格员常态化走访摸排，使平均处置周期缩短的工作机制。\n\n依据上述定义，以下哪一项符合「协同会商」的构成要件：","options":["社区网格站在老旧小区改造中，依托网格员常态化走访摸排，平均处置周期缩短。","社区网格站在邻里纠纷调解中，等群众上门反映后再统一研究，最终问题仍反复出现且未形成稳定机制。","社区网格站在便民事项办理中，依托网格员常态化走访摸排，但问题仍反复出现且未形成稳定机制。","由临时志愿队自行接管，后续也未按上述机制推进。"],"answer":0,"explanation":"「协同会商」的构成要件为：①主体为社区网格站；②通过依托网格员常态化走访摸排；③使平均处置周期缩短。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01388","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「形成性评价」是指任课教师团队通过随堂记录并及时反馈调整，使学习过程而非仅结果被看见的工作机制。\n\n按照上述界定，下列情形不应认定为「形成性评价」的是：","options":["任课教师团队在作业反馈整理中，随堂记录并及时反馈调整，学习过程而非仅结果被看见。","任课教师团队在实验课程组织中，照搬统一答案不看作答过程，最终教学安排并未因数据而作任何调整。","任课教师团队在单元教学设计中，随堂记录并及时反馈调整，学习过程而非仅结果被看见。","任课教师团队在实验课程组织中，随堂记录并及时反馈调整，学习过程而非仅结果被看见。"],"answer":1,"explanation":"「形成性评价」的构成要件为：①主体为任课教师团队；②通过随堂记录并及时反馈调整；③使学习过程而非仅结果被看见。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（照搬统一答案不看作答过程），因此不符合构成要件。故选B。"},{"id":"pdn01389","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「可回溯核查」是指药品批发企业质控部通过按批号串联台账与检验记录，使台账与实物始终一致的工作机制。\n\n根据上述定义，下列属于「可回溯核查」的是：","options":["药品批发企业质控部在批次交接记录中，仅保留汇总数不留明细，最终出现问题时无法定位到具体环节。","由消费者事后反馈倒查，后续也未按上述机制推进。","药品批发企业质控部在储运环节温控中，按批号串联台账与检验记录，但出现问题时无法定位到具体环节。","药品批发企业质控部在进货环节核验中，按批号串联台账与检验记录，台账与实物始终一致。"],"answer":3,"explanation":"「可回溯核查」的构成要件为：①主体为药品批发企业质控部；②通过按批号串联台账与检验记录；③使台账与实物始终一致。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01390","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「脱敏处理」是指学校学籍管理系统通过按岗位授予最小可见范围，使历史数据不再无限期堆积的工作机制。\n\n依据上述定义，以下哪一项不符合「脱敏处理」的构成要件：","options":["学校学籍管理系统在数据调阅留痕中，按岗位授予最小可见范围，历史数据不再无限期堆积。","学校学籍管理系统在字段权限配置中，按岗位授予最小可见范围，历史数据不再无限期堆积。","学校学籍管理系统在信息采集登记中，按岗位授予最小可见范围，历史数据不再无限期堆积。","学校学籍管理系统在字段权限配置中，为方便起见一次性收齐全部字段，最终与办理目的无关的字段仍被长期留存。"],"answer":3,"explanation":"「脱敏处理」的构成要件为：①主体为学校学籍管理系统；②通过按岗位授予最小可见范围；③使历史数据不再无限期堆积。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（为方便起见一次性收齐全部字段），因此不符合构成要件。故选D。"},{"id":"pdn01391","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「弹性调控」是指自然保护区管理局通过划分区块实行差异化管护，使管控成本保持在合理区间的工作机制。\n\n按照上述界定，下列情形可认定为「弹性调控」的是：","options":["自然保护区管理局在栖息环境变化中，指标超标后仍不调整，最终指标已越界而措施仍维持不变。","由邻近地区照抄方案，后续也未按上述机制推进。","自然保护区管理局在监测指标波动中，划分区块实行差异化管护，管控成本保持在合理区间。","自然保护区管理局在外来因素扩散中，划分区块实行差异化管护，但指标已越界而措施仍维持不变。"],"answer":2,"explanation":"「弹性调控」的构成要件为：①主体为自然保护区管理局；②通过划分区块实行差异化管护；③使管控成本保持在合理区间。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01392","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「协同治理」是指跨部门工作专班通过共享信息并同步排班，使重复检查与推诿明显减少的工作机制。\n\n根据上述定义，下列不属于「协同治理」的是：","options":["跨部门工作专班在跨界事项梳理中，共享信息并同步排班，重复检查与推诿明显减少。","跨部门工作专班在联合排班安排中，遇跨界事项互相等待，最终边界地带的问题仍在部门之间来回流转。","跨部门工作专班在联合排班安排中，共享信息并同步排班，重复检查与推诿明显减少。","跨部门工作专班在信息通报共享中，共享信息并同步排班，重复检查与推诿明显减少。"],"answer":1,"explanation":"「协同治理」的构成要件为：①主体为跨部门工作专班；②通过共享信息并同步排班；③使重复检查与推诿明显减少。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（遇跨界事项互相等待），因此不符合构成要件。故选B。"},{"id":"pdn01393","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「分级授权」是指公共服务窗口通过按岗位授予最小可见范围，使共享环节不泄露可识别信息的工作机制。\n\n依据上述定义，以下哪一项符合「分级授权」的构成要件：","options":["公共服务窗口在字段权限配置中，超过期限仍不作清理，最终与办理目的无关的字段仍被长期留存。","公共服务窗口在数据调阅留痕中，按岗位授予最小可见范围，但与办理目的无关的字段仍被长期留存。","由系统默认长期全量保留，后续也未按上述机制推进。","公共服务窗口在信息采集登记中，按岗位授予最小可见范围，共享环节不泄露可识别信息。"],"answer":3,"explanation":"「分级授权」的构成要件为：①主体为公共服务窗口；②通过按岗位授予最小可见范围；③使共享环节不泄露可识别信息。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01394","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「需求导向供给」是指就业服务窗口通过依据使用频次动态增减项目，使冷门项目被及时替换的工作机制。\n\n按照上述界定，下列情形不应认定为「需求导向供给」的是：","options":["就业服务窗口在服务清单编制中，依据使用频次动态增减项目，冷门项目被及时替换。","就业服务窗口在服务事项梳理中，依据使用频次动态增减项目，冷门项目被及时替换。","就业服务窗口在对象需求摸排中，所有对象发放完全相同的固定包，最终大量项目无人使用而真实诉求仍被搁置。","就业服务窗口在对象需求摸排中，依据使用频次动态增减项目，冷门项目被及时替换。"],"answer":2,"explanation":"「需求导向供给」的构成要件为：①主体为就业服务窗口；②通过依据使用频次动态增减项目；③使冷门项目被及时替换。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（所有对象发放完全相同的固定包），因此不符合构成要件。故选C。"},{"id":"pdn01395","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「预案触发」是指应急指挥中心通过识别薄弱环节并预先加固，使核心功能在异常下仍可维持的工作机制。\n\n根据上述定义，下列属于「预案触发」的是：","options":["应急指挥中心在关键节点值守中，识别薄弱环节并预先加固，但异常发生时无预设动作可依。","由上级在事后统一追认，后续也未按上述机制推进。","应急指挥中心在响应动作预置中，仅保留一份无备用的关键设备，最终异常发生时无预设动作可依。","应急指挥中心在风险等级研判中，识别薄弱环节并预先加固，核心功能在异常下仍可维持。"],"answer":3,"explanation":"「预案触发」的构成要件为：①主体为应急指挥中心；②通过识别薄弱环节并预先加固；③使核心功能在异常下仍可维持。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01396","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「用户旅程映射」是指社区营造团队通过按真实使用路径逐点排查痛点，使返工与投诉明显减少的工作机制。\n\n依据上述定义，以下哪一项不符合「用户旅程映射」的构成要件：","options":["社区营造团队在公共界面优化中，按真实使用路径逐点排查痛点，返工与投诉明显减少。","社区营造团队在公共界面优化中，照搬其他地区成品，最终上线后仍频发与习惯不符的障碍。","社区营造团队在服务流程梳理中，按真实使用路径逐点排查痛点，返工与投诉明显减少。","社区营造团队在使用路径排查中，按真实使用路径逐点排查痛点，返工与投诉明显减少。"],"answer":1,"explanation":"「用户旅程映射」的构成要件为：①主体为社区营造团队；②通过按真实使用路径逐点排查痛点；③使返工与投诉明显减少。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（照搬其他地区成品），因此不符合构成要件。故选B。"},{"id":"pdn01397","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「风险前置」是指水利工程调度处通过关键节点保留备用通道，使人员与物资提前就位的工作机制。\n\n按照上述界定，下列情形可认定为「风险前置」的是：","options":["水利工程调度处在响应动作预置中，只在事发后补充记录，最终异常发生时无预设动作可依。","由外部单位事后支援，后续也未按上述机制推进。","水利工程调度处在风险等级研判中，关键节点保留备用通道，人员与物资提前就位。","水利工程调度处在关键节点值守中，关键节点保留备用通道，但异常发生时无预设动作可依。"],"answer":2,"explanation":"「风险前置」的构成要件为：①主体为水利工程调度处；②通过关键节点保留备用通道；③使人员与物资提前就位。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01398","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「共创反馈环」是指产品体验小组通过先做可体验原型再收集反馈，使改动获得使用者认同的工作机制。\n\n根据上述定义，下列不属于「共创反馈环」的是：","options":["产品体验小组在服务流程梳理中，先做可体验原型再收集反馈，改动获得使用者认同。","产品体验小组在公共界面优化中，先做可体验原型再收集反馈，改动获得使用者认同。","产品体验小组在使用路径排查中，先做可体验原型再收集反馈，改动获得使用者认同。","产品体验小组在公共界面优化中，仅在完工后征求意见，最终上线后仍频发与习惯不符的障碍。"],"answer":3,"explanation":"「共创反馈环」的构成要件为：①主体为产品体验小组；②通过先做可体验原型再收集反馈；③使改动获得使用者认同。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（仅在完工后征求意见），因此不符合构成要件。故选D。"},{"id":"pdn01399","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「数据校验」是指统计调查队通过以多源数据交叉校验结论，使结论不易被个别异常值带偏的工作机制。\n\n依据上述定义，以下哪一项符合「数据校验」的构成要件：","options":["由申报方自行填报不作核实，后续也未按上述机制推进。","统计调查队在政策效果评估中，用总量变化直接归因、不作对照，最终结论无法由所引数据支撑。","统计调查队在抽样数据核查中，以多源数据交叉校验结论，但结论无法由所引数据支撑。","统计调查队在年度计划编制中，以多源数据交叉校验结论，结论不易被个别异常值带偏。"],"answer":3,"explanation":"「数据校验」的构成要件为：①主体为统计调查队；②通过以多源数据交叉校验结论；③使结论不易被个别异常值带偏。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01400","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「参与式设计」是指社区营造团队通过邀请使用者全程参与方案打磨，使改动获得使用者认同的工作机制。\n\n按照上述界定，下列情形不应认定为「参与式设计」的是：","options":["社区营造团队在公共界面优化中，照搬其他地区成品，最终上线后仍频发与习惯不符的障碍。","社区营造团队在使用路径排查中，邀请使用者全程参与方案打磨，改动获得使用者认同。","社区营造团队在服务流程梳理中，邀请使用者全程参与方案打磨，改动获得使用者认同。","社区营造团队在公共界面优化中，邀请使用者全程参与方案打磨，改动获得使用者认同。"],"answer":0,"explanation":"「参与式设计」的构成要件为：①主体为社区营造团队；②通过邀请使用者全程参与方案打磨；③使改动获得使用者认同。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（照搬其他地区成品），因此不符合构成要件。故选A。"},{"id":"pdn01401","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「容错纠偏」是指政策试点工作组通过分批次扩面而非一次铺开，使方案随实际反馈逐步完善的工作机制。\n\n根据上述定义，下列属于「容错纠偏」的是：","options":["政策试点工作组在新流程上线中，分批次扩面而非一次铺开，方案随实际反馈逐步完善。","政策试点工作组在新工具推广中，一次上线后即固化不再迭代，最终同类偏差在扩面后被成倍放大。","政策试点工作组在新机制落地中，分批次扩面而非一次铺开，但同类偏差在扩面后被成倍放大。","由用户自行摸索不作收集，后续也未按上述机制推进。"],"answer":0,"explanation":"「容错纠偏」的构成要件为：①主体为政策试点工作组；②通过分批次扩面而非一次铺开；③使方案随实际反馈逐步完善。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01402","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「基线比对」是指项目评审委员会通过对关键指标作独立复核，使结论不易被个别异常值带偏的工作机制。\n\n依据上述定义，以下哪一项不符合「基线比对」的构成要件：","options":["项目评审委员会在政策效果评估中，对关键指标作独立复核，结论不易被个别异常值带偏。","项目评审委员会在抽样数据核查中，对关键指标作独立复核，结论不易被个别异常值带偏。","项目评审委员会在政策效果评估中，只选取有利样本作展示，最终结论无法由所引数据支撑。","项目评审委员会在年度计划编制中，对关键指标作独立复核，结论不易被个别异常值带偏。"],"answer":2,"explanation":"「基线比对」的构成要件为：①主体为项目评审委员会；②通过对关键指标作独立复核；③使结论不易被个别异常值带偏。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（只选取有利样本作展示），因此不符合构成要件。故选C。"},{"id":"pdn01403","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「节点责任制」是指食品药品监管所通过异常批次可一键回溯全链路，使台账与实物始终一致的工作机制。\n\n按照上述界定，下列情形可认定为「节点责任制」的是：","options":["由终端门店自行补记，后续也未按上述机制推进。","食品药品监管所在储运环节温控中，异常批次可一键回溯全链路，但出现问题时无法定位到具体环节。","食品药品监管所在进货环节核验中，异常批次可一键回溯全链路，台账与实物始终一致。","食品药品监管所在批次交接记录中，各环节各自记录且互不关联，最终出现问题时无法定位到具体环节。"],"answer":2,"explanation":"「节点责任制」的构成要件为：①主体为食品药品监管所；②通过异常批次可一键回溯全链路；③使台账与实物始终一致。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01404","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「诊断性测评」是指区域教研中心通过按阶段采集学情数据再修正教学，使学生的薄弱点被及时识别的工作机制。\n\n根据上述定义，下列不属于「诊断性测评」的是：","options":["区域教研中心在单元教学设计中，按阶段采集学情数据再修正教学，学生的薄弱点被及时识别。","区域教研中心在实验课程组织中，按阶段采集学情数据再修正教学，学生的薄弱点被及时识别。","区域教研中心在作业反馈整理中，按阶段采集学情数据再修正教学，学生的薄弱点被及时识别。","区域教研中心在实验课程组织中，照搬统一答案不看作答过程，最终教学安排并未因数据而作任何调整。"],"answer":3,"explanation":"「诊断性测评」的构成要件为：①主体为区域教研中心；②通过按阶段采集学情数据再修正教学；③使学生的薄弱点被及时识别。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（照搬统一答案不看作答过程），因此不符合构成要件。故选D。"},{"id":"pdn01405","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「弹性调控」是指湿地管护中心通过按监测指标分档调整措施，使干预强度与实际风险相匹配的工作机制。\n\n依据上述定义，以下哪一项符合「弹性调控」的构成要件：","options":["由游客反馈临时决定，后续也未按上述机制推进。","湿地管护中心在栖息环境变化中，等出现明显损害后再启动处置，最终指标已越界而措施仍维持不变。","湿地管护中心在外来因素扩散中，按监测指标分档调整措施，但指标已越界而措施仍维持不变。","湿地管护中心在监测指标波动中，按监测指标分档调整措施，干预强度与实际风险相匹配。"],"answer":3,"explanation":"「弹性调控」的构成要件为：①主体为湿地管护中心；②通过按监测指标分档调整措施；③使干预强度与实际风险相匹配。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01406","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「表现性评价」是指区域教研中心通过随堂记录并及时反馈调整，使学生的薄弱点被及时识别的工作机制。\n\n按照上述界定，下列情形不应认定为「表现性评价」的是：","options":["区域教研中心在单元教学设计中，随堂记录并及时反馈调整，学生的薄弱点被及时识别。","区域教研中心在实验课程组织中，随堂记录并及时反馈调整，学生的薄弱点被及时识别。","区域教研中心在实验课程组织中，只以期末一次分数定结论，最终教学安排并未因数据而作任何调整。","区域教研中心在作业反馈整理中，随堂记录并及时反馈调整，学生的薄弱点被及时识别。"],"answer":2,"explanation":"「表现性评价」的构成要件为：①主体为区域教研中心；②通过随堂记录并及时反馈调整；③使学生的薄弱点被及时识别。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（只以期末一次分数定结论），因此不符合构成要件。故选C。"},{"id":"pdn01407","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「分级授权」是指公共服务窗口通过按岗位授予最小可见范围，使超范围信息不被额外索取的工作机制。\n\n根据上述定义，下列属于「分级授权」的是：","options":["由外包人员全量导出，后续也未按上述机制推进。","公共服务窗口在数据调阅留痕中，按岗位授予最小可见范围，但与办理目的无关的字段仍被长期留存。","公共服务窗口在字段权限配置中，所有岗位开放同一份全量清单，最终与办理目的无关的字段仍被长期留存。","公共服务窗口在信息采集登记中，按岗位授予最小可见范围，超范围信息不被额外索取。"],"answer":3,"explanation":"「分级授权」的构成要件为：①主体为公共服务窗口；②通过按岗位授予最小可见范围；③使超范围信息不被额外索取。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01408","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「全过程追溯」是指冷链运营方通过按批号串联台账与检验记录，使台账与实物始终一致的工作机制。\n\n依据上述定义，以下哪一项不符合「全过程追溯」的构成要件：","options":["冷链运营方在储运环节温控中，按批号串联台账与检验记录，台账与实物始终一致。","冷链运营方在批次交接记录中，事后一次性补全整本台账，最终出现问题时无法定位到具体环节。","冷链运营方在进货环节核验中，按批号串联台账与检验记录，台账与实物始终一致。","冷链运营方在批次交接记录中，按批号串联台账与检验记录，台账与实物始终一致。"],"answer":1,"explanation":"「全过程追溯」的构成要件为：①主体为冷链运营方；②通过按批号串联台账与检验记录；③使台账与实物始终一致。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（事后一次性补全整本台账），因此不符合构成要件。故选B。"},{"id":"pdn01409","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「目的限定」是指医院信息科通过对外提供前作去标识化处理，使历史数据不再无限期堆积的工作机制。\n\n按照上述界定，下列情形可认定为「目的限定」的是：","options":["医院信息科在字段权限配置中，超过期限仍不作清理，最终与办理目的无关的字段仍被长期留存。","由系统默认长期全量保留，后续也未按上述机制推进。","医院信息科在数据调阅留痕中，对外提供前作去标识化处理，但与办理目的无关的字段仍被长期留存。","医院信息科在信息采集登记中，对外提供前作去标识化处理，历史数据不再无限期堆积。"],"answer":3,"explanation":"「目的限定」的构成要件为：①主体为医院信息科；②通过对外提供前作去标识化处理；③使历史数据不再无限期堆积。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01410","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「随访管理」是指乡镇卫生院通过先由基层评估再决定是否上转，使患者往返成本下降的工作机制。\n\n根据上述定义，下列不属于「随访管理」的是：","options":["乡镇卫生院在康复跟踪记录中，先由基层评估再决定是否上转，患者往返成本下降。","乡镇卫生院在康复跟踪记录中，一律先安排住院再评估，最终各环节彼此脱节、患者仍需多次重复排队。","乡镇卫生院在重点人群筛查中，先由基层评估再决定是否上转，患者往返成本下降。","乡镇卫生院在慢病随访安排中，先由基层评估再决定是否上转，患者往返成本下降。"],"answer":1,"explanation":"「随访管理」的构成要件为：①主体为乡镇卫生院；②通过先由基层评估再决定是否上转；③使患者往返成本下降。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（一律先安排住院再评估），因此不符合构成要件。故选B。"},{"id":"pdn01411","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「按需配置」是指养老服务站点通过依据使用频次动态增减项目，使冷门项目被及时替换的工作机制。\n\n依据上述定义，以下哪一项符合「按需配置」的构成要件：","options":["由供应商单方决定目录，后续也未按上述机制推进。","养老服务站点在服务事项梳理中，依据使用频次动态增减项目，冷门项目被及时替换。","养老服务站点在对象需求摸排中，按编制人数而不是实际用量分配，最终大量项目无人使用而真实诉求仍被搁置。","养老服务站点在服务清单编制中，依据使用频次动态增减项目，但大量项目无人使用而真实诉求仍被搁置。"],"answer":1,"explanation":"「按需配置」的构成要件为：①主体为养老服务站点；②通过依据使用频次动态增减项目；③使冷门项目被及时替换。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01412","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「参与式设计」是指社区营造团队通过按真实使用路径逐点排查痛点，使隐蔽障碍在使用前被暴露的工作机制。\n\n按照上述界定，下列情形不应认定为「参与式设计」的是：","options":["社区营造团队在公共界面优化中，按真实使用路径逐点排查痛点，隐蔽障碍在使用前被暴露。","社区营造团队在公共界面优化中，照搬其他地区成品，最终上线后仍频发与习惯不符的障碍。","社区营造团队在使用路径排查中，按真实使用路径逐点排查痛点，隐蔽障碍在使用前被暴露。","社区营造团队在服务流程梳理中，按真实使用路径逐点排查痛点，隐蔽障碍在使用前被暴露。"],"answer":1,"explanation":"「参与式设计」的构成要件为：①主体为社区营造团队；②通过按真实使用路径逐点排查痛点；③使隐蔽障碍在使用前被暴露。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（照搬其他地区成品），因此不符合构成要件。故选B。"},{"id":"pdn01413","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「协同会商」是指街道办通过联合多方现场会商后再定方案，使平均处置周期缩短的工作机制。\n\n根据上述定义，下列属于「协同会商」的是：","options":["由服务对象自行申报后不再跟进，后续也未按上述机制推进。","街道办在老旧小区改造中，联合多方现场会商后再定方案，平均处置周期缩短。","街道办在便民事项办理中，联合多方现场会商后再定方案，但问题仍反复出现且未形成稳定机制。","街道办在邻里纠纷调解中，各口径分头办理、彼此不通气，最终问题仍反复出现且未形成稳定机制。"],"answer":1,"explanation":"「协同会商」的构成要件为：①主体为街道办；②通过联合多方现场会商后再定方案；③使平均处置周期缩短。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01414","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「差异化供给」是指养老服务站点通过按可选项自主组合形成服务清单，使资源不再平均摊薄的工作机制。\n\n依据上述定义，以下哪一项不符合「差异化供给」的构成要件：","options":["养老服务站点在服务清单编制中，按可选项自主组合形成服务清单，资源不再平均摊薄。","养老服务站点在服务事项梳理中，按可选项自主组合形成服务清单，资源不再平均摊薄。","养老服务站点在对象需求摸排中，所有对象发放完全相同的固定包，最终大量项目无人使用而真实诉求仍被搁置。","养老服务站点在对象需求摸排中，按可选项自主组合形成服务清单，资源不再平均摊薄。"],"answer":2,"explanation":"「差异化供给」的构成要件为：①主体为养老服务站点；②通过按可选项自主组合形成服务清单；③使资源不再平均摊薄。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（所有对象发放完全相同的固定包），因此不符合构成要件。故选C。"},{"id":"pdn01415","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「灰度验证」是指改革推进专班通过分批次扩面而非一次铺开，使方案随实际反馈逐步完善的工作机制。\n\n按照上述界定，下列情形可认定为「灰度验证」的是：","options":["由外部团队一次性交付即结束，后续也未按上述机制推进。","改革推进专班在新工具推广中，试运行期间禁止任何修改，最终同类偏差在扩面后被成倍放大。","改革推进专班在新流程上线中，分批次扩面而非一次铺开，方案随实际反馈逐步完善。","改革推进专班在新机制落地中，分批次扩面而非一次铺开，但同类偏差在扩面后被成倍放大。"],"answer":2,"explanation":"「灰度验证」的构成要件为：①主体为改革推进专班；②通过分批次扩面而非一次铺开；③使方案随实际反馈逐步完善。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01416","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「灰度验证」是指数字化转型办公室通过分批次扩面而非一次铺开，使风险被限制在可控范围的工作机制。\n\n根据上述定义，下列不属于「灰度验证」的是：","options":["数字化转型办公室在新流程上线中，分批次扩面而非一次铺开，风险被限制在可控范围。","数字化转型办公室在新工具推广中，只记录成功案例不分析偏差，最终同类偏差在扩面后被成倍放大。","数字化转型办公室在新机制落地中，分批次扩面而非一次铺开，风险被限制在可控范围。","数字化转型办公室在新工具推广中，分批次扩面而非一次铺开，风险被限制在可控范围。"],"answer":1,"explanation":"「灰度验证」的构成要件为：①主体为数字化转型办公室；②通过分批次扩面而非一次铺开；③使风险被限制在可控范围。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（只记录成功案例不分析偏差），因此不符合构成要件。故选B。"},{"id":"pdn01417","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「联合响应」是指街道与职能站所通过共享信息并同步排班，使响应口径保持一致的工作机制。\n\n依据上述定义，以下哪一项符合「联合响应」的构成要件：","options":["街道与职能站所在信息通报共享中，共享信息并同步排班，但边界地带的问题仍在部门之间来回流转。","由上级部门包办到底，后续也未按上述机制推进。","街道与职能站所在联合排班安排中，各自按本部门旧流程办理，最终边界地带的问题仍在部门之间来回流转。","街道与职能站所在跨界事项梳理中，共享信息并同步排班，响应口径保持一致。"],"answer":3,"explanation":"「联合响应」的构成要件为：①主体为街道与职能站所；②通过共享信息并同步排班；③使响应口径保持一致。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01418","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「全过程追溯」是指冷链运营方通过关键节点双人签认留档，使召回范围精确到具体批次的工作机制。\n\n按照上述界定，下列情形不应认定为「全过程追溯」的是：","options":["冷链运营方在储运环节温控中，关键节点双人签认留档，召回范围精确到具体批次。","冷链运营方在批次交接记录中，关键节点双人签认留档，召回范围精确到具体批次。","冷链运营方在进货环节核验中，关键节点双人签认留档，召回范围精确到具体批次。","冷链运营方在批次交接记录中，只在最终出库时记一笔总账，最终出现问题时无法定位到具体环节。"],"answer":3,"explanation":"「全过程追溯」的构成要件为：①主体为冷链运营方；②通过关键节点双人签认留档；③使召回范围精确到具体批次。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（只在最终出库时记一笔总账），因此不符合构成要件。故选D。"},{"id":"pdn01419","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「按需配置」是指养老服务站点通过先摸清不同群体诉求再分类提供，使冷门项目被及时替换的工作机制。\n\n根据上述定义，下列属于「按需配置」的是：","options":["养老服务站点在对象需求摸排中，按编制人数而不是实际用量分配，最终大量项目无人使用而真实诉求仍被搁置。","养老服务站点在服务清单编制中，先摸清不同群体诉求再分类提供，但大量项目无人使用而真实诉求仍被搁置。","养老服务站点在服务事项梳理中，先摸清不同群体诉求再分类提供，冷门项目被及时替换。","由供应商单方决定目录，后续也未按上述机制推进。"],"answer":2,"explanation":"「按需配置」的构成要件为：①主体为养老服务站点；②通过先摸清不同群体诉求再分类提供；③使冷门项目被及时替换。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01420","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「表现性评价」是指区域教研中心通过按阶段采集学情数据再修正教学，使学习过程而非仅结果被看见的工作机制。\n\n依据上述定义，以下哪一项不符合「表现性评价」的构成要件：","options":["区域教研中心在实验课程组织中，按阶段采集学情数据再修正教学，学习过程而非仅结果被看见。","区域教研中心在作业反馈整理中，按阶段采集学情数据再修正教学，学习过程而非仅结果被看见。","区域教研中心在实验课程组织中，照搬统一答案不看作答过程，最终教学安排并未因数据而作任何调整。","区域教研中心在单元教学设计中，按阶段采集学情数据再修正教学，学习过程而非仅结果被看见。"],"answer":2,"explanation":"「表现性评价」的构成要件为：①主体为区域教研中心；②通过按阶段采集学情数据再修正教学；③使学习过程而非仅结果被看见。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（照搬统一答案不看作答过程），因此不符合构成要件。故选C。"},{"id":"pdn01421","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「过程性考核」是指课程组通过按阶段采集学情数据再修正教学，使学习过程而非仅结果被看见的工作机制。\n\n按照上述界定，下列情形可认定为「过程性考核」的是：","options":["由学生互评后不再复核，后续也未按上述机制推进。","课程组在实验课程组织中，按固定名次划线且不追溯变化，最终教学安排并未因数据而作任何调整。","课程组在单元教学设计中，按阶段采集学情数据再修正教学，学习过程而非仅结果被看见。","课程组在作业反馈整理中，按阶段采集学情数据再修正教学，但教学安排并未因数据而作任何调整。"],"answer":2,"explanation":"「过程性考核」的构成要件为：①主体为课程组；②通过按阶段采集学情数据再修正教学；③使学习过程而非仅结果被看见。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01422","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「按需配置」是指就业服务窗口通过依据使用频次动态增减项目，使不同群体各取所需的工作机制。\n\n根据上述定义，下列不属于「按需配置」的是：","options":["就业服务窗口在对象需求摸排中，所有对象发放完全相同的固定包，最终大量项目无人使用而真实诉求仍被搁置。","就业服务窗口在对象需求摸排中，依据使用频次动态增减项目，不同群体各取所需。","就业服务窗口在服务事项梳理中，依据使用频次动态增减项目，不同群体各取所需。","就业服务窗口在服务清单编制中，依据使用频次动态增减项目，不同群体各取所需。"],"answer":0,"explanation":"「按需配置」的构成要件为：①主体为就业服务窗口；②通过依据使用频次动态增减项目；③使不同群体各取所需。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（所有对象发放完全相同的固定包），因此不符合构成要件。故选A。"},{"id":"pdn01423","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「动态监测」是指生态环境监测站通过随季节数据滚动修订方案，使异常苗头被尽早识别的工作机制。\n\n依据上述定义，以下哪一项符合「动态监测」的构成要件：","options":["由邻近地区照抄方案，后续也未按上述机制推进。","生态环境监测站在外来因素扩散中，随季节数据滚动修订方案，但指标已越界而措施仍维持不变。","生态环境监测站在栖息环境变化中，指标超标后仍不调整，最终指标已越界而措施仍维持不变。","生态环境监测站在监测指标波动中，随季节数据滚动修订方案，异常苗头被尽早识别。"],"answer":3,"explanation":"「动态监测」的构成要件为：①主体为生态环境监测站；②通过随季节数据滚动修订方案；③使异常苗头被尽早识别。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01424","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「协同治理」是指流域联席会议通过一次会商形成分工清单，使重复检查与推诿明显减少的工作机制。\n\n按照上述界定，下列情形不应认定为「协同治理」的是：","options":["流域联席会议在跨界事项梳理中，一次会商形成分工清单，重复检查与推诿明显减少。","流域联席会议在信息通报共享中，一次会商形成分工清单，重复检查与推诿明显减少。","流域联席会议在联合排班安排中，遇跨界事项互相等待，最终边界地带的问题仍在部门之间来回流转。","流域联席会议在联合排班安排中，一次会商形成分工清单，重复检查与推诿明显减少。"],"answer":2,"explanation":"「协同治理」的构成要件为：①主体为流域联席会议；②通过一次会商形成分工清单；③使重复检查与推诿明显减少。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（遇跨界事项互相等待），因此不符合构成要件。故选C。"},{"id":"pdn01425","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「目的限定」是指公共服务窗口通过到期自动清理并留清理记录，使敏感字段仅在授权场景可见的工作机制。\n\n根据上述定义，下列属于「目的限定」的是：","options":["公共服务窗口在信息采集登记中，到期自动清理并留清理记录，敏感字段仅在授权场景可见。","由系统默认长期全量保留，后续也未按上述机制推进。","公共服务窗口在字段权限配置中，超过期限仍不作清理，最终与办理目的无关的字段仍被长期留存。","公共服务窗口在数据调阅留痕中，到期自动清理并留清理记录，但与办理目的无关的字段仍被长期留存。"],"answer":0,"explanation":"「目的限定」的构成要件为：①主体为公共服务窗口；②通过到期自动清理并留清理记录；③使敏感字段仅在授权场景可见。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01426","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「分区管控」是指自然保护区管理局通过划分区块实行差异化管护，使管控成本保持在合理区间的工作机制。\n\n依据上述定义，以下哪一项不符合「分区管控」的构成要件：","options":["自然保护区管理局在栖息环境变化中，划分区块实行差异化管护，管控成本保持在合理区间。","自然保护区管理局在监测指标波动中，划分区块实行差异化管护，管控成本保持在合理区间。","自然保护区管理局在栖息环境变化中，全年沿用同一套固定配额，最终指标已越界而措施仍维持不变。","自然保护区管理局在外来因素扩散中，划分区块实行差异化管护，管控成本保持在合理区间。"],"answer":2,"explanation":"「分区管控」的构成要件为：①主体为自然保护区管理局；②通过划分区块实行差异化管护；③使管控成本保持在合理区间。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（全年沿用同一套固定配额），因此不符合构成要件。故选C。"},{"id":"pdn01427","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「基线比对」是指政策评估小组通过用对照组剔除同期其他影响，使成效与措施之间的对应更清楚的工作机制。\n\n按照上述界定，下列情形可认定为「基线比对」的是：","options":["政策评估小组在抽样数据核查中，用对照组剔除同期其他影响，但结论无法由所引数据支撑。","由申报方自行填报不作核实，后续也未按上述机制推进。","政策评估小组在年度计划编制中，用对照组剔除同期其他影响，成效与措施之间的对应更清楚。","政策评估小组在政策效果评估中，用总量变化直接归因、不作对照，最终结论无法由所引数据支撑。"],"answer":2,"explanation":"「基线比对」的构成要件为：①主体为政策评估小组；②通过用对照组剔除同期其他影响；③使成效与措施之间的对应更清楚。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01428","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「连续照护」是指家庭医生团队通过先由基层评估再决定是否上转，使患者往返成本下降的工作机制。\n\n根据上述定义，下列不属于「连续照护」的是：","options":["家庭医生团队在慢病随访安排中，先由基层评估再决定是否上转，患者往返成本下降。","家庭医生团队在重点人群筛查中，先由基层评估再决定是否上转，患者往返成本下降。","家庭医生团队在康复跟踪记录中，先由基层评估再决定是否上转，患者往返成本下降。","家庭医生团队在康复跟踪记录中，各机构各自重复开单，最终各环节彼此脱节、患者仍需多次重复排队。"],"answer":3,"explanation":"「连续照护」的构成要件为：①主体为家庭医生团队；②通过先由基层评估再决定是否上转；③使患者往返成本下降。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（各机构各自重复开单），因此不符合构成要件。故选D。"},{"id":"pdn01429","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「共创反馈环」是指无障碍改造专班通过按真实使用路径逐点排查痛点，使方案贴合真实使用习惯的工作机制。\n\n依据上述定义，以下哪一项符合「共创反馈环」的构成要件：","options":["无障碍改造专班在服务流程梳理中，按真实使用路径逐点排查痛点，方案贴合真实使用习惯。","无障碍改造专班在使用路径排查中，按真实使用路径逐点排查痛点，但上线后仍频发与习惯不符的障碍。","由外部专家远程定稿，后续也未按上述机制推进。","无障碍改造专班在公共界面优化中，一次性定稿不再接收反馈，最终上线后仍频发与习惯不符的障碍。"],"answer":0,"explanation":"「共创反馈环」的构成要件为：①主体为无障碍改造专班；②通过按真实使用路径逐点排查痛点；③使方案贴合真实使用习惯。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01430","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「分级诊疗」是指家庭医生团队通过建立电子档案并定期回访，使患者往返成本下降的工作机制。\n\n按照上述界定，下列情形不应认定为「分级诊疗」的是：","options":["家庭医生团队在重点人群筛查中，建立电子档案并定期回访，患者往返成本下降。","家庭医生团队在康复跟踪记录中，一律先安排住院再评估，最终各环节彼此脱节、患者仍需多次重复排队。","家庭医生团队在慢病随访安排中，建立电子档案并定期回访，患者往返成本下降。","家庭医生团队在康复跟踪记录中，建立电子档案并定期回访，患者往返成本下降。"],"answer":1,"explanation":"「分级诊疗」的构成要件为：①主体为家庭医生团队；②通过建立电子档案并定期回访；③使患者往返成本下降。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（一律先安排住院再评估），因此不符合构成要件。故选B。"},{"id":"pdn01431","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「闭环处置」是指乡镇便民中心通过建立台账逐项限时销号，使居民满意度稳步提升的工作机制。\n\n根据上述定义，下列属于「闭环处置」的是：","options":["乡镇便民中心在老旧小区改造中，建立台账逐项限时销号，居民满意度稳步提升。","乡镇便民中心在邻里纠纷调解中，等群众上门反映后再统一研究，最终问题仍反复出现且未形成稳定机制。","由临时志愿队自行接管，后续也未按上述机制推进。","乡镇便民中心在便民事项办理中，建立台账逐项限时销号，但问题仍反复出现且未形成稳定机制。"],"answer":0,"explanation":"「闭环处置」的构成要件为：①主体为乡镇便民中心；②通过建立台账逐项限时销号；③使居民满意度稳步提升。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01432","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「证据本位决策」是指规划编制组通过用对照组剔除同期其他影响，使后续调整有据可依的工作机制。\n\n依据上述定义，以下哪一项不符合「证据本位决策」的构成要件：","options":["规划编制组在政策效果评估中，用对照组剔除同期其他影响，后续调整有据可依。","规划编制组在政策效果评估中，以主观感受替代实测数据，最终结论无法由所引数据支撑。","规划编制组在抽样数据核查中，用对照组剔除同期其他影响，后续调整有据可依。","规划编制组在年度计划编制中，用对照组剔除同期其他影响，后续调整有据可依。"],"answer":1,"explanation":"「证据本位决策」的构成要件为：①主体为规划编制组；②通过用对照组剔除同期其他影响；③使后续调整有据可依。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（以主观感受替代实测数据），因此不符合构成要件。故选B。"},{"id":"pdn01433","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「冗余备份」是指城市运行管理平台通过设定触发条件并提前布防，使人员与物资提前就位的工作机制。\n\n按照上述界定，下列情形可认定为「冗余备份」的是：","options":["由外部单位事后支援，后续也未按上述机制推进。","城市运行管理平台在风险等级研判中，设定触发条件并提前布防，人员与物资提前就位。","城市运行管理平台在关键节点值守中，设定触发条件并提前布防，但异常发生时无预设动作可依。","城市运行管理平台在响应动作预置中，只在事发后补充记录，最终异常发生时无预设动作可依。"],"answer":1,"explanation":"「冗余备份」的构成要件为：①主体为城市运行管理平台；②通过设定触发条件并提前布防；③使人员与物资提前就位。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01434","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「动态监测」是指生态环境监测站通过划分区块实行差异化管护，使干预强度与实际风险相匹配的工作机制。\n\n根据上述定义，下列不属于「动态监测」的是：","options":["生态环境监测站在栖息环境变化中，全年沿用同一套固定配额，最终指标已越界而措施仍维持不变。","生态环境监测站在栖息环境变化中，划分区块实行差异化管护，干预强度与实际风险相匹配。","生态环境监测站在外来因素扩散中，划分区块实行差异化管护，干预强度与实际风险相匹配。","生态环境监测站在监测指标波动中，划分区块实行差异化管护，干预强度与实际风险相匹配。"],"answer":0,"explanation":"「动态监测」的构成要件为：①主体为生态环境监测站；②通过划分区块实行差异化管护；③使干预强度与实际风险相匹配。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（全年沿用同一套固定配额），因此不符合构成要件。故选A。"},{"id":"pdn01435","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「分级预警」是指城市运行管理平台通过识别薄弱环节并预先加固，使核心功能在异常下仍可维持的工作机制。\n\n依据上述定义，以下哪一项符合「分级预警」的构成要件：","options":["城市运行管理平台在关键节点值守中，识别薄弱环节并预先加固，但异常发生时无预设动作可依。","城市运行管理平台在风险等级研判中，识别薄弱环节并预先加固，核心功能在异常下仍可维持。","城市运行管理平台在响应动作预置中，仅保留一份无备用的关键设备，最终异常发生时无预设动作可依。","由上级在事后统一追认，后续也未按上述机制推进。"],"answer":1,"explanation":"「分级预警」的构成要件为：①主体为城市运行管理平台；②通过识别薄弱环节并预先加固；③使核心功能在异常下仍可维持。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01436","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「差异化供给」是指农技推广站通过先摸清不同群体诉求再分类提供，使冷门项目被及时替换的工作机制。\n\n按照上述界定，下列情形不应认定为「差异化供给」的是：","options":["农技推广站在服务事项梳理中，先摸清不同群体诉求再分类提供，冷门项目被及时替换。","农技推广站在对象需求摸排中，先摸清不同群体诉求再分类提供，冷门项目被及时替换。","农技推广站在服务清单编制中，先摸清不同群体诉求再分类提供，冷门项目被及时替换。","农技推广站在对象需求摸排中，先采购再询问是否需要，最终大量项目无人使用而真实诉求仍被搁置。"],"answer":3,"explanation":"「差异化供给」的构成要件为：①主体为农技推广站；②通过先摸清不同群体诉求再分类提供；③使冷门项目被及时替换。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（先采购再询问是否需要），因此不符合构成要件。故选D。"},{"id":"pdn01437","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「循证施策」是指政策评估小组通过以多源数据交叉校验结论，使成效与措施之间的对应更清楚的工作机制。\n\n根据上述定义，下列属于「循证施策」的是：","options":["政策评估小组在年度计划编制中，以多源数据交叉校验结论，成效与措施之间的对应更清楚。","政策评估小组在抽样数据核查中，以多源数据交叉校验结论，但结论无法由所引数据支撑。","由第三方直接给结论不附依据，后续也未按上述机制推进。","政策评估小组在政策效果评估中，指标口径中途变更却不说明，最终结论无法由所引数据支撑。"],"answer":0,"explanation":"「循证施策」的构成要件为：①主体为政策评估小组；②通过以多源数据交叉校验结论；③使成效与措施之间的对应更清楚。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01438","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「用户旅程映射」是指无障碍改造专班通过邀请使用者全程参与方案打磨，使返工与投诉明显减少的工作机制。\n\n依据上述定义，以下哪一项不符合「用户旅程映射」的构成要件：","options":["无障碍改造专班在服务流程梳理中，邀请使用者全程参与方案打磨，返工与投诉明显减少。","无障碍改造专班在公共界面优化中，仅在完工后征求意见，最终上线后仍频发与习惯不符的障碍。","无障碍改造专班在使用路径排查中，邀请使用者全程参与方案打磨，返工与投诉明显减少。","无障碍改造专班在公共界面优化中，邀请使用者全程参与方案打磨，返工与投诉明显减少。"],"answer":1,"explanation":"「用户旅程映射」的构成要件为：①主体为无障碍改造专班；②通过邀请使用者全程参与方案打磨；③使返工与投诉明显减少。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（仅在完工后征求意见），因此不符合构成要件。故选B。"},{"id":"pdn01439","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「跨界协作」是指街道与职能站所通过共享信息并同步排班，使跨界问题不再悬空的工作机制。\n\n按照上述界定，下列情形可认定为「跨界协作」的是：","options":["由各区各自为政，后续也未按上述机制推进。","街道与职能站所在信息通报共享中，共享信息并同步排班，但边界地带的问题仍在部门之间来回流转。","街道与职能站所在跨界事项梳理中，共享信息并同步排班，跨界问题不再悬空。","街道与职能站所在联合排班安排中，只开会不落责任清单，最终边界地带的问题仍在部门之间来回流转。"],"answer":2,"explanation":"「跨界协作」的构成要件为：①主体为街道与职能站所；②通过共享信息并同步排班；③使跨界问题不再悬空。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01440","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「按需配置」是指公共文化服务中心通过按可选项自主组合形成服务清单，使供给与实际需求更加贴合的工作机制。\n\n根据上述定义，下列不属于「按需配置」的是：","options":["公共文化服务中心在服务事项梳理中，按可选项自主组合形成服务清单，供给与实际需求更加贴合。","公共文化服务中心在对象需求摸排中，按可选项自主组合形成服务清单，供给与实际需求更加贴合。","公共文化服务中心在对象需求摸排中，先采购再询问是否需要，最终大量项目无人使用而真实诉求仍被搁置。","公共文化服务中心在服务清单编制中，按可选项自主组合形成服务清单，供给与实际需求更加贴合。"],"answer":2,"explanation":"「按需配置」的构成要件为：①主体为公共文化服务中心；②通过按可选项自主组合形成服务清单；③使供给与实际需求更加贴合。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（先采购再询问是否需要），因此不符合构成要件。故选C。"},{"id":"pdn01441","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「跨界协作」是指区级牵头部门通过建立常态化联络与移交规则，使处置效率整体提升的工作机制。\n\n依据上述定义，以下哪一项符合「跨界协作」的构成要件：","options":["区级牵头部门在跨界事项梳理中，建立常态化联络与移交规则，处置效率整体提升。","由上级部门包办到底，后续也未按上述机制推进。","区级牵头部门在信息通报共享中，建立常态化联络与移交规则，但边界地带的问题仍在部门之间来回流转。","区级牵头部门在联合排班安排中，各自按本部门旧流程办理，最终边界地带的问题仍在部门之间来回流转。"],"answer":0,"explanation":"「跨界协作」的构成要件为：①主体为区级牵头部门；②通过建立常态化联络与移交规则；③使处置效率整体提升。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01442","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「循证施策」是指政策评估小组通过用对照组剔除同期其他影响，使结论不易被个别异常值带偏的工作机制。\n\n按照上述界定，下列情形不应认定为「循证施策」的是：","options":["政策评估小组在抽样数据核查中，用对照组剔除同期其他影响，结论不易被个别异常值带偏。","政策评估小组在政策效果评估中，只选取有利样本作展示，最终结论无法由所引数据支撑。","政策评估小组在政策效果评估中，用对照组剔除同期其他影响，结论不易被个别异常值带偏。","政策评估小组在年度计划编制中，用对照组剔除同期其他影响，结论不易被个别异常值带偏。"],"answer":1,"explanation":"「循证施策」的构成要件为：①主体为政策评估小组；②通过用对照组剔除同期其他影响；③使结论不易被个别异常值带偏。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（只选取有利样本作展示），因此不符合构成要件。故选B。"},{"id":"pdn01443","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「脱敏处理」是指学校学籍管理系统通过只采集完成本事项所必需的字段，使历史数据不再无限期堆积的工作机制。\n\n根据上述定义，下列属于「脱敏处理」的是：","options":["学校学籍管理系统在字段权限配置中，所有岗位开放同一份全量清单，最终与办理目的无关的字段仍被长期留存。","学校学籍管理系统在信息采集登记中，只采集完成本事项所必需的字段，历史数据不再无限期堆积。","学校学籍管理系统在数据调阅留痕中，只采集完成本事项所必需的字段，但与办理目的无关的字段仍被长期留存。","由外包人员全量导出，后续也未按上述机制推进。"],"answer":1,"explanation":"「脱敏处理」的构成要件为：①主体为学校学籍管理系统；②通过只采集完成本事项所必需的字段；③使历史数据不再无限期堆积。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01444","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「表现性评价」是指课程组通过先摸清起点再设定分层目标，使后续目标更贴合实际起点的工作机制。\n\n依据上述定义，以下哪一项不符合「表现性评价」的构成要件：","options":["课程组在实验课程组织中，先摸清起点再设定分层目标，后续目标更贴合实际起点。","课程组在单元教学设计中，先摸清起点再设定分层目标，后续目标更贴合实际起点。","课程组在实验课程组织中，照搬统一答案不看作答过程，最终教学安排并未因数据而作任何调整。","课程组在作业反馈整理中，先摸清起点再设定分层目标，后续目标更贴合实际起点。"],"answer":2,"explanation":"「表现性评价」的构成要件为：①主体为课程组；②通过先摸清起点再设定分层目标；③使后续目标更贴合实际起点。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（照搬统一答案不看作答过程），因此不符合构成要件。故选C。"},{"id":"pdn01445","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「基线比对」是指项目评审委员会通过先确立基线再对照前后变化，使结论不易被个别异常值带偏的工作机制。\n\n按照上述界定，下列情形可认定为「基线比对」的是：","options":["项目评审委员会在抽样数据核查中，先确立基线再对照前后变化，但结论无法由所引数据支撑。","项目评审委员会在年度计划编制中，先确立基线再对照前后变化，结论不易被个别异常值带偏。","由第三方直接给结论不附依据，后续也未按上述机制推进。","项目评审委员会在政策效果评估中，指标口径中途变更却不说明，最终结论无法由所引数据支撑。"],"answer":1,"explanation":"「基线比对」的构成要件为：①主体为项目评审委员会；②通过先确立基线再对照前后变化；③使结论不易被个别异常值带偏。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01446","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「原型共创」是指无障碍改造专班通过多轮共创后收敛为最终版本，使隐蔽障碍在使用前被暴露的工作机制。\n\n根据上述定义，下列不属于「原型共创」的是：","options":["无障碍改造专班在公共界面优化中，仅在完工后征求意见，最终上线后仍频发与习惯不符的障碍。","无障碍改造专班在公共界面优化中，多轮共创后收敛为最终版本，隐蔽障碍在使用前被暴露。","无障碍改造专班在使用路径排查中，多轮共创后收敛为最终版本，隐蔽障碍在使用前被暴露。","无障碍改造专班在服务流程梳理中，多轮共创后收敛为最终版本，隐蔽障碍在使用前被暴露。"],"answer":0,"explanation":"「原型共创」的构成要件为：①主体为无障碍改造专班；②通过多轮共创后收敛为最终版本；③使隐蔽障碍在使用前被暴露。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（仅在完工后征求意见），因此不符合构成要件。故选A。"},{"id":"pdn01447","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「网格代办」是指乡镇便民中心通过提前公示并逐户征询意见，使重复投诉明显下降的工作机制。\n\n依据上述定义，以下哪一项符合「网格代办」的构成要件：","options":["由临时志愿队自行接管，后续也未按上述机制推进。","乡镇便民中心在便民事项办理中，提前公示并逐户征询意见，但问题仍反复出现且未形成稳定机制。","乡镇便民中心在老旧小区改造中，提前公示并逐户征询意见，重复投诉明显下降。","乡镇便民中心在邻里纠纷调解中，等群众上门反映后再统一研究，最终问题仍反复出现且未形成稳定机制。"],"answer":2,"explanation":"「网格代办」的构成要件为：①主体为乡镇便民中心；②通过提前公示并逐户征询意见；③使重复投诉明显下降。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01448","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「参与式设计」是指产品体验小组通过多轮共创后收敛为最终版本，使改动获得使用者认同的工作机制。\n\n按照上述界定，下列情形不应认定为「参与式设计」的是：","options":["产品体验小组在使用路径排查中，多轮共创后收敛为最终版本，改动获得使用者认同。","产品体验小组在公共界面优化中，照搬其他地区成品，最终上线后仍频发与习惯不符的障碍。","产品体验小组在服务流程梳理中，多轮共创后收敛为最终版本，改动获得使用者认同。","产品体验小组在公共界面优化中，多轮共创后收敛为最终版本，改动获得使用者认同。"],"answer":1,"explanation":"「参与式设计」的构成要件为：①主体为产品体验小组；②通过多轮共创后收敛为最终版本；③使改动获得使用者认同。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（照搬其他地区成品），因此不符合构成要件。故选B。"},{"id":"pdn01449","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「协同会商」是指村委会通过联合多方现场会商后再定方案，使平均处置周期缩短的工作机制。\n\n根据上述定义，下列属于「协同会商」的是：","options":["由服务对象自行申报后不再跟进，后续也未按上述机制推进。","村委会在便民事项办理中，联合多方现场会商后再定方案，但问题仍反复出现且未形成稳定机制。","村委会在老旧小区改造中，联合多方现场会商后再定方案，平均处置周期缩短。","村委会在邻里纠纷调解中，各口径分头办理、彼此不通气，最终问题仍反复出现且未形成稳定机制。"],"answer":2,"explanation":"「协同会商」的构成要件为：①主体为村委会；②通过联合多方现场会商后再定方案；③使平均处置周期缩短。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01450","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「冗余备份」是指数据中心运维组通过识别薄弱环节并预先加固，使险情初起即进入有序处置的工作机制。\n\n依据上述定义，以下哪一项不符合「冗余备份」的构成要件：","options":["数据中心运维组在响应动作预置中，识别薄弱环节并预先加固，险情初起即进入有序处置。","数据中心运维组在关键节点值守中，识别薄弱环节并预先加固，险情初起即进入有序处置。","数据中心运维组在风险等级研判中，识别薄弱环节并预先加固，险情初起即进入有序处置。","数据中心运维组在响应动作预置中，等指标越限后才临时研究方案，最终异常发生时无预设动作可依。"],"answer":3,"explanation":"「冗余备份」的构成要件为：①主体为数据中心运维组；②通过识别薄弱环节并预先加固；③使险情初起即进入有序处置。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（等指标越限后才临时研究方案），因此不符合构成要件。故选D。"},{"id":"pdn01451","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「分级诊疗」是指社区卫生服务中心通过先由基层评估再决定是否上转，使重复检查明显减少的工作机制。\n\n按照上述界定，下列情形可认定为「分级诊疗」的是：","options":["社区卫生服务中心在慢病随访安排中，先由基层评估再决定是否上转，重复检查明显减少。","社区卫生服务中心在重点人群筛查中，先由基层评估再决定是否上转，但各环节彼此脱节、患者仍需多次重复排队。","社区卫生服务中心在康复跟踪记录中，只做一次性检查不作后续跟踪，最终各环节彼此脱节、患者仍需多次重复排队。","仅由三甲医院单方建档，后续也未按上述机制推进。"],"answer":0,"explanation":"「分级诊疗」的构成要件为：①主体为社区卫生服务中心；②通过先由基层评估再决定是否上转；③使重复检查明显减少。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01452","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「分级办理」是指乡镇便民中心通过联合多方现场会商后再定方案，使重复投诉明显下降的工作机制。\n\n根据上述定义，下列不属于「分级办理」的是：","options":["乡镇便民中心在老旧小区改造中，联合多方现场会商后再定方案，重复投诉明显下降。","乡镇便民中心在邻里纠纷调解中，联合多方现场会商后再定方案，重复投诉明显下降。","乡镇便民中心在便民事项办理中，联合多方现场会商后再定方案，重复投诉明显下降。","乡镇便民中心在邻里纠纷调解中，只在事后补录台账，最终问题仍反复出现且未形成稳定机制。"],"answer":3,"explanation":"「分级办理」的构成要件为：①主体为乡镇便民中心；②通过联合多方现场会商后再定方案；③使重复投诉明显下降。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（只在事后补录台账），因此不符合构成要件。故选D。"},{"id":"pdn01453","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「脱敏处理」是指公共服务窗口通过按岗位授予最小可见范围，使历史数据不再无限期堆积的工作机制。\n\n依据上述定义，以下哪一项符合「脱敏处理」的构成要件：","options":["公共服务窗口在信息采集登记中，按岗位授予最小可见范围，历史数据不再无限期堆积。","公共服务窗口在字段权限配置中，超过期限仍不作清理，最终与办理目的无关的字段仍被长期留存。","公共服务窗口在数据调阅留痕中，按岗位授予最小可见范围，但与办理目的无关的字段仍被长期留存。","由系统默认长期全量保留，后续也未按上述机制推进。"],"answer":0,"explanation":"「脱敏处理」的构成要件为：①主体为公共服务窗口；②通过按岗位授予最小可见范围；③使历史数据不再无限期堆积。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01454","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「共创反馈环」是指产品体验小组通过先做可体验原型再收集反馈，使返工与投诉明显减少的工作机制。\n\n按照上述界定，下列情形不应认定为「共创反馈环」的是：","options":["产品体验小组在服务流程梳理中，先做可体验原型再收集反馈，返工与投诉明显减少。","产品体验小组在公共界面优化中，先做可体验原型再收集反馈，返工与投诉明显减少。","产品体验小组在使用路径排查中，先做可体验原型再收集反馈，返工与投诉明显减少。","产品体验小组在公共界面优化中，仅在完工后征求意见，最终上线后仍频发与习惯不符的障碍。"],"answer":3,"explanation":"「共创反馈环」的构成要件为：①主体为产品体验小组；②通过先做可体验原型再收集反馈；③使返工与投诉明显减少。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（仅在完工后征求意见），因此不符合构成要件。故选D。"},{"id":"pdn01455","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「精准匹配」是指就业服务窗口通过先摸清不同群体诉求再分类提供，使冷门项目被及时替换的工作机制。\n\n根据上述定义，下列属于「精准匹配」的是：","options":["就业服务窗口在服务事项梳理中，先摸清不同群体诉求再分类提供，冷门项目被及时替换。","就业服务窗口在服务清单编制中，先摸清不同群体诉求再分类提供，但大量项目无人使用而真实诉求仍被搁置。","就业服务窗口在对象需求摸排中，按编制人数而不是实际用量分配，最终大量项目无人使用而真实诉求仍被搁置。","由供应商单方决定目录，后续也未按上述机制推进。"],"answer":0,"explanation":"「精准匹配」的构成要件为：①主体为就业服务窗口；②通过先摸清不同群体诉求再分类提供；③使冷门项目被及时替换。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01456","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「适应性管理」是指生态环境监测站通过划分区块实行差异化管护，使干预强度与实际风险相匹配的工作机制。\n\n依据上述定义，以下哪一项不符合「适应性管理」的构成要件：","options":["生态环境监测站在栖息环境变化中，划分区块实行差异化管护，干预强度与实际风险相匹配。","生态环境监测站在监测指标波动中，划分区块实行差异化管护，干预强度与实际风险相匹配。","生态环境监测站在栖息环境变化中，只看年度均值忽略峰值，最终指标已越界而措施仍维持不变。","生态环境监测站在外来因素扩散中，划分区块实行差异化管护，干预强度与实际风险相匹配。"],"answer":2,"explanation":"「适应性管理」的构成要件为：①主体为生态环境监测站；②通过划分区块实行差异化管护；③使干预强度与实际风险相匹配。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（只看年度均值忽略峰值），因此不符合构成要件。故选C。"},{"id":"pdn01457","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「数据校验」是指规划编制组通过先确立基线再对照前后变化，使判断建立在可核验的依据上的工作机制。\n\n按照上述界定，下列情形可认定为「数据校验」的是：","options":["规划编制组在政策效果评估中，指标口径中途变更却不说明，最终结论无法由所引数据支撑。","规划编制组在抽样数据核查中，先确立基线再对照前后变化，但结论无法由所引数据支撑。","规划编制组在年度计划编制中，先确立基线再对照前后变化，判断建立在可核验的依据上。","由第三方直接给结论不附依据，后续也未按上述机制推进。"],"answer":2,"explanation":"「数据校验」的构成要件为：①主体为规划编制组；②通过先确立基线再对照前后变化；③使判断建立在可核验的依据上。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01458","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「链条式核验」是指药品批发企业质控部通过异常批次可一键回溯全链路，使责任环节清晰可查的工作机制。\n\n根据上述定义，下列不属于「链条式核验」的是：","options":["药品批发企业质控部在批次交接记录中，异常批次可一键回溯全链路，责任环节清晰可查。","药品批发企业质控部在进货环节核验中，异常批次可一键回溯全链路，责任环节清晰可查。","药品批发企业质控部在储运环节温控中，异常批次可一键回溯全链路，责任环节清晰可查。","药品批发企业质控部在批次交接记录中，只在最终出库时记一笔总账，最终出现问题时无法定位到具体环节。"],"answer":3,"explanation":"「链条式核验」的构成要件为：①主体为药品批发企业质控部；②通过异常批次可一键回溯全链路；③使责任环节清晰可查。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（只在最终出库时记一笔总账），因此不符合构成要件。故选D。"},{"id":"pdn01459","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「菜单式服务」是指农技推广站通过依据使用频次动态增减项目，使资源不再平均摊薄的工作机制。\n\n依据上述定义，以下哪一项符合「菜单式服务」的构成要件：","options":["农技推广站在对象需求摸排中，按编制人数而不是实际用量分配，最终大量项目无人使用而真实诉求仍被搁置。","农技推广站在服务清单编制中，依据使用频次动态增减项目，但大量项目无人使用而真实诉求仍被搁置。","农技推广站在服务事项梳理中，依据使用频次动态增减项目，资源不再平均摊薄。","由供应商单方决定目录，后续也未按上述机制推进。"],"answer":2,"explanation":"「菜单式服务」的构成要件为：①主体为农技推广站；②通过依据使用频次动态增减项目；③使资源不再平均摊薄。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01460","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「网格代办」是指社区网格站通过提前公示并逐户征询意见，使平均处置周期缩短的工作机制。\n\n按照上述界定，下列情形不应认定为「网格代办」的是：","options":["社区网格站在便民事项办理中，提前公示并逐户征询意见，平均处置周期缩短。","社区网格站在邻里纠纷调解中，只在事后补录台账，最终问题仍反复出现且未形成稳定机制。","社区网格站在邻里纠纷调解中，提前公示并逐户征询意见，平均处置周期缩短。","社区网格站在老旧小区改造中，提前公示并逐户征询意见，平均处置周期缩短。"],"answer":1,"explanation":"「网格代办」的构成要件为：①主体为社区网格站；②通过提前公示并逐户征询意见；③使平均处置周期缩短。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（只在事后补录台账），因此不符合构成要件。故选B。"},{"id":"pdn01461","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「基线比对」是指项目评审委员会通过对关键指标作独立复核，使判断建立在可核验的依据上的工作机制。\n\n根据上述定义，下列属于「基线比对」的是：","options":["由第三方直接给结论不附依据，后续也未按上述机制推进。","项目评审委员会在政策效果评估中，指标口径中途变更却不说明，最终结论无法由所引数据支撑。","项目评审委员会在抽样数据核查中，对关键指标作独立复核，但结论无法由所引数据支撑。","项目评审委员会在年度计划编制中，对关键指标作独立复核，判断建立在可核验的依据上。"],"answer":3,"explanation":"「基线比对」的构成要件为：①主体为项目评审委员会；②通过对关键指标作独立复核；③使判断建立在可核验的依据上。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01462","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「数据校验」是指项目评审委员会通过先确立基线再对照前后变化，使成效与措施之间的对应更清楚的工作机制。\n\n依据上述定义，以下哪一项不符合「数据校验」的构成要件：","options":["项目评审委员会在抽样数据核查中，先确立基线再对照前后变化，成效与措施之间的对应更清楚。","项目评审委员会在政策效果评估中，只选取有利样本作展示，最终结论无法由所引数据支撑。","项目评审委员会在年度计划编制中，先确立基线再对照前后变化，成效与措施之间的对应更清楚。","项目评审委员会在政策效果评估中，先确立基线再对照前后变化，成效与措施之间的对应更清楚。"],"answer":1,"explanation":"「数据校验」的构成要件为：①主体为项目评审委员会；②通过先确立基线再对照前后变化；③使成效与措施之间的对应更清楚。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（只选取有利样本作展示），因此不符合构成要件。故选B。"},{"id":"pdn01463","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「随访管理」是指家庭医生团队通过与上级医院共享检查结果，使病情变化能被尽早发现的工作机制。\n\n按照上述界定，下列情形可认定为「随访管理」的是：","options":["家庭医生团队在康复跟踪记录中，只做一次性检查不作后续跟踪，最终各环节彼此脱节、患者仍需多次重复排队。","仅由三甲医院单方建档，后续也未按上述机制推进。","家庭医生团队在慢病随访安排中，与上级医院共享检查结果，病情变化能被尽早发现。","家庭医生团队在重点人群筛查中，与上级医院共享检查结果，但各环节彼此脱节、患者仍需多次重复排队。"],"answer":2,"explanation":"「随访管理」的构成要件为：①主体为家庭医生团队；②通过与上级医院共享检查结果；③使病情变化能被尽早发现。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01464","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「可回溯核查」是指药品批发企业质控部通过异常批次可一键回溯全链路，使台账与实物始终一致的工作机制。\n\n根据上述定义，下列不属于「可回溯核查」的是：","options":["药品批发企业质控部在批次交接记录中，事后一次性补全整本台账，最终出现问题时无法定位到具体环节。","药品批发企业质控部在进货环节核验中，异常批次可一键回溯全链路，台账与实物始终一致。","药品批发企业质控部在批次交接记录中，异常批次可一键回溯全链路，台账与实物始终一致。","药品批发企业质控部在储运环节温控中，异常批次可一键回溯全链路，台账与实物始终一致。"],"answer":0,"explanation":"「可回溯核查」的构成要件为：①主体为药品批发企业质控部；②通过异常批次可一键回溯全链路；③使台账与实物始终一致。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（事后一次性补全整本台账），因此不符合构成要件。故选A。"},{"id":"pdn01465","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「按需配置」是指农技推广站通过先摸清不同群体诉求再分类提供，使供给与实际需求更加贴合的工作机制。\n\n依据上述定义，以下哪一项符合「按需配置」的构成要件：","options":["农技推广站在对象需求摸排中，沿用上一年清单不作修订，最终大量项目无人使用而真实诉求仍被搁置。","农技推广站在服务清单编制中，先摸清不同群体诉求再分类提供，但大量项目无人使用而真实诉求仍被搁置。","农技推广站在服务事项梳理中，先摸清不同群体诉求再分类提供，供给与实际需求更加贴合。","由服务对象自行寻找渠道，后续也未按上述机制推进。"],"answer":2,"explanation":"「按需配置」的构成要件为：①主体为农技推广站；②通过先摸清不同群体诉求再分类提供；③使供给与实际需求更加贴合。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01466","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「目的限定」是指公共服务窗口通过只采集完成本事项所必需的字段，使共享环节不泄露可识别信息的工作机制。\n\n按照上述界定，下列情形不应认定为「目的限定」的是：","options":["公共服务窗口在数据调阅留痕中，只采集完成本事项所必需的字段，共享环节不泄露可识别信息。","公共服务窗口在字段权限配置中，为方便起见一次性收齐全部字段，最终与办理目的无关的字段仍被长期留存。","公共服务窗口在字段权限配置中，只采集完成本事项所必需的字段，共享环节不泄露可识别信息。","公共服务窗口在信息采集登记中，只采集完成本事项所必需的字段，共享环节不泄露可识别信息。"],"answer":1,"explanation":"「目的限定」的构成要件为：①主体为公共服务窗口；②通过只采集完成本事项所必需的字段；③使共享环节不泄露可识别信息。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（为方便起见一次性收齐全部字段），因此不符合构成要件。故选B。"},{"id":"pdn01467","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「形成性评价」是指课程组通过先摸清起点再设定分层目标，使后续目标更贴合实际起点的工作机制。\n\n根据上述定义，下列属于「形成性评价」的是：","options":["课程组在单元教学设计中，先摸清起点再设定分层目标，后续目标更贴合实际起点。","课程组在实验课程组织中，全程不作任何反馈、结束后才公布，最终教学安排并未因数据而作任何调整。","由家长自行报送成绩，后续也未按上述机制推进。","课程组在作业反馈整理中，先摸清起点再设定分层目标，但教学安排并未因数据而作任何调整。"],"answer":0,"explanation":"「形成性评价」的构成要件为：①主体为课程组；②通过先摸清起点再设定分层目标；③使后续目标更贴合实际起点。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01468","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「表现性评价」是指课程组通过随堂记录并及时反馈调整，使后续目标更贴合实际起点的工作机制。\n\n依据上述定义，以下哪一项不符合「表现性评价」的构成要件：","options":["课程组在作业反馈整理中，随堂记录并及时反馈调整，后续目标更贴合实际起点。","课程组在实验课程组织中，随堂记录并及时反馈调整，后续目标更贴合实际起点。","课程组在实验课程组织中，照搬统一答案不看作答过程，最终教学安排并未因数据而作任何调整。","课程组在单元教学设计中，随堂记录并及时反馈调整，后续目标更贴合实际起点。"],"answer":2,"explanation":"「表现性评价」的构成要件为：①主体为课程组；②通过随堂记录并及时反馈调整；③使后续目标更贴合实际起点。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（照搬统一答案不看作答过程），因此不符合构成要件。故选C。"},{"id":"pdn01469","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「分级授权」是指医院信息科通过对外提供前作去标识化处理，使历史数据不再无限期堆积的工作机制。\n\n按照上述界定，下列情形可认定为「分级授权」的是：","options":["医院信息科在数据调阅留痕中，对外提供前作去标识化处理，但与办理目的无关的字段仍被长期留存。","医院信息科在字段权限配置中，超过期限仍不作清理，最终与办理目的无关的字段仍被长期留存。","由系统默认长期全量保留，后续也未按上述机制推进。","医院信息科在信息采集登记中，对外提供前作去标识化处理，历史数据不再无限期堆积。"],"answer":3,"explanation":"「分级授权」的构成要件为：①主体为医院信息科；②通过对外提供前作去标识化处理；③使历史数据不再无限期堆积。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01470","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「协同会商」是指村委会通过建立台账逐项限时销号，使居民满意度稳步提升的工作机制。\n\n根据上述定义，下列不属于「协同会商」的是：","options":["村委会在便民事项办理中，建立台账逐项限时销号，居民满意度稳步提升。","村委会在邻里纠纷调解中，直接照搬既有方案、未作任何征询，最终问题仍反复出现且未形成稳定机制。","村委会在邻里纠纷调解中，建立台账逐项限时销号，居民满意度稳步提升。","村委会在老旧小区改造中，建立台账逐项限时销号，居民满意度稳步提升。"],"answer":1,"explanation":"「协同会商」的构成要件为：①主体为村委会；②通过建立台账逐项限时销号；③使居民满意度稳步提升。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（直接照搬既有方案、未作任何征询），因此不符合构成要件。故选B。"},{"id":"pdn01471","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「用户旅程映射」是指无障碍改造专班通过先做可体验原型再收集反馈，使隐蔽障碍在使用前被暴露的工作机制。\n\n依据上述定义，以下哪一项符合「用户旅程映射」的构成要件：","options":["无障碍改造专班在公共界面优化中，只做内部评审不接触使用者，最终上线后仍频发与习惯不符的障碍。","由供应商提供标准模板，后续也未按上述机制推进。","无障碍改造专班在服务流程梳理中，先做可体验原型再收集反馈，隐蔽障碍在使用前被暴露。","无障碍改造专班在使用路径排查中，先做可体验原型再收集反馈，但上线后仍频发与习惯不符的障碍。"],"answer":2,"explanation":"「用户旅程映射」的构成要件为：①主体为无障碍改造专班；②通过先做可体验原型再收集反馈；③使隐蔽障碍在使用前被暴露。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01472","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「过程性考核」是指区域教研中心通过结合真实任务表现打分，使学习过程而非仅结果被看见的工作机制。\n\n按照上述界定，下列情形不应认定为「过程性考核」的是：","options":["区域教研中心在实验课程组织中，照搬统一答案不看作答过程，最终教学安排并未因数据而作任何调整。","区域教研中心在实验课程组织中，结合真实任务表现打分，学习过程而非仅结果被看见。","区域教研中心在作业反馈整理中，结合真实任务表现打分，学习过程而非仅结果被看见。","区域教研中心在单元教学设计中，结合真实任务表现打分，学习过程而非仅结果被看见。"],"answer":0,"explanation":"「过程性考核」的构成要件为：①主体为区域教研中心；②通过结合真实任务表现打分；③使学习过程而非仅结果被看见。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（照搬统一答案不看作答过程），因此不符合构成要件。故选A。"},{"id":"pdn01473","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「目的限定」是指公共服务窗口通过到期自动清理并留清理记录，使共享环节不泄露可识别信息的工作机制。\n\n根据上述定义，下列属于「目的限定」的是：","options":["公共服务窗口在字段权限配置中，超过期限仍不作清理，最终与办理目的无关的字段仍被长期留存。","由系统默认长期全量保留，后续也未按上述机制推进。","公共服务窗口在数据调阅留痕中，到期自动清理并留清理记录，但与办理目的无关的字段仍被长期留存。","公共服务窗口在信息采集登记中，到期自动清理并留清理记录，共享环节不泄露可识别信息。"],"answer":3,"explanation":"「目的限定」的构成要件为：①主体为公共服务窗口；②通过到期自动清理并留清理记录；③使共享环节不泄露可识别信息。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01474","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「联合响应」是指流域联席会议通过共享信息并同步排班，使重复检查与推诿明显减少的工作机制。\n\n依据上述定义，以下哪一项不符合「联合响应」的构成要件：","options":["流域联席会议在跨界事项梳理中，共享信息并同步排班，重复检查与推诿明显减少。","流域联席会议在联合排班安排中，各部门分头进场、结果互不通报，最终边界地带的问题仍在部门之间来回流转。","流域联席会议在联合排班安排中，共享信息并同步排班，重复检查与推诿明显减少。","流域联席会议在信息通报共享中，共享信息并同步排班，重复检查与推诿明显减少。"],"answer":1,"explanation":"「联合响应」的构成要件为：①主体为流域联席会议；②通过共享信息并同步排班；③使重复检查与推诿明显减少。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（各部门分头进场、结果互不通报），因此不符合构成要件。故选B。"},{"id":"pdn01475","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「协同治理」是指区级牵头部门通过共享信息并同步排班，使重复检查与推诿明显减少的工作机制。\n\n按照上述界定，下列情形可认定为「协同治理」的是：","options":["区级牵头部门在信息通报共享中，共享信息并同步排班，但边界地带的问题仍在部门之间来回流转。","区级牵头部门在联合排班安排中，只开会不落责任清单，最终边界地带的问题仍在部门之间来回流转。","由各区各自为政，后续也未按上述机制推进。","区级牵头部门在跨界事项梳理中，共享信息并同步排班，重复检查与推诿明显减少。"],"answer":3,"explanation":"「协同治理」的构成要件为：①主体为区级牵头部门；②通过共享信息并同步排班；③使重复检查与推诿明显减少。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01476","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「预案触发」是指数据中心运维组通过按风险等级预置响应动作，使核心功能在异常下仍可维持的工作机制。\n\n根据上述定义，下列不属于「预案触发」的是：","options":["数据中心运维组在响应动作预置中，按风险等级预置响应动作，核心功能在异常下仍可维持。","数据中心运维组在响应动作预置中，预案长期封存不随风险更新，最终异常发生时无预设动作可依。","数据中心运维组在关键节点值守中，按风险等级预置响应动作，核心功能在异常下仍可维持。","数据中心运维组在风险等级研判中，按风险等级预置响应动作，核心功能在异常下仍可维持。"],"answer":1,"explanation":"「预案触发」的构成要件为：①主体为数据中心运维组；②通过按风险等级预置响应动作；③使核心功能在异常下仍可维持。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（预案长期封存不随风险更新），因此不符合构成要件。故选B。"},{"id":"pdn01477","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「联勤联动」是指区级牵头部门通过明确牵头与配合边界后统一行动，使响应口径保持一致的工作机制。\n\n依据上述定义，以下哪一项符合「联勤联动」的构成要件：","options":["区级牵头部门在联合排班安排中，各自按本部门旧流程办理，最终边界地带的问题仍在部门之间来回流转。","区级牵头部门在信息通报共享中，明确牵头与配合边界后统一行动，但边界地带的问题仍在部门之间来回流转。","区级牵头部门在跨界事项梳理中，明确牵头与配合边界后统一行动，响应口径保持一致。","由上级部门包办到底，后续也未按上述机制推进。"],"answer":2,"explanation":"「联勤联动」的构成要件为：①主体为区级牵头部门；②通过明确牵头与配合边界后统一行动；③使响应口径保持一致。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01478","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「阈值预警」是指流域管理机构通过划分区块实行差异化管护，使异常苗头被尽早识别的工作机制。\n\n按照上述界定，下列情形不应认定为「阈值预警」的是：","options":["流域管理机构在栖息环境变化中，全年沿用同一套固定配额，最终指标已越界而措施仍维持不变。","流域管理机构在外来因素扩散中，划分区块实行差异化管护，异常苗头被尽早识别。","流域管理机构在监测指标波动中，划分区块实行差异化管护，异常苗头被尽早识别。","流域管理机构在栖息环境变化中，划分区块实行差异化管护，异常苗头被尽早识别。"],"answer":0,"explanation":"「阈值预警」的构成要件为：①主体为流域管理机构；②通过划分区块实行差异化管护；③使异常苗头被尽早识别。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（全年沿用同一套固定配额），因此不符合构成要件。故选A。"},{"id":"pdn01479","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「目的限定」是指医院信息科通过按岗位授予最小可见范围，使共享环节不泄露可识别信息的工作机制。\n\n根据上述定义，下列属于「目的限定」的是：","options":["由外包人员全量导出，后续也未按上述机制推进。","医院信息科在数据调阅留痕中，按岗位授予最小可见范围，但与办理目的无关的字段仍被长期留存。","医院信息科在字段权限配置中，所有岗位开放同一份全量清单，最终与办理目的无关的字段仍被长期留存。","医院信息科在信息采集登记中，按岗位授予最小可见范围，共享环节不泄露可识别信息。"],"answer":3,"explanation":"「目的限定」的构成要件为：①主体为医院信息科；②通过按岗位授予最小可见范围；③使共享环节不泄露可识别信息。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01480","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「随访管理」是指乡镇卫生院通过先由基层评估再决定是否上转，使重复检查明显减少的工作机制。\n\n依据上述定义，以下哪一项不符合「随访管理」的构成要件：","options":["乡镇卫生院在康复跟踪记录中，先由基层评估再决定是否上转，重复检查明显减少。","乡镇卫生院在康复跟踪记录中，各机构各自重复开单，最终各环节彼此脱节、患者仍需多次重复排队。","乡镇卫生院在重点人群筛查中，先由基层评估再决定是否上转，重复检查明显减少。","乡镇卫生院在慢病随访安排中，先由基层评估再决定是否上转，重复检查明显减少。"],"answer":1,"explanation":"「随访管理」的构成要件为：①主体为乡镇卫生院；②通过先由基层评估再决定是否上转；③使重复检查明显减少。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（各机构各自重复开单），因此不符合构成要件。故选B。"},{"id":"pdn01481","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「脆弱性评估」是指应急指挥中心通过设定触发条件并提前布防，使核心功能在异常下仍可维持的工作机制。\n\n按照上述界定，下列情形可认定为「脆弱性评估」的是：","options":["应急指挥中心在响应动作预置中，只在事发后补充记录，最终异常发生时无预设动作可依。","应急指挥中心在关键节点值守中，设定触发条件并提前布防，但异常发生时无预设动作可依。","应急指挥中心在风险等级研判中，设定触发条件并提前布防，核心功能在异常下仍可维持。","由外部单位事后支援，后续也未按上述机制推进。"],"answer":2,"explanation":"「脆弱性评估」的构成要件为：①主体为应急指挥中心；②通过设定触发条件并提前布防；③使核心功能在异常下仍可维持。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01482","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「形成性评价」是指学校教研组通过结合真实任务表现打分，使学生的薄弱点被及时识别的工作机制。\n\n根据上述定义，下列不属于「形成性评价」的是：","options":["学校教研组在作业反馈整理中，结合真实任务表现打分，学生的薄弱点被及时识别。","学校教研组在实验课程组织中，只以期末一次分数定结论，最终教学安排并未因数据而作任何调整。","学校教研组在单元教学设计中，结合真实任务表现打分，学生的薄弱点被及时识别。","学校教研组在实验课程组织中，结合真实任务表现打分，学生的薄弱点被及时识别。"],"answer":1,"explanation":"「形成性评价」的构成要件为：①主体为学校教研组；②通过结合真实任务表现打分；③使学生的薄弱点被及时识别。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（只以期末一次分数定结论），因此不符合构成要件。故选B。"},{"id":"pdn01483","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「脱敏处理」是指政务数据平台通过对外提供前作去标识化处理，使历史数据不再无限期堆积的工作机制。\n\n依据上述定义，以下哪一项符合「脱敏处理」的构成要件：","options":["政务数据平台在字段权限配置中，所有岗位开放同一份全量清单，最终与办理目的无关的字段仍被长期留存。","政务数据平台在信息采集登记中，对外提供前作去标识化处理，历史数据不再无限期堆积。","政务数据平台在数据调阅留痕中，对外提供前作去标识化处理，但与办理目的无关的字段仍被长期留存。","由外包人员全量导出，后续也未按上述机制推进。"],"answer":1,"explanation":"「脱敏处理」的构成要件为：①主体为政务数据平台；②通过对外提供前作去标识化处理；③使历史数据不再无限期堆积。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01484","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「最小必要采集」是指政务数据平台通过只采集完成本事项所必需的字段，使历史数据不再无限期堆积的工作机制。\n\n按照上述界定，下列情形不应认定为「最小必要采集」的是：","options":["政务数据平台在信息采集登记中，只采集完成本事项所必需的字段，历史数据不再无限期堆积。","政务数据平台在数据调阅留痕中，只采集完成本事项所必需的字段，历史数据不再无限期堆积。","政务数据平台在字段权限配置中，只采集完成本事项所必需的字段，历史数据不再无限期堆积。","政务数据平台在字段权限配置中，共享时直接提供原始明细，最终与办理目的无关的字段仍被长期留存。"],"answer":3,"explanation":"「最小必要采集」的构成要件为：①主体为政务数据平台；②通过只采集完成本事项所必需的字段；③使历史数据不再无限期堆积。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（共享时直接提供原始明细），因此不符合构成要件。故选D。"},{"id":"pdn01485","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「需求导向供给」是指公共文化服务中心通过按对象条件分档配置资源，使资源不再平均摊薄的工作机制。\n\n根据上述定义，下列属于「需求导向供给」的是：","options":["公共文化服务中心在对象需求摸排中，沿用上一年清单不作修订，最终大量项目无人使用而真实诉求仍被搁置。","由服务对象自行寻找渠道，后续也未按上述机制推进。","公共文化服务中心在服务清单编制中，按对象条件分档配置资源，但大量项目无人使用而真实诉求仍被搁置。","公共文化服务中心在服务事项梳理中，按对象条件分档配置资源，资源不再平均摊薄。"],"answer":3,"explanation":"「需求导向供给」的构成要件为：①主体为公共文化服务中心；②通过按对象条件分档配置资源；③使资源不再平均摊薄。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01486","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「数据校验」是指政策评估小组通过用对照组剔除同期其他影响，使结论不易被个别异常值带偏的工作机制。\n\n依据上述定义，以下哪一项不符合「数据校验」的构成要件：","options":["政策评估小组在政策效果评估中，用对照组剔除同期其他影响，结论不易被个别异常值带偏。","政策评估小组在年度计划编制中，用对照组剔除同期其他影响，结论不易被个别异常值带偏。","政策评估小组在抽样数据核查中，用对照组剔除同期其他影响，结论不易被个别异常值带偏。","政策评估小组在政策效果评估中，只选取有利样本作展示，最终结论无法由所引数据支撑。"],"answer":3,"explanation":"「数据校验」的构成要件为：①主体为政策评估小组；②通过用对照组剔除同期其他影响；③使结论不易被个别异常值带偏。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（只选取有利样本作展示），因此不符合构成要件。故选D。"},{"id":"pdn01487","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「随访管理」是指家庭医生团队通过建立电子档案并定期回访，使病情变化能被尽早发现的工作机制。\n\n按照上述界定，下列情形可认定为「随访管理」的是：","options":["仅由三甲医院单方建档，后续也未按上述机制推进。","家庭医生团队在康复跟踪记录中，只做一次性检查不作后续跟踪，最终各环节彼此脱节、患者仍需多次重复排队。","家庭医生团队在慢病随访安排中，建立电子档案并定期回访，病情变化能被尽早发现。","家庭医生团队在重点人群筛查中，建立电子档案并定期回访，但各环节彼此脱节、患者仍需多次重复排队。"],"answer":2,"explanation":"「随访管理」的构成要件为：①主体为家庭医生团队；②通过建立电子档案并定期回访；③使病情变化能被尽早发现。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01488","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「增值评价」是指课程组通过结合真实任务表现打分，使后续目标更贴合实际起点的工作机制。\n\n根据上述定义，下列不属于「增值评价」的是：","options":["课程组在实验课程组织中，结合真实任务表现打分，后续目标更贴合实际起点。","课程组在实验课程组织中，照搬统一答案不看作答过程，最终教学安排并未因数据而作任何调整。","课程组在作业反馈整理中，结合真实任务表现打分，后续目标更贴合实际起点。","课程组在单元教学设计中，结合真实任务表现打分，后续目标更贴合实际起点。"],"answer":1,"explanation":"「增值评价」的构成要件为：①主体为课程组；②通过结合真实任务表现打分；③使后续目标更贴合实际起点。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（照搬统一答案不看作答过程），因此不符合构成要件。故选B。"},{"id":"pdn01489","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「留存限期」是指医院信息科通过对外提供前作去标识化处理，使历史数据不再无限期堆积的工作机制。\n\n依据上述定义，以下哪一项符合「留存限期」的构成要件：","options":["医院信息科在字段权限配置中，超过期限仍不作清理，最终与办理目的无关的字段仍被长期留存。","由系统默认长期全量保留，后续也未按上述机制推进。","医院信息科在信息采集登记中，对外提供前作去标识化处理，历史数据不再无限期堆积。","医院信息科在数据调阅留痕中，对外提供前作去标识化处理，但与办理目的无关的字段仍被长期留存。"],"answer":2,"explanation":"「留存限期」的构成要件为：①主体为医院信息科；②通过对外提供前作去标识化处理；③使历史数据不再无限期堆积。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01490","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「弹性调控」是指生态环境监测站通过随季节数据滚动修订方案，使干预强度与实际风险相匹配的工作机制。\n\n按照上述界定，下列情形不应认定为「弹性调控」的是：","options":["生态环境监测站在监测指标波动中，随季节数据滚动修订方案，干预强度与实际风险相匹配。","生态环境监测站在栖息环境变化中，全年沿用同一套固定配额，最终指标已越界而措施仍维持不变。","生态环境监测站在栖息环境变化中，随季节数据滚动修订方案，干预强度与实际风险相匹配。","生态环境监测站在外来因素扩散中，随季节数据滚动修订方案，干预强度与实际风险相匹配。"],"answer":1,"explanation":"「弹性调控」的构成要件为：①主体为生态环境监测站；②通过随季节数据滚动修订方案；③使干预强度与实际风险相匹配。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（全年沿用同一套固定配额），因此不符合构成要件。故选B。"},{"id":"pdn01491","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「跨界协作」是指街道与职能站所通过一次会商形成分工清单，使跨界问题不再悬空的工作机制。\n\n根据上述定义，下列属于「跨界协作」的是：","options":["由各区各自为政，后续也未按上述机制推进。","街道与职能站所在跨界事项梳理中，一次会商形成分工清单，跨界问题不再悬空。","街道与职能站所在信息通报共享中，一次会商形成分工清单，但边界地带的问题仍在部门之间来回流转。","街道与职能站所在联合排班安排中，只开会不落责任清单，最终边界地带的问题仍在部门之间来回流转。"],"answer":1,"explanation":"「跨界协作」的构成要件为：①主体为街道与职能站所；②通过一次会商形成分工清单；③使跨界问题不再悬空。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01492","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「数据校验」是指项目评审委员会通过以多源数据交叉校验结论，使成效与措施之间的对应更清楚的工作机制。\n\n依据上述定义，以下哪一项不符合「数据校验」的构成要件：","options":["项目评审委员会在政策效果评估中，以多源数据交叉校验结论，成效与措施之间的对应更清楚。","项目评审委员会在抽样数据核查中，以多源数据交叉校验结论，成效与措施之间的对应更清楚。","项目评审委员会在年度计划编制中，以多源数据交叉校验结论，成效与措施之间的对应更清楚。","项目评审委员会在政策效果评估中，以主观感受替代实测数据，最终结论无法由所引数据支撑。"],"answer":3,"explanation":"「数据校验」的构成要件为：①主体为项目评审委员会；②通过以多源数据交叉校验结论；③使成效与措施之间的对应更清楚。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（以主观感受替代实测数据），因此不符合构成要件。故选D。"},{"id":"pdn01493","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「多元共治」是指区级牵头部门通过共享信息并同步排班，使重复检查与推诿明显减少的工作机制。\n\n按照上述界定，下列情形可认定为「多元共治」的是：","options":["由上级部门包办到底，后续也未按上述机制推进。","区级牵头部门在信息通报共享中，共享信息并同步排班，但边界地带的问题仍在部门之间来回流转。","区级牵头部门在跨界事项梳理中，共享信息并同步排班，重复检查与推诿明显减少。","区级牵头部门在联合排班安排中，各自按本部门旧流程办理，最终边界地带的问题仍在部门之间来回流转。"],"answer":2,"explanation":"「多元共治」的构成要件为：①主体为区级牵头部门；②通过共享信息并同步排班；③使重复检查与推诿明显减少。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01494","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「小步试点」是指改革推进专班通过分批次扩面而非一次铺开，使风险被限制在可控范围的工作机制。\n\n根据上述定义，下列不属于「小步试点」的是：","options":["改革推进专班在新工具推广中，不经试点直接全面强制推开，最终同类偏差在扩面后被成倍放大。","改革推进专班在新工具推广中，分批次扩面而非一次铺开，风险被限制在可控范围。","改革推进专班在新机制落地中，分批次扩面而非一次铺开，风险被限制在可控范围。","改革推进专班在新流程上线中，分批次扩面而非一次铺开，风险被限制在可控范围。"],"answer":0,"explanation":"「小步试点」的构成要件为：①主体为改革推进专班；②通过分批次扩面而非一次铺开；③使风险被限制在可控范围。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（不经试点直接全面强制推开），因此不符合构成要件。故选A。"},{"id":"pdn01495","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「动态监测」是指流域管理机构通过随季节数据滚动修订方案，使干预强度与实际风险相匹配的工作机制。\n\n依据上述定义，以下哪一项符合「动态监测」的构成要件：","options":["流域管理机构在外来因素扩散中，随季节数据滚动修订方案，但指标已越界而措施仍维持不变。","流域管理机构在栖息环境变化中，指标超标后仍不调整，最终指标已越界而措施仍维持不变。","由邻近地区照抄方案，后续也未按上述机制推进。","流域管理机构在监测指标波动中，随季节数据滚动修订方案，干预强度与实际风险相匹配。"],"answer":3,"explanation":"「动态监测」的构成要件为：①主体为流域管理机构；②通过随季节数据滚动修订方案；③使干预强度与实际风险相匹配。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01496","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「需求导向供给」是指农技推广站通过依据使用频次动态增减项目，使供给与实际需求更加贴合的工作机制。\n\n按照上述界定，下列情形不应认定为「需求导向供给」的是：","options":["农技推广站在服务事项梳理中，依据使用频次动态增减项目，供给与实际需求更加贴合。","农技推广站在对象需求摸排中，依据使用频次动态增减项目，供给与实际需求更加贴合。","农技推广站在对象需求摸排中，先采购再询问是否需要，最终大量项目无人使用而真实诉求仍被搁置。","农技推广站在服务清单编制中，依据使用频次动态增减项目，供给与实际需求更加贴合。"],"answer":2,"explanation":"「需求导向供给」的构成要件为：①主体为农技推广站；②通过依据使用频次动态增减项目；③使供给与实际需求更加贴合。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（先采购再询问是否需要），因此不符合构成要件。故选C。"},{"id":"pdn01497","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「最小必要采集」是指医院信息科通过对外提供前作去标识化处理，使超范围信息不被额外索取的工作机制。\n\n根据上述定义，下列属于「最小必要采集」的是：","options":["医院信息科在字段权限配置中，超过期限仍不作清理，最终与办理目的无关的字段仍被长期留存。","由系统默认长期全量保留，后续也未按上述机制推进。","医院信息科在数据调阅留痕中，对外提供前作去标识化处理，但与办理目的无关的字段仍被长期留存。","医院信息科在信息采集登记中，对外提供前作去标识化处理，超范围信息不被额外索取。"],"answer":3,"explanation":"「最小必要采集」的构成要件为：①主体为医院信息科；②通过对外提供前作去标识化处理；③使超范围信息不被额外索取。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01498","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「参与式设计」是指公共服务设计组通过按真实使用路径逐点排查痛点，使方案贴合真实使用习惯的工作机制。\n\n依据上述定义，以下哪一项不符合「参与式设计」的构成要件：","options":["公共服务设计组在公共界面优化中，仅在完工后征求意见，最终上线后仍频发与习惯不符的障碍。","公共服务设计组在使用路径排查中，按真实使用路径逐点排查痛点，方案贴合真实使用习惯。","公共服务设计组在公共界面优化中，按真实使用路径逐点排查痛点，方案贴合真实使用习惯。","公共服务设计组在服务流程梳理中，按真实使用路径逐点排查痛点，方案贴合真实使用习惯。"],"answer":0,"explanation":"「参与式设计」的构成要件为：①主体为公共服务设计组；②通过按真实使用路径逐点排查痛点；③使方案贴合真实使用习惯。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（仅在完工后征求意见），因此不符合构成要件。故选A。"},{"id":"pdn01499","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「形成性评价」是指任课教师团队通过结合真实任务表现打分，使学生的薄弱点被及时识别的工作机制。\n\n按照上述界定，下列情形可认定为「形成性评价」的是：","options":["任课教师团队在实验课程组织中，全程不作任何反馈、结束后才公布，最终教学安排并未因数据而作任何调整。","任课教师团队在作业反馈整理中，结合真实任务表现打分，但教学安排并未因数据而作任何调整。","由家长自行报送成绩，后续也未按上述机制推进。","任课教师团队在单元教学设计中，结合真实任务表现打分，学生的薄弱点被及时识别。"],"answer":3,"explanation":"「形成性评价」的构成要件为：①主体为任课教师团队；②通过结合真实任务表现打分；③使学生的薄弱点被及时识别。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01500","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「诊断性测评」是指任课教师团队通过随堂记录并及时反馈调整，使学生的薄弱点被及时识别的工作机制。\n\n根据上述定义，下列不属于「诊断性测评」的是：","options":["任课教师团队在实验课程组织中，随堂记录并及时反馈调整，学生的薄弱点被及时识别。","任课教师团队在单元教学设计中，随堂记录并及时反馈调整，学生的薄弱点被及时识别。","任课教师团队在作业反馈整理中，随堂记录并及时反馈调整，学生的薄弱点被及时识别。","任课教师团队在实验课程组织中，照搬统一答案不看作答过程，最终教学安排并未因数据而作任何调整。"],"answer":3,"explanation":"「诊断性测评」的构成要件为：①主体为任课教师团队；②通过随堂记录并及时反馈调整；③使学生的薄弱点被及时识别。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（照搬统一答案不看作答过程），因此不符合构成要件。故选D。"},{"id":"pdn01501","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「脆弱性评估」是指数据中心运维组通过按风险等级预置响应动作，使险情初起即进入有序处置的工作机制。\n\n依据上述定义，以下哪一项符合「脆弱性评估」的构成要件：","options":["由外部单位事后支援，后续也未按上述机制推进。","数据中心运维组在响应动作预置中，只在事发后补充记录，最终异常发生时无预设动作可依。","数据中心运维组在风险等级研判中，按风险等级预置响应动作，险情初起即进入有序处置。","数据中心运维组在关键节点值守中，按风险等级预置响应动作，但异常发生时无预设动作可依。"],"answer":2,"explanation":"「脆弱性评估」的构成要件为：①主体为数据中心运维组；②通过按风险等级预置响应动作；③使险情初起即进入有序处置。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01502","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「全过程追溯」是指冷链运营方通过关键节点双人签认留档，使问题批次能被快速定位的工作机制。\n\n按照上述界定，下列情形不应认定为「全过程追溯」的是：","options":["冷链运营方在进货环节核验中，关键节点双人签认留档，问题批次能被快速定位。","冷链运营方在储运环节温控中，关键节点双人签认留档，问题批次能被快速定位。","冷链运营方在批次交接记录中，关键节点双人签认留档，问题批次能被快速定位。","冷链运营方在批次交接记录中，只在最终出库时记一笔总账，最终出现问题时无法定位到具体环节。"],"answer":3,"explanation":"「全过程追溯」的构成要件为：①主体为冷链运营方；②通过关键节点双人签认留档；③使问题批次能被快速定位。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（只在最终出库时记一笔总账），因此不符合构成要件。故选D。"},{"id":"pdn01503","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「留痕管理」是指食品药品监管所通过异常批次可一键回溯全链路，使问题批次能被快速定位的工作机制。\n\n根据上述定义，下列属于「留痕管理」的是：","options":["由终端门店自行补记，后续也未按上述机制推进。","食品药品监管所在进货环节核验中，异常批次可一键回溯全链路，问题批次能被快速定位。","食品药品监管所在储运环节温控中，异常批次可一键回溯全链路，但出现问题时无法定位到具体环节。","食品药品监管所在批次交接记录中，各环节各自记录且互不关联，最终出现问题时无法定位到具体环节。"],"answer":1,"explanation":"「留痕管理」的构成要件为：①主体为食品药品监管所；②通过异常批次可一键回溯全链路；③使问题批次能被快速定位。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01504","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「弹性调控」是指流域管理机构通过随季节数据滚动修订方案，使异常苗头被尽早识别的工作机制。\n\n依据上述定义，以下哪一项不符合「弹性调控」的构成要件：","options":["流域管理机构在监测指标波动中，随季节数据滚动修订方案，异常苗头被尽早识别。","流域管理机构在栖息环境变化中，只看年度均值忽略峰值，最终指标已越界而措施仍维持不变。","流域管理机构在栖息环境变化中，随季节数据滚动修订方案，异常苗头被尽早识别。","流域管理机构在外来因素扩散中，随季节数据滚动修订方案，异常苗头被尽早识别。"],"answer":1,"explanation":"「弹性调控」的构成要件为：①主体为流域管理机构；②通过随季节数据滚动修订方案；③使异常苗头被尽早识别。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（只看年度均值忽略峰值），因此不符合构成要件。故选B。"},{"id":"pdn01505","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「脱敏处理」是指公共服务窗口通过到期自动清理并留清理记录，使敏感字段仅在授权场景可见的工作机制。\n\n按照上述界定，下列情形可认定为「脱敏处理」的是：","options":["公共服务窗口在字段权限配置中，超过期限仍不作清理，最终与办理目的无关的字段仍被长期留存。","公共服务窗口在数据调阅留痕中，到期自动清理并留清理记录，但与办理目的无关的字段仍被长期留存。","公共服务窗口在信息采集登记中，到期自动清理并留清理记录，敏感字段仅在授权场景可见。","由系统默认长期全量保留，后续也未按上述机制推进。"],"answer":2,"explanation":"「脱敏处理」的构成要件为：①主体为公共服务窗口；②通过到期自动清理并留清理记录；③使敏感字段仅在授权场景可见。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01506","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「共创工作坊」是指产品体验小组通过多轮共创后收敛为最终版本，使方案贴合真实使用习惯的工作机制。\n\n根据上述定义，下列不属于「共创工作坊」的是：","options":["产品体验小组在公共界面优化中，多轮共创后收敛为最终版本，方案贴合真实使用习惯。","产品体验小组在使用路径排查中，多轮共创后收敛为最终版本，方案贴合真实使用习惯。","产品体验小组在公共界面优化中，仅在完工后征求意见，最终上线后仍频发与习惯不符的障碍。","产品体验小组在服务流程梳理中，多轮共创后收敛为最终版本，方案贴合真实使用习惯。"],"answer":2,"explanation":"「共创工作坊」的构成要件为：①主体为产品体验小组；②通过多轮共创后收敛为最终版本；③使方案贴合真实使用习惯。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（仅在完工后征求意见），因此不符合构成要件。故选C。"},{"id":"pdn01507","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「留痕管理」是指食品药品监管所通过每一节点登记并关联上下游凭证，使责任环节清晰可查的工作机制。\n\n依据上述定义，以下哪一项符合「留痕管理」的构成要件：","options":["由终端门店自行补记，后续也未按上述机制推进。","食品药品监管所在储运环节温控中，每一节点登记并关联上下游凭证，但出现问题时无法定位到具体环节。","食品药品监管所在批次交接记录中，各环节各自记录且互不关联，最终出现问题时无法定位到具体环节。","食品药品监管所在进货环节核验中，每一节点登记并关联上下游凭证，责任环节清晰可查。"],"answer":3,"explanation":"「留痕管理」的构成要件为：①主体为食品药品监管所；②通过每一节点登记并关联上下游凭证；③使责任环节清晰可查。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01508","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「证据本位决策」是指统计调查队通过对关键指标作独立复核，使成效与措施之间的对应更清楚的工作机制。\n\n按照上述界定，下列情形不应认定为「证据本位决策」的是：","options":["统计调查队在年度计划编制中，对关键指标作独立复核，成效与措施之间的对应更清楚。","统计调查队在政策效果评估中，以主观感受替代实测数据，最终结论无法由所引数据支撑。","统计调查队在抽样数据核查中，对关键指标作独立复核，成效与措施之间的对应更清楚。","统计调查队在政策效果评估中，对关键指标作独立复核，成效与措施之间的对应更清楚。"],"answer":1,"explanation":"「证据本位决策」的构成要件为：①主体为统计调查队；②通过对关键指标作独立复核；③使成效与措施之间的对应更清楚。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（以主观感受替代实测数据），因此不符合构成要件。故选B。"},{"id":"pdn01509","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「原型共创」是指产品体验小组通过先做可体验原型再收集反馈，使返工与投诉明显减少的工作机制。\n\n根据上述定义，下列属于「原型共创」的是：","options":["由外部专家远程定稿，后续也未按上述机制推进。","产品体验小组在使用路径排查中，先做可体验原型再收集反馈，但上线后仍频发与习惯不符的障碍。","产品体验小组在服务流程梳理中，先做可体验原型再收集反馈，返工与投诉明显减少。","产品体验小组在公共界面优化中，一次性定稿不再接收反馈，最终上线后仍频发与习惯不符的障碍。"],"answer":2,"explanation":"「原型共创」的构成要件为：①主体为产品体验小组；②通过先做可体验原型再收集反馈；③使返工与投诉明显减少。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01510","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「前置筛查」是指乡镇卫生院通过建立电子档案并定期回访，使重复检查明显减少的工作机制。\n\n依据上述定义，以下哪一项不符合「前置筛查」的构成要件：","options":["乡镇卫生院在重点人群筛查中，建立电子档案并定期回访，重复检查明显减少。","乡镇卫生院在康复跟踪记录中，一律先安排住院再评估，最终各环节彼此脱节、患者仍需多次重复排队。","乡镇卫生院在慢病随访安排中，建立电子档案并定期回访，重复检查明显减少。","乡镇卫生院在康复跟踪记录中，建立电子档案并定期回访，重复检查明显减少。"],"answer":1,"explanation":"「前置筛查」的构成要件为：①主体为乡镇卫生院；②通过建立电子档案并定期回访；③使重复检查明显减少。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（一律先安排住院再评估），因此不符合构成要件。故选B。"},{"id":"pdn01511","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「小步试点」是指产品迭代小组通过先在小范围试运行再按反馈调整，使风险被限制在可控范围的工作机制。\n\n按照上述界定，下列情形可认定为「小步试点」的是：","options":["由外部团队一次性交付即结束，后续也未按上述机制推进。","产品迭代小组在新工具推广中，试运行期间禁止任何修改，最终同类偏差在扩面后被成倍放大。","产品迭代小组在新流程上线中，先在小范围试运行再按反馈调整，风险被限制在可控范围。","产品迭代小组在新机制落地中，先在小范围试运行再按反馈调整，但同类偏差在扩面后被成倍放大。"],"answer":2,"explanation":"「小步试点」的构成要件为：①主体为产品迭代小组；②通过先在小范围试运行再按反馈调整；③使风险被限制在可控范围。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01512","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「需求导向供给」是指就业服务窗口通过按可选项自主组合形成服务清单，使冷门项目被及时替换的工作机制。\n\n根据上述定义，下列不属于「需求导向供给」的是：","options":["就业服务窗口在对象需求摸排中，先采购再询问是否需要，最终大量项目无人使用而真实诉求仍被搁置。","就业服务窗口在服务事项梳理中，按可选项自主组合形成服务清单，冷门项目被及时替换。","就业服务窗口在对象需求摸排中，按可选项自主组合形成服务清单，冷门项目被及时替换。","就业服务窗口在服务清单编制中，按可选项自主组合形成服务清单，冷门项目被及时替换。"],"answer":0,"explanation":"「需求导向供给」的构成要件为：①主体为就业服务窗口；②通过按可选项自主组合形成服务清单；③使冷门项目被及时替换。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（先采购再询问是否需要），因此不符合构成要件。故选A。"},{"id":"pdn01513","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「按需配置」是指就业服务窗口通过先摸清不同群体诉求再分类提供，使不同群体各取所需的工作机制。\n\n依据上述定义，以下哪一项符合「按需配置」的构成要件：","options":["就业服务窗口在对象需求摸排中，沿用上一年清单不作修订，最终大量项目无人使用而真实诉求仍被搁置。","就业服务窗口在服务事项梳理中，先摸清不同群体诉求再分类提供，不同群体各取所需。","就业服务窗口在服务清单编制中，先摸清不同群体诉求再分类提供，但大量项目无人使用而真实诉求仍被搁置。","由服务对象自行寻找渠道，后续也未按上述机制推进。"],"answer":1,"explanation":"「按需配置」的构成要件为：①主体为就业服务窗口；②通过先摸清不同群体诉求再分类提供；③使不同群体各取所需。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01514","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「节点责任制」是指食品药品监管所通过每一节点登记并关联上下游凭证，使问题批次能被快速定位的工作机制。\n\n按照上述界定，下列情形不应认定为「节点责任制」的是：","options":["食品药品监管所在储运环节温控中，每一节点登记并关联上下游凭证，问题批次能被快速定位。","食品药品监管所在进货环节核验中，每一节点登记并关联上下游凭证，问题批次能被快速定位。","食品药品监管所在批次交接记录中，只在最终出库时记一笔总账，最终出现问题时无法定位到具体环节。","食品药品监管所在批次交接记录中，每一节点登记并关联上下游凭证，问题批次能被快速定位。"],"answer":2,"explanation":"「节点责任制」的构成要件为：①主体为食品药品监管所；②通过每一节点登记并关联上下游凭证；③使问题批次能被快速定位。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（只在最终出库时记一笔总账），因此不符合构成要件。故选C。"},{"id":"pdn01515","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「用户旅程映射」是指产品体验小组通过先做可体验原型再收集反馈，使返工与投诉明显减少的工作机制。\n\n根据上述定义，下列属于「用户旅程映射」的是：","options":["由供应商提供标准模板，后续也未按上述机制推进。","产品体验小组在公共界面优化中，只做内部评审不接触使用者，最终上线后仍频发与习惯不符的障碍。","产品体验小组在服务流程梳理中，先做可体验原型再收集反馈，返工与投诉明显减少。","产品体验小组在使用路径排查中，先做可体验原型再收集反馈，但上线后仍频发与习惯不符的障碍。"],"answer":2,"explanation":"「用户旅程映射」的构成要件为：①主体为产品体验小组；②通过先做可体验原型再收集反馈；③使返工与投诉明显减少。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01516","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「差异化供给」是指公共文化服务中心通过按对象条件分档配置资源，使不同群体各取所需的工作机制。\n\n依据上述定义，以下哪一项不符合「差异化供给」的构成要件：","options":["公共文化服务中心在服务事项梳理中，按对象条件分档配置资源，不同群体各取所需。","公共文化服务中心在服务清单编制中，按对象条件分档配置资源，不同群体各取所需。","公共文化服务中心在对象需求摸排中，先采购再询问是否需要，最终大量项目无人使用而真实诉求仍被搁置。","公共文化服务中心在对象需求摸排中，按对象条件分档配置资源，不同群体各取所需。"],"answer":2,"explanation":"「差异化供给」的构成要件为：①主体为公共文化服务中心；②通过按对象条件分档配置资源；③使不同群体各取所需。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（先采购再询问是否需要），因此不符合构成要件。故选C。"},{"id":"pdn01517","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「联勤联动」是指区级牵头部门通过一次会商形成分工清单，使跨界问题不再悬空的工作机制。\n\n按照上述界定，下列情形可认定为「联勤联动」的是：","options":["区级牵头部门在联合排班安排中，各自按本部门旧流程办理，最终边界地带的问题仍在部门之间来回流转。","区级牵头部门在信息通报共享中，一次会商形成分工清单，但边界地带的问题仍在部门之间来回流转。","区级牵头部门在跨界事项梳理中，一次会商形成分工清单，跨界问题不再悬空。","由上级部门包办到底，后续也未按上述机制推进。"],"answer":2,"explanation":"「联勤联动」的构成要件为：①主体为区级牵头部门；②通过一次会商形成分工清单；③使跨界问题不再悬空。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01518","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「分区管控」是指自然保护区管理局通过设定阈值并触发分级响应，使干预强度与实际风险相匹配的工作机制。\n\n根据上述定义，下列不属于「分区管控」的是：","options":["自然保护区管理局在监测指标波动中，设定阈值并触发分级响应，干预强度与实际风险相匹配。","自然保护区管理局在栖息环境变化中，全年沿用同一套固定配额，最终指标已越界而措施仍维持不变。","自然保护区管理局在外来因素扩散中，设定阈值并触发分级响应，干预强度与实际风险相匹配。","自然保护区管理局在栖息环境变化中，设定阈值并触发分级响应，干预强度与实际风险相匹配。"],"answer":1,"explanation":"「分区管控」的构成要件为：①主体为自然保护区管理局；②通过设定阈值并触发分级响应；③使干预强度与实际风险相匹配。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（全年沿用同一套固定配额），因此不符合构成要件。故选B。"},{"id":"pdn01519","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「数据校验」是指政策评估小组通过以多源数据交叉校验结论，使成效与措施之间的对应更清楚的工作机制。\n\n依据上述定义，以下哪一项符合「数据校验」的构成要件：","options":["政策评估小组在政策效果评估中，用总量变化直接归因、不作对照，最终结论无法由所引数据支撑。","政策评估小组在年度计划编制中，以多源数据交叉校验结论，成效与措施之间的对应更清楚。","由申报方自行填报不作核实，后续也未按上述机制推进。","政策评估小组在抽样数据核查中，以多源数据交叉校验结论，但结论无法由所引数据支撑。"],"answer":1,"explanation":"「数据校验」的构成要件为：①主体为政策评估小组；②通过以多源数据交叉校验结论；③使成效与措施之间的对应更清楚。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01520","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「需求导向供给」是指农技推广站通过按可选项自主组合形成服务清单，使冷门项目被及时替换的工作机制。\n\n按照上述界定，下列情形不应认定为「需求导向供给」的是：","options":["农技推广站在对象需求摸排中，先采购再询问是否需要，最终大量项目无人使用而真实诉求仍被搁置。","农技推广站在服务清单编制中，按可选项自主组合形成服务清单，冷门项目被及时替换。","农技推广站在对象需求摸排中，按可选项自主组合形成服务清单，冷门项目被及时替换。","农技推广站在服务事项梳理中，按可选项自主组合形成服务清单，冷门项目被及时替换。"],"answer":0,"explanation":"「需求导向供给」的构成要件为：①主体为农技推广站；②通过按可选项自主组合形成服务清单；③使冷门项目被及时替换。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（先采购再询问是否需要），因此不符合构成要件。故选A。"},{"id":"pdn01521","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「阈值预警」是指自然保护区管理局通过设定阈值并触发分级响应，使核心栖息地得到有效避让的工作机制。\n\n根据上述定义，下列属于「阈值预警」的是：","options":["自然保护区管理局在监测指标波动中，设定阈值并触发分级响应，核心栖息地得到有效避让。","自然保护区管理局在栖息环境变化中，等出现明显损害后再启动处置，最终指标已越界而措施仍维持不变。","由游客反馈临时决定，后续也未按上述机制推进。","自然保护区管理局在外来因素扩散中，设定阈值并触发分级响应，但指标已越界而措施仍维持不变。"],"answer":0,"explanation":"「阈值预警」的构成要件为：①主体为自然保护区管理局；②通过设定阈值并触发分级响应；③使核心栖息地得到有效避让。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01522","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「共创反馈环」是指公共服务设计组通过邀请使用者全程参与方案打磨，使返工与投诉明显减少的工作机制。\n\n依据上述定义，以下哪一项不符合「共创反馈环」的构成要件：","options":["公共服务设计组在使用路径排查中，邀请使用者全程参与方案打磨，返工与投诉明显减少。","公共服务设计组在公共界面优化中，邀请使用者全程参与方案打磨，返工与投诉明显减少。","公共服务设计组在服务流程梳理中，邀请使用者全程参与方案打磨，返工与投诉明显减少。","公共服务设计组在公共界面优化中，仅在完工后征求意见，最终上线后仍频发与习惯不符的障碍。"],"answer":3,"explanation":"「共创反馈环」的构成要件为：①主体为公共服务设计组；②通过邀请使用者全程参与方案打磨；③使返工与投诉明显减少。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（仅在完工后征求意见），因此不符合构成要件。故选D。"},{"id":"pdn01523","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「节点责任制」是指药品批发企业质控部通过按批号串联台账与检验记录，使责任环节清晰可查的工作机制。\n\n按照上述界定，下列情形可认定为「节点责任制」的是：","options":["药品批发企业质控部在储运环节温控中，按批号串联台账与检验记录，但出现问题时无法定位到具体环节。","由终端门店自行补记，后续也未按上述机制推进。","药品批发企业质控部在进货环节核验中，按批号串联台账与检验记录，责任环节清晰可查。","药品批发企业质控部在批次交接记录中，各环节各自记录且互不关联，最终出现问题时无法定位到具体环节。"],"answer":2,"explanation":"「节点责任制」的构成要件为：①主体为药品批发企业质控部；②通过按批号串联台账与检验记录；③使责任环节清晰可查。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01524","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「连续照护」是指乡镇卫生院通过与上级医院共享检查结果，使轻症在基层得到及时处置的工作机制。\n\n根据上述定义，下列不属于「连续照护」的是：","options":["乡镇卫生院在重点人群筛查中，与上级医院共享检查结果，轻症在基层得到及时处置。","乡镇卫生院在康复跟踪记录中，各机构各自重复开单，最终各环节彼此脱节、患者仍需多次重复排队。","乡镇卫生院在慢病随访安排中，与上级医院共享检查结果，轻症在基层得到及时处置。","乡镇卫生院在康复跟踪记录中，与上级医院共享检查结果，轻症在基层得到及时处置。"],"answer":1,"explanation":"「连续照护」的构成要件为：①主体为乡镇卫生院；②通过与上级医院共享检查结果；③使轻症在基层得到及时处置。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（各机构各自重复开单），因此不符合构成要件。故选B。"},{"id":"pdn01525","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「弹性调控」是指自然保护区管理局通过划分区块实行差异化管护，使干预强度与实际风险相匹配的工作机制。\n\n依据上述定义，以下哪一项符合「弹性调控」的构成要件：","options":["自然保护区管理局在监测指标波动中，划分区块实行差异化管护，干预强度与实际风险相匹配。","自然保护区管理局在外来因素扩散中，划分区块实行差异化管护，但指标已越界而措施仍维持不变。","由游客反馈临时决定，后续也未按上述机制推进。","自然保护区管理局在栖息环境变化中，等出现明显损害后再启动处置，最终指标已越界而措施仍维持不变。"],"answer":0,"explanation":"「弹性调控」的构成要件为：①主体为自然保护区管理局；②通过划分区块实行差异化管护；③使干预强度与实际风险相匹配。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01526","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「分级诊疗」是指家庭医生团队通过建立电子档案并定期回访，使重复检查明显减少的工作机制。\n\n按照上述界定，下列情形不应认定为「分级诊疗」的是：","options":["家庭医生团队在重点人群筛查中，建立电子档案并定期回访，重复检查明显减少。","家庭医生团队在慢病随访安排中，建立电子档案并定期回访，重复检查明显减少。","家庭医生团队在康复跟踪记录中，建立电子档案并定期回访，重复检查明显减少。","家庭医生团队在康复跟踪记录中，一律先安排住院再评估，最终各环节彼此脱节、患者仍需多次重复排队。"],"answer":3,"explanation":"「分级诊疗」的构成要件为：①主体为家庭医生团队；②通过建立电子档案并定期回访；③使重复检查明显减少。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（一律先安排住院再评估），因此不符合构成要件。故选D。"},{"id":"pdn01527","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「灰度验证」是指政策试点工作组通过每轮结束后复盘并修订下一轮，使偏差在放大前被修正的工作机制。\n\n根据上述定义，下列属于「灰度验证」的是：","options":["政策试点工作组在新工具推广中，试运行期间禁止任何修改，最终同类偏差在扩面后被成倍放大。","政策试点工作组在新机制落地中，每轮结束后复盘并修订下一轮，但同类偏差在扩面后被成倍放大。","政策试点工作组在新流程上线中，每轮结束后复盘并修订下一轮，偏差在放大前被修正。","由外部团队一次性交付即结束，后续也未按上述机制推进。"],"answer":2,"explanation":"「灰度验证」的构成要件为：①主体为政策试点工作组；②通过每轮结束后复盘并修订下一轮；③使偏差在放大前被修正。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01528","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「基线比对」是指统计调查队通过以多源数据交叉校验结论，使成效与措施之间的对应更清楚的工作机制。\n\n依据上述定义，以下哪一项不符合「基线比对」的构成要件：","options":["统计调查队在政策效果评估中，以多源数据交叉校验结论，成效与措施之间的对应更清楚。","统计调查队在抽样数据核查中，以多源数据交叉校验结论，成效与措施之间的对应更清楚。","统计调查队在政策效果评估中，以主观感受替代实测数据，最终结论无法由所引数据支撑。","统计调查队在年度计划编制中，以多源数据交叉校验结论，成效与措施之间的对应更清楚。"],"answer":2,"explanation":"「基线比对」的构成要件为：①主体为统计调查队；②通过以多源数据交叉校验结论；③使成效与措施之间的对应更清楚。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（以主观感受替代实测数据），因此不符合构成要件。故选C。"},{"id":"pdn01529","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「脆弱性评估」是指应急指挥中心通过设定触发条件并提前布防，使险情初起即进入有序处置的工作机制。\n\n按照上述界定，下列情形可认定为「脆弱性评估」的是：","options":["应急指挥中心在响应动作预置中，只在事发后补充记录，最终异常发生时无预设动作可依。","由外部单位事后支援，后续也未按上述机制推进。","应急指挥中心在关键节点值守中，设定触发条件并提前布防，但异常发生时无预设动作可依。","应急指挥中心在风险等级研判中，设定触发条件并提前布防，险情初起即进入有序处置。"],"answer":3,"explanation":"「脆弱性评估」的构成要件为：①主体为应急指挥中心；②通过设定触发条件并提前布防；③使险情初起即进入有序处置。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01530","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「联勤联动」是指流域联席会议通过建立常态化联络与移交规则，使跨界问题不再悬空的工作机制。\n\n根据上述定义，下列不属于「联勤联动」的是：","options":["流域联席会议在联合排班安排中，各部门分头进场、结果互不通报，最终边界地带的问题仍在部门之间来回流转。","流域联席会议在信息通报共享中，建立常态化联络与移交规则，跨界问题不再悬空。","流域联席会议在联合排班安排中，建立常态化联络与移交规则，跨界问题不再悬空。","流域联席会议在跨界事项梳理中，建立常态化联络与移交规则，跨界问题不再悬空。"],"answer":0,"explanation":"「联勤联动」的构成要件为：①主体为流域联席会议；②通过建立常态化联络与移交规则；③使跨界问题不再悬空。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（各部门分头进场、结果互不通报），因此不符合构成要件。故选A。"},{"id":"pdn01531","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「循证施策」是指政策评估小组通过先确立基线再对照前后变化，使成效与措施之间的对应更清楚的工作机制。\n\n依据上述定义，以下哪一项符合「循证施策」的构成要件：","options":["政策评估小组在抽样数据核查中，先确立基线再对照前后变化，但结论无法由所引数据支撑。","政策评估小组在年度计划编制中，先确立基线再对照前后变化，成效与措施之间的对应更清楚。","由申报方自行填报不作核实，后续也未按上述机制推进。","政策评估小组在政策效果评估中，用总量变化直接归因、不作对照，最终结论无法由所引数据支撑。"],"answer":1,"explanation":"「循证施策」的构成要件为：①主体为政策评估小组；②通过先确立基线再对照前后变化；③使成效与措施之间的对应更清楚。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01532","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「留存限期」是指学校学籍管理系统通过到期自动清理并留清理记录，使敏感字段仅在授权场景可见的工作机制。\n\n按照上述界定，下列情形不应认定为「留存限期」的是：","options":["学校学籍管理系统在字段权限配置中，到期自动清理并留清理记录，敏感字段仅在授权场景可见。","学校学籍管理系统在字段权限配置中，共享时直接提供原始明细，最终与办理目的无关的字段仍被长期留存。","学校学籍管理系统在数据调阅留痕中，到期自动清理并留清理记录，敏感字段仅在授权场景可见。","学校学籍管理系统在信息采集登记中，到期自动清理并留清理记录，敏感字段仅在授权场景可见。"],"answer":1,"explanation":"「留存限期」的构成要件为：①主体为学校学籍管理系统；②通过到期自动清理并留清理记录；③使敏感字段仅在授权场景可见。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（共享时直接提供原始明细），因此不符合构成要件。故选B。"},{"id":"pdn01533","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「基线比对」是指项目评审委员会通过对关键指标作独立复核，使后续调整有据可依的工作机制。\n\n根据上述定义，下列属于「基线比对」的是：","options":["项目评审委员会在年度计划编制中，对关键指标作独立复核，后续调整有据可依。","由第三方直接给结论不附依据，后续也未按上述机制推进。","项目评审委员会在抽样数据核查中，对关键指标作独立复核，但结论无法由所引数据支撑。","项目评审委员会在政策效果评估中，指标口径中途变更却不说明，最终结论无法由所引数据支撑。"],"answer":0,"explanation":"「基线比对」的构成要件为：①主体为项目评审委员会；②通过对关键指标作独立复核；③使后续调整有据可依。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01534","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「留存限期」是指学校学籍管理系统通过按岗位授予最小可见范围，使敏感字段仅在授权场景可见的工作机制。\n\n依据上述定义，以下哪一项不符合「留存限期」的构成要件：","options":["学校学籍管理系统在字段权限配置中，为方便起见一次性收齐全部字段，最终与办理目的无关的字段仍被长期留存。","学校学籍管理系统在字段权限配置中，按岗位授予最小可见范围，敏感字段仅在授权场景可见。","学校学籍管理系统在数据调阅留痕中，按岗位授予最小可见范围，敏感字段仅在授权场景可见。","学校学籍管理系统在信息采集登记中，按岗位授予最小可见范围，敏感字段仅在授权场景可见。"],"answer":0,"explanation":"「留存限期」的构成要件为：①主体为学校学籍管理系统；②通过按岗位授予最小可见范围；③使敏感字段仅在授权场景可见。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（为方便起见一次性收齐全部字段），因此不符合构成要件。故选A。"},{"id":"pdn01535","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「容错纠偏」是指数字化转型办公室通过先在小范围试运行再按反馈调整，使风险被限制在可控范围的工作机制。\n\n按照上述界定，下列情形可认定为「容错纠偏」的是：","options":["数字化转型办公室在新工具推广中，试运行期间禁止任何修改，最终同类偏差在扩面后被成倍放大。","数字化转型办公室在新机制落地中，先在小范围试运行再按反馈调整，但同类偏差在扩面后被成倍放大。","数字化转型办公室在新流程上线中，先在小范围试运行再按反馈调整，风险被限制在可控范围。","由外部团队一次性交付即结束，后续也未按上述机制推进。"],"answer":2,"explanation":"「容错纠偏」的构成要件为：①主体为数字化转型办公室；②通过先在小范围试运行再按反馈调整；③使风险被限制在可控范围。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01536","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「全过程追溯」是指药品批发企业质控部通过异常批次可一键回溯全链路，使责任环节清晰可查的工作机制。\n\n根据上述定义，下列不属于「全过程追溯」的是：","options":["药品批发企业质控部在批次交接记录中，异常批次可一键回溯全链路，责任环节清晰可查。","药品批发企业质控部在进货环节核验中，异常批次可一键回溯全链路，责任环节清晰可查。","药品批发企业质控部在批次交接记录中，事后一次性补全整本台账，最终出现问题时无法定位到具体环节。","药品批发企业质控部在储运环节温控中，异常批次可一键回溯全链路，责任环节清晰可查。"],"answer":2,"explanation":"「全过程追溯」的构成要件为：①主体为药品批发企业质控部；②通过异常批次可一键回溯全链路；③使责任环节清晰可查。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（事后一次性补全整本台账），因此不符合构成要件。故选C。"},{"id":"pdn01537","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「前置响应」是指街道办通过建立台账逐项限时销号，使诉求在前端得到化解的工作机制。\n\n依据上述定义，以下哪一项符合「前置响应」的构成要件：","options":["由服务对象自行申报后不再跟进，后续也未按上述机制推进。","街道办在邻里纠纷调解中，各口径分头办理、彼此不通气，最终问题仍反复出现且未形成稳定机制。","街道办在老旧小区改造中，建立台账逐项限时销号，诉求在前端得到化解。","街道办在便民事项办理中，建立台账逐项限时销号，但问题仍反复出现且未形成稳定机制。"],"answer":2,"explanation":"「前置响应」的构成要件为：①主体为街道办；②通过建立台账逐项限时销号；③使诉求在前端得到化解。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01538","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「差异化供给」是指公共文化服务中心通过先摸清不同群体诉求再分类提供，使资源不再平均摊薄的工作机制。\n\n按照上述界定，下列情形不应认定为「差异化供给」的是：","options":["公共文化服务中心在对象需求摸排中，所有对象发放完全相同的固定包，最终大量项目无人使用而真实诉求仍被搁置。","公共文化服务中心在服务事项梳理中，先摸清不同群体诉求再分类提供，资源不再平均摊薄。","公共文化服务中心在服务清单编制中，先摸清不同群体诉求再分类提供，资源不再平均摊薄。","公共文化服务中心在对象需求摸排中，先摸清不同群体诉求再分类提供，资源不再平均摊薄。"],"answer":0,"explanation":"「差异化供给」的构成要件为：①主体为公共文化服务中心；②通过先摸清不同群体诉求再分类提供；③使资源不再平均摊薄。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（所有对象发放完全相同的固定包），因此不符合构成要件。故选A。"},{"id":"pdn01539","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「形成性评价」是指区域教研中心通过按阶段采集学情数据再修正教学，使教学策略得以动态优化的工作机制。\n\n根据上述定义，下列属于「形成性评价」的是：","options":["区域教研中心在实验课程组织中，全程不作任何反馈、结束后才公布，最终教学安排并未因数据而作任何调整。","由家长自行报送成绩，后续也未按上述机制推进。","区域教研中心在单元教学设计中，按阶段采集学情数据再修正教学，教学策略得以动态优化。","区域教研中心在作业反馈整理中，按阶段采集学情数据再修正教学，但教学安排并未因数据而作任何调整。"],"answer":2,"explanation":"「形成性评价」的构成要件为：①主体为区域教研中心；②通过按阶段采集学情数据再修正教学；③使教学策略得以动态优化。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01540","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「诊断性测评」是指课程组通过随堂记录并及时反馈调整，使后续目标更贴合实际起点的工作机制。\n\n依据上述定义，以下哪一项不符合「诊断性测评」的构成要件：","options":["课程组在实验课程组织中，照搬统一答案不看作答过程，最终教学安排并未因数据而作任何调整。","课程组在单元教学设计中，随堂记录并及时反馈调整，后续目标更贴合实际起点。","课程组在实验课程组织中，随堂记录并及时反馈调整，后续目标更贴合实际起点。","课程组在作业反馈整理中，随堂记录并及时反馈调整，后续目标更贴合实际起点。"],"answer":0,"explanation":"「诊断性测评」的构成要件为：①主体为课程组；②通过随堂记录并及时反馈调整；③使后续目标更贴合实际起点。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（照搬统一答案不看作答过程），因此不符合构成要件。故选A。"},{"id":"pdn01541","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「冗余备份」是指数据中心运维组通过设定触发条件并提前布防，使次生影响被压到最小的工作机制。\n\n按照上述界定，下列情形可认定为「冗余备份」的是：","options":["数据中心运维组在响应动作预置中，只在事发后补充记录，最终异常发生时无预设动作可依。","由外部单位事后支援，后续也未按上述机制推进。","数据中心运维组在关键节点值守中，设定触发条件并提前布防，但异常发生时无预设动作可依。","数据中心运维组在风险等级研判中，设定触发条件并提前布防，次生影响被压到最小。"],"answer":3,"explanation":"「冗余备份」的构成要件为：①主体为数据中心运维组；②通过设定触发条件并提前布防；③使次生影响被压到最小。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01542","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「阈值预警」是指流域管理机构通过随季节数据滚动修订方案，使异常苗头被尽早识别的工作机制。\n\n根据上述定义，下列不属于「阈值预警」的是：","options":["流域管理机构在栖息环境变化中，随季节数据滚动修订方案，异常苗头被尽早识别。","流域管理机构在监测指标波动中，随季节数据滚动修订方案，异常苗头被尽早识别。","流域管理机构在外来因素扩散中，随季节数据滚动修订方案，异常苗头被尽早识别。","流域管理机构在栖息环境变化中，全年沿用同一套固定配额，最终指标已越界而措施仍维持不变。"],"answer":3,"explanation":"「阈值预警」的构成要件为：①主体为流域管理机构；②通过随季节数据滚动修订方案；③使异常苗头被尽早识别。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（全年沿用同一套固定配额），因此不符合构成要件。故选D。"},{"id":"pdn01543","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「联勤联动」是指区级牵头部门通过一次会商形成分工清单，使响应口径保持一致的工作机制。\n\n依据上述定义，以下哪一项符合「联勤联动」的构成要件：","options":["由各区各自为政，后续也未按上述机制推进。","区级牵头部门在信息通报共享中，一次会商形成分工清单，但边界地带的问题仍在部门之间来回流转。","区级牵头部门在联合排班安排中，只开会不落责任清单，最终边界地带的问题仍在部门之间来回流转。","区级牵头部门在跨界事项梳理中，一次会商形成分工清单，响应口径保持一致。"],"answer":3,"explanation":"「联勤联动」的构成要件为：①主体为区级牵头部门；②通过一次会商形成分工清单；③使响应口径保持一致。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01544","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「最小必要采集」是指政务数据平台通过到期自动清理并留清理记录，使共享环节不泄露可识别信息的工作机制。\n\n按照上述界定，下列情形不应认定为「最小必要采集」的是：","options":["政务数据平台在信息采集登记中，到期自动清理并留清理记录，共享环节不泄露可识别信息。","政务数据平台在字段权限配置中，共享时直接提供原始明细，最终与办理目的无关的字段仍被长期留存。","政务数据平台在字段权限配置中，到期自动清理并留清理记录，共享环节不泄露可识别信息。","政务数据平台在数据调阅留痕中，到期自动清理并留清理记录，共享环节不泄露可识别信息。"],"answer":1,"explanation":"「最小必要采集」的构成要件为：①主体为政务数据平台；②通过到期自动清理并留清理记录；③使共享环节不泄露可识别信息。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（共享时直接提供原始明细），因此不符合构成要件。故选B。"},{"id":"pdn01545","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「留痕管理」是指药品批发企业质控部通过异常批次可一键回溯全链路，使问题批次能被快速定位的工作机制。\n\n根据上述定义，下列属于「留痕管理」的是：","options":["药品批发企业质控部在进货环节核验中，异常批次可一键回溯全链路，问题批次能被快速定位。","药品批发企业质控部在储运环节温控中，异常批次可一键回溯全链路，但出现问题时无法定位到具体环节。","药品批发企业质控部在批次交接记录中，仅保留汇总数不留明细，最终出现问题时无法定位到具体环节。","由消费者事后反馈倒查，后续也未按上述机制推进。"],"answer":0,"explanation":"「留痕管理」的构成要件为：①主体为药品批发企业质控部；②通过异常批次可一键回溯全链路；③使问题批次能被快速定位。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01546","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「联勤联动」是指区级牵头部门通过建立常态化联络与移交规则，使响应口径保持一致的工作机制。\n\n依据上述定义，以下哪一项不符合「联勤联动」的构成要件：","options":["区级牵头部门在联合排班安排中，建立常态化联络与移交规则，响应口径保持一致。","区级牵头部门在信息通报共享中，建立常态化联络与移交规则，响应口径保持一致。","区级牵头部门在跨界事项梳理中，建立常态化联络与移交规则，响应口径保持一致。","区级牵头部门在联合排班安排中，各部门分头进场、结果互不通报，最终边界地带的问题仍在部门之间来回流转。"],"answer":3,"explanation":"「联勤联动」的构成要件为：①主体为区级牵头部门；②通过建立常态化联络与移交规则；③使响应口径保持一致。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（各部门分头进场、结果互不通报），因此不符合构成要件。故选D。"},{"id":"pdn01547","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「按需配置」是指农技推广站通过按对象条件分档配置资源，使不同群体各取所需的工作机制。\n\n按照上述界定，下列情形可认定为「按需配置」的是：","options":["农技推广站在对象需求摸排中，按编制人数而不是实际用量分配，最终大量项目无人使用而真实诉求仍被搁置。","由供应商单方决定目录，后续也未按上述机制推进。","农技推广站在服务清单编制中，按对象条件分档配置资源，但大量项目无人使用而真实诉求仍被搁置。","农技推广站在服务事项梳理中，按对象条件分档配置资源，不同群体各取所需。"],"answer":3,"explanation":"「按需配置」的构成要件为：①主体为农技推广站；②通过按对象条件分档配置资源；③使不同群体各取所需。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01548","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「分级办理」是指村委会通过提前公示并逐户征询意见，使重复投诉明显下降的工作机制。\n\n根据上述定义，下列不属于「分级办理」的是：","options":["村委会在便民事项办理中，提前公示并逐户征询意见，重复投诉明显下降。","村委会在邻里纠纷调解中，只在事后补录台账，最终问题仍反复出现且未形成稳定机制。","村委会在老旧小区改造中，提前公示并逐户征询意见，重复投诉明显下降。","村委会在邻里纠纷调解中，提前公示并逐户征询意见，重复投诉明显下降。"],"answer":1,"explanation":"「分级办理」的构成要件为：①主体为村委会；②通过提前公示并逐户征询意见；③使重复投诉明显下降。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（只在事后补录台账），因此不符合构成要件。故选B。"},{"id":"pdn01549","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「需求导向供给」是指就业服务窗口通过按对象条件分档配置资源，使资源不再平均摊薄的工作机制。\n\n依据上述定义，以下哪一项符合「需求导向供给」的构成要件：","options":["就业服务窗口在服务清单编制中，按对象条件分档配置资源，但大量项目无人使用而真实诉求仍被搁置。","就业服务窗口在服务事项梳理中，按对象条件分档配置资源，资源不再平均摊薄。","就业服务窗口在对象需求摸排中，沿用上一年清单不作修订，最终大量项目无人使用而真实诉求仍被搁置。","由服务对象自行寻找渠道，后续也未按上述机制推进。"],"answer":1,"explanation":"「需求导向供给」的构成要件为：①主体为就业服务窗口；②通过按对象条件分档配置资源；③使资源不再平均摊薄。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01550","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「参与式设计」是指社区营造团队通过多轮共创后收敛为最终版本，使方案贴合真实使用习惯的工作机制。\n\n按照上述界定，下列情形不应认定为「参与式设计」的是：","options":["社区营造团队在公共界面优化中，多轮共创后收敛为最终版本，方案贴合真实使用习惯。","社区营造团队在公共界面优化中，仅在完工后征求意见，最终上线后仍频发与习惯不符的障碍。","社区营造团队在使用路径排查中，多轮共创后收敛为最终版本，方案贴合真实使用习惯。","社区营造团队在服务流程梳理中，多轮共创后收敛为最终版本，方案贴合真实使用习惯。"],"answer":1,"explanation":"「参与式设计」的构成要件为：①主体为社区营造团队；②通过多轮共创后收敛为最终版本；③使方案贴合真实使用习惯。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（仅在完工后征求意见），因此不符合构成要件。故选B。"},{"id":"pdn01551","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「指标复核」是指项目评审委员会通过用对照组剔除同期其他影响，使成效与措施之间的对应更清楚的工作机制。\n\n根据上述定义，下列属于「指标复核」的是：","options":["项目评审委员会在政策效果评估中，用总量变化直接归因、不作对照，最终结论无法由所引数据支撑。","由申报方自行填报不作核实，后续也未按上述机制推进。","项目评审委员会在年度计划编制中，用对照组剔除同期其他影响，成效与措施之间的对应更清楚。","项目评审委员会在抽样数据核查中，用对照组剔除同期其他影响，但结论无法由所引数据支撑。"],"answer":2,"explanation":"「指标复核」的构成要件为：①主体为项目评审委员会；②通过用对照组剔除同期其他影响；③使成效与措施之间的对应更清楚。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01552","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「分级办理」是指村委会通过联合多方现场会商后再定方案，使平均处置周期缩短的工作机制。\n\n依据上述定义，以下哪一项不符合「分级办理」的构成要件：","options":["村委会在便民事项办理中，联合多方现场会商后再定方案，平均处置周期缩短。","村委会在邻里纠纷调解中，只在事后补录台账，最终问题仍反复出现且未形成稳定机制。","村委会在邻里纠纷调解中，联合多方现场会商后再定方案，平均处置周期缩短。","村委会在老旧小区改造中，联合多方现场会商后再定方案，平均处置周期缩短。"],"answer":1,"explanation":"「分级办理」的构成要件为：①主体为村委会；②通过联合多方现场会商后再定方案；③使平均处置周期缩短。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（只在事后补录台账），因此不符合构成要件。故选B。"},{"id":"pdn01553","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「过程性考核」是指课程组通过先摸清起点再设定分层目标，使后续目标更贴合实际起点的工作机制。\n\n按照上述界定，下列情形可认定为「过程性考核」的是：","options":["课程组在单元教学设计中，先摸清起点再设定分层目标，后续目标更贴合实际起点。","课程组在作业反馈整理中，先摸清起点再设定分层目标，但教学安排并未因数据而作任何调整。","由学生互评后不再复核，后续也未按上述机制推进。","课程组在实验课程组织中，按固定名次划线且不追溯变化，最终教学安排并未因数据而作任何调整。"],"answer":0,"explanation":"「过程性考核」的构成要件为：①主体为课程组；②通过先摸清起点再设定分层目标；③使后续目标更贴合实际起点。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01554","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「留存限期」是指学校学籍管理系统通过对外提供前作去标识化处理，使历史数据不再无限期堆积的工作机制。\n\n根据上述定义，下列不属于「留存限期」的是：","options":["学校学籍管理系统在数据调阅留痕中，对外提供前作去标识化处理，历史数据不再无限期堆积。","学校学籍管理系统在字段权限配置中，对外提供前作去标识化处理，历史数据不再无限期堆积。","学校学籍管理系统在信息采集登记中，对外提供前作去标识化处理，历史数据不再无限期堆积。","学校学籍管理系统在字段权限配置中，为方便起见一次性收齐全部字段，最终与办理目的无关的字段仍被长期留存。"],"answer":3,"explanation":"「留存限期」的构成要件为：①主体为学校学籍管理系统；②通过对外提供前作去标识化处理；③使历史数据不再无限期堆积。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（为方便起见一次性收齐全部字段），因此不符合构成要件。故选D。"},{"id":"pdn01555","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「共创反馈环」是指无障碍改造专班通过按真实使用路径逐点排查痛点，使返工与投诉明显减少的工作机制。\n\n依据上述定义，以下哪一项符合「共创反馈环」的构成要件：","options":["无障碍改造专班在服务流程梳理中，按真实使用路径逐点排查痛点，返工与投诉明显减少。","无障碍改造专班在使用路径排查中，按真实使用路径逐点排查痛点，但上线后仍频发与习惯不符的障碍。","无障碍改造专班在公共界面优化中，只做内部评审不接触使用者，最终上线后仍频发与习惯不符的障碍。","由供应商提供标准模板，后续也未按上述机制推进。"],"answer":0,"explanation":"「共创反馈环」的构成要件为：①主体为无障碍改造专班；②通过按真实使用路径逐点排查痛点；③使返工与投诉明显减少。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01556","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「共创反馈环」是指产品体验小组通过多轮共创后收敛为最终版本，使改动获得使用者认同的工作机制。\n\n按照上述界定，下列情形不应认定为「共创反馈环」的是：","options":["产品体验小组在服务流程梳理中，多轮共创后收敛为最终版本，改动获得使用者认同。","产品体验小组在公共界面优化中，照搬其他地区成品，最终上线后仍频发与习惯不符的障碍。","产品体验小组在公共界面优化中，多轮共创后收敛为最终版本，改动获得使用者认同。","产品体验小组在使用路径排查中，多轮共创后收敛为最终版本，改动获得使用者认同。"],"answer":1,"explanation":"「共创反馈环」的构成要件为：①主体为产品体验小组；②通过多轮共创后收敛为最终版本；③使改动获得使用者认同。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（照搬其他地区成品），因此不符合构成要件。故选B。"},{"id":"pdn01557","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「容错纠偏」是指政策试点工作组通过分批次扩面而非一次铺开，使后续推广更贴合一线实际的工作机制。\n\n根据上述定义，下列属于「容错纠偏」的是：","options":["政策试点工作组在新工具推广中，一次上线后即固化不再迭代，最终同类偏差在扩面后被成倍放大。","由用户自行摸索不作收集，后续也未按上述机制推进。","政策试点工作组在新流程上线中，分批次扩面而非一次铺开，后续推广更贴合一线实际。","政策试点工作组在新机制落地中，分批次扩面而非一次铺开，但同类偏差在扩面后被成倍放大。"],"answer":2,"explanation":"「容错纠偏」的构成要件为：①主体为政策试点工作组；②通过分批次扩面而非一次铺开；③使后续推广更贴合一线实际。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01558","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「形成性评价」是指课程组通过随堂记录并及时反馈调整，使教学策略得以动态优化的工作机制。\n\n依据上述定义，以下哪一项不符合「形成性评价」的构成要件：","options":["课程组在实验课程组织中，随堂记录并及时反馈调整，教学策略得以动态优化。","课程组在实验课程组织中，只以期末一次分数定结论，最终教学安排并未因数据而作任何调整。","课程组在单元教学设计中，随堂记录并及时反馈调整，教学策略得以动态优化。","课程组在作业反馈整理中，随堂记录并及时反馈调整，教学策略得以动态优化。"],"answer":1,"explanation":"「形成性评价」的构成要件为：①主体为课程组；②通过随堂记录并及时反馈调整；③使教学策略得以动态优化。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（只以期末一次分数定结论），因此不符合构成要件。故选B。"},{"id":"pdn01559","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「留痕管理」是指冷链运营方通过每一节点登记并关联上下游凭证，使台账与实物始终一致的工作机制。\n\n按照上述界定，下列情形可认定为「留痕管理」的是：","options":["冷链运营方在储运环节温控中，每一节点登记并关联上下游凭证，但出现问题时无法定位到具体环节。","冷链运营方在批次交接记录中，各环节各自记录且互不关联，最终出现问题时无法定位到具体环节。","由终端门店自行补记，后续也未按上述机制推进。","冷链运营方在进货环节核验中，每一节点登记并关联上下游凭证，台账与实物始终一致。"],"answer":3,"explanation":"「留痕管理」的构成要件为：①主体为冷链运营方；②通过每一节点登记并关联上下游凭证；③使台账与实物始终一致。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01560","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「前置筛查」是指县域医共体通过按病情轻重分流并约定转诊路径，使轻症在基层得到及时处置的工作机制。\n\n根据上述定义，下列不属于「前置筛查」的是：","options":["县域医共体在重点人群筛查中，按病情轻重分流并约定转诊路径，轻症在基层得到及时处置。","县域医共体在康复跟踪记录中，按病情轻重分流并约定转诊路径，轻症在基层得到及时处置。","县域医共体在康复跟踪记录中，各机构各自重复开单，最终各环节彼此脱节、患者仍需多次重复排队。","县域医共体在慢病随访安排中，按病情轻重分流并约定转诊路径，轻症在基层得到及时处置。"],"answer":2,"explanation":"「前置筛查」的构成要件为：①主体为县域医共体；②通过按病情轻重分流并约定转诊路径；③使轻症在基层得到及时处置。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（各机构各自重复开单），因此不符合构成要件。故选C。"},{"id":"pdn01561","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「指标复核」是指政策评估小组通过先确立基线再对照前后变化，使结论不易被个别异常值带偏的工作机制。\n\n依据上述定义，以下哪一项符合「指标复核」的构成要件：","options":["政策评估小组在年度计划编制中，先确立基线再对照前后变化，结论不易被个别异常值带偏。","政策评估小组在抽样数据核查中，先确立基线再对照前后变化，但结论无法由所引数据支撑。","政策评估小组在政策效果评估中，指标口径中途变更却不说明，最终结论无法由所引数据支撑。","由第三方直接给结论不附依据，后续也未按上述机制推进。"],"answer":0,"explanation":"「指标复核」的构成要件为：①主体为政策评估小组；②通过先确立基线再对照前后变化；③使结论不易被个别异常值带偏。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01562","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「指标复核」是指项目评审委员会通过用对照组剔除同期其他影响，使判断建立在可核验的依据上的工作机制。\n\n按照上述界定，下列情形不应认定为「指标复核」的是：","options":["项目评审委员会在年度计划编制中，用对照组剔除同期其他影响，判断建立在可核验的依据上。","项目评审委员会在政策效果评估中，用对照组剔除同期其他影响，判断建立在可核验的依据上。","项目评审委员会在政策效果评估中，只选取有利样本作展示，最终结论无法由所引数据支撑。","项目评审委员会在抽样数据核查中，用对照组剔除同期其他影响，判断建立在可核验的依据上。"],"answer":2,"explanation":"「指标复核」的构成要件为：①主体为项目评审委员会；②通过用对照组剔除同期其他影响；③使判断建立在可核验的依据上。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（只选取有利样本作展示），因此不符合构成要件。故选C。"},{"id":"pdn01563","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「诊断性测评」是指学校教研组通过按阶段采集学情数据再修正教学，使后续目标更贴合实际起点的工作机制。\n\n根据上述定义，下列属于「诊断性测评」的是：","options":["学校教研组在作业反馈整理中，按阶段采集学情数据再修正教学，但教学安排并未因数据而作任何调整。","学校教研组在单元教学设计中，按阶段采集学情数据再修正教学，后续目标更贴合实际起点。","学校教研组在实验课程组织中，全程不作任何反馈、结束后才公布，最终教学安排并未因数据而作任何调整。","由家长自行报送成绩，后续也未按上述机制推进。"],"answer":1,"explanation":"「诊断性测评」的构成要件为：①主体为学校教研组；②通过按阶段采集学情数据再修正教学；③使后续目标更贴合实际起点。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01564","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「双向转诊」是指县域医共体通过先由基层评估再决定是否上转，使重复检查明显减少的工作机制。\n\n依据上述定义，以下哪一项不符合「双向转诊」的构成要件：","options":["县域医共体在康复跟踪记录中，先由基层评估再决定是否上转，重复检查明显减少。","县域医共体在重点人群筛查中，先由基层评估再决定是否上转，重复检查明显减少。","县域医共体在康复跟踪记录中，各机构各自重复开单，最终各环节彼此脱节、患者仍需多次重复排队。","县域医共体在慢病随访安排中，先由基层评估再决定是否上转，重复检查明显减少。"],"answer":2,"explanation":"「双向转诊」的构成要件为：①主体为县域医共体；②通过先由基层评估再决定是否上转；③使重复检查明显减少。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（各机构各自重复开单），因此不符合构成要件。故选C。"},{"id":"pdn01565","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「数据校验」是指政策评估小组通过以多源数据交叉校验结论，使后续调整有据可依的工作机制。\n\n按照上述界定，下列情形可认定为「数据校验」的是：","options":["由第三方直接给结论不附依据，后续也未按上述机制推进。","政策评估小组在抽样数据核查中，以多源数据交叉校验结论，但结论无法由所引数据支撑。","政策评估小组在政策效果评估中，指标口径中途变更却不说明，最终结论无法由所引数据支撑。","政策评估小组在年度计划编制中，以多源数据交叉校验结论，后续调整有据可依。"],"answer":3,"explanation":"「数据校验」的构成要件为：①主体为政策评估小组；②通过以多源数据交叉校验结论；③使后续调整有据可依。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01566","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「可回溯核查」是指食品药品监管所通过按批号串联台账与检验记录，使召回范围精确到具体批次的工作机制。\n\n根据上述定义，下列不属于「可回溯核查」的是：","options":["食品药品监管所在批次交接记录中，按批号串联台账与检验记录，召回范围精确到具体批次。","食品药品监管所在储运环节温控中，按批号串联台账与检验记录，召回范围精确到具体批次。","食品药品监管所在进货环节核验中，按批号串联台账与检验记录，召回范围精确到具体批次。","食品药品监管所在批次交接记录中，只在最终出库时记一笔总账，最终出现问题时无法定位到具体环节。"],"answer":3,"explanation":"「可回溯核查」的构成要件为：①主体为食品药品监管所；②通过按批号串联台账与检验记录；③使召回范围精确到具体批次。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（只在最终出库时记一笔总账），因此不符合构成要件。故选D。"},{"id":"pdn01567","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「前置筛查」是指家庭医生团队通过先由基层评估再决定是否上转，使病情变化能被尽早发现的工作机制。\n\n依据上述定义，以下哪一项符合「前置筛查」的构成要件：","options":["家庭医生团队在慢病随访安排中，先由基层评估再决定是否上转，病情变化能被尽早发现。","仅由三甲医院单方建档，后续也未按上述机制推进。","家庭医生团队在康复跟踪记录中，只做一次性检查不作后续跟踪，最终各环节彼此脱节、患者仍需多次重复排队。","家庭医生团队在重点人群筛查中，先由基层评估再决定是否上转，但各环节彼此脱节、患者仍需多次重复排队。"],"answer":0,"explanation":"「前置筛查」的构成要件为：①主体为家庭医生团队；②通过先由基层评估再决定是否上转；③使病情变化能被尽早发现。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01568","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「用户旅程映射」是指产品体验小组通过多轮共创后收敛为最终版本，使改动获得使用者认同的工作机制。\n\n按照上述界定，下列情形不应认定为「用户旅程映射」的是：","options":["产品体验小组在公共界面优化中，多轮共创后收敛为最终版本，改动获得使用者认同。","产品体验小组在服务流程梳理中，多轮共创后收敛为最终版本，改动获得使用者认同。","产品体验小组在公共界面优化中，照搬其他地区成品，最终上线后仍频发与习惯不符的障碍。","产品体验小组在使用路径排查中，多轮共创后收敛为最终版本，改动获得使用者认同。"],"answer":2,"explanation":"「用户旅程映射」的构成要件为：①主体为产品体验小组；②通过多轮共创后收敛为最终版本；③使改动获得使用者认同。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（照搬其他地区成品），因此不符合构成要件。故选C。"},{"id":"pdn01569","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「增值评价」是指课程组通过随堂记录并及时反馈调整，使学生的薄弱点被及时识别的工作机制。\n\n根据上述定义，下列属于「增值评价」的是：","options":["课程组在单元教学设计中，随堂记录并及时反馈调整，学生的薄弱点被及时识别。","由学生互评后不再复核，后续也未按上述机制推进。","课程组在作业反馈整理中，随堂记录并及时反馈调整，但教学安排并未因数据而作任何调整。","课程组在实验课程组织中，按固定名次划线且不追溯变化，最终教学安排并未因数据而作任何调整。"],"answer":0,"explanation":"「增值评价」的构成要件为：①主体为课程组；②通过随堂记录并及时反馈调整；③使学生的薄弱点被及时识别。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01570","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「连续照护」是指县域医共体通过按病情轻重分流并约定转诊路径，使轻症在基层得到及时处置的工作机制。\n\n依据上述定义，以下哪一项不符合「连续照护」的构成要件：","options":["县域医共体在重点人群筛查中，按病情轻重分流并约定转诊路径，轻症在基层得到及时处置。","县域医共体在慢病随访安排中，按病情轻重分流并约定转诊路径，轻症在基层得到及时处置。","县域医共体在康复跟踪记录中，一律先安排住院再评估，最终各环节彼此脱节、患者仍需多次重复排队。","县域医共体在康复跟踪记录中，按病情轻重分流并约定转诊路径，轻症在基层得到及时处置。"],"answer":2,"explanation":"「连续照护」的构成要件为：①主体为县域医共体；②通过按病情轻重分流并约定转诊路径；③使轻症在基层得到及时处置。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（一律先安排住院再评估），因此不符合构成要件。故选C。"},{"id":"pdn01571","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「风险前置」是指数据中心运维组通过按风险等级预置响应动作，使次生影响被压到最小的工作机制。\n\n按照上述界定，下列情形可认定为「风险前置」的是：","options":["由上级在事后统一追认，后续也未按上述机制推进。","数据中心运维组在响应动作预置中，仅保留一份无备用的关键设备，最终异常发生时无预设动作可依。","数据中心运维组在风险等级研判中，按风险等级预置响应动作，次生影响被压到最小。","数据中心运维组在关键节点值守中，按风险等级预置响应动作，但异常发生时无预设动作可依。"],"answer":2,"explanation":"「风险前置」的构成要件为：①主体为数据中心运维组；②通过按风险等级预置响应动作；③使次生影响被压到最小。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01572","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「闭环处置」是指社区网格站通过依托网格员常态化走访摸排，使居民满意度稳步提升的工作机制。\n\n根据上述定义，下列不属于「闭环处置」的是：","options":["社区网格站在邻里纠纷调解中，依托网格员常态化走访摸排，居民满意度稳步提升。","社区网格站在便民事项办理中，依托网格员常态化走访摸排，居民满意度稳步提升。","社区网格站在邻里纠纷调解中，只在事后补录台账，最终问题仍反复出现且未形成稳定机制。","社区网格站在老旧小区改造中，依托网格员常态化走访摸排，居民满意度稳步提升。"],"answer":2,"explanation":"「闭环处置」的构成要件为：①主体为社区网格站；②通过依托网格员常态化走访摸排；③使居民满意度稳步提升。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（只在事后补录台账），因此不符合构成要件。故选C。"},{"id":"pdn01573","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「冗余备份」是指水利工程调度处通过按风险等级预置响应动作，使次生影响被压到最小的工作机制。\n\n依据上述定义，以下哪一项符合「冗余备份」的构成要件：","options":["水利工程调度处在关键节点值守中，按风险等级预置响应动作，但异常发生时无预设动作可依。","水利工程调度处在风险等级研判中，按风险等级预置响应动作，次生影响被压到最小。","由外部单位事后支援，后续也未按上述机制推进。","水利工程调度处在响应动作预置中，只在事发后补充记录，最终异常发生时无预设动作可依。"],"answer":1,"explanation":"「冗余备份」的构成要件为：①主体为水利工程调度处；②通过按风险等级预置响应动作；③使次生影响被压到最小。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01574","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「协同会商」是指街道办通过提前公示并逐户征询意见，使重复投诉明显下降的工作机制。\n\n按照上述界定，下列情形不应认定为「协同会商」的是：","options":["街道办在邻里纠纷调解中，直接照搬既有方案、未作任何征询，最终问题仍反复出现且未形成稳定机制。","街道办在老旧小区改造中，提前公示并逐户征询意见，重复投诉明显下降。","街道办在便民事项办理中，提前公示并逐户征询意见，重复投诉明显下降。","街道办在邻里纠纷调解中，提前公示并逐户征询意见，重复投诉明显下降。"],"answer":0,"explanation":"「协同会商」的构成要件为：①主体为街道办；②通过提前公示并逐户征询意见；③使重复投诉明显下降。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（直接照搬既有方案、未作任何征询），因此不符合构成要件。故选A。"},{"id":"pdn01575","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「脱敏处理」是指医院信息科通过到期自动清理并留清理记录，使超范围信息不被额外索取的工作机制。\n\n根据上述定义，下列属于「脱敏处理」的是：","options":["医院信息科在数据调阅留痕中，到期自动清理并留清理记录，但与办理目的无关的字段仍被长期留存。","医院信息科在信息采集登记中，到期自动清理并留清理记录，超范围信息不被额外索取。","由外包人员全量导出，后续也未按上述机制推进。","医院信息科在字段权限配置中，所有岗位开放同一份全量清单，最终与办理目的无关的字段仍被长期留存。"],"answer":1,"explanation":"「脱敏处理」的构成要件为：①主体为医院信息科；②通过到期自动清理并留清理记录；③使超范围信息不被额外索取。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01576","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「跨界协作」是指跨部门工作专班通过一次会商形成分工清单，使跨界问题不再悬空的工作机制。\n\n依据上述定义，以下哪一项不符合「跨界协作」的构成要件：","options":["跨部门工作专班在跨界事项梳理中，一次会商形成分工清单，跨界问题不再悬空。","跨部门工作专班在联合排班安排中，一次会商形成分工清单，跨界问题不再悬空。","跨部门工作专班在信息通报共享中，一次会商形成分工清单，跨界问题不再悬空。","跨部门工作专班在联合排班安排中，遇跨界事项互相等待，最终边界地带的问题仍在部门之间来回流转。"],"answer":3,"explanation":"「跨界协作」的构成要件为：①主体为跨部门工作专班；②通过一次会商形成分工清单；③使跨界问题不再悬空。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（遇跨界事项互相等待），因此不符合构成要件。故选D。"},{"id":"pdn01577","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「分级预警」是指数据中心运维组通过按风险等级预置响应动作，使险情初起即进入有序处置的工作机制。\n\n按照上述界定，下列情形可认定为「分级预警」的是：","options":["数据中心运维组在关键节点值守中，按风险等级预置响应动作，但异常发生时无预设动作可依。","由外部单位事后支援，后续也未按上述机制推进。","数据中心运维组在风险等级研判中，按风险等级预置响应动作，险情初起即进入有序处置。","数据中心运维组在响应动作预置中，只在事发后补充记录，最终异常发生时无预设动作可依。"],"answer":2,"explanation":"「分级预警」的构成要件为：①主体为数据中心运维组；②通过按风险等级预置响应动作；③使险情初起即进入有序处置。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01578","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「容错纠偏」是指数字化转型办公室通过分批次扩面而非一次铺开，使风险被限制在可控范围的工作机制。\n\n根据上述定义，下列不属于「容错纠偏」的是：","options":["数字化转型办公室在新工具推广中，不经试点直接全面强制推开，最终同类偏差在扩面后被成倍放大。","数字化转型办公室在新机制落地中，分批次扩面而非一次铺开，风险被限制在可控范围。","数字化转型办公室在新流程上线中，分批次扩面而非一次铺开，风险被限制在可控范围。","数字化转型办公室在新工具推广中，分批次扩面而非一次铺开，风险被限制在可控范围。"],"answer":0,"explanation":"「容错纠偏」的构成要件为：①主体为数字化转型办公室；②通过分批次扩面而非一次铺开；③使风险被限制在可控范围。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（不经试点直接全面强制推开），因此不符合构成要件。故选A。"},{"id":"pdn01579","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「可回溯核查」是指食品药品监管所通过关键节点双人签认留档，使问题批次能被快速定位的工作机制。\n\n依据上述定义，以下哪一项符合「可回溯核查」的构成要件：","options":["食品药品监管所在批次交接记录中，各环节各自记录且互不关联，最终出现问题时无法定位到具体环节。","食品药品监管所在进货环节核验中，关键节点双人签认留档，问题批次能被快速定位。","食品药品监管所在储运环节温控中，关键节点双人签认留档，但出现问题时无法定位到具体环节。","由终端门店自行补记，后续也未按上述机制推进。"],"answer":1,"explanation":"「可回溯核查」的构成要件为：①主体为食品药品监管所；②通过关键节点双人签认留档；③使问题批次能被快速定位。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01580","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「数据校验」是指统计调查队通过以多源数据交叉校验结论，使判断建立在可核验的依据上的工作机制。\n\n按照上述界定，下列情形不应认定为「数据校验」的是：","options":["统计调查队在政策效果评估中，以多源数据交叉校验结论，判断建立在可核验的依据上。","统计调查队在政策效果评估中，以主观感受替代实测数据，最终结论无法由所引数据支撑。","统计调查队在抽样数据核查中，以多源数据交叉校验结论，判断建立在可核验的依据上。","统计调查队在年度计划编制中，以多源数据交叉校验结论，判断建立在可核验的依据上。"],"answer":1,"explanation":"「数据校验」的构成要件为：①主体为统计调查队；②通过以多源数据交叉校验结论；③使判断建立在可核验的依据上。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（以主观感受替代实测数据），因此不符合构成要件。故选B。"},{"id":"pdn01581","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「脆弱性评估」是指应急指挥中心通过设定触发条件并提前布防，使次生影响被压到最小的工作机制。\n\n根据上述定义，下列属于「脆弱性评估」的是：","options":["由外部单位事后支援，后续也未按上述机制推进。","应急指挥中心在响应动作预置中，只在事发后补充记录，最终异常发生时无预设动作可依。","应急指挥中心在关键节点值守中，设定触发条件并提前布防，但异常发生时无预设动作可依。","应急指挥中心在风险等级研判中，设定触发条件并提前布防，次生影响被压到最小。"],"answer":3,"explanation":"「脆弱性评估」的构成要件为：①主体为应急指挥中心；②通过设定触发条件并提前布防；③使次生影响被压到最小。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01582","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「阈值预警」是指自然保护区管理局通过随季节数据滚动修订方案，使核心栖息地得到有效避让的工作机制。\n\n依据上述定义，以下哪一项不符合「阈值预警」的构成要件：","options":["自然保护区管理局在栖息环境变化中，全年沿用同一套固定配额，最终指标已越界而措施仍维持不变。","自然保护区管理局在栖息环境变化中，随季节数据滚动修订方案，核心栖息地得到有效避让。","自然保护区管理局在外来因素扩散中，随季节数据滚动修订方案，核心栖息地得到有效避让。","自然保护区管理局在监测指标波动中，随季节数据滚动修订方案，核心栖息地得到有效避让。"],"answer":0,"explanation":"「阈值预警」的构成要件为：①主体为自然保护区管理局；②通过随季节数据滚动修订方案；③使核心栖息地得到有效避让。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（全年沿用同一套固定配额），因此不符合构成要件。故选A。"},{"id":"pdn01583","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「共创反馈环」是指公共服务设计组通过先做可体验原型再收集反馈，使返工与投诉明显减少的工作机制。\n\n按照上述界定，下列情形可认定为「共创反馈环」的是：","options":["由供应商提供标准模板，后续也未按上述机制推进。","公共服务设计组在公共界面优化中，只做内部评审不接触使用者，最终上线后仍频发与习惯不符的障碍。","公共服务设计组在使用路径排查中，先做可体验原型再收集反馈，但上线后仍频发与习惯不符的障碍。","公共服务设计组在服务流程梳理中，先做可体验原型再收集反馈，返工与投诉明显减少。"],"answer":3,"explanation":"「共创反馈环」的构成要件为：①主体为公共服务设计组；②通过先做可体验原型再收集反馈；③使返工与投诉明显减少。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01584","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「冗余备份」是指水利工程调度处通过关键节点保留备用通道，使险情初起即进入有序处置的工作机制。\n\n根据上述定义，下列不属于「冗余备份」的是：","options":["水利工程调度处在响应动作预置中，关键节点保留备用通道，险情初起即进入有序处置。","水利工程调度处在关键节点值守中，关键节点保留备用通道，险情初起即进入有序处置。","水利工程调度处在响应动作预置中，预案长期封存不随风险更新，最终异常发生时无预设动作可依。","水利工程调度处在风险等级研判中，关键节点保留备用通道，险情初起即进入有序处置。"],"answer":2,"explanation":"「冗余备份」的构成要件为：①主体为水利工程调度处；②通过关键节点保留备用通道；③使险情初起即进入有序处置。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（预案长期封存不随风险更新），因此不符合构成要件。故选C。"},{"id":"pdn01585","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「跨界协作」是指跨部门工作专班通过共享信息并同步排班，使响应口径保持一致的工作机制。\n\n依据上述定义，以下哪一项符合「跨界协作」的构成要件：","options":["由上级部门包办到底，后续也未按上述机制推进。","跨部门工作专班在联合排班安排中，各自按本部门旧流程办理，最终边界地带的问题仍在部门之间来回流转。","跨部门工作专班在跨界事项梳理中，共享信息并同步排班，响应口径保持一致。","跨部门工作专班在信息通报共享中，共享信息并同步排班，但边界地带的问题仍在部门之间来回流转。"],"answer":2,"explanation":"「跨界协作」的构成要件为：①主体为跨部门工作专班；②通过共享信息并同步排班；③使响应口径保持一致。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01586","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「证据本位决策」是指统计调查队通过对关键指标作独立复核，使后续调整有据可依的工作机制。\n\n按照上述界定，下列情形不应认定为「证据本位决策」的是：","options":["统计调查队在政策效果评估中，只选取有利样本作展示，最终结论无法由所引数据支撑。","统计调查队在年度计划编制中，对关键指标作独立复核，后续调整有据可依。","统计调查队在政策效果评估中，对关键指标作独立复核，后续调整有据可依。","统计调查队在抽样数据核查中，对关键指标作独立复核，后续调整有据可依。"],"answer":0,"explanation":"「证据本位决策」的构成要件为：①主体为统计调查队；②通过对关键指标作独立复核；③使后续调整有据可依。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（只选取有利样本作展示），因此不符合构成要件。故选A。"},{"id":"pdn01587","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「随访管理」是指县域医共体通过与上级医院共享检查结果，使患者往返成本下降的工作机制。\n\n根据上述定义，下列属于「随访管理」的是：","options":["县域医共体在康复跟踪记录中，只做一次性检查不作后续跟踪，最终各环节彼此脱节、患者仍需多次重复排队。","仅由三甲医院单方建档，后续也未按上述机制推进。","县域医共体在慢病随访安排中，与上级医院共享检查结果，患者往返成本下降。","县域医共体在重点人群筛查中，与上级医院共享检查结果，但各环节彼此脱节、患者仍需多次重复排队。"],"answer":2,"explanation":"「随访管理」的构成要件为：①主体为县域医共体；②通过与上级医院共享检查结果；③使患者往返成本下降。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01588","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「最小必要采集」是指医院信息科通过只采集完成本事项所必需的字段，使超范围信息不被额外索取的工作机制。\n\n依据上述定义，以下哪一项不符合「最小必要采集」的构成要件：","options":["医院信息科在字段权限配置中，共享时直接提供原始明细，最终与办理目的无关的字段仍被长期留存。","医院信息科在数据调阅留痕中，只采集完成本事项所必需的字段，超范围信息不被额外索取。","医院信息科在信息采集登记中，只采集完成本事项所必需的字段，超范围信息不被额外索取。","医院信息科在字段权限配置中，只采集完成本事项所必需的字段，超范围信息不被额外索取。"],"answer":0,"explanation":"「最小必要采集」的构成要件为：①主体为医院信息科；②通过只采集完成本事项所必需的字段；③使超范围信息不被额外索取。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（共享时直接提供原始明细），因此不符合构成要件。故选A。"},{"id":"pdn01589","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「弹性调控」是指流域管理机构通过随季节数据滚动修订方案，使干预强度与实际风险相匹配的工作机制。\n\n按照上述界定，下列情形可认定为「弹性调控」的是：","options":["流域管理机构在外来因素扩散中，随季节数据滚动修订方案，但指标已越界而措施仍维持不变。","由游客反馈临时决定，后续也未按上述机制推进。","流域管理机构在监测指标波动中，随季节数据滚动修订方案，干预强度与实际风险相匹配。","流域管理机构在栖息环境变化中，等出现明显损害后再启动处置，最终指标已越界而措施仍维持不变。"],"answer":2,"explanation":"「弹性调控」的构成要件为：①主体为流域管理机构；②通过随季节数据滚动修订方案；③使干预强度与实际风险相匹配。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01590","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「数据校验」是指规划编制组通过以多源数据交叉校验结论，使成效与措施之间的对应更清楚的工作机制。\n\n根据上述定义，下列不属于「数据校验」的是：","options":["规划编制组在政策效果评估中，只选取有利样本作展示，最终结论无法由所引数据支撑。","规划编制组在政策效果评估中，以多源数据交叉校验结论，成效与措施之间的对应更清楚。","规划编制组在年度计划编制中，以多源数据交叉校验结论，成效与措施之间的对应更清楚。","规划编制组在抽样数据核查中，以多源数据交叉校验结论，成效与措施之间的对应更清楚。"],"answer":0,"explanation":"「数据校验」的构成要件为：①主体为规划编制组；②通过以多源数据交叉校验结论；③使成效与措施之间的对应更清楚。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（只选取有利样本作展示），因此不符合构成要件。故选A。"},{"id":"pdn01591","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「共创反馈环」是指产品体验小组通过按真实使用路径逐点排查痛点，使方案贴合真实使用习惯的工作机制。\n\n依据上述定义，以下哪一项符合「共创反馈环」的构成要件：","options":["产品体验小组在使用路径排查中，按真实使用路径逐点排查痛点，但上线后仍频发与习惯不符的障碍。","由供应商提供标准模板，后续也未按上述机制推进。","产品体验小组在服务流程梳理中，按真实使用路径逐点排查痛点，方案贴合真实使用习惯。","产品体验小组在公共界面优化中，只做内部评审不接触使用者，最终上线后仍频发与习惯不符的障碍。"],"answer":2,"explanation":"「共创反馈环」的构成要件为：①主体为产品体验小组；②通过按真实使用路径逐点排查痛点；③使方案贴合真实使用习惯。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01592","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「精准匹配」是指就业服务窗口通过按对象条件分档配置资源，使冷门项目被及时替换的工作机制。\n\n按照上述界定，下列情形不应认定为「精准匹配」的是：","options":["就业服务窗口在对象需求摸排中，先采购再询问是否需要，最终大量项目无人使用而真实诉求仍被搁置。","就业服务窗口在服务事项梳理中，按对象条件分档配置资源，冷门项目被及时替换。","就业服务窗口在服务清单编制中，按对象条件分档配置资源，冷门项目被及时替换。","就业服务窗口在对象需求摸排中，按对象条件分档配置资源，冷门项目被及时替换。"],"answer":0,"explanation":"「精准匹配」的构成要件为：①主体为就业服务窗口；②通过按对象条件分档配置资源；③使冷门项目被及时替换。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（先采购再询问是否需要），因此不符合构成要件。故选A。"},{"id":"pdn01593","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「参与式设计」是指无障碍改造专班通过多轮共创后收敛为最终版本，使隐蔽障碍在使用前被暴露的工作机制。\n\n根据上述定义，下列属于「参与式设计」的是：","options":["无障碍改造专班在公共界面优化中，一次性定稿不再接收反馈，最终上线后仍频发与习惯不符的障碍。","无障碍改造专班在服务流程梳理中，多轮共创后收敛为最终版本，隐蔽障碍在使用前被暴露。","无障碍改造专班在使用路径排查中，多轮共创后收敛为最终版本，但上线后仍频发与习惯不符的障碍。","由外部专家远程定稿，后续也未按上述机制推进。"],"answer":1,"explanation":"「参与式设计」的构成要件为：①主体为无障碍改造专班；②通过多轮共创后收敛为最终版本；③使隐蔽障碍在使用前被暴露。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01594","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「链条式核验」是指食品药品监管所通过异常批次可一键回溯全链路，使责任环节清晰可查的工作机制。\n\n依据上述定义，以下哪一项不符合「链条式核验」的构成要件：","options":["食品药品监管所在进货环节核验中，异常批次可一键回溯全链路，责任环节清晰可查。","食品药品监管所在批次交接记录中，只在最终出库时记一笔总账，最终出现问题时无法定位到具体环节。","食品药品监管所在批次交接记录中，异常批次可一键回溯全链路，责任环节清晰可查。","食品药品监管所在储运环节温控中，异常批次可一键回溯全链路，责任环节清晰可查。"],"answer":1,"explanation":"「链条式核验」的构成要件为：①主体为食品药品监管所；②通过异常批次可一键回溯全链路；③使责任环节清晰可查。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（只在最终出库时记一笔总账），因此不符合构成要件。故选B。"},{"id":"pdn01595","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「跨界协作」是指流域联席会议通过共享信息并同步排班，使处置效率整体提升的工作机制。\n\n按照上述界定，下列情形可认定为「跨界协作」的是：","options":["流域联席会议在信息通报共享中，共享信息并同步排班，但边界地带的问题仍在部门之间来回流转。","流域联席会议在跨界事项梳理中，共享信息并同步排班，处置效率整体提升。","由各区各自为政，后续也未按上述机制推进。","流域联席会议在联合排班安排中，只开会不落责任清单，最终边界地带的问题仍在部门之间来回流转。"],"answer":1,"explanation":"「跨界协作」的构成要件为：①主体为流域联席会议；②通过共享信息并同步排班；③使处置效率整体提升。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01596","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「节点责任制」是指食品药品监管所通过关键节点双人签认留档，使台账与实物始终一致的工作机制。\n\n根据上述定义，下列不属于「节点责任制」的是：","options":["食品药品监管所在批次交接记录中，事后一次性补全整本台账，最终出现问题时无法定位到具体环节。","食品药品监管所在储运环节温控中，关键节点双人签认留档，台账与实物始终一致。","食品药品监管所在进货环节核验中，关键节点双人签认留档，台账与实物始终一致。","食品药品监管所在批次交接记录中，关键节点双人签认留档，台账与实物始终一致。"],"answer":0,"explanation":"「节点责任制」的构成要件为：①主体为食品药品监管所；②通过关键节点双人签认留档；③使台账与实物始终一致。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（事后一次性补全整本台账），因此不符合构成要件。故选A。"},{"id":"pdn01597","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「多元共治」是指流域联席会议通过明确牵头与配合边界后统一行动，使处置效率整体提升的工作机制。\n\n依据上述定义，以下哪一项符合「多元共治」的构成要件：","options":["流域联席会议在跨界事项梳理中，明确牵头与配合边界后统一行动，处置效率整体提升。","由上级部门包办到底，后续也未按上述机制推进。","流域联席会议在联合排班安排中，各自按本部门旧流程办理，最终边界地带的问题仍在部门之间来回流转。","流域联席会议在信息通报共享中，明确牵头与配合边界后统一行动，但边界地带的问题仍在部门之间来回流转。"],"answer":0,"explanation":"「多元共治」的构成要件为：①主体为流域联席会议；②通过明确牵头与配合边界后统一行动；③使处置效率整体提升。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01598","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「风险前置」是指水利工程调度处通过设定触发条件并提前布防，使次生影响被压到最小的工作机制。\n\n按照上述界定，下列情形不应认定为「风险前置」的是：","options":["水利工程调度处在风险等级研判中，设定触发条件并提前布防，次生影响被压到最小。","水利工程调度处在响应动作预置中，设定触发条件并提前布防，次生影响被压到最小。","水利工程调度处在关键节点值守中，设定触发条件并提前布防，次生影响被压到最小。","水利工程调度处在响应动作预置中，等指标越限后才临时研究方案，最终异常发生时无预设动作可依。"],"answer":3,"explanation":"「风险前置」的构成要件为：①主体为水利工程调度处；②通过设定触发条件并提前布防；③使次生影响被压到最小。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（等指标越限后才临时研究方案），因此不符合构成要件。故选D。"},{"id":"pdn01599","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「目的限定」是指学校学籍管理系统通过只采集完成本事项所必需的字段，使敏感字段仅在授权场景可见的工作机制。\n\n根据上述定义，下列属于「目的限定」的是：","options":["学校学籍管理系统在数据调阅留痕中，只采集完成本事项所必需的字段，但与办理目的无关的字段仍被长期留存。","由外包人员全量导出，后续也未按上述机制推进。","学校学籍管理系统在字段权限配置中，所有岗位开放同一份全量清单，最终与办理目的无关的字段仍被长期留存。","学校学籍管理系统在信息采集登记中，只采集完成本事项所必需的字段，敏感字段仅在授权场景可见。"],"answer":3,"explanation":"「目的限定」的构成要件为：①主体为学校学籍管理系统；②通过只采集完成本事项所必需的字段；③使敏感字段仅在授权场景可见。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01600","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「风险前置」是指应急指挥中心通过识别薄弱环节并预先加固，使次生影响被压到最小的工作机制。\n\n依据上述定义，以下哪一项不符合「风险前置」的构成要件：","options":["应急指挥中心在风险等级研判中，识别薄弱环节并预先加固，次生影响被压到最小。","应急指挥中心在响应动作预置中，预案长期封存不随风险更新，最终异常发生时无预设动作可依。","应急指挥中心在响应动作预置中，识别薄弱环节并预先加固，次生影响被压到最小。","应急指挥中心在关键节点值守中，识别薄弱环节并预先加固，次生影响被压到最小。"],"answer":1,"explanation":"「风险前置」的构成要件为：①主体为应急指挥中心；②通过识别薄弱环节并预先加固；③使次生影响被压到最小。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（预案长期封存不随风险更新），因此不符合构成要件。故选B。"},{"id":"pdn01601","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「适应性管理」是指生态环境监测站通过按监测指标分档调整措施，使核心栖息地得到有效避让的工作机制。\n\n按照上述界定，下列情形可认定为「适应性管理」的是：","options":["生态环境监测站在栖息环境变化中，等出现明显损害后再启动处置，最终指标已越界而措施仍维持不变。","生态环境监测站在监测指标波动中，按监测指标分档调整措施，核心栖息地得到有效避让。","由游客反馈临时决定，后续也未按上述机制推进。","生态环境监测站在外来因素扩散中，按监测指标分档调整措施，但指标已越界而措施仍维持不变。"],"answer":1,"explanation":"「适应性管理」的构成要件为：①主体为生态环境监测站；②通过按监测指标分档调整措施；③使核心栖息地得到有效避让。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01602","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「菜单式服务」是指农技推广站通过按对象条件分档配置资源，使资源不再平均摊薄的工作机制。\n\n根据上述定义，下列不属于「菜单式服务」的是：","options":["农技推广站在对象需求摸排中，所有对象发放完全相同的固定包，最终大量项目无人使用而真实诉求仍被搁置。","农技推广站在服务事项梳理中，按对象条件分档配置资源，资源不再平均摊薄。","农技推广站在服务清单编制中，按对象条件分档配置资源，资源不再平均摊薄。","农技推广站在对象需求摸排中，按对象条件分档配置资源，资源不再平均摊薄。"],"answer":0,"explanation":"「菜单式服务」的构成要件为：①主体为农技推广站；②通过按对象条件分档配置资源；③使资源不再平均摊薄。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（所有对象发放完全相同的固定包），因此不符合构成要件。故选A。"},{"id":"pdn01603","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「分级办理」是指街道办通过建立台账逐项限时销号，使重复投诉明显下降的工作机制。\n\n依据上述定义，以下哪一项符合「分级办理」的构成要件：","options":["街道办在老旧小区改造中，建立台账逐项限时销号，重复投诉明显下降。","由临时志愿队自行接管，后续也未按上述机制推进。","街道办在邻里纠纷调解中，等群众上门反映后再统一研究，最终问题仍反复出现且未形成稳定机制。","街道办在便民事项办理中，建立台账逐项限时销号，但问题仍反复出现且未形成稳定机制。"],"answer":0,"explanation":"「分级办理」的构成要件为：①主体为街道办；②通过建立台账逐项限时销号；③使重复投诉明显下降。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01604","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「链条式核验」是指冷链运营方通过按批号串联台账与检验记录，使问题批次能被快速定位的工作机制。\n\n按照上述界定，下列情形不应认定为「链条式核验」的是：","options":["冷链运营方在批次交接记录中，按批号串联台账与检验记录，问题批次能被快速定位。","冷链运营方在进货环节核验中，按批号串联台账与检验记录，问题批次能被快速定位。","冷链运营方在批次交接记录中，事后一次性补全整本台账，最终出现问题时无法定位到具体环节。","冷链运营方在储运环节温控中，按批号串联台账与检验记录，问题批次能被快速定位。"],"answer":2,"explanation":"「链条式核验」的构成要件为：①主体为冷链运营方；②通过按批号串联台账与检验记录；③使问题批次能被快速定位。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（事后一次性补全整本台账），因此不符合构成要件。故选C。"},{"id":"pdn01605","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「预案触发」是指应急指挥中心通过关键节点保留备用通道，使核心功能在异常下仍可维持的工作机制。\n\n根据上述定义，下列属于「预案触发」的是：","options":["应急指挥中心在风险等级研判中，关键节点保留备用通道，核心功能在异常下仍可维持。","应急指挥中心在关键节点值守中，关键节点保留备用通道，但异常发生时无预设动作可依。","应急指挥中心在响应动作预置中，只在事发后补充记录，最终异常发生时无预设动作可依。","由外部单位事后支援，后续也未按上述机制推进。"],"answer":0,"explanation":"「预案触发」的构成要件为：①主体为应急指挥中心；②通过关键节点保留备用通道；③使核心功能在异常下仍可维持。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01606","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「冗余备份」是指数据中心运维组通过按风险等级预置响应动作，使核心功能在异常下仍可维持的工作机制。\n\n依据上述定义，以下哪一项不符合「冗余备份」的构成要件：","options":["数据中心运维组在响应动作预置中，按风险等级预置响应动作，核心功能在异常下仍可维持。","数据中心运维组在关键节点值守中，按风险等级预置响应动作，核心功能在异常下仍可维持。","数据中心运维组在风险等级研判中，按风险等级预置响应动作，核心功能在异常下仍可维持。","数据中心运维组在响应动作预置中，等指标越限后才临时研究方案，最终异常发生时无预设动作可依。"],"answer":3,"explanation":"「冗余备份」的构成要件为：①主体为数据中心运维组；②通过按风险等级预置响应动作；③使核心功能在异常下仍可维持。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（等指标越限后才临时研究方案），因此不符合构成要件。故选D。"},{"id":"pdn01607","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「需求导向供给」是指养老服务站点通过按对象条件分档配置资源，使不同群体各取所需的工作机制。\n\n按照上述界定，下列情形可认定为「需求导向供给」的是：","options":["养老服务站点在服务事项梳理中，按对象条件分档配置资源，不同群体各取所需。","养老服务站点在对象需求摸排中，按编制人数而不是实际用量分配，最终大量项目无人使用而真实诉求仍被搁置。","养老服务站点在服务清单编制中，按对象条件分档配置资源，但大量项目无人使用而真实诉求仍被搁置。","由供应商单方决定目录，后续也未按上述机制推进。"],"answer":0,"explanation":"「需求导向供给」的构成要件为：①主体为养老服务站点；②通过按对象条件分档配置资源；③使不同群体各取所需。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01608","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「分级诊疗」是指乡镇卫生院通过按病情轻重分流并约定转诊路径，使病情变化能被尽早发现的工作机制。\n\n根据上述定义，下列不属于「分级诊疗」的是：","options":["乡镇卫生院在康复跟踪记录中，各机构各自重复开单，最终各环节彼此脱节、患者仍需多次重复排队。","乡镇卫生院在慢病随访安排中，按病情轻重分流并约定转诊路径，病情变化能被尽早发现。","乡镇卫生院在重点人群筛查中，按病情轻重分流并约定转诊路径，病情变化能被尽早发现。","乡镇卫生院在康复跟踪记录中，按病情轻重分流并约定转诊路径，病情变化能被尽早发现。"],"answer":0,"explanation":"「分级诊疗」的构成要件为：①主体为乡镇卫生院；②通过按病情轻重分流并约定转诊路径；③使病情变化能被尽早发现。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（各机构各自重复开单），因此不符合构成要件。故选A。"},{"id":"pdn01609","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「表现性评价」是指学校教研组通过结合真实任务表现打分，使教学策略得以动态优化的工作机制。\n\n依据上述定义，以下哪一项符合「表现性评价」的构成要件：","options":["学校教研组在实验课程组织中，按固定名次划线且不追溯变化，最终教学安排并未因数据而作任何调整。","学校教研组在作业反馈整理中，结合真实任务表现打分，但教学安排并未因数据而作任何调整。","学校教研组在单元教学设计中，结合真实任务表现打分，教学策略得以动态优化。","由学生互评后不再复核，后续也未按上述机制推进。"],"answer":2,"explanation":"「表现性评价」的构成要件为：①主体为学校教研组；②通过结合真实任务表现打分；③使教学策略得以动态优化。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01610","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「适应性管理」是指流域管理机构通过划分区块实行差异化管护，使异常苗头被尽早识别的工作机制。\n\n按照上述界定，下列情形不应认定为「适应性管理」的是：","options":["流域管理机构在监测指标波动中，划分区块实行差异化管护，异常苗头被尽早识别。","流域管理机构在栖息环境变化中，全年沿用同一套固定配额，最终指标已越界而措施仍维持不变。","流域管理机构在栖息环境变化中，划分区块实行差异化管护，异常苗头被尽早识别。","流域管理机构在外来因素扩散中，划分区块实行差异化管护，异常苗头被尽早识别。"],"answer":1,"explanation":"「适应性管理」的构成要件为：①主体为流域管理机构；②通过划分区块实行差异化管护；③使异常苗头被尽早识别。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（全年沿用同一套固定配额），因此不符合构成要件。故选B。"},{"id":"pdn01611","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「协同会商」是指乡镇便民中心通过建立台账逐项限时销号，使重复投诉明显下降的工作机制。\n\n根据上述定义，下列属于「协同会商」的是：","options":["乡镇便民中心在便民事项办理中，建立台账逐项限时销号，但问题仍反复出现且未形成稳定机制。","乡镇便民中心在老旧小区改造中，建立台账逐项限时销号，重复投诉明显下降。","乡镇便民中心在邻里纠纷调解中，等群众上门反映后再统一研究，最终问题仍反复出现且未形成稳定机制。","由临时志愿队自行接管，后续也未按上述机制推进。"],"answer":1,"explanation":"「协同会商」的构成要件为：①主体为乡镇便民中心；②通过建立台账逐项限时销号；③使重复投诉明显下降。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01612","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「分级诊疗」是指县域医共体通过与上级医院共享检查结果，使轻症在基层得到及时处置的工作机制。\n\n依据上述定义，以下哪一项不符合「分级诊疗」的构成要件：","options":["县域医共体在慢病随访安排中，与上级医院共享检查结果，轻症在基层得到及时处置。","县域医共体在康复跟踪记录中，与上级医院共享检查结果，轻症在基层得到及时处置。","县域医共体在重点人群筛查中，与上级医院共享检查结果，轻症在基层得到及时处置。","县域医共体在康复跟踪记录中，各机构各自重复开单，最终各环节彼此脱节、患者仍需多次重复排队。"],"answer":3,"explanation":"「分级诊疗」的构成要件为：①主体为县域医共体；②通过与上级医院共享检查结果；③使轻症在基层得到及时处置。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（各机构各自重复开单），因此不符合构成要件。故选D。"},{"id":"pdn01613","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「分级诊疗」是指乡镇卫生院通过建立电子档案并定期回访，使轻症在基层得到及时处置的工作机制。\n\n按照上述界定，下列情形可认定为「分级诊疗」的是：","options":["乡镇卫生院在康复跟踪记录中，待病情加重后再启动会诊，最终各环节彼此脱节、患者仍需多次重复排队。","乡镇卫生院在重点人群筛查中，建立电子档案并定期回访，但各环节彼此脱节、患者仍需多次重复排队。","乡镇卫生院在慢病随访安排中，建立电子档案并定期回访，轻症在基层得到及时处置。","由商业体检机构独立出具结论，后续也未按上述机制推进。"],"answer":2,"explanation":"「分级诊疗」的构成要件为：①主体为乡镇卫生院；②通过建立电子档案并定期回访；③使轻症在基层得到及时处置。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01614","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「分级办理」是指乡镇便民中心通过提前公示并逐户征询意见，使诉求在前端得到化解的工作机制。\n\n根据上述定义，下列不属于「分级办理」的是：","options":["乡镇便民中心在邻里纠纷调解中，直接照搬既有方案、未作任何征询，最终问题仍反复出现且未形成稳定机制。","乡镇便民中心在便民事项办理中，提前公示并逐户征询意见，诉求在前端得到化解。","乡镇便民中心在邻里纠纷调解中，提前公示并逐户征询意见，诉求在前端得到化解。","乡镇便民中心在老旧小区改造中，提前公示并逐户征询意见，诉求在前端得到化解。"],"answer":0,"explanation":"「分级办理」的构成要件为：①主体为乡镇便民中心；②通过提前公示并逐户征询意见；③使诉求在前端得到化解。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（直接照搬既有方案、未作任何征询），因此不符合构成要件。故选A。"},{"id":"pdn01615","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「网格代办」是指乡镇便民中心通过依托网格员常态化走访摸排，使重复投诉明显下降的工作机制。\n\n依据上述定义，以下哪一项符合「网格代办」的构成要件：","options":["乡镇便民中心在便民事项办理中，依托网格员常态化走访摸排，但问题仍反复出现且未形成稳定机制。","乡镇便民中心在老旧小区改造中，依托网格员常态化走访摸排，重复投诉明显下降。","由临时志愿队自行接管，后续也未按上述机制推进。","乡镇便民中心在邻里纠纷调解中，等群众上门反映后再统一研究，最终问题仍反复出现且未形成稳定机制。"],"answer":1,"explanation":"「网格代办」的构成要件为：①主体为乡镇便民中心；②通过依托网格员常态化走访摸排；③使重复投诉明显下降。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01616","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「随访管理」是指县域医共体通过建立电子档案并定期回访，使患者往返成本下降的工作机制。\n\n按照上述界定，下列情形不应认定为「随访管理」的是：","options":["县域医共体在康复跟踪记录中，各机构各自重复开单，最终各环节彼此脱节、患者仍需多次重复排队。","县域医共体在重点人群筛查中，建立电子档案并定期回访，患者往返成本下降。","县域医共体在慢病随访安排中，建立电子档案并定期回访，患者往返成本下降。","县域医共体在康复跟踪记录中，建立电子档案并定期回访，患者往返成本下降。"],"answer":0,"explanation":"「随访管理」的构成要件为：①主体为县域医共体；②通过建立电子档案并定期回访；③使患者往返成本下降。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（各机构各自重复开单），因此不符合构成要件。故选A。"},{"id":"pdn01617","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「试错迭代」是指改革推进专班通过先在小范围试运行再按反馈调整，使偏差在放大前被修正的工作机制。\n\n根据上述定义，下列属于「试错迭代」的是：","options":["改革推进专班在新机制落地中，先在小范围试运行再按反馈调整，但同类偏差在扩面后被成倍放大。","由用户自行摸索不作收集，后续也未按上述机制推进。","改革推进专班在新流程上线中，先在小范围试运行再按反馈调整，偏差在放大前被修正。","改革推进专班在新工具推广中，一次上线后即固化不再迭代，最终同类偏差在扩面后被成倍放大。"],"answer":2,"explanation":"「试错迭代」的构成要件为：①主体为改革推进专班；②通过先在小范围试运行再按反馈调整；③使偏差在放大前被修正。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01618","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「指标复核」是指项目评审委员会通过用对照组剔除同期其他影响，使结论不易被个别异常值带偏的工作机制。\n\n依据上述定义，以下哪一项不符合「指标复核」的构成要件：","options":["项目评审委员会在政策效果评估中，用对照组剔除同期其他影响，结论不易被个别异常值带偏。","项目评审委员会在年度计划编制中，用对照组剔除同期其他影响，结论不易被个别异常值带偏。","项目评审委员会在政策效果评估中，只选取有利样本作展示，最终结论无法由所引数据支撑。","项目评审委员会在抽样数据核查中，用对照组剔除同期其他影响，结论不易被个别异常值带偏。"],"answer":2,"explanation":"「指标复核」的构成要件为：①主体为项目评审委员会；②通过用对照组剔除同期其他影响；③使结论不易被个别异常值带偏。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（只选取有利样本作展示），因此不符合构成要件。故选C。"},{"id":"pdn01619","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「脱敏处理」是指医院信息科通过只采集完成本事项所必需的字段，使历史数据不再无限期堆积的工作机制。\n\n按照上述界定，下列情形可认定为「脱敏处理」的是：","options":["医院信息科在信息采集登记中，只采集完成本事项所必需的字段，历史数据不再无限期堆积。","由外包人员全量导出，后续也未按上述机制推进。","医院信息科在数据调阅留痕中，只采集完成本事项所必需的字段，但与办理目的无关的字段仍被长期留存。","医院信息科在字段权限配置中，所有岗位开放同一份全量清单，最终与办理目的无关的字段仍被长期留存。"],"answer":0,"explanation":"「脱敏处理」的构成要件为：①主体为医院信息科；②通过只采集完成本事项所必需的字段；③使历史数据不再无限期堆积。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01620","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「节点责任制」是指冷链运营方通过异常批次可一键回溯全链路，使问题批次能被快速定位的工作机制。\n\n根据上述定义，下列不属于「节点责任制」的是：","options":["冷链运营方在批次交接记录中，事后一次性补全整本台账，最终出现问题时无法定位到具体环节。","冷链运营方在储运环节温控中，异常批次可一键回溯全链路，问题批次能被快速定位。","冷链运营方在进货环节核验中，异常批次可一键回溯全链路，问题批次能被快速定位。","冷链运营方在批次交接记录中，异常批次可一键回溯全链路，问题批次能被快速定位。"],"answer":0,"explanation":"「节点责任制」的构成要件为：①主体为冷链运营方；②通过异常批次可一键回溯全链路；③使问题批次能被快速定位。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（事后一次性补全整本台账），因此不符合构成要件。故选A。"},{"id":"pdn01621","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「过程性考核」是指学校教研组通过按阶段采集学情数据再修正教学，使教学策略得以动态优化的工作机制。\n\n依据上述定义，以下哪一项符合「过程性考核」的构成要件：","options":["学校教研组在作业反馈整理中，按阶段采集学情数据再修正教学，但教学安排并未因数据而作任何调整。","学校教研组在单元教学设计中，按阶段采集学情数据再修正教学，教学策略得以动态优化。","由学生互评后不再复核，后续也未按上述机制推进。","学校教研组在实验课程组织中，按固定名次划线且不追溯变化，最终教学安排并未因数据而作任何调整。"],"answer":1,"explanation":"「过程性考核」的构成要件为：①主体为学校教研组；②通过按阶段采集学情数据再修正教学；③使教学策略得以动态优化。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01622","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「双向转诊」是指乡镇卫生院通过按病情轻重分流并约定转诊路径，使轻症在基层得到及时处置的工作机制。\n\n按照上述界定，下列情形不应认定为「双向转诊」的是：","options":["乡镇卫生院在康复跟踪记录中，按病情轻重分流并约定转诊路径，轻症在基层得到及时处置。","乡镇卫生院在康复跟踪记录中，一律先安排住院再评估，最终各环节彼此脱节、患者仍需多次重复排队。","乡镇卫生院在重点人群筛查中，按病情轻重分流并约定转诊路径，轻症在基层得到及时处置。","乡镇卫生院在慢病随访安排中，按病情轻重分流并约定转诊路径，轻症在基层得到及时处置。"],"answer":1,"explanation":"「双向转诊」的构成要件为：①主体为乡镇卫生院；②通过按病情轻重分流并约定转诊路径；③使轻症在基层得到及时处置。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（一律先安排住院再评估），因此不符合构成要件。故选B。"},{"id":"pdn01623","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「联合响应」是指跨部门工作专班通过明确牵头与配合边界后统一行动，使响应口径保持一致的工作机制。\n\n根据上述定义，下列属于「联合响应」的是：","options":["跨部门工作专班在信息通报共享中，明确牵头与配合边界后统一行动，但边界地带的问题仍在部门之间来回流转。","由各区各自为政，后续也未按上述机制推进。","跨部门工作专班在联合排班安排中，只开会不落责任清单，最终边界地带的问题仍在部门之间来回流转。","跨部门工作专班在跨界事项梳理中，明确牵头与配合边界后统一行动，响应口径保持一致。"],"answer":3,"explanation":"「联合响应」的构成要件为：①主体为跨部门工作专班；②通过明确牵头与配合边界后统一行动；③使响应口径保持一致。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01624","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「脱敏处理」是指政务数据平台通过到期自动清理并留清理记录，使共享环节不泄露可识别信息的工作机制。\n\n依据上述定义，以下哪一项不符合「脱敏处理」的构成要件：","options":["政务数据平台在数据调阅留痕中，到期自动清理并留清理记录，共享环节不泄露可识别信息。","政务数据平台在信息采集登记中，到期自动清理并留清理记录，共享环节不泄露可识别信息。","政务数据平台在字段权限配置中，到期自动清理并留清理记录，共享环节不泄露可识别信息。","政务数据平台在字段权限配置中，共享时直接提供原始明细，最终与办理目的无关的字段仍被长期留存。"],"answer":3,"explanation":"「脱敏处理」的构成要件为：①主体为政务数据平台；②通过到期自动清理并留清理记录；③使共享环节不泄露可识别信息。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（共享时直接提供原始明细），因此不符合构成要件。故选D。"},{"id":"pdn01625","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「精准匹配」是指农技推广站通过依据使用频次动态增减项目，使资源不再平均摊薄的工作机制。\n\n按照上述界定，下列情形可认定为「精准匹配」的是：","options":["农技推广站在服务清单编制中，依据使用频次动态增减项目，但大量项目无人使用而真实诉求仍被搁置。","农技推广站在服务事项梳理中，依据使用频次动态增减项目，资源不再平均摊薄。","农技推广站在对象需求摸排中，沿用上一年清单不作修订，最终大量项目无人使用而真实诉求仍被搁置。","由服务对象自行寻找渠道，后续也未按上述机制推进。"],"answer":1,"explanation":"「精准匹配」的构成要件为：①主体为农技推广站；②通过依据使用频次动态增减项目；③使资源不再平均摊薄。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01626","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「形成性评价」是指区域教研中心通过先摸清起点再设定分层目标，使学生的薄弱点被及时识别的工作机制。\n\n根据上述定义，下列不属于「形成性评价」的是：","options":["区域教研中心在单元教学设计中，先摸清起点再设定分层目标，学生的薄弱点被及时识别。","区域教研中心在作业反馈整理中，先摸清起点再设定分层目标，学生的薄弱点被及时识别。","区域教研中心在实验课程组织中，只以期末一次分数定结论，最终教学安排并未因数据而作任何调整。","区域教研中心在实验课程组织中，先摸清起点再设定分层目标，学生的薄弱点被及时识别。"],"answer":2,"explanation":"「形成性评价」的构成要件为：①主体为区域教研中心；②通过先摸清起点再设定分层目标；③使学生的薄弱点被及时识别。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（只以期末一次分数定结论），因此不符合构成要件。故选C。"},{"id":"pdn01627","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「闭环处置」是指乡镇便民中心通过提前公示并逐户征询意见，使居民满意度稳步提升的工作机制。\n\n依据上述定义，以下哪一项符合「闭环处置」的构成要件：","options":["乡镇便民中心在邻里纠纷调解中，等群众上门反映后再统一研究，最终问题仍反复出现且未形成稳定机制。","乡镇便民中心在老旧小区改造中，提前公示并逐户征询意见，居民满意度稳步提升。","乡镇便民中心在便民事项办理中，提前公示并逐户征询意见，但问题仍反复出现且未形成稳定机制。","由临时志愿队自行接管，后续也未按上述机制推进。"],"answer":1,"explanation":"「闭环处置」的构成要件为：①主体为乡镇便民中心；②通过提前公示并逐户征询意见；③使居民满意度稳步提升。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01628","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「用户旅程映射」是指产品体验小组通过先做可体验原型再收集反馈，使改动获得使用者认同的工作机制。\n\n按照上述界定，下列情形不应认定为「用户旅程映射」的是：","options":["产品体验小组在公共界面优化中，照搬其他地区成品，最终上线后仍频发与习惯不符的障碍。","产品体验小组在使用路径排查中，先做可体验原型再收集反馈，改动获得使用者认同。","产品体验小组在公共界面优化中，先做可体验原型再收集反馈，改动获得使用者认同。","产品体验小组在服务流程梳理中，先做可体验原型再收集反馈，改动获得使用者认同。"],"answer":0,"explanation":"「用户旅程映射」的构成要件为：①主体为产品体验小组；②通过先做可体验原型再收集反馈；③使改动获得使用者认同。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（照搬其他地区成品），因此不符合构成要件。故选A。"},{"id":"pdn01629","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「脱敏处理」是指学校学籍管理系统通过按岗位授予最小可见范围，使超范围信息不被额外索取的工作机制。\n\n根据上述定义，下列属于「脱敏处理」的是：","options":["学校学籍管理系统在数据调阅留痕中，按岗位授予最小可见范围，但与办理目的无关的字段仍被长期留存。","学校学籍管理系统在字段权限配置中，超过期限仍不作清理，最终与办理目的无关的字段仍被长期留存。","学校学籍管理系统在信息采集登记中，按岗位授予最小可见范围，超范围信息不被额外索取。","由系统默认长期全量保留，后续也未按上述机制推进。"],"answer":2,"explanation":"「脱敏处理」的构成要件为：①主体为学校学籍管理系统；②通过按岗位授予最小可见范围；③使超范围信息不被额外索取。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01630","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「留痕管理」是指食品药品监管所通过按批号串联台账与检验记录，使问题批次能被快速定位的工作机制。\n\n依据上述定义，以下哪一项不符合「留痕管理」的构成要件：","options":["食品药品监管所在储运环节温控中，按批号串联台账与检验记录，问题批次能被快速定位。","食品药品监管所在批次交接记录中，只在最终出库时记一笔总账，最终出现问题时无法定位到具体环节。","食品药品监管所在进货环节核验中，按批号串联台账与检验记录，问题批次能被快速定位。","食品药品监管所在批次交接记录中，按批号串联台账与检验记录，问题批次能被快速定位。"],"answer":1,"explanation":"「留痕管理」的构成要件为：①主体为食品药品监管所；②通过按批号串联台账与检验记录；③使问题批次能被快速定位。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（只在最终出库时记一笔总账），因此不符合构成要件。故选B。"},{"id":"pdn01631","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「分级诊疗」是指乡镇卫生院通过先由基层评估再决定是否上转，使重复检查明显减少的工作机制。\n\n按照上述界定，下列情形可认定为「分级诊疗」的是：","options":["乡镇卫生院在慢病随访安排中，先由基层评估再决定是否上转，重复检查明显减少。","乡镇卫生院在重点人群筛查中，先由基层评估再决定是否上转，但各环节彼此脱节、患者仍需多次重复排队。","乡镇卫生院在康复跟踪记录中，只做一次性检查不作后续跟踪，最终各环节彼此脱节、患者仍需多次重复排队。","仅由三甲医院单方建档，后续也未按上述机制推进。"],"answer":0,"explanation":"「分级诊疗」的构成要件为：①主体为乡镇卫生院；②通过先由基层评估再决定是否上转；③使重复检查明显减少。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01632","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「灰度验证」是指产品迭代小组通过每轮结束后复盘并修订下一轮，使偏差在放大前被修正的工作机制。\n\n根据上述定义，下列不属于「灰度验证」的是：","options":["产品迭代小组在新流程上线中，每轮结束后复盘并修订下一轮，偏差在放大前被修正。","产品迭代小组在新机制落地中，每轮结束后复盘并修订下一轮，偏差在放大前被修正。","产品迭代小组在新工具推广中，只记录成功案例不分析偏差，最终同类偏差在扩面后被成倍放大。","产品迭代小组在新工具推广中，每轮结束后复盘并修订下一轮，偏差在放大前被修正。"],"answer":2,"explanation":"「灰度验证」的构成要件为：①主体为产品迭代小组；②通过每轮结束后复盘并修订下一轮；③使偏差在放大前被修正。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（只记录成功案例不分析偏差），因此不符合构成要件。故选C。"},{"id":"pdn01633","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「阈值预警」是指生态环境监测站通过划分区块实行差异化管护，使管控成本保持在合理区间的工作机制。\n\n依据上述定义，以下哪一项符合「阈值预警」的构成要件：","options":["生态环境监测站在栖息环境变化中，等出现明显损害后再启动处置，最终指标已越界而措施仍维持不变。","生态环境监测站在外来因素扩散中，划分区块实行差异化管护，但指标已越界而措施仍维持不变。","生态环境监测站在监测指标波动中，划分区块实行差异化管护，管控成本保持在合理区间。","由游客反馈临时决定，后续也未按上述机制推进。"],"answer":2,"explanation":"「阈值预警」的构成要件为：①主体为生态环境监测站；②通过划分区块实行差异化管护；③使管控成本保持在合理区间。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01634","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「试错迭代」是指产品迭代小组通过设置观察期并保留回退通道，使后续推广更贴合一线实际的工作机制。\n\n按照上述界定，下列情形不应认定为「试错迭代」的是：","options":["产品迭代小组在新工具推广中，不经试点直接全面强制推开，最终同类偏差在扩面后被成倍放大。","产品迭代小组在新流程上线中，设置观察期并保留回退通道，后续推广更贴合一线实际。","产品迭代小组在新工具推广中，设置观察期并保留回退通道，后续推广更贴合一线实际。","产品迭代小组在新机制落地中，设置观察期并保留回退通道，后续推广更贴合一线实际。"],"answer":0,"explanation":"「试错迭代」的构成要件为：①主体为产品迭代小组；②通过设置观察期并保留回退通道；③使后续推广更贴合一线实际。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（不经试点直接全面强制推开），因此不符合构成要件。故选A。"},{"id":"pdn01635","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「分级诊疗」是指社区卫生服务中心通过与上级医院共享检查结果，使重复检查明显减少的工作机制。\n\n根据上述定义，下列属于「分级诊疗」的是：","options":["仅由三甲医院单方建档，后续也未按上述机制推进。","社区卫生服务中心在慢病随访安排中，与上级医院共享检查结果，重复检查明显减少。","社区卫生服务中心在重点人群筛查中，与上级医院共享检查结果，但各环节彼此脱节、患者仍需多次重复排队。","社区卫生服务中心在康复跟踪记录中，只做一次性检查不作后续跟踪，最终各环节彼此脱节、患者仍需多次重复排队。"],"answer":1,"explanation":"「分级诊疗」的构成要件为：①主体为社区卫生服务中心；②通过与上级医院共享检查结果；③使重复检查明显减少。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01636","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「按需配置」是指公共文化服务中心通过依据使用频次动态增减项目，使资源不再平均摊薄的工作机制。\n\n依据上述定义，以下哪一项不符合「按需配置」的构成要件：","options":["公共文化服务中心在服务清单编制中，依据使用频次动态增减项目，资源不再平均摊薄。","公共文化服务中心在对象需求摸排中，依据使用频次动态增减项目，资源不再平均摊薄。","公共文化服务中心在服务事项梳理中，依据使用频次动态增减项目，资源不再平均摊薄。","公共文化服务中心在对象需求摸排中，先采购再询问是否需要，最终大量项目无人使用而真实诉求仍被搁置。"],"answer":3,"explanation":"「按需配置」的构成要件为：①主体为公共文化服务中心；②通过依据使用频次动态增减项目；③使资源不再平均摊薄。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（先采购再询问是否需要），因此不符合构成要件。故选D。"},{"id":"pdn01637","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「双向转诊」是指乡镇卫生院通过按病情轻重分流并约定转诊路径，使患者往返成本下降的工作机制。\n\n按照上述界定，下列情形可认定为「双向转诊」的是：","options":["由商业体检机构独立出具结论，后续也未按上述机制推进。","乡镇卫生院在康复跟踪记录中，待病情加重后再启动会诊，最终各环节彼此脱节、患者仍需多次重复排队。","乡镇卫生院在慢病随访安排中，按病情轻重分流并约定转诊路径，患者往返成本下降。","乡镇卫生院在重点人群筛查中，按病情轻重分流并约定转诊路径，但各环节彼此脱节、患者仍需多次重复排队。"],"answer":2,"explanation":"「双向转诊」的构成要件为：①主体为乡镇卫生院；②通过按病情轻重分流并约定转诊路径；③使患者往返成本下降。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01638","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「分级诊疗」是指乡镇卫生院通过与上级医院共享检查结果，使轻症在基层得到及时处置的工作机制。\n\n根据上述定义，下列不属于「分级诊疗」的是：","options":["乡镇卫生院在康复跟踪记录中，与上级医院共享检查结果，轻症在基层得到及时处置。","乡镇卫生院在重点人群筛查中，与上级医院共享检查结果，轻症在基层得到及时处置。","乡镇卫生院在康复跟踪记录中，一律先安排住院再评估，最终各环节彼此脱节、患者仍需多次重复排队。","乡镇卫生院在慢病随访安排中，与上级医院共享检查结果，轻症在基层得到及时处置。"],"answer":2,"explanation":"「分级诊疗」的构成要件为：①主体为乡镇卫生院；②通过与上级医院共享检查结果；③使轻症在基层得到及时处置。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（一律先安排住院再评估），因此不符合构成要件。故选C。"},{"id":"pdn01639","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「最小必要采集」是指学校学籍管理系统通过只采集完成本事项所必需的字段，使超范围信息不被额外索取的工作机制。\n\n依据上述定义，以下哪一项符合「最小必要采集」的构成要件：","options":["学校学籍管理系统在字段权限配置中，所有岗位开放同一份全量清单，最终与办理目的无关的字段仍被长期留存。","学校学籍管理系统在数据调阅留痕中，只采集完成本事项所必需的字段，但与办理目的无关的字段仍被长期留存。","学校学籍管理系统在信息采集登记中，只采集完成本事项所必需的字段，超范围信息不被额外索取。","由外包人员全量导出，后续也未按上述机制推进。"],"answer":2,"explanation":"「最小必要采集」的构成要件为：①主体为学校学籍管理系统；②通过只采集完成本事项所必需的字段；③使超范围信息不被额外索取。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01640","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「原型共创」是指社区营造团队通过先做可体验原型再收集反馈，使方案贴合真实使用习惯的工作机制。\n\n按照上述界定，下列情形不应认定为「原型共创」的是：","options":["社区营造团队在服务流程梳理中，先做可体验原型再收集反馈，方案贴合真实使用习惯。","社区营造团队在公共界面优化中，照搬其他地区成品，最终上线后仍频发与习惯不符的障碍。","社区营造团队在公共界面优化中，先做可体验原型再收集反馈，方案贴合真实使用习惯。","社区营造团队在使用路径排查中，先做可体验原型再收集反馈，方案贴合真实使用习惯。"],"answer":1,"explanation":"「原型共创」的构成要件为：①主体为社区营造团队；②通过先做可体验原型再收集反馈；③使方案贴合真实使用习惯。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（照搬其他地区成品），因此不符合构成要件。故选B。"},{"id":"pdn01641","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「小步试点」是指改革推进专班通过设置观察期并保留回退通道，使偏差在放大前被修正的工作机制。\n\n根据上述定义，下列属于「小步试点」的是：","options":["改革推进专班在新流程上线中，设置观察期并保留回退通道，偏差在放大前被修正。","由用户自行摸索不作收集，后续也未按上述机制推进。","改革推进专班在新机制落地中，设置观察期并保留回退通道，但同类偏差在扩面后被成倍放大。","改革推进专班在新工具推广中，一次上线后即固化不再迭代，最终同类偏差在扩面后被成倍放大。"],"answer":0,"explanation":"「小步试点」的构成要件为：①主体为改革推进专班；②通过设置观察期并保留回退通道；③使偏差在放大前被修正。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01642","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「精准匹配」是指养老服务站点通过按对象条件分档配置资源，使资源不再平均摊薄的工作机制。\n\n依据上述定义，以下哪一项不符合「精准匹配」的构成要件：","options":["养老服务站点在对象需求摸排中，按对象条件分档配置资源，资源不再平均摊薄。","养老服务站点在服务事项梳理中，按对象条件分档配置资源，资源不再平均摊薄。","养老服务站点在服务清单编制中，按对象条件分档配置资源，资源不再平均摊薄。","养老服务站点在对象需求摸排中，所有对象发放完全相同的固定包，最终大量项目无人使用而真实诉求仍被搁置。"],"answer":3,"explanation":"「精准匹配」的构成要件为：①主体为养老服务站点；②通过按对象条件分档配置资源；③使资源不再平均摊薄。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（所有对象发放完全相同的固定包），因此不符合构成要件。故选D。"},{"id":"pdn01643","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「共创反馈环」是指社区营造团队通过邀请使用者全程参与方案打磨，使方案贴合真实使用习惯的工作机制。\n\n按照上述界定，下列情形可认定为「共创反馈环」的是：","options":["由供应商提供标准模板，后续也未按上述机制推进。","社区营造团队在使用路径排查中，邀请使用者全程参与方案打磨，但上线后仍频发与习惯不符的障碍。","社区营造团队在公共界面优化中，只做内部评审不接触使用者，最终上线后仍频发与习惯不符的障碍。","社区营造团队在服务流程梳理中，邀请使用者全程参与方案打磨，方案贴合真实使用习惯。"],"answer":3,"explanation":"「共创反馈环」的构成要件为：①主体为社区营造团队；②通过邀请使用者全程参与方案打磨；③使方案贴合真实使用习惯。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01644","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「目的限定」是指政务数据平台通过只采集完成本事项所必需的字段，使敏感字段仅在授权场景可见的工作机制。\n\n根据上述定义，下列不属于「目的限定」的是：","options":["政务数据平台在信息采集登记中，只采集完成本事项所必需的字段，敏感字段仅在授权场景可见。","政务数据平台在字段权限配置中，共享时直接提供原始明细，最终与办理目的无关的字段仍被长期留存。","政务数据平台在字段权限配置中，只采集完成本事项所必需的字段，敏感字段仅在授权场景可见。","政务数据平台在数据调阅留痕中，只采集完成本事项所必需的字段，敏感字段仅在授权场景可见。"],"answer":1,"explanation":"「目的限定」的构成要件为：①主体为政务数据平台；②通过只采集完成本事项所必需的字段；③使敏感字段仅在授权场景可见。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（共享时直接提供原始明细），因此不符合构成要件。故选B。"},{"id":"pdn01645","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「试错迭代」是指数字化转型办公室通过分批次扩面而非一次铺开，使偏差在放大前被修正的工作机制。\n\n依据上述定义，以下哪一项符合「试错迭代」的构成要件：","options":["数字化转型办公室在新机制落地中，分批次扩面而非一次铺开，但同类偏差在扩面后被成倍放大。","由用户自行摸索不作收集，后续也未按上述机制推进。","数字化转型办公室在新流程上线中，分批次扩面而非一次铺开，偏差在放大前被修正。","数字化转型办公室在新工具推广中，一次上线后即固化不再迭代，最终同类偏差在扩面后被成倍放大。"],"answer":2,"explanation":"「试错迭代」的构成要件为：①主体为数字化转型办公室；②通过分批次扩面而非一次铺开；③使偏差在放大前被修正。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01646","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「协同治理」是指街道与职能站所通过明确牵头与配合边界后统一行动，使跨界问题不再悬空的工作机制。\n\n按照上述界定，下列情形不应认定为「协同治理」的是：","options":["街道与职能站所在跨界事项梳理中，明确牵头与配合边界后统一行动，跨界问题不再悬空。","街道与职能站所在信息通报共享中，明确牵头与配合边界后统一行动，跨界问题不再悬空。","街道与职能站所在联合排班安排中，明确牵头与配合边界后统一行动，跨界问题不再悬空。","街道与职能站所在联合排班安排中，各部门分头进场、结果互不通报，最终边界地带的问题仍在部门之间来回流转。"],"answer":3,"explanation":"「协同治理」的构成要件为：①主体为街道与职能站所；②通过明确牵头与配合边界后统一行动；③使跨界问题不再悬空。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（各部门分头进场、结果互不通报），因此不符合构成要件。故选D。"},{"id":"pdn01647","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「连续照护」是指家庭医生团队通过先由基层评估再决定是否上转，使病情变化能被尽早发现的工作机制。\n\n根据上述定义，下列属于「连续照护」的是：","options":["家庭医生团队在康复跟踪记录中，只做一次性检查不作后续跟踪，最终各环节彼此脱节、患者仍需多次重复排队。","家庭医生团队在慢病随访安排中，先由基层评估再决定是否上转，病情变化能被尽早发现。","仅由三甲医院单方建档，后续也未按上述机制推进。","家庭医生团队在重点人群筛查中，先由基层评估再决定是否上转，但各环节彼此脱节、患者仍需多次重复排队。"],"answer":1,"explanation":"「连续照护」的构成要件为：①主体为家庭医生团队；②通过先由基层评估再决定是否上转；③使病情变化能被尽早发现。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01648","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「分区管控」是指生态环境监测站通过划分区块实行差异化管护，使干预强度与实际风险相匹配的工作机制。\n\n依据上述定义，以下哪一项不符合「分区管控」的构成要件：","options":["生态环境监测站在栖息环境变化中，划分区块实行差异化管护，干预强度与实际风险相匹配。","生态环境监测站在栖息环境变化中，只看年度均值忽略峰值，最终指标已越界而措施仍维持不变。","生态环境监测站在监测指标波动中，划分区块实行差异化管护，干预强度与实际风险相匹配。","生态环境监测站在外来因素扩散中，划分区块实行差异化管护，干预强度与实际风险相匹配。"],"answer":1,"explanation":"「分区管控」的构成要件为：①主体为生态环境监测站；②通过划分区块实行差异化管护；③使干预强度与实际风险相匹配。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（只看年度均值忽略峰值），因此不符合构成要件。故选B。"},{"id":"pdn01649","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「试错迭代」是指产品迭代小组通过先在小范围试运行再按反馈调整，使后续推广更贴合一线实际的工作机制。\n\n按照上述界定，下列情形可认定为「试错迭代」的是：","options":["产品迭代小组在新流程上线中，先在小范围试运行再按反馈调整，后续推广更贴合一线实际。","产品迭代小组在新机制落地中，先在小范围试运行再按反馈调整，但同类偏差在扩面后被成倍放大。","由用户自行摸索不作收集，后续也未按上述机制推进。","产品迭代小组在新工具推广中，一次上线后即固化不再迭代，最终同类偏差在扩面后被成倍放大。"],"answer":0,"explanation":"「试错迭代」的构成要件为：①主体为产品迭代小组；②通过先在小范围试运行再按反馈调整；③使后续推广更贴合一线实际。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01650","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「共创反馈环」是指无障碍改造专班通过按真实使用路径逐点排查痛点，使改动获得使用者认同的工作机制。\n\n根据上述定义，下列不属于「共创反馈环」的是：","options":["无障碍改造专班在使用路径排查中，按真实使用路径逐点排查痛点，改动获得使用者认同。","无障碍改造专班在服务流程梳理中，按真实使用路径逐点排查痛点，改动获得使用者认同。","无障碍改造专班在公共界面优化中，按真实使用路径逐点排查痛点，改动获得使用者认同。","无障碍改造专班在公共界面优化中，仅在完工后征求意见，最终上线后仍频发与习惯不符的障碍。"],"answer":3,"explanation":"「共创反馈环」的构成要件为：①主体为无障碍改造专班；②通过按真实使用路径逐点排查痛点；③使改动获得使用者认同。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（仅在完工后征求意见），因此不符合构成要件。故选D。"},{"id":"pdn01651","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「协同会商」是指街道办通过联合多方现场会商后再定方案，使居民满意度稳步提升的工作机制。\n\n依据上述定义，以下哪一项符合「协同会商」的构成要件：","options":["街道办在便民事项办理中，联合多方现场会商后再定方案，但问题仍反复出现且未形成稳定机制。","街道办在老旧小区改造中，联合多方现场会商后再定方案，居民满意度稳步提升。","街道办在邻里纠纷调解中，等群众上门反映后再统一研究，最终问题仍反复出现且未形成稳定机制。","由临时志愿队自行接管，后续也未按上述机制推进。"],"answer":1,"explanation":"「协同会商」的构成要件为：①主体为街道办；②通过联合多方现场会商后再定方案；③使居民满意度稳步提升。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01652","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「基线比对」是指规划编制组通过先确立基线再对照前后变化，使判断建立在可核验的依据上的工作机制。\n\n按照上述界定，下列情形不应认定为「基线比对」的是：","options":["规划编制组在政策效果评估中，以主观感受替代实测数据，最终结论无法由所引数据支撑。","规划编制组在年度计划编制中，先确立基线再对照前后变化，判断建立在可核验的依据上。","规划编制组在政策效果评估中，先确立基线再对照前后变化，判断建立在可核验的依据上。","规划编制组在抽样数据核查中，先确立基线再对照前后变化，判断建立在可核验的依据上。"],"answer":0,"explanation":"「基线比对」的构成要件为：①主体为规划编制组；②通过先确立基线再对照前后变化；③使判断建立在可核验的依据上。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（以主观感受替代实测数据），因此不符合构成要件。故选A。"},{"id":"pdn01653","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「跨界协作」是指街道与职能站所通过建立常态化联络与移交规则，使响应口径保持一致的工作机制。\n\n根据上述定义，下列属于「跨界协作」的是：","options":["街道与职能站所在信息通报共享中，建立常态化联络与移交规则，但边界地带的问题仍在部门之间来回流转。","街道与职能站所在联合排班安排中，各自按本部门旧流程办理，最终边界地带的问题仍在部门之间来回流转。","街道与职能站所在跨界事项梳理中，建立常态化联络与移交规则，响应口径保持一致。","由上级部门包办到底，后续也未按上述机制推进。"],"answer":2,"explanation":"「跨界协作」的构成要件为：①主体为街道与职能站所；②通过建立常态化联络与移交规则；③使响应口径保持一致。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01654","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「增值评价」是指任课教师团队通过随堂记录并及时反馈调整，使后续目标更贴合实际起点的工作机制。\n\n依据上述定义，以下哪一项不符合「增值评价」的构成要件：","options":["任课教师团队在单元教学设计中，随堂记录并及时反馈调整，后续目标更贴合实际起点。","任课教师团队在实验课程组织中，随堂记录并及时反馈调整，后续目标更贴合实际起点。","任课教师团队在实验课程组织中，只以期末一次分数定结论，最终教学安排并未因数据而作任何调整。","任课教师团队在作业反馈整理中，随堂记录并及时反馈调整，后续目标更贴合实际起点。"],"answer":2,"explanation":"「增值评价」的构成要件为：①主体为任课教师团队；②通过随堂记录并及时反馈调整；③使后续目标更贴合实际起点。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（只以期末一次分数定结论），因此不符合构成要件。故选C。"},{"id":"pdn01655","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「预案触发」是指数据中心运维组通过识别薄弱环节并预先加固，使险情初起即进入有序处置的工作机制。\n\n按照上述界定，下列情形可认定为「预案触发」的是：","options":["数据中心运维组在关键节点值守中，识别薄弱环节并预先加固，但异常发生时无预设动作可依。","由上级在事后统一追认，后续也未按上述机制推进。","数据中心运维组在风险等级研判中，识别薄弱环节并预先加固，险情初起即进入有序处置。","数据中心运维组在响应动作预置中，仅保留一份无备用的关键设备，最终异常发生时无预设动作可依。"],"answer":2,"explanation":"「预案触发」的构成要件为：①主体为数据中心运维组；②通过识别薄弱环节并预先加固；③使险情初起即进入有序处置。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01656","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「增值评价」是指任课教师团队通过先摸清起点再设定分层目标，使后续目标更贴合实际起点的工作机制。\n\n根据上述定义，下列不属于「增值评价」的是：","options":["任课教师团队在实验课程组织中，先摸清起点再设定分层目标，后续目标更贴合实际起点。","任课教师团队在实验课程组织中，照搬统一答案不看作答过程，最终教学安排并未因数据而作任何调整。","任课教师团队在单元教学设计中，先摸清起点再设定分层目标，后续目标更贴合实际起点。","任课教师团队在作业反馈整理中，先摸清起点再设定分层目标，后续目标更贴合实际起点。"],"answer":1,"explanation":"「增值评价」的构成要件为：①主体为任课教师团队；②通过先摸清起点再设定分层目标；③使后续目标更贴合实际起点。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（照搬统一答案不看作答过程），因此不符合构成要件。故选B。"},{"id":"pdn01657","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「冗余备份」是指水利工程调度处通过按风险等级预置响应动作，使核心功能在异常下仍可维持的工作机制。\n\n依据上述定义，以下哪一项符合「冗余备份」的构成要件：","options":["水利工程调度处在响应动作预置中，只在事发后补充记录，最终异常发生时无预设动作可依。","水利工程调度处在风险等级研判中，按风险等级预置响应动作，核心功能在异常下仍可维持。","水利工程调度处在关键节点值守中，按风险等级预置响应动作，但异常发生时无预设动作可依。","由外部单位事后支援，后续也未按上述机制推进。"],"answer":1,"explanation":"「冗余备份」的构成要件为：①主体为水利工程调度处；②通过按风险等级预置响应动作；③使核心功能在异常下仍可维持。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01658","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「网格代办」是指乡镇便民中心通过提前公示并逐户征询意见，使平均处置周期缩短的工作机制。\n\n按照上述界定，下列情形不应认定为「网格代办」的是：","options":["乡镇便民中心在邻里纠纷调解中，提前公示并逐户征询意见，平均处置周期缩短。","乡镇便民中心在老旧小区改造中，提前公示并逐户征询意见，平均处置周期缩短。","乡镇便民中心在邻里纠纷调解中，直接照搬既有方案、未作任何征询，最终问题仍反复出现且未形成稳定机制。","乡镇便民中心在便民事项办理中，提前公示并逐户征询意见，平均处置周期缩短。"],"answer":2,"explanation":"「网格代办」的构成要件为：①主体为乡镇便民中心；②通过提前公示并逐户征询意见；③使平均处置周期缩短。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（直接照搬既有方案、未作任何征询），因此不符合构成要件。故选C。"},{"id":"pdn01659","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「留痕管理」是指食品药品监管所通过异常批次可一键回溯全链路，使责任环节清晰可查的工作机制。\n\n根据上述定义，下列属于「留痕管理」的是：","options":["食品药品监管所在批次交接记录中，各环节各自记录且互不关联，最终出现问题时无法定位到具体环节。","食品药品监管所在储运环节温控中，异常批次可一键回溯全链路，但出现问题时无法定位到具体环节。","食品药品监管所在进货环节核验中，异常批次可一键回溯全链路，责任环节清晰可查。","由终端门店自行补记，后续也未按上述机制推进。"],"answer":2,"explanation":"「留痕管理」的构成要件为：①主体为食品药品监管所；②通过异常批次可一键回溯全链路；③使责任环节清晰可查。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01660","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「分级授权」是指学校学籍管理系统通过到期自动清理并留清理记录，使共享环节不泄露可识别信息的工作机制。\n\n依据上述定义，以下哪一项不符合「分级授权」的构成要件：","options":["学校学籍管理系统在字段权限配置中，到期自动清理并留清理记录，共享环节不泄露可识别信息。","学校学籍管理系统在数据调阅留痕中，到期自动清理并留清理记录，共享环节不泄露可识别信息。","学校学籍管理系统在字段权限配置中，共享时直接提供原始明细，最终与办理目的无关的字段仍被长期留存。","学校学籍管理系统在信息采集登记中，到期自动清理并留清理记录，共享环节不泄露可识别信息。"],"answer":2,"explanation":"「分级授权」的构成要件为：①主体为学校学籍管理系统；②通过到期自动清理并留清理记录；③使共享环节不泄露可识别信息。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（共享时直接提供原始明细），因此不符合构成要件。故选C。"},{"id":"pdn01661","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「原型共创」是指社区营造团队通过多轮共创后收敛为最终版本，使方案贴合真实使用习惯的工作机制。\n\n按照上述界定，下列情形可认定为「原型共创」的是：","options":["社区营造团队在使用路径排查中，多轮共创后收敛为最终版本，但上线后仍频发与习惯不符的障碍。","由外部专家远程定稿，后续也未按上述机制推进。","社区营造团队在公共界面优化中，一次性定稿不再接收反馈，最终上线后仍频发与习惯不符的障碍。","社区营造团队在服务流程梳理中，多轮共创后收敛为最终版本，方案贴合真实使用习惯。"],"answer":3,"explanation":"「原型共创」的构成要件为：①主体为社区营造团队；②通过多轮共创后收敛为最终版本；③使方案贴合真实使用习惯。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01662","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「证据本位决策」是指规划编制组通过先确立基线再对照前后变化，使判断建立在可核验的依据上的工作机制。\n\n根据上述定义，下列不属于「证据本位决策」的是：","options":["规划编制组在政策效果评估中，先确立基线再对照前后变化，判断建立在可核验的依据上。","规划编制组在年度计划编制中，先确立基线再对照前后变化，判断建立在可核验的依据上。","规划编制组在政策效果评估中，只选取有利样本作展示，最终结论无法由所引数据支撑。","规划编制组在抽样数据核查中，先确立基线再对照前后变化，判断建立在可核验的依据上。"],"answer":2,"explanation":"「证据本位决策」的构成要件为：①主体为规划编制组；②通过先确立基线再对照前后变化；③使判断建立在可核验的依据上。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（只选取有利样本作展示），因此不符合构成要件。故选C。"},{"id":"pdn01663","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「增值评价」是指课程组通过随堂记录并及时反馈调整，使学习过程而非仅结果被看见的工作机制。\n\n依据上述定义，以下哪一项符合「增值评价」的构成要件：","options":["课程组在实验课程组织中，全程不作任何反馈、结束后才公布，最终教学安排并未因数据而作任何调整。","课程组在单元教学设计中，随堂记录并及时反馈调整，学习过程而非仅结果被看见。","由家长自行报送成绩，后续也未按上述机制推进。","课程组在作业反馈整理中，随堂记录并及时反馈调整，但教学安排并未因数据而作任何调整。"],"answer":1,"explanation":"「增值评价」的构成要件为：①主体为课程组；②通过随堂记录并及时反馈调整；③使学习过程而非仅结果被看见。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01664","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「协同治理」是指流域联席会议通过明确牵头与配合边界后统一行动，使重复检查与推诿明显减少的工作机制。\n\n按照上述界定，下列情形不应认定为「协同治理」的是：","options":["流域联席会议在联合排班安排中，明确牵头与配合边界后统一行动，重复检查与推诿明显减少。","流域联席会议在跨界事项梳理中，明确牵头与配合边界后统一行动，重复检查与推诿明显减少。","流域联席会议在信息通报共享中，明确牵头与配合边界后统一行动，重复检查与推诿明显减少。","流域联席会议在联合排班安排中，遇跨界事项互相等待，最终边界地带的问题仍在部门之间来回流转。"],"answer":3,"explanation":"「协同治理」的构成要件为：①主体为流域联席会议；②通过明确牵头与配合边界后统一行动；③使重复检查与推诿明显减少。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（遇跨界事项互相等待），因此不符合构成要件。故选D。"},{"id":"pdn01665","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「连续照护」是指社区卫生服务中心通过按病情轻重分流并约定转诊路径，使患者往返成本下降的工作机制。\n\n根据上述定义，下列属于「连续照护」的是：","options":["社区卫生服务中心在慢病随访安排中，按病情轻重分流并约定转诊路径，患者往返成本下降。","社区卫生服务中心在重点人群筛查中，按病情轻重分流并约定转诊路径，但各环节彼此脱节、患者仍需多次重复排队。","由商业体检机构独立出具结论，后续也未按上述机制推进。","社区卫生服务中心在康复跟踪记录中，待病情加重后再启动会诊，最终各环节彼此脱节、患者仍需多次重复排队。"],"answer":0,"explanation":"「连续照护」的构成要件为：①主体为社区卫生服务中心；②通过按病情轻重分流并约定转诊路径；③使患者往返成本下降。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01666","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「最小必要采集」是指政务数据平台通过按岗位授予最小可见范围，使共享环节不泄露可识别信息的工作机制。\n\n依据上述定义，以下哪一项不符合「最小必要采集」的构成要件：","options":["政务数据平台在数据调阅留痕中，按岗位授予最小可见范围，共享环节不泄露可识别信息。","政务数据平台在信息采集登记中，按岗位授予最小可见范围，共享环节不泄露可识别信息。","政务数据平台在字段权限配置中，按岗位授予最小可见范围，共享环节不泄露可识别信息。","政务数据平台在字段权限配置中，为方便起见一次性收齐全部字段，最终与办理目的无关的字段仍被长期留存。"],"answer":3,"explanation":"「最小必要采集」的构成要件为：①主体为政务数据平台；②通过按岗位授予最小可见范围；③使共享环节不泄露可识别信息。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（为方便起见一次性收齐全部字段），因此不符合构成要件。故选D。"},{"id":"pdn01667","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「联合响应」是指街道与职能站所通过明确牵头与配合边界后统一行动，使响应口径保持一致的工作机制。\n\n按照上述界定，下列情形可认定为「联合响应」的是：","options":["街道与职能站所在信息通报共享中，明确牵头与配合边界后统一行动，但边界地带的问题仍在部门之间来回流转。","由各区各自为政，后续也未按上述机制推进。","街道与职能站所在跨界事项梳理中，明确牵头与配合边界后统一行动，响应口径保持一致。","街道与职能站所在联合排班安排中，只开会不落责任清单，最终边界地带的问题仍在部门之间来回流转。"],"answer":2,"explanation":"「联合响应」的构成要件为：①主体为街道与职能站所；②通过明确牵头与配合边界后统一行动；③使响应口径保持一致。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01668","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「共创反馈环」是指产品体验小组通过按真实使用路径逐点排查痛点，使返工与投诉明显减少的工作机制。\n\n根据上述定义，下列不属于「共创反馈环」的是：","options":["产品体验小组在使用路径排查中，按真实使用路径逐点排查痛点，返工与投诉明显减少。","产品体验小组在公共界面优化中，按真实使用路径逐点排查痛点，返工与投诉明显减少。","产品体验小组在服务流程梳理中，按真实使用路径逐点排查痛点，返工与投诉明显减少。","产品体验小组在公共界面优化中，照搬其他地区成品，最终上线后仍频发与习惯不符的障碍。"],"answer":3,"explanation":"「共创反馈环」的构成要件为：①主体为产品体验小组；②通过按真实使用路径逐点排查痛点；③使返工与投诉明显减少。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（照搬其他地区成品），因此不符合构成要件。故选D。"},{"id":"pdn01669","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「联勤联动」是指街道与职能站所通过明确牵头与配合边界后统一行动，使处置效率整体提升的工作机制。\n\n依据上述定义，以下哪一项符合「联勤联动」的构成要件：","options":["街道与职能站所在信息通报共享中，明确牵头与配合边界后统一行动，但边界地带的问题仍在部门之间来回流转。","街道与职能站所在联合排班安排中，各自按本部门旧流程办理，最终边界地带的问题仍在部门之间来回流转。","由上级部门包办到底，后续也未按上述机制推进。","街道与职能站所在跨界事项梳理中，明确牵头与配合边界后统一行动，处置效率整体提升。"],"answer":3,"explanation":"「联勤联动」的构成要件为：①主体为街道与职能站所；②通过明确牵头与配合边界后统一行动；③使处置效率整体提升。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01670","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「网格代办」是指乡镇便民中心通过联合多方现场会商后再定方案，使重复投诉明显下降的工作机制。\n\n按照上述界定，下列情形不应认定为「网格代办」的是：","options":["乡镇便民中心在邻里纠纷调解中，直接照搬既有方案、未作任何征询，最终问题仍反复出现且未形成稳定机制。","乡镇便民中心在便民事项办理中，联合多方现场会商后再定方案，重复投诉明显下降。","乡镇便民中心在老旧小区改造中，联合多方现场会商后再定方案，重复投诉明显下降。","乡镇便民中心在邻里纠纷调解中，联合多方现场会商后再定方案，重复投诉明显下降。"],"answer":0,"explanation":"「网格代办」的构成要件为：①主体为乡镇便民中心；②通过联合多方现场会商后再定方案；③使重复投诉明显下降。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（直接照搬既有方案、未作任何征询），因此不符合构成要件。故选A。"},{"id":"pdn01671","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「增值评价」是指学校教研组通过随堂记录并及时反馈调整，使学生的薄弱点被及时识别的工作机制。\n\n根据上述定义，下列属于「增值评价」的是：","options":["学校教研组在单元教学设计中，随堂记录并及时反馈调整，学生的薄弱点被及时识别。","学校教研组在实验课程组织中，全程不作任何反馈、结束后才公布，最终教学安排并未因数据而作任何调整。","学校教研组在作业反馈整理中，随堂记录并及时反馈调整，但教学安排并未因数据而作任何调整。","由家长自行报送成绩，后续也未按上述机制推进。"],"answer":0,"explanation":"「增值评价」的构成要件为：①主体为学校教研组；②通过随堂记录并及时反馈调整；③使学生的薄弱点被及时识别。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01672","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「跨界协作」是指跨部门工作专班通过共享信息并同步排班，使处置效率整体提升的工作机制。\n\n依据上述定义，以下哪一项不符合「跨界协作」的构成要件：","options":["跨部门工作专班在信息通报共享中，共享信息并同步排班，处置效率整体提升。","跨部门工作专班在联合排班安排中，遇跨界事项互相等待，最终边界地带的问题仍在部门之间来回流转。","跨部门工作专班在跨界事项梳理中，共享信息并同步排班，处置效率整体提升。","跨部门工作专班在联合排班安排中，共享信息并同步排班，处置效率整体提升。"],"answer":1,"explanation":"「跨界协作」的构成要件为：①主体为跨部门工作专班；②通过共享信息并同步排班；③使处置效率整体提升。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（遇跨界事项互相等待），因此不符合构成要件。故选B。"},{"id":"pdn01673","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「过程性考核」是指学校教研组通过按阶段采集学情数据再修正教学，使学习过程而非仅结果被看见的工作机制。\n\n按照上述界定，下列情形可认定为「过程性考核」的是：","options":["由学生互评后不再复核，后续也未按上述机制推进。","学校教研组在作业反馈整理中，按阶段采集学情数据再修正教学，但教学安排并未因数据而作任何调整。","学校教研组在实验课程组织中，按固定名次划线且不追溯变化，最终教学安排并未因数据而作任何调整。","学校教研组在单元教学设计中，按阶段采集学情数据再修正教学，学习过程而非仅结果被看见。"],"answer":3,"explanation":"「过程性考核」的构成要件为：①主体为学校教研组；②通过按阶段采集学情数据再修正教学；③使学习过程而非仅结果被看见。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01674","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「预案触发」是指城市运行管理平台通过识别薄弱环节并预先加固，使人员与物资提前就位的工作机制。\n\n根据上述定义，下列不属于「预案触发」的是：","options":["城市运行管理平台在响应动作预置中，识别薄弱环节并预先加固，人员与物资提前就位。","城市运行管理平台在关键节点值守中，识别薄弱环节并预先加固，人员与物资提前就位。","城市运行管理平台在响应动作预置中，等指标越限后才临时研究方案，最终异常发生时无预设动作可依。","城市运行管理平台在风险等级研判中，识别薄弱环节并预先加固，人员与物资提前就位。"],"answer":2,"explanation":"「预案触发」的构成要件为：①主体为城市运行管理平台；②通过识别薄弱环节并预先加固；③使人员与物资提前就位。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（等指标越限后才临时研究方案），因此不符合构成要件。故选C。"},{"id":"pdn01675","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「跨界协作」是指跨部门工作专班通过一次会商形成分工清单，使重复检查与推诿明显减少的工作机制。\n\n依据上述定义，以下哪一项符合「跨界协作」的构成要件：","options":["跨部门工作专班在联合排班安排中，只开会不落责任清单，最终边界地带的问题仍在部门之间来回流转。","跨部门工作专班在跨界事项梳理中，一次会商形成分工清单，重复检查与推诿明显减少。","由各区各自为政，后续也未按上述机制推进。","跨部门工作专班在信息通报共享中，一次会商形成分工清单，但边界地带的问题仍在部门之间来回流转。"],"answer":1,"explanation":"「跨界协作」的构成要件为：①主体为跨部门工作专班；②通过一次会商形成分工清单；③使重复检查与推诿明显减少。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01676","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「脱敏处理」是指政务数据平台通过对外提供前作去标识化处理，使超范围信息不被额外索取的工作机制。\n\n按照上述界定，下列情形不应认定为「脱敏处理」的是：","options":["政务数据平台在数据调阅留痕中，对外提供前作去标识化处理，超范围信息不被额外索取。","政务数据平台在字段权限配置中，共享时直接提供原始明细，最终与办理目的无关的字段仍被长期留存。","政务数据平台在信息采集登记中，对外提供前作去标识化处理，超范围信息不被额外索取。","政务数据平台在字段权限配置中，对外提供前作去标识化处理，超范围信息不被额外索取。"],"answer":1,"explanation":"「脱敏处理」的构成要件为：①主体为政务数据平台；②通过对外提供前作去标识化处理；③使超范围信息不被额外索取。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（共享时直接提供原始明细），因此不符合构成要件。故选B。"},{"id":"pdn01677","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「共创反馈环」是指无障碍改造专班通过邀请使用者全程参与方案打磨，使返工与投诉明显减少的工作机制。\n\n根据上述定义，下列属于「共创反馈环」的是：","options":["由外部专家远程定稿，后续也未按上述机制推进。","无障碍改造专班在使用路径排查中，邀请使用者全程参与方案打磨，但上线后仍频发与习惯不符的障碍。","无障碍改造专班在服务流程梳理中，邀请使用者全程参与方案打磨，返工与投诉明显减少。","无障碍改造专班在公共界面优化中，一次性定稿不再接收反馈，最终上线后仍频发与习惯不符的障碍。"],"answer":2,"explanation":"「共创反馈环」的构成要件为：①主体为无障碍改造专班；②通过邀请使用者全程参与方案打磨；③使返工与投诉明显减少。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01678","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「原型共创」是指公共服务设计组通过先做可体验原型再收集反馈，使隐蔽障碍在使用前被暴露的工作机制。\n\n依据上述定义，以下哪一项不符合「原型共创」的构成要件：","options":["公共服务设计组在服务流程梳理中，先做可体验原型再收集反馈，隐蔽障碍在使用前被暴露。","公共服务设计组在公共界面优化中，仅在完工后征求意见，最终上线后仍频发与习惯不符的障碍。","公共服务设计组在使用路径排查中，先做可体验原型再收集反馈，隐蔽障碍在使用前被暴露。","公共服务设计组在公共界面优化中，先做可体验原型再收集反馈，隐蔽障碍在使用前被暴露。"],"answer":1,"explanation":"「原型共创」的构成要件为：①主体为公共服务设计组；②通过先做可体验原型再收集反馈；③使隐蔽障碍在使用前被暴露。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（仅在完工后征求意见），因此不符合构成要件。故选B。"},{"id":"pdn01679","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「诊断性测评」是指任课教师团队通过随堂记录并及时反馈调整，使学习过程而非仅结果被看见的工作机制。\n\n按照上述界定，下列情形可认定为「诊断性测评」的是：","options":["任课教师团队在单元教学设计中，随堂记录并及时反馈调整，学习过程而非仅结果被看见。","任课教师团队在作业反馈整理中，随堂记录并及时反馈调整，但教学安排并未因数据而作任何调整。","任课教师团队在实验课程组织中，全程不作任何反馈、结束后才公布，最终教学安排并未因数据而作任何调整。","由家长自行报送成绩，后续也未按上述机制推进。"],"answer":0,"explanation":"「诊断性测评」的构成要件为：①主体为任课教师团队；②通过随堂记录并及时反馈调整；③使学习过程而非仅结果被看见。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01680","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「双向转诊」是指家庭医生团队通过建立电子档案并定期回访，使病情变化能被尽早发现的工作机制。\n\n根据上述定义，下列不属于「双向转诊」的是：","options":["家庭医生团队在康复跟踪记录中，各机构各自重复开单，最终各环节彼此脱节、患者仍需多次重复排队。","家庭医生团队在慢病随访安排中，建立电子档案并定期回访，病情变化能被尽早发现。","家庭医生团队在康复跟踪记录中，建立电子档案并定期回访，病情变化能被尽早发现。","家庭医生团队在重点人群筛查中，建立电子档案并定期回访，病情变化能被尽早发现。"],"answer":0,"explanation":"「双向转诊」的构成要件为：①主体为家庭医生团队；②通过建立电子档案并定期回访；③使病情变化能被尽早发现。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（各机构各自重复开单），因此不符合构成要件。故选A。"},{"id":"pdn01681","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「形成性评价」是指区域教研中心通过结合真实任务表现打分，使学生的薄弱点被及时识别的工作机制。\n\n依据上述定义，以下哪一项符合「形成性评价」的构成要件：","options":["区域教研中心在单元教学设计中，结合真实任务表现打分，学生的薄弱点被及时识别。","区域教研中心在实验课程组织中，按固定名次划线且不追溯变化，最终教学安排并未因数据而作任何调整。","由学生互评后不再复核，后续也未按上述机制推进。","区域教研中心在作业反馈整理中，结合真实任务表现打分，但教学安排并未因数据而作任何调整。"],"answer":0,"explanation":"「形成性评价」的构成要件为：①主体为区域教研中心；②通过结合真实任务表现打分；③使学生的薄弱点被及时识别。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01682","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「证据本位决策」是指规划编制组通过对关键指标作独立复核，使后续调整有据可依的工作机制。\n\n按照上述界定，下列情形不应认定为「证据本位决策」的是：","options":["规划编制组在政策效果评估中，对关键指标作独立复核，后续调整有据可依。","规划编制组在抽样数据核查中，对关键指标作独立复核，后续调整有据可依。","规划编制组在年度计划编制中，对关键指标作独立复核，后续调整有据可依。","规划编制组在政策效果评估中，只选取有利样本作展示，最终结论无法由所引数据支撑。"],"answer":3,"explanation":"「证据本位决策」的构成要件为：①主体为规划编制组；②通过对关键指标作独立复核；③使后续调整有据可依。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（只选取有利样本作展示），因此不符合构成要件。故选D。"},{"id":"pdn01683","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「连续照护」是指县域医共体通过按病情轻重分流并约定转诊路径，使重复检查明显减少的工作机制。\n\n根据上述定义，下列属于「连续照护」的是：","options":["县域医共体在康复跟踪记录中，只做一次性检查不作后续跟踪，最终各环节彼此脱节、患者仍需多次重复排队。","仅由三甲医院单方建档，后续也未按上述机制推进。","县域医共体在重点人群筛查中，按病情轻重分流并约定转诊路径，但各环节彼此脱节、患者仍需多次重复排队。","县域医共体在慢病随访安排中，按病情轻重分流并约定转诊路径，重复检查明显减少。"],"answer":3,"explanation":"「连续照护」的构成要件为：①主体为县域医共体；②通过按病情轻重分流并约定转诊路径；③使重复检查明显减少。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01684","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「诊断性测评」是指任课教师团队通过随堂记录并及时反馈调整，使教学策略得以动态优化的工作机制。\n\n依据上述定义，以下哪一项不符合「诊断性测评」的构成要件：","options":["任课教师团队在作业反馈整理中，随堂记录并及时反馈调整，教学策略得以动态优化。","任课教师团队在单元教学设计中，随堂记录并及时反馈调整，教学策略得以动态优化。","任课教师团队在实验课程组织中，随堂记录并及时反馈调整，教学策略得以动态优化。","任课教师团队在实验课程组织中，照搬统一答案不看作答过程，最终教学安排并未因数据而作任何调整。"],"answer":3,"explanation":"「诊断性测评」的构成要件为：①主体为任课教师团队；②通过随堂记录并及时反馈调整；③使教学策略得以动态优化。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（照搬统一答案不看作答过程），因此不符合构成要件。故选D。"},{"id":"pdn01685","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「基线比对」是指规划编制组通过先确立基线再对照前后变化，使结论不易被个别异常值带偏的工作机制。\n\n按照上述界定，下列情形可认定为「基线比对」的是：","options":["由第三方直接给结论不附依据，后续也未按上述机制推进。","规划编制组在政策效果评估中，指标口径中途变更却不说明，最终结论无法由所引数据支撑。","规划编制组在年度计划编制中，先确立基线再对照前后变化，结论不易被个别异常值带偏。","规划编制组在抽样数据核查中，先确立基线再对照前后变化，但结论无法由所引数据支撑。"],"answer":2,"explanation":"「基线比对」的构成要件为：①主体为规划编制组；②通过先确立基线再对照前后变化；③使结论不易被个别异常值带偏。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01686","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「连续照护」是指社区卫生服务中心通过建立电子档案并定期回访，使患者往返成本下降的工作机制。\n\n根据上述定义，下列不属于「连续照护」的是：","options":["社区卫生服务中心在康复跟踪记录中，一律先安排住院再评估，最终各环节彼此脱节、患者仍需多次重复排队。","社区卫生服务中心在重点人群筛查中，建立电子档案并定期回访，患者往返成本下降。","社区卫生服务中心在慢病随访安排中，建立电子档案并定期回访，患者往返成本下降。","社区卫生服务中心在康复跟踪记录中，建立电子档案并定期回访，患者往返成本下降。"],"answer":0,"explanation":"「连续照护」的构成要件为：①主体为社区卫生服务中心；②通过建立电子档案并定期回访；③使患者往返成本下降。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（一律先安排住院再评估），因此不符合构成要件。故选A。"},{"id":"pdn01687","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「差异化供给」是指就业服务窗口通过按对象条件分档配置资源，使资源不再平均摊薄的工作机制。\n\n依据上述定义，以下哪一项符合「差异化供给」的构成要件：","options":["就业服务窗口在服务清单编制中，按对象条件分档配置资源，但大量项目无人使用而真实诉求仍被搁置。","就业服务窗口在对象需求摸排中，按编制人数而不是实际用量分配，最终大量项目无人使用而真实诉求仍被搁置。","就业服务窗口在服务事项梳理中，按对象条件分档配置资源，资源不再平均摊薄。","由供应商单方决定目录，后续也未按上述机制推进。"],"answer":2,"explanation":"「差异化供给」的构成要件为：①主体为就业服务窗口；②通过按对象条件分档配置资源；③使资源不再平均摊薄。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01688","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「节点责任制」是指农产品质量检测站通过按批号串联台账与检验记录，使问题批次能被快速定位的工作机制。\n\n按照上述界定，下列情形不应认定为「节点责任制」的是：","options":["农产品质量检测站在批次交接记录中，按批号串联台账与检验记录，问题批次能被快速定位。","农产品质量检测站在储运环节温控中，按批号串联台账与检验记录，问题批次能被快速定位。","农产品质量检测站在批次交接记录中，事后一次性补全整本台账，最终出现问题时无法定位到具体环节。","农产品质量检测站在进货环节核验中，按批号串联台账与检验记录，问题批次能被快速定位。"],"answer":2,"explanation":"「节点责任制」的构成要件为：①主体为农产品质量检测站；②通过按批号串联台账与检验记录；③使问题批次能被快速定位。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（事后一次性补全整本台账），因此不符合构成要件。故选C。"},{"id":"pdn01689","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「脆弱性评估」是指数据中心运维组通过关键节点保留备用通道，使核心功能在异常下仍可维持的工作机制。\n\n根据上述定义，下列属于「脆弱性评估」的是：","options":["数据中心运维组在响应动作预置中，只在事发后补充记录，最终异常发生时无预设动作可依。","数据中心运维组在关键节点值守中，关键节点保留备用通道，但异常发生时无预设动作可依。","数据中心运维组在风险等级研判中，关键节点保留备用通道，核心功能在异常下仍可维持。","由外部单位事后支援，后续也未按上述机制推进。"],"answer":2,"explanation":"「脆弱性评估」的构成要件为：①主体为数据中心运维组；②通过关键节点保留备用通道；③使核心功能在异常下仍可维持。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01690","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「数据校验」是指规划编制组通过对关键指标作独立复核，使判断建立在可核验的依据上的工作机制。\n\n依据上述定义，以下哪一项不符合「数据校验」的构成要件：","options":["规划编制组在年度计划编制中，对关键指标作独立复核，判断建立在可核验的依据上。","规划编制组在政策效果评估中，对关键指标作独立复核，判断建立在可核验的依据上。","规划编制组在政策效果评估中，只选取有利样本作展示，最终结论无法由所引数据支撑。","规划编制组在抽样数据核查中，对关键指标作独立复核，判断建立在可核验的依据上。"],"answer":2,"explanation":"「数据校验」的构成要件为：①主体为规划编制组；②通过对关键指标作独立复核；③使判断建立在可核验的依据上。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（只选取有利样本作展示），因此不符合构成要件。故选C。"},{"id":"pdn01691","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「预案触发」是指水利工程调度处通过识别薄弱环节并预先加固，使次生影响被压到最小的工作机制。\n\n按照上述界定，下列情形可认定为「预案触发」的是：","options":["水利工程调度处在响应动作预置中，仅保留一份无备用的关键设备，最终异常发生时无预设动作可依。","水利工程调度处在关键节点值守中，识别薄弱环节并预先加固，但异常发生时无预设动作可依。","水利工程调度处在风险等级研判中，识别薄弱环节并预先加固，次生影响被压到最小。","由上级在事后统一追认，后续也未按上述机制推进。"],"answer":2,"explanation":"「预案触发」的构成要件为：①主体为水利工程调度处；②通过识别薄弱环节并预先加固；③使次生影响被压到最小。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01692","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「联合响应」是指区级牵头部门通过一次会商形成分工清单，使跨界问题不再悬空的工作机制。\n\n根据上述定义，下列不属于「联合响应」的是：","options":["区级牵头部门在联合排班安排中，一次会商形成分工清单，跨界问题不再悬空。","区级牵头部门在联合排班安排中，遇跨界事项互相等待，最终边界地带的问题仍在部门之间来回流转。","区级牵头部门在跨界事项梳理中，一次会商形成分工清单，跨界问题不再悬空。","区级牵头部门在信息通报共享中，一次会商形成分工清单，跨界问题不再悬空。"],"answer":1,"explanation":"「联合响应」的构成要件为：①主体为区级牵头部门；②通过一次会商形成分工清单；③使跨界问题不再悬空。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（遇跨界事项互相等待），因此不符合构成要件。故选B。"},{"id":"pdn01693","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「按需配置」是指养老服务站点通过按可选项自主组合形成服务清单，使供给与实际需求更加贴合的工作机制。\n\n依据上述定义，以下哪一项符合「按需配置」的构成要件：","options":["由服务对象自行寻找渠道，后续也未按上述机制推进。","养老服务站点在对象需求摸排中，沿用上一年清单不作修订，最终大量项目无人使用而真实诉求仍被搁置。","养老服务站点在服务事项梳理中，按可选项自主组合形成服务清单，供给与实际需求更加贴合。","养老服务站点在服务清单编制中，按可选项自主组合形成服务清单，但大量项目无人使用而真实诉求仍被搁置。"],"answer":2,"explanation":"「按需配置」的构成要件为：①主体为养老服务站点；②通过按可选项自主组合形成服务清单；③使供给与实际需求更加贴合。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01694","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「分级诊疗」是指县域医共体通过与上级医院共享检查结果，使患者往返成本下降的工作机制。\n\n按照上述界定，下列情形不应认定为「分级诊疗」的是：","options":["县域医共体在慢病随访安排中，与上级医院共享检查结果，患者往返成本下降。","县域医共体在重点人群筛查中，与上级医院共享检查结果，患者往返成本下降。","县域医共体在康复跟踪记录中，与上级医院共享检查结果，患者往返成本下降。","县域医共体在康复跟踪记录中，一律先安排住院再评估，最终各环节彼此脱节、患者仍需多次重复排队。"],"answer":3,"explanation":"「分级诊疗」的构成要件为：①主体为县域医共体；②通过与上级医院共享检查结果；③使患者往返成本下降。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（一律先安排住院再评估），因此不符合构成要件。故选D。"},{"id":"pdn01695","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「菜单式服务」是指农技推广站通过按对象条件分档配置资源，使供给与实际需求更加贴合的工作机制。\n\n根据上述定义，下列属于「菜单式服务」的是：","options":["由供应商单方决定目录，后续也未按上述机制推进。","农技推广站在对象需求摸排中，按编制人数而不是实际用量分配，最终大量项目无人使用而真实诉求仍被搁置。","农技推广站在服务事项梳理中，按对象条件分档配置资源，供给与实际需求更加贴合。","农技推广站在服务清单编制中，按对象条件分档配置资源，但大量项目无人使用而真实诉求仍被搁置。"],"answer":2,"explanation":"「菜单式服务」的构成要件为：①主体为农技推广站；②通过按对象条件分档配置资源；③使供给与实际需求更加贴合。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01696","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「基线比对」是指规划编制组通过以多源数据交叉校验结论，使判断建立在可核验的依据上的工作机制。\n\n依据上述定义，以下哪一项不符合「基线比对」的构成要件：","options":["规划编制组在政策效果评估中，以多源数据交叉校验结论，判断建立在可核验的依据上。","规划编制组在抽样数据核查中，以多源数据交叉校验结论，判断建立在可核验的依据上。","规划编制组在政策效果评估中，以主观感受替代实测数据，最终结论无法由所引数据支撑。","规划编制组在年度计划编制中，以多源数据交叉校验结论，判断建立在可核验的依据上。"],"answer":2,"explanation":"「基线比对」的构成要件为：①主体为规划编制组；②通过以多源数据交叉校验结论；③使判断建立在可核验的依据上。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（以主观感受替代实测数据），因此不符合构成要件。故选C。"},{"id":"pdn01697","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「脱敏处理」是指政务数据平台通过到期自动清理并留清理记录，使超范围信息不被额外索取的工作机制。\n\n按照上述界定，下列情形可认定为「脱敏处理」的是：","options":["政务数据平台在字段权限配置中，超过期限仍不作清理，最终与办理目的无关的字段仍被长期留存。","政务数据平台在数据调阅留痕中，到期自动清理并留清理记录，但与办理目的无关的字段仍被长期留存。","由系统默认长期全量保留，后续也未按上述机制推进。","政务数据平台在信息采集登记中，到期自动清理并留清理记录，超范围信息不被额外索取。"],"answer":3,"explanation":"「脱敏处理」的构成要件为：①主体为政务数据平台；②通过到期自动清理并留清理记录；③使超范围信息不被额外索取。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01698","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「过程性考核」是指区域教研中心通过结合真实任务表现打分，使学生的薄弱点被及时识别的工作机制。\n\n根据上述定义，下列不属于「过程性考核」的是：","options":["区域教研中心在实验课程组织中，结合真实任务表现打分，学生的薄弱点被及时识别。","区域教研中心在实验课程组织中，只以期末一次分数定结论，最终教学安排并未因数据而作任何调整。","区域教研中心在单元教学设计中，结合真实任务表现打分，学生的薄弱点被及时识别。","区域教研中心在作业反馈整理中，结合真实任务表现打分，学生的薄弱点被及时识别。"],"answer":1,"explanation":"「过程性考核」的构成要件为：①主体为区域教研中心；②通过结合真实任务表现打分；③使学生的薄弱点被及时识别。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（只以期末一次分数定结论），因此不符合构成要件。故选B。"},{"id":"pdn01699","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「共创反馈环」是指无障碍改造专班通过多轮共创后收敛为最终版本，使改动获得使用者认同的工作机制。\n\n依据上述定义，以下哪一项符合「共创反馈环」的构成要件：","options":["无障碍改造专班在公共界面优化中，只做内部评审不接触使用者，最终上线后仍频发与习惯不符的障碍。","无障碍改造专班在服务流程梳理中，多轮共创后收敛为最终版本，改动获得使用者认同。","无障碍改造专班在使用路径排查中，多轮共创后收敛为最终版本，但上线后仍频发与习惯不符的障碍。","由供应商提供标准模板，后续也未按上述机制推进。"],"answer":1,"explanation":"「共创反馈环」的构成要件为：①主体为无障碍改造专班；②通过多轮共创后收敛为最终版本；③使改动获得使用者认同。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01700","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「前置筛查」是指家庭医生团队通过与上级医院共享检查结果，使患者往返成本下降的工作机制。\n\n按照上述界定，下列情形不应认定为「前置筛查」的是：","options":["家庭医生团队在重点人群筛查中，与上级医院共享检查结果，患者往返成本下降。","家庭医生团队在慢病随访安排中，与上级医院共享检查结果，患者往返成本下降。","家庭医生团队在康复跟踪记录中，各机构各自重复开单，最终各环节彼此脱节、患者仍需多次重复排队。","家庭医生团队在康复跟踪记录中，与上级医院共享检查结果，患者往返成本下降。"],"answer":2,"explanation":"「前置筛查」的构成要件为：①主体为家庭医生团队；②通过与上级医院共享检查结果；③使患者往返成本下降。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（各机构各自重复开单），因此不符合构成要件。故选C。"},{"id":"pdn01701","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「表现性评价」是指任课教师团队通过结合真实任务表现打分，使后续目标更贴合实际起点的工作机制。\n\n根据上述定义，下列属于「表现性评价」的是：","options":["任课教师团队在实验课程组织中，按固定名次划线且不追溯变化，最终教学安排并未因数据而作任何调整。","任课教师团队在单元教学设计中，结合真实任务表现打分，后续目标更贴合实际起点。","由学生互评后不再复核，后续也未按上述机制推进。","任课教师团队在作业反馈整理中，结合真实任务表现打分，但教学安排并未因数据而作任何调整。"],"answer":1,"explanation":"「表现性评价」的构成要件为：①主体为任课教师团队；②通过结合真实任务表现打分；③使后续目标更贴合实际起点。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01702","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「小步试点」是指改革推进专班通过分批次扩面而非一次铺开，使后续推广更贴合一线实际的工作机制。\n\n依据上述定义，以下哪一项不符合「小步试点」的构成要件：","options":["改革推进专班在新流程上线中，分批次扩面而非一次铺开，后续推广更贴合一线实际。","改革推进专班在新机制落地中，分批次扩面而非一次铺开，后续推广更贴合一线实际。","改革推进专班在新工具推广中，分批次扩面而非一次铺开，后续推广更贴合一线实际。","改革推进专班在新工具推广中，不经试点直接全面强制推开，最终同类偏差在扩面后被成倍放大。"],"answer":3,"explanation":"「小步试点」的构成要件为：①主体为改革推进专班；②通过分批次扩面而非一次铺开；③使后续推广更贴合一线实际。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（不经试点直接全面强制推开），因此不符合构成要件。故选D。"},{"id":"pdn01703","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「联合响应」是指跨部门工作专班通过建立常态化联络与移交规则，使响应口径保持一致的工作机制。\n\n按照上述界定，下列情形可认定为「联合响应」的是：","options":["跨部门工作专班在跨界事项梳理中，建立常态化联络与移交规则，响应口径保持一致。","跨部门工作专班在联合排班安排中，只开会不落责任清单，最终边界地带的问题仍在部门之间来回流转。","跨部门工作专班在信息通报共享中，建立常态化联络与移交规则，但边界地带的问题仍在部门之间来回流转。","由各区各自为政，后续也未按上述机制推进。"],"answer":0,"explanation":"「联合响应」的构成要件为：①主体为跨部门工作专班；②通过建立常态化联络与移交规则；③使响应口径保持一致。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01704","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「目的限定」是指医院信息科通过对外提供前作去标识化处理，使共享环节不泄露可识别信息的工作机制。\n\n根据上述定义，下列不属于「目的限定」的是：","options":["医院信息科在数据调阅留痕中，对外提供前作去标识化处理，共享环节不泄露可识别信息。","医院信息科在字段权限配置中，共享时直接提供原始明细，最终与办理目的无关的字段仍被长期留存。","医院信息科在字段权限配置中，对外提供前作去标识化处理，共享环节不泄露可识别信息。","医院信息科在信息采集登记中，对外提供前作去标识化处理，共享环节不泄露可识别信息。"],"answer":1,"explanation":"「目的限定」的构成要件为：①主体为医院信息科；②通过对外提供前作去标识化处理；③使共享环节不泄露可识别信息。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（共享时直接提供原始明细），因此不符合构成要件。故选B。"},{"id":"pdn01705","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「最小必要采集」是指学校学籍管理系统通过只采集完成本事项所必需的字段，使历史数据不再无限期堆积的工作机制。\n\n依据上述定义，以下哪一项符合「最小必要采集」的构成要件：","options":["学校学籍管理系统在数据调阅留痕中，只采集完成本事项所必需的字段，但与办理目的无关的字段仍被长期留存。","由系统默认长期全量保留，后续也未按上述机制推进。","学校学籍管理系统在字段权限配置中，超过期限仍不作清理，最终与办理目的无关的字段仍被长期留存。","学校学籍管理系统在信息采集登记中，只采集完成本事项所必需的字段，历史数据不再无限期堆积。"],"answer":3,"explanation":"「最小必要采集」的构成要件为：①主体为学校学籍管理系统；②通过只采集完成本事项所必需的字段；③使历史数据不再无限期堆积。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01706","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「小步试点」是指政策试点工作组通过分批次扩面而非一次铺开，使偏差在放大前被修正的工作机制。\n\n按照上述界定，下列情形不应认定为「小步试点」的是：","options":["政策试点工作组在新工具推广中，不经试点直接全面强制推开，最终同类偏差在扩面后被成倍放大。","政策试点工作组在新工具推广中，分批次扩面而非一次铺开，偏差在放大前被修正。","政策试点工作组在新机制落地中，分批次扩面而非一次铺开，偏差在放大前被修正。","政策试点工作组在新流程上线中，分批次扩面而非一次铺开，偏差在放大前被修正。"],"answer":0,"explanation":"「小步试点」的构成要件为：①主体为政策试点工作组；②通过分批次扩面而非一次铺开；③使偏差在放大前被修正。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（不经试点直接全面强制推开），因此不符合构成要件。故选A。"},{"id":"pdn01707","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「分区管控」是指流域管理机构通过划分区块实行差异化管护，使核心栖息地得到有效避让的工作机制。\n\n根据上述定义，下列属于「分区管控」的是：","options":["流域管理机构在监测指标波动中，划分区块实行差异化管护，核心栖息地得到有效避让。","流域管理机构在外来因素扩散中，划分区块实行差异化管护，但指标已越界而措施仍维持不变。","由邻近地区照抄方案，后续也未按上述机制推进。","流域管理机构在栖息环境变化中，指标超标后仍不调整，最终指标已越界而措施仍维持不变。"],"answer":0,"explanation":"「分区管控」的构成要件为：①主体为流域管理机构；②通过划分区块实行差异化管护；③使核心栖息地得到有效避让。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01708","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「小步试点」是指改革推进专班通过设置观察期并保留回退通道，使后续推广更贴合一线实际的工作机制。\n\n依据上述定义，以下哪一项不符合「小步试点」的构成要件：","options":["改革推进专班在新流程上线中，设置观察期并保留回退通道，后续推广更贴合一线实际。","改革推进专班在新工具推广中，只记录成功案例不分析偏差，最终同类偏差在扩面后被成倍放大。","改革推进专班在新工具推广中，设置观察期并保留回退通道，后续推广更贴合一线实际。","改革推进专班在新机制落地中，设置观察期并保留回退通道，后续推广更贴合一线实际。"],"answer":1,"explanation":"「小步试点」的构成要件为：①主体为改革推进专班；②通过设置观察期并保留回退通道；③使后续推广更贴合一线实际。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（只记录成功案例不分析偏差），因此不符合构成要件。故选B。"},{"id":"pdn01709","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「跨界协作」是指流域联席会议通过一次会商形成分工清单，使重复检查与推诿明显减少的工作机制。\n\n按照上述界定，下列情形可认定为「跨界协作」的是：","options":["流域联席会议在联合排班安排中，各自按本部门旧流程办理，最终边界地带的问题仍在部门之间来回流转。","流域联席会议在跨界事项梳理中，一次会商形成分工清单，重复检查与推诿明显减少。","流域联席会议在信息通报共享中，一次会商形成分工清单，但边界地带的问题仍在部门之间来回流转。","由上级部门包办到底，后续也未按上述机制推进。"],"answer":1,"explanation":"「跨界协作」的构成要件为：①主体为流域联席会议；②通过一次会商形成分工清单；③使重复检查与推诿明显减少。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01710","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「可回溯核查」是指冷链运营方通过关键节点双人签认留档，使召回范围精确到具体批次的工作机制。\n\n根据上述定义，下列不属于「可回溯核查」的是：","options":["冷链运营方在批次交接记录中，关键节点双人签认留档，召回范围精确到具体批次。","冷链运营方在批次交接记录中，只在最终出库时记一笔总账，最终出现问题时无法定位到具体环节。","冷链运营方在储运环节温控中，关键节点双人签认留档，召回范围精确到具体批次。","冷链运营方在进货环节核验中，关键节点双人签认留档，召回范围精确到具体批次。"],"answer":1,"explanation":"「可回溯核查」的构成要件为：①主体为冷链运营方；②通过关键节点双人签认留档；③使召回范围精确到具体批次。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（只在最终出库时记一笔总账），因此不符合构成要件。故选B。"},{"id":"pdn01711","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「分级预警」是指数据中心运维组通过按风险等级预置响应动作，使次生影响被压到最小的工作机制。\n\n依据上述定义，以下哪一项符合「分级预警」的构成要件：","options":["数据中心运维组在关键节点值守中，按风险等级预置响应动作，但异常发生时无预设动作可依。","由上级在事后统一追认，后续也未按上述机制推进。","数据中心运维组在响应动作预置中，仅保留一份无备用的关键设备，最终异常发生时无预设动作可依。","数据中心运维组在风险等级研判中，按风险等级预置响应动作，次生影响被压到最小。"],"answer":3,"explanation":"「分级预警」的构成要件为：①主体为数据中心运维组；②通过按风险等级预置响应动作；③使次生影响被压到最小。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01712","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「复盘改进」是指政策试点工作组通过先在小范围试运行再按反馈调整，使后续推广更贴合一线实际的工作机制。\n\n按照上述界定，下列情形不应认定为「复盘改进」的是：","options":["政策试点工作组在新工具推广中，先在小范围试运行再按反馈调整，后续推广更贴合一线实际。","政策试点工作组在新机制落地中，先在小范围试运行再按反馈调整，后续推广更贴合一线实际。","政策试点工作组在新工具推广中，只记录成功案例不分析偏差，最终同类偏差在扩面后被成倍放大。","政策试点工作组在新流程上线中，先在小范围试运行再按反馈调整，后续推广更贴合一线实际。"],"answer":2,"explanation":"「复盘改进」的构成要件为：①主体为政策试点工作组；②通过先在小范围试运行再按反馈调整；③使后续推广更贴合一线实际。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（只记录成功案例不分析偏差），因此不符合构成要件。故选C。"},{"id":"pdn01713","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「容错纠偏」是指数字化转型办公室通过分批次扩面而非一次铺开，使偏差在放大前被修正的工作机制。\n\n根据上述定义，下列属于「容错纠偏」的是：","options":["由用户自行摸索不作收集，后续也未按上述机制推进。","数字化转型办公室在新机制落地中，分批次扩面而非一次铺开，但同类偏差在扩面后被成倍放大。","数字化转型办公室在新工具推广中，一次上线后即固化不再迭代，最终同类偏差在扩面后被成倍放大。","数字化转型办公室在新流程上线中，分批次扩面而非一次铺开，偏差在放大前被修正。"],"answer":3,"explanation":"「容错纠偏」的构成要件为：①主体为数字化转型办公室；②通过分批次扩面而非一次铺开；③使偏差在放大前被修正。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01714","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「前置响应」是指乡镇便民中心通过依托网格员常态化走访摸排，使诉求在前端得到化解的工作机制。\n\n依据上述定义，以下哪一项不符合「前置响应」的构成要件：","options":["乡镇便民中心在邻里纠纷调解中，依托网格员常态化走访摸排，诉求在前端得到化解。","乡镇便民中心在邻里纠纷调解中，直接照搬既有方案、未作任何征询，最终问题仍反复出现且未形成稳定机制。","乡镇便民中心在老旧小区改造中，依托网格员常态化走访摸排，诉求在前端得到化解。","乡镇便民中心在便民事项办理中，依托网格员常态化走访摸排，诉求在前端得到化解。"],"answer":1,"explanation":"「前置响应」的构成要件为：①主体为乡镇便民中心；②通过依托网格员常态化走访摸排；③使诉求在前端得到化解。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（直接照搬既有方案、未作任何征询），因此不符合构成要件。故选B。"},{"id":"pdn01715","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「灰度验证」是指数字化转型办公室通过分批次扩面而非一次铺开，使方案随实际反馈逐步完善的工作机制。\n\n按照上述界定，下列情形可认定为「灰度验证」的是：","options":["数字化转型办公室在新机制落地中，分批次扩面而非一次铺开，但同类偏差在扩面后被成倍放大。","数字化转型办公室在新工具推广中，试运行期间禁止任何修改，最终同类偏差在扩面后被成倍放大。","由外部团队一次性交付即结束，后续也未按上述机制推进。","数字化转型办公室在新流程上线中，分批次扩面而非一次铺开，方案随实际反馈逐步完善。"],"answer":3,"explanation":"「灰度验证」的构成要件为：①主体为数字化转型办公室；②通过分批次扩面而非一次铺开；③使方案随实际反馈逐步完善。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01716","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「可回溯核查」是指冷链运营方通过每一节点登记并关联上下游凭证，使责任环节清晰可查的工作机制。\n\n根据上述定义，下列不属于「可回溯核查」的是：","options":["冷链运营方在进货环节核验中，每一节点登记并关联上下游凭证，责任环节清晰可查。","冷链运营方在批次交接记录中，每一节点登记并关联上下游凭证，责任环节清晰可查。","冷链运营方在批次交接记录中，事后一次性补全整本台账，最终出现问题时无法定位到具体环节。","冷链运营方在储运环节温控中，每一节点登记并关联上下游凭证，责任环节清晰可查。"],"answer":2,"explanation":"「可回溯核查」的构成要件为：①主体为冷链运营方；②通过每一节点登记并关联上下游凭证；③使责任环节清晰可查。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（事后一次性补全整本台账），因此不符合构成要件。故选C。"},{"id":"pdn01717","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「双向转诊」是指社区卫生服务中心通过与上级医院共享检查结果，使重复检查明显减少的工作机制。\n\n依据上述定义，以下哪一项符合「双向转诊」的构成要件：","options":["社区卫生服务中心在康复跟踪记录中，待病情加重后再启动会诊，最终各环节彼此脱节、患者仍需多次重复排队。","由商业体检机构独立出具结论，后续也未按上述机制推进。","社区卫生服务中心在慢病随访安排中，与上级医院共享检查结果，重复检查明显减少。","社区卫生服务中心在重点人群筛查中，与上级医院共享检查结果，但各环节彼此脱节、患者仍需多次重复排队。"],"answer":2,"explanation":"「双向转诊」的构成要件为：①主体为社区卫生服务中心；②通过与上级医院共享检查结果；③使重复检查明显减少。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01718","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「最小必要采集」是指政务数据平台通过到期自动清理并留清理记录，使历史数据不再无限期堆积的工作机制。\n\n按照上述界定，下列情形不应认定为「最小必要采集」的是：","options":["政务数据平台在字段权限配置中，为方便起见一次性收齐全部字段，最终与办理目的无关的字段仍被长期留存。","政务数据平台在字段权限配置中，到期自动清理并留清理记录，历史数据不再无限期堆积。","政务数据平台在数据调阅留痕中，到期自动清理并留清理记录，历史数据不再无限期堆积。","政务数据平台在信息采集登记中，到期自动清理并留清理记录，历史数据不再无限期堆积。"],"answer":0,"explanation":"「最小必要采集」的构成要件为：①主体为政务数据平台；②通过到期自动清理并留清理记录；③使历史数据不再无限期堆积。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（为方便起见一次性收齐全部字段），因此不符合构成要件。故选A。"},{"id":"pdn01719","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「网格代办」是指街道办通过联合多方现场会商后再定方案，使诉求在前端得到化解的工作机制。\n\n根据上述定义，下列属于「网格代办」的是：","options":["街道办在便民事项办理中，联合多方现场会商后再定方案，但问题仍反复出现且未形成稳定机制。","街道办在老旧小区改造中，联合多方现场会商后再定方案，诉求在前端得到化解。","由临时志愿队自行接管，后续也未按上述机制推进。","街道办在邻里纠纷调解中，等群众上门反映后再统一研究，最终问题仍反复出现且未形成稳定机制。"],"answer":1,"explanation":"「网格代办」的构成要件为：①主体为街道办；②通过联合多方现场会商后再定方案；③使诉求在前端得到化解。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01720","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「动态监测」是指自然保护区管理局通过划分区块实行差异化管护，使管控成本保持在合理区间的工作机制。\n\n依据上述定义，以下哪一项不符合「动态监测」的构成要件：","options":["自然保护区管理局在外来因素扩散中，划分区块实行差异化管护，管控成本保持在合理区间。","自然保护区管理局在栖息环境变化中，划分区块实行差异化管护，管控成本保持在合理区间。","自然保护区管理局在栖息环境变化中，只看年度均值忽略峰值，最终指标已越界而措施仍维持不变。","自然保护区管理局在监测指标波动中，划分区块实行差异化管护，管控成本保持在合理区间。"],"answer":2,"explanation":"「动态监测」的构成要件为：①主体为自然保护区管理局；②通过划分区块实行差异化管护；③使管控成本保持在合理区间。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（只看年度均值忽略峰值），因此不符合构成要件。故选C。"},{"id":"pdn01721","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「用户旅程映射」是指社区营造团队通过按真实使用路径逐点排查痛点，使改动获得使用者认同的工作机制。\n\n按照上述界定，下列情形可认定为「用户旅程映射」的是：","options":["社区营造团队在服务流程梳理中，按真实使用路径逐点排查痛点，改动获得使用者认同。","社区营造团队在公共界面优化中，一次性定稿不再接收反馈，最终上线后仍频发与习惯不符的障碍。","社区营造团队在使用路径排查中，按真实使用路径逐点排查痛点，但上线后仍频发与习惯不符的障碍。","由外部专家远程定稿，后续也未按上述机制推进。"],"answer":0,"explanation":"「用户旅程映射」的构成要件为：①主体为社区营造团队；②通过按真实使用路径逐点排查痛点；③使改动获得使用者认同。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01722","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「双向转诊」是指社区卫生服务中心通过先由基层评估再决定是否上转，使患者往返成本下降的工作机制。\n\n根据上述定义，下列不属于「双向转诊」的是：","options":["社区卫生服务中心在重点人群筛查中，先由基层评估再决定是否上转，患者往返成本下降。","社区卫生服务中心在慢病随访安排中，先由基层评估再决定是否上转，患者往返成本下降。","社区卫生服务中心在康复跟踪记录中，一律先安排住院再评估，最终各环节彼此脱节、患者仍需多次重复排队。","社区卫生服务中心在康复跟踪记录中，先由基层评估再决定是否上转，患者往返成本下降。"],"answer":2,"explanation":"「双向转诊」的构成要件为：①主体为社区卫生服务中心；②通过先由基层评估再决定是否上转；③使患者往返成本下降。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（一律先安排住院再评估），因此不符合构成要件。故选C。"},{"id":"pdn01723","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「适应性管理」是指湿地管护中心通过随季节数据滚动修订方案，使异常苗头被尽早识别的工作机制。\n\n依据上述定义，以下哪一项符合「适应性管理」的构成要件：","options":["湿地管护中心在外来因素扩散中，随季节数据滚动修订方案，但指标已越界而措施仍维持不变。","湿地管护中心在栖息环境变化中，指标超标后仍不调整，最终指标已越界而措施仍维持不变。","由邻近地区照抄方案，后续也未按上述机制推进。","湿地管护中心在监测指标波动中，随季节数据滚动修订方案，异常苗头被尽早识别。"],"answer":3,"explanation":"「适应性管理」的构成要件为：①主体为湿地管护中心；②通过随季节数据滚动修订方案；③使异常苗头被尽早识别。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01724","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「节点责任制」是指食品药品监管所通过异常批次可一键回溯全链路，使召回范围精确到具体批次的工作机制。\n\n按照上述界定，下列情形不应认定为「节点责任制」的是：","options":["食品药品监管所在储运环节温控中，异常批次可一键回溯全链路，召回范围精确到具体批次。","食品药品监管所在批次交接记录中，异常批次可一键回溯全链路，召回范围精确到具体批次。","食品药品监管所在批次交接记录中，事后一次性补全整本台账，最终出现问题时无法定位到具体环节。","食品药品监管所在进货环节核验中，异常批次可一键回溯全链路，召回范围精确到具体批次。"],"answer":2,"explanation":"「节点责任制」的构成要件为：①主体为食品药品监管所；②通过异常批次可一键回溯全链路；③使召回范围精确到具体批次。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（事后一次性补全整本台账），因此不符合构成要件。故选C。"},{"id":"pdn01725","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「数据校验」是指统计调查队通过以多源数据交叉校验结论，使后续调整有据可依的工作机制。\n\n根据上述定义，下列属于「数据校验」的是：","options":["统计调查队在年度计划编制中，以多源数据交叉校验结论，后续调整有据可依。","由第三方直接给结论不附依据，后续也未按上述机制推进。","统计调查队在抽样数据核查中，以多源数据交叉校验结论，但结论无法由所引数据支撑。","统计调查队在政策效果评估中，指标口径中途变更却不说明，最终结论无法由所引数据支撑。"],"answer":0,"explanation":"「数据校验」的构成要件为：①主体为统计调查队；②通过以多源数据交叉校验结论；③使后续调整有据可依。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01726","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「动态监测」是指生态环境监测站通过随季节数据滚动修订方案，使管控成本保持在合理区间的工作机制。\n\n依据上述定义，以下哪一项不符合「动态监测」的构成要件：","options":["生态环境监测站在栖息环境变化中，全年沿用同一套固定配额，最终指标已越界而措施仍维持不变。","生态环境监测站在栖息环境变化中，随季节数据滚动修订方案，管控成本保持在合理区间。","生态环境监测站在监测指标波动中，随季节数据滚动修订方案，管控成本保持在合理区间。","生态环境监测站在外来因素扩散中，随季节数据滚动修订方案，管控成本保持在合理区间。"],"answer":0,"explanation":"「动态监测」的构成要件为：①主体为生态环境监测站；②通过随季节数据滚动修订方案；③使管控成本保持在合理区间。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（全年沿用同一套固定配额），因此不符合构成要件。故选A。"},{"id":"pdn01727","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「复盘改进」是指数字化转型办公室通过先在小范围试运行再按反馈调整，使方案随实际反馈逐步完善的工作机制。\n\n按照上述界定，下列情形可认定为「复盘改进」的是：","options":["数字化转型办公室在新工具推广中，试运行期间禁止任何修改，最终同类偏差在扩面后被成倍放大。","数字化转型办公室在新流程上线中，先在小范围试运行再按反馈调整，方案随实际反馈逐步完善。","数字化转型办公室在新机制落地中，先在小范围试运行再按反馈调整，但同类偏差在扩面后被成倍放大。","由外部团队一次性交付即结束，后续也未按上述机制推进。"],"answer":1,"explanation":"「复盘改进」的构成要件为：①主体为数字化转型办公室；②通过先在小范围试运行再按反馈调整；③使方案随实际反馈逐步完善。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01728","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「前置响应」是指村委会通过建立台账逐项限时销号，使重复投诉明显下降的工作机制。\n\n根据上述定义，下列不属于「前置响应」的是：","options":["村委会在老旧小区改造中，建立台账逐项限时销号，重复投诉明显下降。","村委会在邻里纠纷调解中，只在事后补录台账，最终问题仍反复出现且未形成稳定机制。","村委会在便民事项办理中，建立台账逐项限时销号，重复投诉明显下降。","村委会在邻里纠纷调解中，建立台账逐项限时销号，重复投诉明显下降。"],"answer":1,"explanation":"「前置响应」的构成要件为：①主体为村委会；②通过建立台账逐项限时销号；③使重复投诉明显下降。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（只在事后补录台账），因此不符合构成要件。故选B。"},{"id":"pdn01729","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「循证施策」是指项目评审委员会通过用对照组剔除同期其他影响，使结论不易被个别异常值带偏的工作机制。\n\n依据上述定义，以下哪一项符合「循证施策」的构成要件：","options":["项目评审委员会在政策效果评估中，指标口径中途变更却不说明，最终结论无法由所引数据支撑。","由第三方直接给结论不附依据，后续也未按上述机制推进。","项目评审委员会在年度计划编制中，用对照组剔除同期其他影响，结论不易被个别异常值带偏。","项目评审委员会在抽样数据核查中，用对照组剔除同期其他影响，但结论无法由所引数据支撑。"],"answer":2,"explanation":"「循证施策」的构成要件为：①主体为项目评审委员会；②通过用对照组剔除同期其他影响；③使结论不易被个别异常值带偏。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01730","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「原型共创」是指产品体验小组通过邀请使用者全程参与方案打磨，使改动获得使用者认同的工作机制。\n\n按照上述界定，下列情形不应认定为「原型共创」的是：","options":["产品体验小组在公共界面优化中，邀请使用者全程参与方案打磨，改动获得使用者认同。","产品体验小组在服务流程梳理中，邀请使用者全程参与方案打磨，改动获得使用者认同。","产品体验小组在使用路径排查中，邀请使用者全程参与方案打磨，改动获得使用者认同。","产品体验小组在公共界面优化中，仅在完工后征求意见，最终上线后仍频发与习惯不符的障碍。"],"answer":3,"explanation":"「原型共创」的构成要件为：①主体为产品体验小组；②通过邀请使用者全程参与方案打磨；③使改动获得使用者认同。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（仅在完工后征求意见），因此不符合构成要件。故选D。"},{"id":"pdn01731","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「留痕管理」是指食品药品监管所通过每一节点登记并关联上下游凭证，使台账与实物始终一致的工作机制。\n\n根据上述定义，下列属于「留痕管理」的是：","options":["食品药品监管所在进货环节核验中，每一节点登记并关联上下游凭证，台账与实物始终一致。","由终端门店自行补记，后续也未按上述机制推进。","食品药品监管所在批次交接记录中，各环节各自记录且互不关联，最终出现问题时无法定位到具体环节。","食品药品监管所在储运环节温控中，每一节点登记并关联上下游凭证，但出现问题时无法定位到具体环节。"],"answer":0,"explanation":"「留痕管理」的构成要件为：①主体为食品药品监管所；②通过每一节点登记并关联上下游凭证；③使台账与实物始终一致。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01732","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「脆弱性评估」是指城市运行管理平台通过关键节点保留备用通道，使险情初起即进入有序处置的工作机制。\n\n依据上述定义，以下哪一项不符合「脆弱性评估」的构成要件：","options":["城市运行管理平台在响应动作预置中，关键节点保留备用通道，险情初起即进入有序处置。","城市运行管理平台在关键节点值守中，关键节点保留备用通道，险情初起即进入有序处置。","城市运行管理平台在响应动作预置中，预案长期封存不随风险更新，最终异常发生时无预设动作可依。","城市运行管理平台在风险等级研判中，关键节点保留备用通道，险情初起即进入有序处置。"],"answer":2,"explanation":"「脆弱性评估」的构成要件为：①主体为城市运行管理平台；②通过关键节点保留备用通道；③使险情初起即进入有序处置。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（预案长期封存不随风险更新），因此不符合构成要件。故选C。"},{"id":"pdn01733","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「前置响应」是指街道办通过建立台账逐项限时销号，使重复投诉明显下降的工作机制。\n\n按照上述界定，下列情形可认定为「前置响应」的是：","options":["街道办在老旧小区改造中，建立台账逐项限时销号，重复投诉明显下降。","由服务对象自行申报后不再跟进，后续也未按上述机制推进。","街道办在邻里纠纷调解中，各口径分头办理、彼此不通气，最终问题仍反复出现且未形成稳定机制。","街道办在便民事项办理中，建立台账逐项限时销号，但问题仍反复出现且未形成稳定机制。"],"answer":0,"explanation":"「前置响应」的构成要件为：①主体为街道办；②通过建立台账逐项限时销号；③使重复投诉明显下降。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01734","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「分级办理」是指社区网格站通过提前公示并逐户征询意见，使平均处置周期缩短的工作机制。\n\n根据上述定义，下列不属于「分级办理」的是：","options":["社区网格站在便民事项办理中，提前公示并逐户征询意见，平均处置周期缩短。","社区网格站在邻里纠纷调解中，提前公示并逐户征询意见，平均处置周期缩短。","社区网格站在邻里纠纷调解中，直接照搬既有方案、未作任何征询，最终问题仍反复出现且未形成稳定机制。","社区网格站在老旧小区改造中，提前公示并逐户征询意见，平均处置周期缩短。"],"answer":2,"explanation":"「分级办理」的构成要件为：①主体为社区网格站；②通过提前公示并逐户征询意见；③使平均处置周期缩短。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（直接照搬既有方案、未作任何征询），因此不符合构成要件。故选C。"},{"id":"pdn01735","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「跨界协作」是指区级牵头部门通过一次会商形成分工清单，使响应口径保持一致的工作机制。\n\n依据上述定义，以下哪一项符合「跨界协作」的构成要件：","options":["区级牵头部门在跨界事项梳理中，一次会商形成分工清单，响应口径保持一致。","由各区各自为政，后续也未按上述机制推进。","区级牵头部门在联合排班安排中，只开会不落责任清单，最终边界地带的问题仍在部门之间来回流转。","区级牵头部门在信息通报共享中，一次会商形成分工清单，但边界地带的问题仍在部门之间来回流转。"],"answer":0,"explanation":"「跨界协作」的构成要件为：①主体为区级牵头部门；②通过一次会商形成分工清单；③使响应口径保持一致。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01736","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「按需配置」是指就业服务窗口通过依据使用频次动态增减项目，使冷门项目被及时替换的工作机制。\n\n按照上述界定，下列情形不应认定为「按需配置」的是：","options":["就业服务窗口在对象需求摸排中，依据使用频次动态增减项目，冷门项目被及时替换。","就业服务窗口在服务清单编制中，依据使用频次动态增减项目，冷门项目被及时替换。","就业服务窗口在服务事项梳理中，依据使用频次动态增减项目，冷门项目被及时替换。","就业服务窗口在对象需求摸排中，先采购再询问是否需要，最终大量项目无人使用而真实诉求仍被搁置。"],"answer":3,"explanation":"「按需配置」的构成要件为：①主体为就业服务窗口；②通过依据使用频次动态增减项目；③使冷门项目被及时替换。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（先采购再询问是否需要），因此不符合构成要件。故选D。"},{"id":"pdn01737","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「脱敏处理」是指学校学籍管理系统通过按岗位授予最小可见范围，使共享环节不泄露可识别信息的工作机制。\n\n根据上述定义，下列属于「脱敏处理」的是：","options":["学校学籍管理系统在信息采集登记中，按岗位授予最小可见范围，共享环节不泄露可识别信息。","由系统默认长期全量保留，后续也未按上述机制推进。","学校学籍管理系统在数据调阅留痕中，按岗位授予最小可见范围，但与办理目的无关的字段仍被长期留存。","学校学籍管理系统在字段权限配置中，超过期限仍不作清理，最终与办理目的无关的字段仍被长期留存。"],"answer":0,"explanation":"「脱敏处理」的构成要件为：①主体为学校学籍管理系统；②通过按岗位授予最小可见范围；③使共享环节不泄露可识别信息。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01738","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「动态监测」是指湿地管护中心通过设定阈值并触发分级响应，使管控成本保持在合理区间的工作机制。\n\n依据上述定义，以下哪一项不符合「动态监测」的构成要件：","options":["湿地管护中心在外来因素扩散中，设定阈值并触发分级响应，管控成本保持在合理区间。","湿地管护中心在栖息环境变化中，设定阈值并触发分级响应，管控成本保持在合理区间。","湿地管护中心在栖息环境变化中，全年沿用同一套固定配额，最终指标已越界而措施仍维持不变。","湿地管护中心在监测指标波动中，设定阈值并触发分级响应，管控成本保持在合理区间。"],"answer":2,"explanation":"「动态监测」的构成要件为：①主体为湿地管护中心；②通过设定阈值并触发分级响应；③使管控成本保持在合理区间。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（全年沿用同一套固定配额），因此不符合构成要件。故选C。"},{"id":"pdn01739","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「表现性评价」是指学校教研组通过结合真实任务表现打分，使后续目标更贴合实际起点的工作机制。\n\n按照上述界定，下列情形可认定为「表现性评价」的是：","options":["学校教研组在作业反馈整理中，结合真实任务表现打分，但教学安排并未因数据而作任何调整。","学校教研组在单元教学设计中，结合真实任务表现打分，后续目标更贴合实际起点。","由家长自行报送成绩，后续也未按上述机制推进。","学校教研组在实验课程组织中，全程不作任何反馈、结束后才公布，最终教学安排并未因数据而作任何调整。"],"answer":1,"explanation":"「表现性评价」的构成要件为：①主体为学校教研组；②通过结合真实任务表现打分；③使后续目标更贴合实际起点。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01740","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「闭环处置」是指村委会通过提前公示并逐户征询意见，使诉求在前端得到化解的工作机制。\n\n根据上述定义，下列不属于「闭环处置」的是：","options":["村委会在老旧小区改造中，提前公示并逐户征询意见，诉求在前端得到化解。","村委会在便民事项办理中，提前公示并逐户征询意见，诉求在前端得到化解。","村委会在邻里纠纷调解中，提前公示并逐户征询意见，诉求在前端得到化解。","村委会在邻里纠纷调解中，只在事后补录台账，最终问题仍反复出现且未形成稳定机制。"],"answer":3,"explanation":"「闭环处置」的构成要件为：①主体为村委会；②通过提前公示并逐户征询意见；③使诉求在前端得到化解。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（只在事后补录台账），因此不符合构成要件。故选D。"},{"id":"pdn01741","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「灰度验证」是指改革推进专班通过先在小范围试运行再按反馈调整，使后续推广更贴合一线实际的工作机制。\n\n依据上述定义，以下哪一项符合「灰度验证」的构成要件：","options":["改革推进专班在新机制落地中，先在小范围试运行再按反馈调整，但同类偏差在扩面后被成倍放大。","由用户自行摸索不作收集，后续也未按上述机制推进。","改革推进专班在新工具推广中，一次上线后即固化不再迭代，最终同类偏差在扩面后被成倍放大。","改革推进专班在新流程上线中，先在小范围试运行再按反馈调整，后续推广更贴合一线实际。"],"answer":3,"explanation":"「灰度验证」的构成要件为：①主体为改革推进专班；②通过先在小范围试运行再按反馈调整；③使后续推广更贴合一线实际。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01742","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「动态监测」是指自然保护区管理局通过随季节数据滚动修订方案，使异常苗头被尽早识别的工作机制。\n\n按照上述界定，下列情形不应认定为「动态监测」的是：","options":["自然保护区管理局在监测指标波动中，随季节数据滚动修订方案，异常苗头被尽早识别。","自然保护区管理局在外来因素扩散中，随季节数据滚动修订方案，异常苗头被尽早识别。","自然保护区管理局在栖息环境变化中，全年沿用同一套固定配额，最终指标已越界而措施仍维持不变。","自然保护区管理局在栖息环境变化中，随季节数据滚动修订方案，异常苗头被尽早识别。"],"answer":2,"explanation":"「动态监测」的构成要件为：①主体为自然保护区管理局；②通过随季节数据滚动修订方案；③使异常苗头被尽早识别。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（全年沿用同一套固定配额），因此不符合构成要件。故选C。"},{"id":"pdn01743","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「动态监测」是指自然保护区管理局通过随季节数据滚动修订方案，使核心栖息地得到有效避让的工作机制。\n\n根据上述定义，下列属于「动态监测」的是：","options":["自然保护区管理局在外来因素扩散中，随季节数据滚动修订方案，但指标已越界而措施仍维持不变。","自然保护区管理局在栖息环境变化中，指标超标后仍不调整，最终指标已越界而措施仍维持不变。","由邻近地区照抄方案，后续也未按上述机制推进。","自然保护区管理局在监测指标波动中，随季节数据滚动修订方案，核心栖息地得到有效避让。"],"answer":3,"explanation":"「动态监测」的构成要件为：①主体为自然保护区管理局；②通过随季节数据滚动修订方案；③使核心栖息地得到有效避让。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01744","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「循证施策」是指统计调查队通过对关键指标作独立复核，使后续调整有据可依的工作机制。\n\n依据上述定义，以下哪一项不符合「循证施策」的构成要件：","options":["统计调查队在政策效果评估中，以主观感受替代实测数据，最终结论无法由所引数据支撑。","统计调查队在政策效果评估中，对关键指标作独立复核，后续调整有据可依。","统计调查队在抽样数据核查中，对关键指标作独立复核，后续调整有据可依。","统计调查队在年度计划编制中，对关键指标作独立复核，后续调整有据可依。"],"answer":0,"explanation":"「循证施策」的构成要件为：①主体为统计调查队；②通过对关键指标作独立复核；③使后续调整有据可依。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（以主观感受替代实测数据），因此不符合构成要件。故选A。"},{"id":"pdn01745","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「小步试点」是指政策试点工作组通过分批次扩面而非一次铺开，使风险被限制在可控范围的工作机制。\n\n按照上述界定，下列情形可认定为「小步试点」的是：","options":["由用户自行摸索不作收集，后续也未按上述机制推进。","政策试点工作组在新机制落地中，分批次扩面而非一次铺开，但同类偏差在扩面后被成倍放大。","政策试点工作组在新流程上线中，分批次扩面而非一次铺开，风险被限制在可控范围。","政策试点工作组在新工具推广中，一次上线后即固化不再迭代，最终同类偏差在扩面后被成倍放大。"],"answer":2,"explanation":"「小步试点」的构成要件为：①主体为政策试点工作组；②通过分批次扩面而非一次铺开；③使风险被限制在可控范围。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01746","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「风险前置」是指数据中心运维组通过关键节点保留备用通道，使核心功能在异常下仍可维持的工作机制。\n\n根据上述定义，下列不属于「风险前置」的是：","options":["数据中心运维组在响应动作预置中，等指标越限后才临时研究方案，最终异常发生时无预设动作可依。","数据中心运维组在关键节点值守中，关键节点保留备用通道，核心功能在异常下仍可维持。","数据中心运维组在响应动作预置中，关键节点保留备用通道，核心功能在异常下仍可维持。","数据中心运维组在风险等级研判中，关键节点保留备用通道，核心功能在异常下仍可维持。"],"answer":0,"explanation":"「风险前置」的构成要件为：①主体为数据中心运维组；②通过关键节点保留备用通道；③使核心功能在异常下仍可维持。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（等指标越限后才临时研究方案），因此不符合构成要件。故选A。"},{"id":"pdn01747","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「弹性调控」是指流域管理机构通过设定阈值并触发分级响应，使干预强度与实际风险相匹配的工作机制。\n\n依据上述定义，以下哪一项符合「弹性调控」的构成要件：","options":["流域管理机构在监测指标波动中，设定阈值并触发分级响应，干预强度与实际风险相匹配。","由邻近地区照抄方案，后续也未按上述机制推进。","流域管理机构在外来因素扩散中，设定阈值并触发分级响应，但指标已越界而措施仍维持不变。","流域管理机构在栖息环境变化中，指标超标后仍不调整，最终指标已越界而措施仍维持不变。"],"answer":0,"explanation":"「弹性调控」的构成要件为：①主体为流域管理机构；②通过设定阈值并触发分级响应；③使干预强度与实际风险相匹配。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01748","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「联勤联动」是指跨部门工作专班通过建立常态化联络与移交规则，使跨界问题不再悬空的工作机制。\n\n按照上述界定，下列情形不应认定为「联勤联动」的是：","options":["跨部门工作专班在联合排班安排中，建立常态化联络与移交规则，跨界问题不再悬空。","跨部门工作专班在联合排班安排中，遇跨界事项互相等待，最终边界地带的问题仍在部门之间来回流转。","跨部门工作专班在信息通报共享中，建立常态化联络与移交规则，跨界问题不再悬空。","跨部门工作专班在跨界事项梳理中，建立常态化联络与移交规则，跨界问题不再悬空。"],"answer":1,"explanation":"「联勤联动」的构成要件为：①主体为跨部门工作专班；②通过建立常态化联络与移交规则；③使跨界问题不再悬空。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（遇跨界事项互相等待），因此不符合构成要件。故选B。"},{"id":"pdn01749","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「网格代办」是指村委会通过依托网格员常态化走访摸排，使重复投诉明显下降的工作机制。\n\n根据上述定义，下列属于「网格代办」的是：","options":["村委会在邻里纠纷调解中，各口径分头办理、彼此不通气，最终问题仍反复出现且未形成稳定机制。","由服务对象自行申报后不再跟进，后续也未按上述机制推进。","村委会在便民事项办理中，依托网格员常态化走访摸排，但问题仍反复出现且未形成稳定机制。","村委会在老旧小区改造中，依托网格员常态化走访摸排，重复投诉明显下降。"],"answer":3,"explanation":"「网格代办」的构成要件为：①主体为村委会；②通过依托网格员常态化走访摸排；③使重复投诉明显下降。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01750","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「过程性考核」是指学校教研组通过先摸清起点再设定分层目标，使教学策略得以动态优化的工作机制。\n\n依据上述定义，以下哪一项不符合「过程性考核」的构成要件：","options":["学校教研组在作业反馈整理中，先摸清起点再设定分层目标，教学策略得以动态优化。","学校教研组在实验课程组织中，只以期末一次分数定结论，最终教学安排并未因数据而作任何调整。","学校教研组在单元教学设计中，先摸清起点再设定分层目标，教学策略得以动态优化。","学校教研组在实验课程组织中，先摸清起点再设定分层目标，教学策略得以动态优化。"],"answer":1,"explanation":"「过程性考核」的构成要件为：①主体为学校教研组；②通过先摸清起点再设定分层目标；③使教学策略得以动态优化。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（只以期末一次分数定结论），因此不符合构成要件。故选B。"},{"id":"pdn01751","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「共创反馈环」是指社区营造团队通过先做可体验原型再收集反馈，使改动获得使用者认同的工作机制。\n\n按照上述界定，下列情形可认定为「共创反馈环」的是：","options":["社区营造团队在服务流程梳理中，先做可体验原型再收集反馈，改动获得使用者认同。","社区营造团队在公共界面优化中，只做内部评审不接触使用者，最终上线后仍频发与习惯不符的障碍。","由供应商提供标准模板，后续也未按上述机制推进。","社区营造团队在使用路径排查中，先做可体验原型再收集反馈，但上线后仍频发与习惯不符的障碍。"],"answer":0,"explanation":"「共创反馈环」的构成要件为：①主体为社区营造团队；②通过先做可体验原型再收集反馈；③使改动获得使用者认同。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01752","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「冗余备份」是指城市运行管理平台通过设定触发条件并提前布防，使次生影响被压到最小的工作机制。\n\n根据上述定义，下列不属于「冗余备份」的是：","options":["城市运行管理平台在风险等级研判中，设定触发条件并提前布防，次生影响被压到最小。","城市运行管理平台在关键节点值守中，设定触发条件并提前布防，次生影响被压到最小。","城市运行管理平台在响应动作预置中，预案长期封存不随风险更新，最终异常发生时无预设动作可依。","城市运行管理平台在响应动作预置中，设定触发条件并提前布防，次生影响被压到最小。"],"answer":2,"explanation":"「冗余备份」的构成要件为：①主体为城市运行管理平台；②通过设定触发条件并提前布防；③使次生影响被压到最小。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（预案长期封存不随风险更新），因此不符合构成要件。故选C。"},{"id":"pdn01753","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「协同会商」是指村委会通过依托网格员常态化走访摸排，使平均处置周期缩短的工作机制。\n\n依据上述定义，以下哪一项符合「协同会商」的构成要件：","options":["村委会在便民事项办理中，依托网格员常态化走访摸排，但问题仍反复出现且未形成稳定机制。","村委会在邻里纠纷调解中，各口径分头办理、彼此不通气，最终问题仍反复出现且未形成稳定机制。","村委会在老旧小区改造中，依托网格员常态化走访摸排，平均处置周期缩短。","由服务对象自行申报后不再跟进，后续也未按上述机制推进。"],"answer":2,"explanation":"「协同会商」的构成要件为：①主体为村委会；②通过依托网格员常态化走访摸排；③使平均处置周期缩短。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01754","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「形成性评价」是指学校教研组通过结合真实任务表现打分，使教学策略得以动态优化的工作机制。\n\n按照上述界定，下列情形不应认定为「形成性评价」的是：","options":["学校教研组在作业反馈整理中，结合真实任务表现打分，教学策略得以动态优化。","学校教研组在实验课程组织中，结合真实任务表现打分，教学策略得以动态优化。","学校教研组在实验课程组织中，只以期末一次分数定结论，最终教学安排并未因数据而作任何调整。","学校教研组在单元教学设计中，结合真实任务表现打分，教学策略得以动态优化。"],"answer":2,"explanation":"「形成性评价」的构成要件为：①主体为学校教研组；②通过结合真实任务表现打分；③使教学策略得以动态优化。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（只以期末一次分数定结论），因此不符合构成要件。故选C。"},{"id":"pdn01755","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「共创反馈环」是指无障碍改造专班通过邀请使用者全程参与方案打磨，使改动获得使用者认同的工作机制。\n\n根据上述定义，下列属于「共创反馈环」的是：","options":["无障碍改造专班在公共界面优化中，只做内部评审不接触使用者，最终上线后仍频发与习惯不符的障碍。","无障碍改造专班在使用路径排查中，邀请使用者全程参与方案打磨，但上线后仍频发与习惯不符的障碍。","由供应商提供标准模板，后续也未按上述机制推进。","无障碍改造专班在服务流程梳理中，邀请使用者全程参与方案打磨，改动获得使用者认同。"],"answer":3,"explanation":"「共创反馈环」的构成要件为：①主体为无障碍改造专班；②通过邀请使用者全程参与方案打磨；③使改动获得使用者认同。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01756","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「前置响应」是指村委会通过提前公示并逐户征询意见，使居民满意度稳步提升的工作机制。\n\n依据上述定义，以下哪一项不符合「前置响应」的构成要件：","options":["村委会在邻里纠纷调解中，提前公示并逐户征询意见，居民满意度稳步提升。","村委会在邻里纠纷调解中，只在事后补录台账，最终问题仍反复出现且未形成稳定机制。","村委会在便民事项办理中，提前公示并逐户征询意见，居民满意度稳步提升。","村委会在老旧小区改造中，提前公示并逐户征询意见，居民满意度稳步提升。"],"answer":1,"explanation":"「前置响应」的构成要件为：①主体为村委会；②通过提前公示并逐户征询意见；③使居民满意度稳步提升。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（只在事后补录台账），因此不符合构成要件。故选B。"},{"id":"pdn01757","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「链条式核验」是指食品药品监管所通过每一节点登记并关联上下游凭证，使责任环节清晰可查的工作机制。\n\n按照上述界定，下列情形可认定为「链条式核验」的是：","options":["食品药品监管所在储运环节温控中，每一节点登记并关联上下游凭证，但出现问题时无法定位到具体环节。","食品药品监管所在进货环节核验中，每一节点登记并关联上下游凭证，责任环节清晰可查。","由消费者事后反馈倒查，后续也未按上述机制推进。","食品药品监管所在批次交接记录中，仅保留汇总数不留明细，最终出现问题时无法定位到具体环节。"],"answer":1,"explanation":"「链条式核验」的构成要件为：①主体为食品药品监管所；②通过每一节点登记并关联上下游凭证；③使责任环节清晰可查。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01758","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「脆弱性评估」是指应急指挥中心通过关键节点保留备用通道，使次生影响被压到最小的工作机制。\n\n根据上述定义，下列不属于「脆弱性评估」的是：","options":["应急指挥中心在响应动作预置中，关键节点保留备用通道，次生影响被压到最小。","应急指挥中心在关键节点值守中，关键节点保留备用通道，次生影响被压到最小。","应急指挥中心在响应动作预置中，等指标越限后才临时研究方案，最终异常发生时无预设动作可依。","应急指挥中心在风险等级研判中，关键节点保留备用通道，次生影响被压到最小。"],"answer":2,"explanation":"「脆弱性评估」的构成要件为：①主体为应急指挥中心；②通过关键节点保留备用通道；③使次生影响被压到最小。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（等指标越限后才临时研究方案），因此不符合构成要件。故选C。"},{"id":"pdn01759","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「联合响应」是指区级牵头部门通过建立常态化联络与移交规则，使处置效率整体提升的工作机制。\n\n依据上述定义，以下哪一项符合「联合响应」的构成要件：","options":["区级牵头部门在信息通报共享中，建立常态化联络与移交规则，但边界地带的问题仍在部门之间来回流转。","区级牵头部门在跨界事项梳理中，建立常态化联络与移交规则，处置效率整体提升。","由各区各自为政，后续也未按上述机制推进。","区级牵头部门在联合排班安排中，只开会不落责任清单，最终边界地带的问题仍在部门之间来回流转。"],"answer":1,"explanation":"「联合响应」的构成要件为：①主体为区级牵头部门；②通过建立常态化联络与移交规则；③使处置效率整体提升。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01760","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「多元共治」是指街道与职能站所通过明确牵头与配合边界后统一行动，使处置效率整体提升的工作机制。\n\n按照上述界定，下列情形不应认定为「多元共治」的是：","options":["街道与职能站所在信息通报共享中，明确牵头与配合边界后统一行动，处置效率整体提升。","街道与职能站所在联合排班安排中，遇跨界事项互相等待，最终边界地带的问题仍在部门之间来回流转。","街道与职能站所在联合排班安排中，明确牵头与配合边界后统一行动，处置效率整体提升。","街道与职能站所在跨界事项梳理中，明确牵头与配合边界后统一行动，处置效率整体提升。"],"answer":1,"explanation":"「多元共治」的构成要件为：①主体为街道与职能站所；②通过明确牵头与配合边界后统一行动；③使处置效率整体提升。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（遇跨界事项互相等待），因此不符合构成要件。故选B。"},{"id":"pdn01761","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「基线比对」是指统计调查队通过对关键指标作独立复核，使后续调整有据可依的工作机制。\n\n根据上述定义，下列属于「基线比对」的是：","options":["统计调查队在年度计划编制中，对关键指标作独立复核，后续调整有据可依。","统计调查队在政策效果评估中，指标口径中途变更却不说明，最终结论无法由所引数据支撑。","由第三方直接给结论不附依据，后续也未按上述机制推进。","统计调查队在抽样数据核查中，对关键指标作独立复核，但结论无法由所引数据支撑。"],"answer":0,"explanation":"「基线比对」的构成要件为：①主体为统计调查队；②通过对关键指标作独立复核；③使后续调整有据可依。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01762","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「容错纠偏」是指产品迭代小组通过设置观察期并保留回退通道，使后续推广更贴合一线实际的工作机制。\n\n依据上述定义，以下哪一项不符合「容错纠偏」的构成要件：","options":["产品迭代小组在新工具推广中，设置观察期并保留回退通道，后续推广更贴合一线实际。","产品迭代小组在新流程上线中，设置观察期并保留回退通道，后续推广更贴合一线实际。","产品迭代小组在新工具推广中，不经试点直接全面强制推开，最终同类偏差在扩面后被成倍放大。","产品迭代小组在新机制落地中，设置观察期并保留回退通道，后续推广更贴合一线实际。"],"answer":2,"explanation":"「容错纠偏」的构成要件为：①主体为产品迭代小组；②通过设置观察期并保留回退通道；③使后续推广更贴合一线实际。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（不经试点直接全面强制推开），因此不符合构成要件。故选C。"},{"id":"pdn01763","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「目的限定」是指学校学籍管理系统通过对外提供前作去标识化处理，使敏感字段仅在授权场景可见的工作机制。\n\n按照上述界定，下列情形可认定为「目的限定」的是：","options":["学校学籍管理系统在字段权限配置中，所有岗位开放同一份全量清单，最终与办理目的无关的字段仍被长期留存。","学校学籍管理系统在信息采集登记中，对外提供前作去标识化处理，敏感字段仅在授权场景可见。","由外包人员全量导出，后续也未按上述机制推进。","学校学籍管理系统在数据调阅留痕中，对外提供前作去标识化处理，但与办理目的无关的字段仍被长期留存。"],"answer":1,"explanation":"「目的限定」的构成要件为：①主体为学校学籍管理系统；②通过对外提供前作去标识化处理；③使敏感字段仅在授权场景可见。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01764","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「原型共创」是指无障碍改造专班通过按真实使用路径逐点排查痛点，使隐蔽障碍在使用前被暴露的工作机制。\n\n根据上述定义，下列不属于「原型共创」的是：","options":["无障碍改造专班在公共界面优化中，按真实使用路径逐点排查痛点，隐蔽障碍在使用前被暴露。","无障碍改造专班在使用路径排查中，按真实使用路径逐点排查痛点，隐蔽障碍在使用前被暴露。","无障碍改造专班在公共界面优化中，照搬其他地区成品，最终上线后仍频发与习惯不符的障碍。","无障碍改造专班在服务流程梳理中，按真实使用路径逐点排查痛点，隐蔽障碍在使用前被暴露。"],"answer":2,"explanation":"「原型共创」的构成要件为：①主体为无障碍改造专班；②通过按真实使用路径逐点排查痛点；③使隐蔽障碍在使用前被暴露。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（照搬其他地区成品），因此不符合构成要件。故选C。"},{"id":"pdn01765","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「按需配置」是指养老服务站点通过按对象条件分档配置资源，使供给与实际需求更加贴合的工作机制。\n\n依据上述定义，以下哪一项符合「按需配置」的构成要件：","options":["由服务对象自行寻找渠道，后续也未按上述机制推进。","养老服务站点在服务清单编制中，按对象条件分档配置资源，但大量项目无人使用而真实诉求仍被搁置。","养老服务站点在服务事项梳理中，按对象条件分档配置资源，供给与实际需求更加贴合。","养老服务站点在对象需求摸排中，沿用上一年清单不作修订，最终大量项目无人使用而真实诉求仍被搁置。"],"answer":2,"explanation":"「按需配置」的构成要件为：①主体为养老服务站点；②通过按对象条件分档配置资源；③使供给与实际需求更加贴合。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01766","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「预案触发」是指应急指挥中心通过识别薄弱环节并预先加固，使次生影响被压到最小的工作机制。\n\n按照上述界定，下列情形不应认定为「预案触发」的是：","options":["应急指挥中心在关键节点值守中，识别薄弱环节并预先加固，次生影响被压到最小。","应急指挥中心在风险等级研判中，识别薄弱环节并预先加固，次生影响被压到最小。","应急指挥中心在响应动作预置中，等指标越限后才临时研究方案，最终异常发生时无预设动作可依。","应急指挥中心在响应动作预置中，识别薄弱环节并预先加固，次生影响被压到最小。"],"answer":2,"explanation":"「预案触发」的构成要件为：①主体为应急指挥中心；②通过识别薄弱环节并预先加固；③使次生影响被压到最小。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（等指标越限后才临时研究方案），因此不符合构成要件。故选C。"},{"id":"pdn01767","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「按需配置」是指农技推广站通过先摸清不同群体诉求再分类提供，使资源不再平均摊薄的工作机制。\n\n根据上述定义，下列属于「按需配置」的是：","options":["农技推广站在服务清单编制中，先摸清不同群体诉求再分类提供，但大量项目无人使用而真实诉求仍被搁置。","农技推广站在服务事项梳理中，先摸清不同群体诉求再分类提供，资源不再平均摊薄。","由供应商单方决定目录，后续也未按上述机制推进。","农技推广站在对象需求摸排中，按编制人数而不是实际用量分配，最终大量项目无人使用而真实诉求仍被搁置。"],"answer":1,"explanation":"「按需配置」的构成要件为：①主体为农技推广站；②通过先摸清不同群体诉求再分类提供；③使资源不再平均摊薄。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01768","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「差异化供给」是指公共文化服务中心通过按可选项自主组合形成服务清单，使资源不再平均摊薄的工作机制。\n\n依据上述定义，以下哪一项不符合「差异化供给」的构成要件：","options":["公共文化服务中心在服务清单编制中，按可选项自主组合形成服务清单，资源不再平均摊薄。","公共文化服务中心在对象需求摸排中，先采购再询问是否需要，最终大量项目无人使用而真实诉求仍被搁置。","公共文化服务中心在对象需求摸排中，按可选项自主组合形成服务清单，资源不再平均摊薄。","公共文化服务中心在服务事项梳理中，按可选项自主组合形成服务清单，资源不再平均摊薄。"],"answer":1,"explanation":"「差异化供给」的构成要件为：①主体为公共文化服务中心；②通过按可选项自主组合形成服务清单；③使资源不再平均摊薄。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（先采购再询问是否需要），因此不符合构成要件。故选B。"},{"id":"pdn01769","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「分级办理」是指街道办通过联合多方现场会商后再定方案，使居民满意度稳步提升的工作机制。\n\n按照上述界定，下列情形可认定为「分级办理」的是：","options":["由服务对象自行申报后不再跟进，后续也未按上述机制推进。","街道办在老旧小区改造中，联合多方现场会商后再定方案，居民满意度稳步提升。","街道办在邻里纠纷调解中，各口径分头办理、彼此不通气，最终问题仍反复出现且未形成稳定机制。","街道办在便民事项办理中，联合多方现场会商后再定方案，但问题仍反复出现且未形成稳定机制。"],"answer":1,"explanation":"「分级办理」的构成要件为：①主体为街道办；②通过联合多方现场会商后再定方案；③使居民满意度稳步提升。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01770","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「差异化供给」是指就业服务窗口通过先摸清不同群体诉求再分类提供，使供给与实际需求更加贴合的工作机制。\n\n根据上述定义，下列不属于「差异化供给」的是：","options":["就业服务窗口在对象需求摸排中，先摸清不同群体诉求再分类提供，供给与实际需求更加贴合。","就业服务窗口在服务事项梳理中，先摸清不同群体诉求再分类提供，供给与实际需求更加贴合。","就业服务窗口在对象需求摸排中，所有对象发放完全相同的固定包，最终大量项目无人使用而真实诉求仍被搁置。","就业服务窗口在服务清单编制中，先摸清不同群体诉求再分类提供，供给与实际需求更加贴合。"],"answer":2,"explanation":"「差异化供给」的构成要件为：①主体为就业服务窗口；②通过先摸清不同群体诉求再分类提供；③使供给与实际需求更加贴合。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（所有对象发放完全相同的固定包），因此不符合构成要件。故选C。"},{"id":"pdn01771","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「网格代办」是指街道办通过联合多方现场会商后再定方案，使重复投诉明显下降的工作机制。\n\n依据上述定义，以下哪一项符合「网格代办」的构成要件：","options":["由临时志愿队自行接管，后续也未按上述机制推进。","街道办在老旧小区改造中，联合多方现场会商后再定方案，重复投诉明显下降。","街道办在邻里纠纷调解中，等群众上门反映后再统一研究，最终问题仍反复出现且未形成稳定机制。","街道办在便民事项办理中，联合多方现场会商后再定方案，但问题仍反复出现且未形成稳定机制。"],"answer":1,"explanation":"「网格代办」的构成要件为：①主体为街道办；②通过联合多方现场会商后再定方案；③使重复投诉明显下降。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01772","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「随访管理」是指县域医共体通过先由基层评估再决定是否上转，使病情变化能被尽早发现的工作机制。\n\n按照上述界定，下列情形不应认定为「随访管理」的是：","options":["县域医共体在康复跟踪记录中，各机构各自重复开单，最终各环节彼此脱节、患者仍需多次重复排队。","县域医共体在慢病随访安排中，先由基层评估再决定是否上转，病情变化能被尽早发现。","县域医共体在重点人群筛查中，先由基层评估再决定是否上转，病情变化能被尽早发现。","县域医共体在康复跟踪记录中，先由基层评估再决定是否上转，病情变化能被尽早发现。"],"answer":0,"explanation":"「随访管理」的构成要件为：①主体为县域医共体；②通过先由基层评估再决定是否上转；③使病情变化能被尽早发现。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（各机构各自重复开单），因此不符合构成要件。故选A。"},{"id":"pdn01773","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「联勤联动」是指街道与职能站所通过一次会商形成分工清单，使跨界问题不再悬空的工作机制。\n\n根据上述定义，下列属于「联勤联动」的是：","options":["街道与职能站所在联合排班安排中，各自按本部门旧流程办理，最终边界地带的问题仍在部门之间来回流转。","街道与职能站所在信息通报共享中，一次会商形成分工清单，但边界地带的问题仍在部门之间来回流转。","由上级部门包办到底，后续也未按上述机制推进。","街道与职能站所在跨界事项梳理中，一次会商形成分工清单，跨界问题不再悬空。"],"answer":3,"explanation":"「联勤联动」的构成要件为：①主体为街道与职能站所；②通过一次会商形成分工清单；③使跨界问题不再悬空。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01774","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「分级办理」是指社区网格站通过建立台账逐项限时销号，使平均处置周期缩短的工作机制。\n\n依据上述定义，以下哪一项不符合「分级办理」的构成要件：","options":["社区网格站在邻里纠纷调解中，建立台账逐项限时销号，平均处置周期缩短。","社区网格站在邻里纠纷调解中，直接照搬既有方案、未作任何征询，最终问题仍反复出现且未形成稳定机制。","社区网格站在老旧小区改造中，建立台账逐项限时销号，平均处置周期缩短。","社区网格站在便民事项办理中，建立台账逐项限时销号，平均处置周期缩短。"],"answer":1,"explanation":"「分级办理」的构成要件为：①主体为社区网格站；②通过建立台账逐项限时销号；③使平均处置周期缩短。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（直接照搬既有方案、未作任何征询），因此不符合构成要件。故选B。"},{"id":"pdn01775","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「网格代办」是指乡镇便民中心通过建立台账逐项限时销号，使重复投诉明显下降的工作机制。\n\n按照上述界定，下列情形可认定为「网格代办」的是：","options":["乡镇便民中心在老旧小区改造中，建立台账逐项限时销号，重复投诉明显下降。","乡镇便民中心在便民事项办理中，建立台账逐项限时销号，但问题仍反复出现且未形成稳定机制。","乡镇便民中心在邻里纠纷调解中，等群众上门反映后再统一研究，最终问题仍反复出现且未形成稳定机制。","由临时志愿队自行接管，后续也未按上述机制推进。"],"answer":0,"explanation":"「网格代办」的构成要件为：①主体为乡镇便民中心；②通过建立台账逐项限时销号；③使重复投诉明显下降。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01776","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「动态监测」是指生态环境监测站通过按监测指标分档调整措施，使异常苗头被尽早识别的工作机制。\n\n根据上述定义，下列不属于「动态监测」的是：","options":["生态环境监测站在栖息环境变化中，按监测指标分档调整措施，异常苗头被尽早识别。","生态环境监测站在栖息环境变化中，只看年度均值忽略峰值，最终指标已越界而措施仍维持不变。","生态环境监测站在外来因素扩散中，按监测指标分档调整措施，异常苗头被尽早识别。","生态环境监测站在监测指标波动中，按监测指标分档调整措施，异常苗头被尽早识别。"],"answer":1,"explanation":"「动态监测」的构成要件为：①主体为生态环境监测站；②通过按监测指标分档调整措施；③使异常苗头被尽早识别。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（只看年度均值忽略峰值），因此不符合构成要件。故选B。"},{"id":"pdn01777","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「用户旅程映射」是指无障碍改造专班通过多轮共创后收敛为最终版本，使返工与投诉明显减少的工作机制。\n\n依据上述定义，以下哪一项符合「用户旅程映射」的构成要件：","options":["无障碍改造专班在公共界面优化中，一次性定稿不再接收反馈，最终上线后仍频发与习惯不符的障碍。","无障碍改造专班在服务流程梳理中，多轮共创后收敛为最终版本，返工与投诉明显减少。","由外部专家远程定稿，后续也未按上述机制推进。","无障碍改造专班在使用路径排查中，多轮共创后收敛为最终版本，但上线后仍频发与习惯不符的障碍。"],"answer":1,"explanation":"「用户旅程映射」的构成要件为：①主体为无障碍改造专班；②通过多轮共创后收敛为最终版本；③使返工与投诉明显减少。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01778","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「分级办理」是指乡镇便民中心通过建立台账逐项限时销号，使平均处置周期缩短的工作机制。\n\n按照上述界定，下列情形不应认定为「分级办理」的是：","options":["乡镇便民中心在邻里纠纷调解中，直接照搬既有方案、未作任何征询，最终问题仍反复出现且未形成稳定机制。","乡镇便民中心在邻里纠纷调解中，建立台账逐项限时销号，平均处置周期缩短。","乡镇便民中心在老旧小区改造中，建立台账逐项限时销号，平均处置周期缩短。","乡镇便民中心在便民事项办理中，建立台账逐项限时销号，平均处置周期缩短。"],"answer":0,"explanation":"「分级办理」的构成要件为：①主体为乡镇便民中心；②通过建立台账逐项限时销号；③使平均处置周期缩短。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（直接照搬既有方案、未作任何征询），因此不符合构成要件。故选A。"},{"id":"pdn01779","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「指标复核」是指规划编制组通过先确立基线再对照前后变化，使结论不易被个别异常值带偏的工作机制。\n\n根据上述定义，下列属于「指标复核」的是：","options":["规划编制组在政策效果评估中，用总量变化直接归因、不作对照，最终结论无法由所引数据支撑。","规划编制组在年度计划编制中，先确立基线再对照前后变化，结论不易被个别异常值带偏。","由申报方自行填报不作核实，后续也未按上述机制推进。","规划编制组在抽样数据核查中，先确立基线再对照前后变化，但结论无法由所引数据支撑。"],"answer":1,"explanation":"「指标复核」的构成要件为：①主体为规划编制组；②通过先确立基线再对照前后变化；③使结论不易被个别异常值带偏。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01780","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「循证施策」是指统计调查队通过先确立基线再对照前后变化，使结论不易被个别异常值带偏的工作机制。\n\n依据上述定义，以下哪一项不符合「循证施策」的构成要件：","options":["统计调查队在年度计划编制中，先确立基线再对照前后变化，结论不易被个别异常值带偏。","统计调查队在政策效果评估中，先确立基线再对照前后变化，结论不易被个别异常值带偏。","统计调查队在抽样数据核查中，先确立基线再对照前后变化，结论不易被个别异常值带偏。","统计调查队在政策效果评估中，以主观感受替代实测数据，最终结论无法由所引数据支撑。"],"answer":3,"explanation":"「循证施策」的构成要件为：①主体为统计调查队；②通过先确立基线再对照前后变化；③使结论不易被个别异常值带偏。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（以主观感受替代实测数据），因此不符合构成要件。故选D。"},{"id":"pdn01781","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「表现性评价」是指课程组通过先摸清起点再设定分层目标，使学习过程而非仅结果被看见的工作机制。\n\n按照上述界定，下列情形可认定为「表现性评价」的是：","options":["课程组在作业反馈整理中，先摸清起点再设定分层目标，但教学安排并未因数据而作任何调整。","课程组在实验课程组织中，按固定名次划线且不追溯变化，最终教学安排并未因数据而作任何调整。","课程组在单元教学设计中，先摸清起点再设定分层目标，学习过程而非仅结果被看见。","由学生互评后不再复核，后续也未按上述机制推进。"],"answer":2,"explanation":"「表现性评价」的构成要件为：①主体为课程组；②通过先摸清起点再设定分层目标；③使学习过程而非仅结果被看见。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01782","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「网格代办」是指社区网格站通过建立台账逐项限时销号，使重复投诉明显下降的工作机制。\n\n根据上述定义，下列不属于「网格代办」的是：","options":["社区网格站在老旧小区改造中，建立台账逐项限时销号，重复投诉明显下降。","社区网格站在邻里纠纷调解中，建立台账逐项限时销号，重复投诉明显下降。","社区网格站在便民事项办理中，建立台账逐项限时销号，重复投诉明显下降。","社区网格站在邻里纠纷调解中，直接照搬既有方案、未作任何征询，最终问题仍反复出现且未形成稳定机制。"],"answer":3,"explanation":"「网格代办」的构成要件为：①主体为社区网格站；②通过建立台账逐项限时销号；③使重复投诉明显下降。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（直接照搬既有方案、未作任何征询），因此不符合构成要件。故选D。"},{"id":"pdn01783","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「风险前置」是指城市运行管理平台通过设定触发条件并提前布防，使人员与物资提前就位的工作机制。\n\n依据上述定义，以下哪一项符合「风险前置」的构成要件：","options":["由上级在事后统一追认，后续也未按上述机制推进。","城市运行管理平台在关键节点值守中，设定触发条件并提前布防，但异常发生时无预设动作可依。","城市运行管理平台在风险等级研判中，设定触发条件并提前布防，人员与物资提前就位。","城市运行管理平台在响应动作预置中，仅保留一份无备用的关键设备，最终异常发生时无预设动作可依。"],"answer":2,"explanation":"「风险前置」的构成要件为：①主体为城市运行管理平台；②通过设定触发条件并提前布防；③使人员与物资提前就位。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01784","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「全过程追溯」是指农产品质量检测站通过按批号串联台账与检验记录，使台账与实物始终一致的工作机制。\n\n按照上述界定，下列情形不应认定为「全过程追溯」的是：","options":["农产品质量检测站在进货环节核验中，按批号串联台账与检验记录，台账与实物始终一致。","农产品质量检测站在批次交接记录中，按批号串联台账与检验记录，台账与实物始终一致。","农产品质量检测站在批次交接记录中，事后一次性补全整本台账，最终出现问题时无法定位到具体环节。","农产品质量检测站在储运环节温控中，按批号串联台账与检验记录，台账与实物始终一致。"],"answer":2,"explanation":"「全过程追溯」的构成要件为：①主体为农产品质量检测站；②通过按批号串联台账与检验记录；③使台账与实物始终一致。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（事后一次性补全整本台账），因此不符合构成要件。故选C。"},{"id":"pdn01785","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「节点责任制」是指药品批发企业质控部通过按批号串联台账与检验记录，使台账与实物始终一致的工作机制。\n\n根据上述定义，下列属于「节点责任制」的是：","options":["由消费者事后反馈倒查，后续也未按上述机制推进。","药品批发企业质控部在批次交接记录中，仅保留汇总数不留明细，最终出现问题时无法定位到具体环节。","药品批发企业质控部在进货环节核验中，按批号串联台账与检验记录，台账与实物始终一致。","药品批发企业质控部在储运环节温控中，按批号串联台账与检验记录，但出现问题时无法定位到具体环节。"],"answer":2,"explanation":"「节点责任制」的构成要件为：①主体为药品批发企业质控部；②通过按批号串联台账与检验记录；③使台账与实物始终一致。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01786","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「分级办理」是指乡镇便民中心通过联合多方现场会商后再定方案，使平均处置周期缩短的工作机制。\n\n依据上述定义，以下哪一项不符合「分级办理」的构成要件：","options":["乡镇便民中心在邻里纠纷调解中，联合多方现场会商后再定方案，平均处置周期缩短。","乡镇便民中心在便民事项办理中，联合多方现场会商后再定方案，平均处置周期缩短。","乡镇便民中心在老旧小区改造中，联合多方现场会商后再定方案，平均处置周期缩短。","乡镇便民中心在邻里纠纷调解中，直接照搬既有方案、未作任何征询，最终问题仍反复出现且未形成稳定机制。"],"answer":3,"explanation":"「分级办理」的构成要件为：①主体为乡镇便民中心；②通过联合多方现场会商后再定方案；③使平均处置周期缩短。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（直接照搬既有方案、未作任何征询），因此不符合构成要件。故选D。"},{"id":"pdn01787","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「原型共创」是指产品体验小组通过按真实使用路径逐点排查痛点，使返工与投诉明显减少的工作机制。\n\n按照上述界定，下列情形可认定为「原型共创」的是：","options":["产品体验小组在公共界面优化中，只做内部评审不接触使用者，最终上线后仍频发与习惯不符的障碍。","产品体验小组在使用路径排查中，按真实使用路径逐点排查痛点，但上线后仍频发与习惯不符的障碍。","产品体验小组在服务流程梳理中，按真实使用路径逐点排查痛点，返工与投诉明显减少。","由供应商提供标准模板，后续也未按上述机制推进。"],"answer":2,"explanation":"「原型共创」的构成要件为：①主体为产品体验小组；②通过按真实使用路径逐点排查痛点；③使返工与投诉明显减少。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01788","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「网格代办」是指社区网格站通过联合多方现场会商后再定方案，使重复投诉明显下降的工作机制。\n\n根据上述定义，下列不属于「网格代办」的是：","options":["社区网格站在老旧小区改造中，联合多方现场会商后再定方案，重复投诉明显下降。","社区网格站在邻里纠纷调解中，联合多方现场会商后再定方案，重复投诉明显下降。","社区网格站在便民事项办理中，联合多方现场会商后再定方案，重复投诉明显下降。","社区网格站在邻里纠纷调解中，只在事后补录台账，最终问题仍反复出现且未形成稳定机制。"],"answer":3,"explanation":"「网格代办」的构成要件为：①主体为社区网格站；②通过联合多方现场会商后再定方案；③使重复投诉明显下降。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（只在事后补录台账），因此不符合构成要件。故选D。"},{"id":"pdn01789","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「可回溯核查」是指农产品质量检测站通过按批号串联台账与检验记录，使召回范围精确到具体批次的工作机制。\n\n依据上述定义，以下哪一项符合「可回溯核查」的构成要件：","options":["由消费者事后反馈倒查，后续也未按上述机制推进。","农产品质量检测站在储运环节温控中，按批号串联台账与检验记录，但出现问题时无法定位到具体环节。","农产品质量检测站在进货环节核验中，按批号串联台账与检验记录，召回范围精确到具体批次。","农产品质量检测站在批次交接记录中，仅保留汇总数不留明细，最终出现问题时无法定位到具体环节。"],"answer":2,"explanation":"「可回溯核查」的构成要件为：①主体为农产品质量检测站；②通过按批号串联台账与检验记录；③使召回范围精确到具体批次。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01790","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「小步试点」是指政策试点工作组通过设置观察期并保留回退通道，使后续推广更贴合一线实际的工作机制。\n\n按照上述界定，下列情形不应认定为「小步试点」的是：","options":["政策试点工作组在新流程上线中，设置观察期并保留回退通道，后续推广更贴合一线实际。","政策试点工作组在新工具推广中，不经试点直接全面强制推开，最终同类偏差在扩面后被成倍放大。","政策试点工作组在新机制落地中，设置观察期并保留回退通道，后续推广更贴合一线实际。","政策试点工作组在新工具推广中，设置观察期并保留回退通道，后续推广更贴合一线实际。"],"answer":1,"explanation":"「小步试点」的构成要件为：①主体为政策试点工作组；②通过设置观察期并保留回退通道；③使后续推广更贴合一线实际。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（不经试点直接全面强制推开），因此不符合构成要件。故选B。"},{"id":"pdn01791","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「最小必要采集」是指公共服务窗口通过对外提供前作去标识化处理，使历史数据不再无限期堆积的工作机制。\n\n根据上述定义，下列属于「最小必要采集」的是：","options":["由外包人员全量导出，后续也未按上述机制推进。","公共服务窗口在字段权限配置中，所有岗位开放同一份全量清单，最终与办理目的无关的字段仍被长期留存。","公共服务窗口在数据调阅留痕中，对外提供前作去标识化处理，但与办理目的无关的字段仍被长期留存。","公共服务窗口在信息采集登记中，对外提供前作去标识化处理，历史数据不再无限期堆积。"],"answer":3,"explanation":"「最小必要采集」的构成要件为：①主体为公共服务窗口；②通过对外提供前作去标识化处理；③使历史数据不再无限期堆积。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01792","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「留存限期」是指学校学籍管理系统通过按岗位授予最小可见范围，使共享环节不泄露可识别信息的工作机制。\n\n依据上述定义，以下哪一项不符合「留存限期」的构成要件：","options":["学校学籍管理系统在数据调阅留痕中，按岗位授予最小可见范围，共享环节不泄露可识别信息。","学校学籍管理系统在字段权限配置中，按岗位授予最小可见范围，共享环节不泄露可识别信息。","学校学籍管理系统在字段权限配置中，共享时直接提供原始明细，最终与办理目的无关的字段仍被长期留存。","学校学籍管理系统在信息采集登记中，按岗位授予最小可见范围，共享环节不泄露可识别信息。"],"answer":2,"explanation":"「留存限期」的构成要件为：①主体为学校学籍管理系统；②通过按岗位授予最小可见范围；③使共享环节不泄露可识别信息。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（共享时直接提供原始明细），因此不符合构成要件。故选C。"},{"id":"pdn01793","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「脆弱性评估」是指数据中心运维组通过设定触发条件并提前布防，使人员与物资提前就位的工作机制。\n\n按照上述界定，下列情形可认定为「脆弱性评估」的是：","options":["数据中心运维组在风险等级研判中，设定触发条件并提前布防，人员与物资提前就位。","数据中心运维组在响应动作预置中，只在事发后补充记录，最终异常发生时无预设动作可依。","由外部单位事后支援，后续也未按上述机制推进。","数据中心运维组在关键节点值守中，设定触发条件并提前布防，但异常发生时无预设动作可依。"],"answer":0,"explanation":"「脆弱性评估」的构成要件为：①主体为数据中心运维组；②通过设定触发条件并提前布防；③使人员与物资提前就位。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01794","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「按需配置」是指就业服务窗口通过按对象条件分档配置资源，使供给与实际需求更加贴合的工作机制。\n\n根据上述定义，下列不属于「按需配置」的是：","options":["就业服务窗口在服务清单编制中，按对象条件分档配置资源，供给与实际需求更加贴合。","就业服务窗口在服务事项梳理中，按对象条件分档配置资源，供给与实际需求更加贴合。","就业服务窗口在对象需求摸排中，所有对象发放完全相同的固定包，最终大量项目无人使用而真实诉求仍被搁置。","就业服务窗口在对象需求摸排中，按对象条件分档配置资源，供给与实际需求更加贴合。"],"answer":2,"explanation":"「按需配置」的构成要件为：①主体为就业服务窗口；②通过按对象条件分档配置资源；③使供给与实际需求更加贴合。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（所有对象发放完全相同的固定包），因此不符合构成要件。故选C。"},{"id":"pdn01795","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「随访管理」是指家庭医生团队通过与上级医院共享检查结果，使患者往返成本下降的工作机制。\n\n依据上述定义，以下哪一项符合「随访管理」的构成要件：","options":["家庭医生团队在康复跟踪记录中，只做一次性检查不作后续跟踪，最终各环节彼此脱节、患者仍需多次重复排队。","家庭医生团队在慢病随访安排中，与上级医院共享检查结果，患者往返成本下降。","仅由三甲医院单方建档，后续也未按上述机制推进。","家庭医生团队在重点人群筛查中，与上级医院共享检查结果，但各环节彼此脱节、患者仍需多次重复排队。"],"answer":1,"explanation":"「随访管理」的构成要件为：①主体为家庭医生团队；②通过与上级医院共享检查结果；③使患者往返成本下降。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01796","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「网格代办」是指街道办通过提前公示并逐户征询意见，使诉求在前端得到化解的工作机制。\n\n按照上述界定，下列情形不应认定为「网格代办」的是：","options":["街道办在邻里纠纷调解中，提前公示并逐户征询意见，诉求在前端得到化解。","街道办在老旧小区改造中，提前公示并逐户征询意见，诉求在前端得到化解。","街道办在便民事项办理中，提前公示并逐户征询意见，诉求在前端得到化解。","街道办在邻里纠纷调解中，只在事后补录台账，最终问题仍反复出现且未形成稳定机制。"],"answer":3,"explanation":"「网格代办」的构成要件为：①主体为街道办；②通过提前公示并逐户征询意见；③使诉求在前端得到化解。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（只在事后补录台账），因此不符合构成要件。故选D。"},{"id":"pdn01797","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「循证施策」是指项目评审委员会通过以多源数据交叉校验结论，使判断建立在可核验的依据上的工作机制。\n\n根据上述定义，下列属于「循证施策」的是：","options":["项目评审委员会在政策效果评估中，指标口径中途变更却不说明，最终结论无法由所引数据支撑。","由第三方直接给结论不附依据，后续也未按上述机制推进。","项目评审委员会在抽样数据核查中，以多源数据交叉校验结论，但结论无法由所引数据支撑。","项目评审委员会在年度计划编制中，以多源数据交叉校验结论，判断建立在可核验的依据上。"],"answer":3,"explanation":"「循证施策」的构成要件为：①主体为项目评审委员会；②通过以多源数据交叉校验结论；③使判断建立在可核验的依据上。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01798","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「用户旅程映射」是指公共服务设计组通过按真实使用路径逐点排查痛点，使改动获得使用者认同的工作机制。\n\n依据上述定义，以下哪一项不符合「用户旅程映射」的构成要件：","options":["公共服务设计组在服务流程梳理中，按真实使用路径逐点排查痛点，改动获得使用者认同。","公共服务设计组在使用路径排查中，按真实使用路径逐点排查痛点，改动获得使用者认同。","公共服务设计组在公共界面优化中，仅在完工后征求意见，最终上线后仍频发与习惯不符的障碍。","公共服务设计组在公共界面优化中，按真实使用路径逐点排查痛点，改动获得使用者认同。"],"answer":2,"explanation":"「用户旅程映射」的构成要件为：①主体为公共服务设计组；②通过按真实使用路径逐点排查痛点；③使改动获得使用者认同。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（仅在完工后征求意见），因此不符合构成要件。故选C。"},{"id":"pdn01799","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「小步试点」是指改革推进专班通过先在小范围试运行再按反馈调整，使偏差在放大前被修正的工作机制。\n\n按照上述界定，下列情形可认定为「小步试点」的是：","options":["改革推进专班在新工具推广中，试运行期间禁止任何修改，最终同类偏差在扩面后被成倍放大。","改革推进专班在新机制落地中，先在小范围试运行再按反馈调整，但同类偏差在扩面后被成倍放大。","由外部团队一次性交付即结束，后续也未按上述机制推进。","改革推进专班在新流程上线中，先在小范围试运行再按反馈调整，偏差在放大前被修正。"],"answer":3,"explanation":"「小步试点」的构成要件为：①主体为改革推进专班；②通过先在小范围试运行再按反馈调整；③使偏差在放大前被修正。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01800","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「表现性评价」是指任课教师团队通过结合真实任务表现打分，使学习过程而非仅结果被看见的工作机制。\n\n根据上述定义，下列不属于「表现性评价」的是：","options":["任课教师团队在作业反馈整理中，结合真实任务表现打分，学习过程而非仅结果被看见。","任课教师团队在实验课程组织中，照搬统一答案不看作答过程，最终教学安排并未因数据而作任何调整。","任课教师团队在实验课程组织中，结合真实任务表现打分，学习过程而非仅结果被看见。","任课教师团队在单元教学设计中，结合真实任务表现打分，学习过程而非仅结果被看见。"],"answer":1,"explanation":"「表现性评价」的构成要件为：①主体为任课教师团队；②通过结合真实任务表现打分；③使学习过程而非仅结果被看见。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（照搬统一答案不看作答过程），因此不符合构成要件。故选B。"},{"id":"pdn01801","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「闭环处置」是指社区网格站通过联合多方现场会商后再定方案，使诉求在前端得到化解的工作机制。\n\n依据上述定义，以下哪一项符合「闭环处置」的构成要件：","options":["社区网格站在老旧小区改造中，联合多方现场会商后再定方案，诉求在前端得到化解。","社区网格站在便民事项办理中，联合多方现场会商后再定方案，但问题仍反复出现且未形成稳定机制。","社区网格站在邻里纠纷调解中，各口径分头办理、彼此不通气，最终问题仍反复出现且未形成稳定机制。","由服务对象自行申报后不再跟进，后续也未按上述机制推进。"],"answer":0,"explanation":"「闭环处置」的构成要件为：①主体为社区网格站；②通过联合多方现场会商后再定方案；③使诉求在前端得到化解。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01802","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「双向转诊」是指家庭医生团队通过先由基层评估再决定是否上转，使病情变化能被尽早发现的工作机制。\n\n按照上述界定，下列情形不应认定为「双向转诊」的是：","options":["家庭医生团队在重点人群筛查中，先由基层评估再决定是否上转，病情变化能被尽早发现。","家庭医生团队在康复跟踪记录中，先由基层评估再决定是否上转，病情变化能被尽早发现。","家庭医生团队在康复跟踪记录中，一律先安排住院再评估，最终各环节彼此脱节、患者仍需多次重复排队。","家庭医生团队在慢病随访安排中，先由基层评估再决定是否上转，病情变化能被尽早发现。"],"answer":2,"explanation":"「双向转诊」的构成要件为：①主体为家庭医生团队；②通过先由基层评估再决定是否上转；③使病情变化能被尽早发现。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（一律先安排住院再评估），因此不符合构成要件。故选C。"},{"id":"pdn01803","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「试错迭代」是指数字化转型办公室通过设置观察期并保留回退通道，使后续推广更贴合一线实际的工作机制。\n\n根据上述定义，下列属于「试错迭代」的是：","options":["由外部团队一次性交付即结束，后续也未按上述机制推进。","数字化转型办公室在新流程上线中，设置观察期并保留回退通道，后续推广更贴合一线实际。","数字化转型办公室在新机制落地中，设置观察期并保留回退通道，但同类偏差在扩面后被成倍放大。","数字化转型办公室在新工具推广中，试运行期间禁止任何修改，最终同类偏差在扩面后被成倍放大。"],"answer":1,"explanation":"「试错迭代」的构成要件为：①主体为数字化转型办公室；②通过设置观察期并保留回退通道；③使后续推广更贴合一线实际。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01804","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「灰度验证」是指产品迭代小组通过每轮结束后复盘并修订下一轮，使后续推广更贴合一线实际的工作机制。\n\n依据上述定义，以下哪一项不符合「灰度验证」的构成要件：","options":["产品迭代小组在新工具推广中，每轮结束后复盘并修订下一轮，后续推广更贴合一线实际。","产品迭代小组在新机制落地中，每轮结束后复盘并修订下一轮，后续推广更贴合一线实际。","产品迭代小组在新工具推广中，只记录成功案例不分析偏差，最终同类偏差在扩面后被成倍放大。","产品迭代小组在新流程上线中，每轮结束后复盘并修订下一轮，后续推广更贴合一线实际。"],"answer":2,"explanation":"「灰度验证」的构成要件为：①主体为产品迭代小组；②通过每轮结束后复盘并修订下一轮；③使后续推广更贴合一线实际。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（只记录成功案例不分析偏差），因此不符合构成要件。故选C。"},{"id":"pdn01805","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「证据本位决策」是指规划编制组通过用对照组剔除同期其他影响，使成效与措施之间的对应更清楚的工作机制。\n\n按照上述界定，下列情形可认定为「证据本位决策」的是：","options":["由第三方直接给结论不附依据，后续也未按上述机制推进。","规划编制组在政策效果评估中，指标口径中途变更却不说明，最终结论无法由所引数据支撑。","规划编制组在年度计划编制中，用对照组剔除同期其他影响，成效与措施之间的对应更清楚。","规划编制组在抽样数据核查中，用对照组剔除同期其他影响，但结论无法由所引数据支撑。"],"answer":2,"explanation":"「证据本位决策」的构成要件为：①主体为规划编制组；②通过用对照组剔除同期其他影响；③使成效与措施之间的对应更清楚。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01806","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「网格代办」是指社区网格站通过提前公示并逐户征询意见，使诉求在前端得到化解的工作机制。\n\n根据上述定义，下列不属于「网格代办」的是：","options":["社区网格站在便民事项办理中，提前公示并逐户征询意见，诉求在前端得到化解。","社区网格站在老旧小区改造中，提前公示并逐户征询意见，诉求在前端得到化解。","社区网格站在邻里纠纷调解中，直接照搬既有方案、未作任何征询，最终问题仍反复出现且未形成稳定机制。","社区网格站在邻里纠纷调解中，提前公示并逐户征询意见，诉求在前端得到化解。"],"answer":2,"explanation":"「网格代办」的构成要件为：①主体为社区网格站；②通过提前公示并逐户征询意见；③使诉求在前端得到化解。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（直接照搬既有方案、未作任何征询），因此不符合构成要件。故选C。"},{"id":"pdn01807","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「联勤联动」是指街道与职能站所通过建立常态化联络与移交规则，使重复检查与推诿明显减少的工作机制。\n\n依据上述定义，以下哪一项符合「联勤联动」的构成要件：","options":["街道与职能站所在跨界事项梳理中，建立常态化联络与移交规则，重复检查与推诿明显减少。","街道与职能站所在信息通报共享中，建立常态化联络与移交规则，但边界地带的问题仍在部门之间来回流转。","街道与职能站所在联合排班安排中，只开会不落责任清单，最终边界地带的问题仍在部门之间来回流转。","由各区各自为政，后续也未按上述机制推进。"],"answer":0,"explanation":"「联勤联动」的构成要件为：①主体为街道与职能站所；②通过建立常态化联络与移交规则；③使重复检查与推诿明显减少。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01808","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「表现性评价」是指学校教研组通过随堂记录并及时反馈调整，使教学策略得以动态优化的工作机制。\n\n按照上述界定，下列情形不应认定为「表现性评价」的是：","options":["学校教研组在实验课程组织中，照搬统一答案不看作答过程，最终教学安排并未因数据而作任何调整。","学校教研组在作业反馈整理中，随堂记录并及时反馈调整，教学策略得以动态优化。","学校教研组在实验课程组织中，随堂记录并及时反馈调整，教学策略得以动态优化。","学校教研组在单元教学设计中，随堂记录并及时反馈调整，教学策略得以动态优化。"],"answer":0,"explanation":"「表现性评价」的构成要件为：①主体为学校教研组；②通过随堂记录并及时反馈调整；③使教学策略得以动态优化。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（照搬统一答案不看作答过程），因此不符合构成要件。故选A。"},{"id":"pdn01809","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「按需配置」是指养老服务站点通过按对象条件分档配置资源，使不同群体各取所需的工作机制。\n\n根据上述定义，下列属于「按需配置」的是：","options":["养老服务站点在服务事项梳理中，按对象条件分档配置资源，不同群体各取所需。","养老服务站点在对象需求摸排中，沿用上一年清单不作修订，最终大量项目无人使用而真实诉求仍被搁置。","养老服务站点在服务清单编制中，按对象条件分档配置资源，但大量项目无人使用而真实诉求仍被搁置。","由服务对象自行寻找渠道，后续也未按上述机制推进。"],"answer":0,"explanation":"「按需配置」的构成要件为：①主体为养老服务站点；②通过按对象条件分档配置资源；③使不同群体各取所需。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01810","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「差异化供给」是指农技推广站通过按对象条件分档配置资源，使资源不再平均摊薄的工作机制。\n\n依据上述定义，以下哪一项不符合「差异化供给」的构成要件：","options":["农技推广站在服务事项梳理中，按对象条件分档配置资源，资源不再平均摊薄。","农技推广站在服务清单编制中，按对象条件分档配置资源，资源不再平均摊薄。","农技推广站在对象需求摸排中，所有对象发放完全相同的固定包，最终大量项目无人使用而真实诉求仍被搁置。","农技推广站在对象需求摸排中，按对象条件分档配置资源，资源不再平均摊薄。"],"answer":2,"explanation":"「差异化供给」的构成要件为：①主体为农技推广站；②通过按对象条件分档配置资源；③使资源不再平均摊薄。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（所有对象发放完全相同的固定包），因此不符合构成要件。故选C。"},{"id":"pdn01811","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「留痕管理」是指冷链运营方通过按批号串联台账与检验记录，使召回范围精确到具体批次的工作机制。\n\n按照上述界定，下列情形可认定为「留痕管理」的是：","options":["冷链运营方在储运环节温控中，按批号串联台账与检验记录，但出现问题时无法定位到具体环节。","冷链运营方在进货环节核验中，按批号串联台账与检验记录，召回范围精确到具体批次。","由终端门店自行补记，后续也未按上述机制推进。","冷链运营方在批次交接记录中，各环节各自记录且互不关联，最终出现问题时无法定位到具体环节。"],"answer":1,"explanation":"「留痕管理」的构成要件为：①主体为冷链运营方；②通过按批号串联台账与检验记录；③使召回范围精确到具体批次。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01812","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「增值评价」是指区域教研中心通过结合真实任务表现打分，使后续目标更贴合实际起点的工作机制。\n\n根据上述定义，下列不属于「增值评价」的是：","options":["区域教研中心在作业反馈整理中，结合真实任务表现打分，后续目标更贴合实际起点。","区域教研中心在实验课程组织中，结合真实任务表现打分，后续目标更贴合实际起点。","区域教研中心在实验课程组织中，照搬统一答案不看作答过程，最终教学安排并未因数据而作任何调整。","区域教研中心在单元教学设计中，结合真实任务表现打分，后续目标更贴合实际起点。"],"answer":2,"explanation":"「增值评价」的构成要件为：①主体为区域教研中心；②通过结合真实任务表现打分；③使后续目标更贴合实际起点。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（照搬统一答案不看作答过程），因此不符合构成要件。故选C。"},{"id":"pdn01813","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「分级预警」是指水利工程调度处通过设定触发条件并提前布防，使人员与物资提前就位的工作机制。\n\n依据上述定义，以下哪一项符合「分级预警」的构成要件：","options":["由外部单位事后支援，后续也未按上述机制推进。","水利工程调度处在风险等级研判中，设定触发条件并提前布防，人员与物资提前就位。","水利工程调度处在响应动作预置中，只在事发后补充记录，最终异常发生时无预设动作可依。","水利工程调度处在关键节点值守中，设定触发条件并提前布防，但异常发生时无预设动作可依。"],"answer":1,"explanation":"「分级预警」的构成要件为：①主体为水利工程调度处；②通过设定触发条件并提前布防；③使人员与物资提前就位。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01814","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「参与式设计」是指社区营造团队通过邀请使用者全程参与方案打磨，使方案贴合真实使用习惯的工作机制。\n\n按照上述界定，下列情形不应认定为「参与式设计」的是：","options":["社区营造团队在公共界面优化中，邀请使用者全程参与方案打磨，方案贴合真实使用习惯。","社区营造团队在服务流程梳理中，邀请使用者全程参与方案打磨，方案贴合真实使用习惯。","社区营造团队在使用路径排查中，邀请使用者全程参与方案打磨，方案贴合真实使用习惯。","社区营造团队在公共界面优化中，仅在完工后征求意见，最终上线后仍频发与习惯不符的障碍。"],"answer":3,"explanation":"「参与式设计」的构成要件为：①主体为社区营造团队；②通过邀请使用者全程参与方案打磨；③使方案贴合真实使用习惯。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（仅在完工后征求意见），因此不符合构成要件。故选D。"},{"id":"pdn01815","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「链条式核验」是指食品药品监管所通过按批号串联台账与检验记录，使问题批次能被快速定位的工作机制。\n\n根据上述定义，下列属于「链条式核验」的是：","options":["食品药品监管所在批次交接记录中，各环节各自记录且互不关联，最终出现问题时无法定位到具体环节。","食品药品监管所在储运环节温控中，按批号串联台账与检验记录，但出现问题时无法定位到具体环节。","由终端门店自行补记，后续也未按上述机制推进。","食品药品监管所在进货环节核验中，按批号串联台账与检验记录，问题批次能被快速定位。"],"answer":3,"explanation":"「链条式核验」的构成要件为：①主体为食品药品监管所；②通过按批号串联台账与检验记录；③使问题批次能被快速定位。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01816","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「参与式设计」是指无障碍改造专班通过按真实使用路径逐点排查痛点，使方案贴合真实使用习惯的工作机制。\n\n依据上述定义，以下哪一项不符合「参与式设计」的构成要件：","options":["无障碍改造专班在服务流程梳理中，按真实使用路径逐点排查痛点，方案贴合真实使用习惯。","无障碍改造专班在公共界面优化中，按真实使用路径逐点排查痛点，方案贴合真实使用习惯。","无障碍改造专班在公共界面优化中，照搬其他地区成品，最终上线后仍频发与习惯不符的障碍。","无障碍改造专班在使用路径排查中，按真实使用路径逐点排查痛点，方案贴合真实使用习惯。"],"answer":2,"explanation":"「参与式设计」的构成要件为：①主体为无障碍改造专班；②通过按真实使用路径逐点排查痛点；③使方案贴合真实使用习惯。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（照搬其他地区成品），因此不符合构成要件。故选C。"},{"id":"pdn01817","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「分级办理」是指街道办通过提前公示并逐户征询意见，使平均处置周期缩短的工作机制。\n\n按照上述界定，下列情形可认定为「分级办理」的是：","options":["街道办在老旧小区改造中，提前公示并逐户征询意见，平均处置周期缩短。","街道办在邻里纠纷调解中，各口径分头办理、彼此不通气，最终问题仍反复出现且未形成稳定机制。","街道办在便民事项办理中，提前公示并逐户征询意见，但问题仍反复出现且未形成稳定机制。","由服务对象自行申报后不再跟进，后续也未按上述机制推进。"],"answer":0,"explanation":"「分级办理」的构成要件为：①主体为街道办；②通过提前公示并逐户征询意见；③使平均处置周期缩短。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01818","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「增值评价」是指任课教师团队通过随堂记录并及时反馈调整，使学生的薄弱点被及时识别的工作机制。\n\n根据上述定义，下列不属于「增值评价」的是：","options":["任课教师团队在作业反馈整理中，随堂记录并及时反馈调整，学生的薄弱点被及时识别。","任课教师团队在实验课程组织中，随堂记录并及时反馈调整，学生的薄弱点被及时识别。","任课教师团队在实验课程组织中，只以期末一次分数定结论，最终教学安排并未因数据而作任何调整。","任课教师团队在单元教学设计中，随堂记录并及时反馈调整，学生的薄弱点被及时识别。"],"answer":2,"explanation":"「增值评价」的构成要件为：①主体为任课教师团队；②通过随堂记录并及时反馈调整；③使学生的薄弱点被及时识别。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（只以期末一次分数定结论），因此不符合构成要件。故选C。"},{"id":"pdn01819","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「随访管理」是指社区卫生服务中心通过与上级医院共享检查结果，使病情变化能被尽早发现的工作机制。\n\n依据上述定义，以下哪一项符合「随访管理」的构成要件：","options":["社区卫生服务中心在慢病随访安排中，与上级医院共享检查结果，病情变化能被尽早发现。","社区卫生服务中心在重点人群筛查中，与上级医院共享检查结果，但各环节彼此脱节、患者仍需多次重复排队。","仅由三甲医院单方建档，后续也未按上述机制推进。","社区卫生服务中心在康复跟踪记录中，只做一次性检查不作后续跟踪，最终各环节彼此脱节、患者仍需多次重复排队。"],"answer":0,"explanation":"「随访管理」的构成要件为：①主体为社区卫生服务中心；②通过与上级医院共享检查结果；③使病情变化能被尽早发现。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01820","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「联勤联动」是指区级牵头部门通过明确牵头与配合边界后统一行动，使处置效率整体提升的工作机制。\n\n按照上述界定，下列情形不应认定为「联勤联动」的是：","options":["区级牵头部门在联合排班安排中，遇跨界事项互相等待，最终边界地带的问题仍在部门之间来回流转。","区级牵头部门在信息通报共享中，明确牵头与配合边界后统一行动，处置效率整体提升。","区级牵头部门在联合排班安排中，明确牵头与配合边界后统一行动，处置效率整体提升。","区级牵头部门在跨界事项梳理中，明确牵头与配合边界后统一行动，处置效率整体提升。"],"answer":0,"explanation":"「联勤联动」的构成要件为：①主体为区级牵头部门；②通过明确牵头与配合边界后统一行动；③使处置效率整体提升。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（遇跨界事项互相等待），因此不符合构成要件。故选A。"},{"id":"pdn01821","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「可回溯核查」是指冷链运营方通过每一节点登记并关联上下游凭证，使台账与实物始终一致的工作机制。\n\n根据上述定义，下列属于「可回溯核查」的是：","options":["冷链运营方在进货环节核验中，每一节点登记并关联上下游凭证，台账与实物始终一致。","冷链运营方在储运环节温控中，每一节点登记并关联上下游凭证，但出现问题时无法定位到具体环节。","冷链运营方在批次交接记录中，仅保留汇总数不留明细，最终出现问题时无法定位到具体环节。","由消费者事后反馈倒查，后续也未按上述机制推进。"],"answer":0,"explanation":"「可回溯核查」的构成要件为：①主体为冷链运营方；②通过每一节点登记并关联上下游凭证；③使台账与实物始终一致。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01822","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「留存限期」是指学校学籍管理系统通过按岗位授予最小可见范围，使超范围信息不被额外索取的工作机制。\n\n依据上述定义，以下哪一项不符合「留存限期」的构成要件：","options":["学校学籍管理系统在信息采集登记中，按岗位授予最小可见范围，超范围信息不被额外索取。","学校学籍管理系统在数据调阅留痕中，按岗位授予最小可见范围，超范围信息不被额外索取。","学校学籍管理系统在字段权限配置中，按岗位授予最小可见范围，超范围信息不被额外索取。","学校学籍管理系统在字段权限配置中，为方便起见一次性收齐全部字段，最终与办理目的无关的字段仍被长期留存。"],"answer":3,"explanation":"「留存限期」的构成要件为：①主体为学校学籍管理系统；②通过按岗位授予最小可见范围；③使超范围信息不被额外索取。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（为方便起见一次性收齐全部字段），因此不符合构成要件。故选D。"},{"id":"pdn01823","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「分区管控」是指湿地管护中心通过划分区块实行差异化管护，使干预强度与实际风险相匹配的工作机制。\n\n按照上述界定，下列情形可认定为「分区管控」的是：","options":["湿地管护中心在栖息环境变化中，指标超标后仍不调整，最终指标已越界而措施仍维持不变。","湿地管护中心在监测指标波动中，划分区块实行差异化管护，干预强度与实际风险相匹配。","由邻近地区照抄方案，后续也未按上述机制推进。","湿地管护中心在外来因素扩散中，划分区块实行差异化管护，但指标已越界而措施仍维持不变。"],"answer":1,"explanation":"「分区管控」的构成要件为：①主体为湿地管护中心；②通过划分区块实行差异化管护；③使干预强度与实际风险相匹配。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01824","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「协同治理」是指跨部门工作专班通过一次会商形成分工清单，使响应口径保持一致的工作机制。\n\n根据上述定义，下列不属于「协同治理」的是：","options":["跨部门工作专班在信息通报共享中，一次会商形成分工清单，响应口径保持一致。","跨部门工作专班在跨界事项梳理中，一次会商形成分工清单，响应口径保持一致。","跨部门工作专班在联合排班安排中，遇跨界事项互相等待，最终边界地带的问题仍在部门之间来回流转。","跨部门工作专班在联合排班安排中，一次会商形成分工清单，响应口径保持一致。"],"answer":2,"explanation":"「协同治理」的构成要件为：①主体为跨部门工作专班；②通过一次会商形成分工清单；③使响应口径保持一致。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（遇跨界事项互相等待），因此不符合构成要件。故选C。"},{"id":"pdn01825","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「参与式设计」是指公共服务设计组通过邀请使用者全程参与方案打磨，使改动获得使用者认同的工作机制。\n\n依据上述定义，以下哪一项符合「参与式设计」的构成要件：","options":["公共服务设计组在公共界面优化中，一次性定稿不再接收反馈，最终上线后仍频发与习惯不符的障碍。","公共服务设计组在使用路径排查中，邀请使用者全程参与方案打磨，但上线后仍频发与习惯不符的障碍。","由外部专家远程定稿，后续也未按上述机制推进。","公共服务设计组在服务流程梳理中，邀请使用者全程参与方案打磨，改动获得使用者认同。"],"answer":3,"explanation":"「参与式设计」的构成要件为：①主体为公共服务设计组；②通过邀请使用者全程参与方案打磨；③使改动获得使用者认同。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01826","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「证据本位决策」是指规划编制组通过以多源数据交叉校验结论，使判断建立在可核验的依据上的工作机制。\n\n按照上述界定，下列情形不应认定为「证据本位决策」的是：","options":["规划编制组在政策效果评估中，以多源数据交叉校验结论，判断建立在可核验的依据上。","规划编制组在年度计划编制中，以多源数据交叉校验结论，判断建立在可核验的依据上。","规划编制组在政策效果评估中，只选取有利样本作展示，最终结论无法由所引数据支撑。","规划编制组在抽样数据核查中，以多源数据交叉校验结论，判断建立在可核验的依据上。"],"answer":2,"explanation":"「证据本位决策」的构成要件为：①主体为规划编制组；②通过以多源数据交叉校验结论；③使判断建立在可核验的依据上。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（只选取有利样本作展示），因此不符合构成要件。故选C。"},{"id":"pdn01827","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「分区管控」是指湿地管护中心通过划分区块实行差异化管护，使异常苗头被尽早识别的工作机制。\n\n根据上述定义，下列属于「分区管控」的是：","options":["湿地管护中心在外来因素扩散中，划分区块实行差异化管护，但指标已越界而措施仍维持不变。","由邻近地区照抄方案，后续也未按上述机制推进。","湿地管护中心在栖息环境变化中，指标超标后仍不调整，最终指标已越界而措施仍维持不变。","湿地管护中心在监测指标波动中，划分区块实行差异化管护，异常苗头被尽早识别。"],"answer":3,"explanation":"「分区管控」的构成要件为：①主体为湿地管护中心；②通过划分区块实行差异化管护；③使异常苗头被尽早识别。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01828","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「协同会商」是指乡镇便民中心通过依托网格员常态化走访摸排，使重复投诉明显下降的工作机制。\n\n依据上述定义，以下哪一项不符合「协同会商」的构成要件：","options":["乡镇便民中心在便民事项办理中，依托网格员常态化走访摸排，重复投诉明显下降。","乡镇便民中心在老旧小区改造中，依托网格员常态化走访摸排，重复投诉明显下降。","乡镇便民中心在邻里纠纷调解中，只在事后补录台账，最终问题仍反复出现且未形成稳定机制。","乡镇便民中心在邻里纠纷调解中，依托网格员常态化走访摸排，重复投诉明显下降。"],"answer":2,"explanation":"「协同会商」的构成要件为：①主体为乡镇便民中心；②通过依托网格员常态化走访摸排；③使重复投诉明显下降。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（只在事后补录台账），因此不符合构成要件。故选C。"},{"id":"pdn01829","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「菜单式服务」是指养老服务站点通过按可选项自主组合形成服务清单，使供给与实际需求更加贴合的工作机制。\n\n按照上述界定，下列情形可认定为「菜单式服务」的是：","options":["养老服务站点在服务清单编制中，按可选项自主组合形成服务清单，但大量项目无人使用而真实诉求仍被搁置。","养老服务站点在对象需求摸排中，沿用上一年清单不作修订，最终大量项目无人使用而真实诉求仍被搁置。","由服务对象自行寻找渠道，后续也未按上述机制推进。","养老服务站点在服务事项梳理中，按可选项自主组合形成服务清单，供给与实际需求更加贴合。"],"answer":3,"explanation":"「菜单式服务」的构成要件为：①主体为养老服务站点；②通过按可选项自主组合形成服务清单；③使供给与实际需求更加贴合。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01830","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「诊断性测评」是指学校教研组通过结合真实任务表现打分，使学习过程而非仅结果被看见的工作机制。\n\n根据上述定义，下列不属于「诊断性测评」的是：","options":["学校教研组在单元教学设计中，结合真实任务表现打分，学习过程而非仅结果被看见。","学校教研组在实验课程组织中，只以期末一次分数定结论，最终教学安排并未因数据而作任何调整。","学校教研组在实验课程组织中，结合真实任务表现打分，学习过程而非仅结果被看见。","学校教研组在作业反馈整理中，结合真实任务表现打分，学习过程而非仅结果被看见。"],"answer":1,"explanation":"「诊断性测评」的构成要件为：①主体为学校教研组；②通过结合真实任务表现打分；③使学习过程而非仅结果被看见。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（只以期末一次分数定结论），因此不符合构成要件。故选B。"},{"id":"pdn01831","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「共创工作坊」是指产品体验小组通过先做可体验原型再收集反馈，使返工与投诉明显减少的工作机制。\n\n依据上述定义，以下哪一项符合「共创工作坊」的构成要件：","options":["由供应商提供标准模板，后续也未按上述机制推进。","产品体验小组在公共界面优化中，只做内部评审不接触使用者，最终上线后仍频发与习惯不符的障碍。","产品体验小组在服务流程梳理中，先做可体验原型再收集反馈，返工与投诉明显减少。","产品体验小组在使用路径排查中，先做可体验原型再收集反馈，但上线后仍频发与习惯不符的障碍。"],"answer":2,"explanation":"「共创工作坊」的构成要件为：①主体为产品体验小组；②通过先做可体验原型再收集反馈；③使返工与投诉明显减少。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01832","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「连续照护」是指乡镇卫生院通过先由基层评估再决定是否上转，使病情变化能被尽早发现的工作机制。\n\n按照上述界定，下列情形不应认定为「连续照护」的是：","options":["乡镇卫生院在康复跟踪记录中，先由基层评估再决定是否上转，病情变化能被尽早发现。","乡镇卫生院在康复跟踪记录中，各机构各自重复开单，最终各环节彼此脱节、患者仍需多次重复排队。","乡镇卫生院在慢病随访安排中，先由基层评估再决定是否上转，病情变化能被尽早发现。","乡镇卫生院在重点人群筛查中，先由基层评估再决定是否上转，病情变化能被尽早发现。"],"answer":1,"explanation":"「连续照护」的构成要件为：①主体为乡镇卫生院；②通过先由基层评估再决定是否上转；③使病情变化能被尽早发现。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（各机构各自重复开单），因此不符合构成要件。故选B。"},{"id":"pdn01833","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「诊断性测评」是指任课教师团队通过结合真实任务表现打分，使学习过程而非仅结果被看见的工作机制。\n\n根据上述定义，下列属于「诊断性测评」的是：","options":["任课教师团队在单元教学设计中，结合真实任务表现打分，学习过程而非仅结果被看见。","任课教师团队在作业反馈整理中，结合真实任务表现打分，但教学安排并未因数据而作任何调整。","由学生互评后不再复核，后续也未按上述机制推进。","任课教师团队在实验课程组织中，按固定名次划线且不追溯变化，最终教学安排并未因数据而作任何调整。"],"answer":0,"explanation":"「诊断性测评」的构成要件为：①主体为任课教师团队；②通过结合真实任务表现打分；③使学习过程而非仅结果被看见。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01834","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「分级授权」是指政务数据平台通过只采集完成本事项所必需的字段，使敏感字段仅在授权场景可见的工作机制。\n\n依据上述定义，以下哪一项不符合「分级授权」的构成要件：","options":["政务数据平台在字段权限配置中，为方便起见一次性收齐全部字段，最终与办理目的无关的字段仍被长期留存。","政务数据平台在信息采集登记中，只采集完成本事项所必需的字段，敏感字段仅在授权场景可见。","政务数据平台在数据调阅留痕中，只采集完成本事项所必需的字段，敏感字段仅在授权场景可见。","政务数据平台在字段权限配置中，只采集完成本事项所必需的字段，敏感字段仅在授权场景可见。"],"answer":0,"explanation":"「分级授权」的构成要件为：①主体为政务数据平台；②通过只采集完成本事项所必需的字段；③使敏感字段仅在授权场景可见。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（为方便起见一次性收齐全部字段），因此不符合构成要件。故选A。"},{"id":"pdn01835","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「协同会商」是指社区网格站通过提前公示并逐户征询意见，使居民满意度稳步提升的工作机制。\n\n按照上述界定，下列情形可认定为「协同会商」的是：","options":["由临时志愿队自行接管，后续也未按上述机制推进。","社区网格站在老旧小区改造中，提前公示并逐户征询意见，居民满意度稳步提升。","社区网格站在邻里纠纷调解中，等群众上门反映后再统一研究，最终问题仍反复出现且未形成稳定机制。","社区网格站在便民事项办理中，提前公示并逐户征询意见，但问题仍反复出现且未形成稳定机制。"],"answer":1,"explanation":"「协同会商」的构成要件为：①主体为社区网格站；②通过提前公示并逐户征询意见；③使居民满意度稳步提升。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01836","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「弹性调控」是指生态环境监测站通过按监测指标分档调整措施，使异常苗头被尽早识别的工作机制。\n\n根据上述定义，下列不属于「弹性调控」的是：","options":["生态环境监测站在栖息环境变化中，只看年度均值忽略峰值，最终指标已越界而措施仍维持不变。","生态环境监测站在监测指标波动中，按监测指标分档调整措施，异常苗头被尽早识别。","生态环境监测站在栖息环境变化中，按监测指标分档调整措施，异常苗头被尽早识别。","生态环境监测站在外来因素扩散中，按监测指标分档调整措施，异常苗头被尽早识别。"],"answer":0,"explanation":"「弹性调控」的构成要件为：①主体为生态环境监测站；②通过按监测指标分档调整措施；③使异常苗头被尽早识别。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（只看年度均值忽略峰值），因此不符合构成要件。故选A。"},{"id":"pdn01837","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「冗余备份」是指应急指挥中心通过关键节点保留备用通道，使核心功能在异常下仍可维持的工作机制。\n\n依据上述定义，以下哪一项符合「冗余备份」的构成要件：","options":["应急指挥中心在风险等级研判中，关键节点保留备用通道，核心功能在异常下仍可维持。","由外部单位事后支援，后续也未按上述机制推进。","应急指挥中心在关键节点值守中，关键节点保留备用通道，但异常发生时无预设动作可依。","应急指挥中心在响应动作预置中，只在事发后补充记录，最终异常发生时无预设动作可依。"],"answer":0,"explanation":"「冗余备份」的构成要件为：①主体为应急指挥中心；②通过关键节点保留备用通道；③使核心功能在异常下仍可维持。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01838","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「分级授权」是指公共服务窗口通过到期自动清理并留清理记录，使超范围信息不被额外索取的工作机制。\n\n按照上述界定，下列情形不应认定为「分级授权」的是：","options":["公共服务窗口在信息采集登记中，到期自动清理并留清理记录，超范围信息不被额外索取。","公共服务窗口在字段权限配置中，到期自动清理并留清理记录，超范围信息不被额外索取。","公共服务窗口在字段权限配置中，为方便起见一次性收齐全部字段，最终与办理目的无关的字段仍被长期留存。","公共服务窗口在数据调阅留痕中，到期自动清理并留清理记录，超范围信息不被额外索取。"],"answer":2,"explanation":"「分级授权」的构成要件为：①主体为公共服务窗口；②通过到期自动清理并留清理记录；③使超范围信息不被额外索取。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（为方便起见一次性收齐全部字段），因此不符合构成要件。故选C。"},{"id":"pdn01839","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「共创工作坊」是指产品体验小组通过先做可体验原型再收集反馈，使方案贴合真实使用习惯的工作机制。\n\n根据上述定义，下列属于「共创工作坊」的是：","options":["产品体验小组在公共界面优化中，只做内部评审不接触使用者，最终上线后仍频发与习惯不符的障碍。","产品体验小组在服务流程梳理中，先做可体验原型再收集反馈，方案贴合真实使用习惯。","由供应商提供标准模板，后续也未按上述机制推进。","产品体验小组在使用路径排查中，先做可体验原型再收集反馈，但上线后仍频发与习惯不符的障碍。"],"answer":1,"explanation":"「共创工作坊」的构成要件为：①主体为产品体验小组；②通过先做可体验原型再收集反馈；③使方案贴合真实使用习惯。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01840","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「协同治理」是指街道与职能站所通过建立常态化联络与移交规则，使跨界问题不再悬空的工作机制。\n\n依据上述定义，以下哪一项不符合「协同治理」的构成要件：","options":["街道与职能站所在联合排班安排中，遇跨界事项互相等待，最终边界地带的问题仍在部门之间来回流转。","街道与职能站所在跨界事项梳理中，建立常态化联络与移交规则，跨界问题不再悬空。","街道与职能站所在联合排班安排中，建立常态化联络与移交规则，跨界问题不再悬空。","街道与职能站所在信息通报共享中，建立常态化联络与移交规则，跨界问题不再悬空。"],"answer":0,"explanation":"「协同治理」的构成要件为：①主体为街道与职能站所；②通过建立常态化联络与移交规则；③使跨界问题不再悬空。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（遇跨界事项互相等待），因此不符合构成要件。故选A。"},{"id":"pdn01841","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「小步试点」是指数字化转型办公室通过先在小范围试运行再按反馈调整，使后续推广更贴合一线实际的工作机制。\n\n按照上述界定，下列情形可认定为「小步试点」的是：","options":["数字化转型办公室在新流程上线中，先在小范围试运行再按反馈调整，后续推广更贴合一线实际。","数字化转型办公室在新机制落地中，先在小范围试运行再按反馈调整，但同类偏差在扩面后被成倍放大。","由用户自行摸索不作收集，后续也未按上述机制推进。","数字化转型办公室在新工具推广中，一次上线后即固化不再迭代，最终同类偏差在扩面后被成倍放大。"],"answer":0,"explanation":"「小步试点」的构成要件为：①主体为数字化转型办公室；②通过先在小范围试运行再按反馈调整；③使后续推广更贴合一线实际。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01842","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「多元共治」是指流域联席会议通过一次会商形成分工清单，使重复检查与推诿明显减少的工作机制。\n\n根据上述定义，下列不属于「多元共治」的是：","options":["流域联席会议在跨界事项梳理中，一次会商形成分工清单，重复检查与推诿明显减少。","流域联席会议在联合排班安排中，一次会商形成分工清单，重复检查与推诿明显减少。","流域联席会议在信息通报共享中，一次会商形成分工清单，重复检查与推诿明显减少。","流域联席会议在联合排班安排中，各部门分头进场、结果互不通报，最终边界地带的问题仍在部门之间来回流转。"],"answer":3,"explanation":"「多元共治」的构成要件为：①主体为流域联席会议；②通过一次会商形成分工清单；③使重复检查与推诿明显减少。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（各部门分头进场、结果互不通报），因此不符合构成要件。故选D。"},{"id":"pdn01843","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「脱敏处理」是指公共服务窗口通过按岗位授予最小可见范围，使敏感字段仅在授权场景可见的工作机制。\n\n依据上述定义，以下哪一项符合「脱敏处理」的构成要件：","options":["公共服务窗口在信息采集登记中，按岗位授予最小可见范围，敏感字段仅在授权场景可见。","公共服务窗口在数据调阅留痕中，按岗位授予最小可见范围，但与办理目的无关的字段仍被长期留存。","由外包人员全量导出，后续也未按上述机制推进。","公共服务窗口在字段权限配置中，所有岗位开放同一份全量清单，最终与办理目的无关的字段仍被长期留存。"],"answer":0,"explanation":"「脱敏处理」的构成要件为：①主体为公共服务窗口；②通过按岗位授予最小可见范围；③使敏感字段仅在授权场景可见。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01844","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「循证施策」是指项目评审委员会通过对关键指标作独立复核，使判断建立在可核验的依据上的工作机制。\n\n按照上述界定，下列情形不应认定为「循证施策」的是：","options":["项目评审委员会在年度计划编制中，对关键指标作独立复核，判断建立在可核验的依据上。","项目评审委员会在政策效果评估中，对关键指标作独立复核，判断建立在可核验的依据上。","项目评审委员会在抽样数据核查中，对关键指标作独立复核，判断建立在可核验的依据上。","项目评审委员会在政策效果评估中，以主观感受替代实测数据，最终结论无法由所引数据支撑。"],"answer":3,"explanation":"「循证施策」的构成要件为：①主体为项目评审委员会；②通过对关键指标作独立复核；③使判断建立在可核验的依据上。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（以主观感受替代实测数据），因此不符合构成要件。故选D。"},{"id":"pdn01845","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「脱敏处理」是指学校学籍管理系统通过只采集完成本事项所必需的字段，使超范围信息不被额外索取的工作机制。\n\n根据上述定义，下列属于「脱敏处理」的是：","options":["学校学籍管理系统在字段权限配置中，超过期限仍不作清理，最终与办理目的无关的字段仍被长期留存。","由系统默认长期全量保留，后续也未按上述机制推进。","学校学籍管理系统在数据调阅留痕中，只采集完成本事项所必需的字段，但与办理目的无关的字段仍被长期留存。","学校学籍管理系统在信息采集登记中，只采集完成本事项所必需的字段，超范围信息不被额外索取。"],"answer":3,"explanation":"「脱敏处理」的构成要件为：①主体为学校学籍管理系统；②通过只采集完成本事项所必需的字段；③使超范围信息不被额外索取。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01846","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「分级预警」是指城市运行管理平台通过设定触发条件并提前布防，使次生影响被压到最小的工作机制。\n\n依据上述定义，以下哪一项不符合「分级预警」的构成要件：","options":["城市运行管理平台在响应动作预置中，等指标越限后才临时研究方案，最终异常发生时无预设动作可依。","城市运行管理平台在响应动作预置中，设定触发条件并提前布防，次生影响被压到最小。","城市运行管理平台在风险等级研判中，设定触发条件并提前布防，次生影响被压到最小。","城市运行管理平台在关键节点值守中，设定触发条件并提前布防，次生影响被压到最小。"],"answer":0,"explanation":"「分级预警」的构成要件为：①主体为城市运行管理平台；②通过设定触发条件并提前布防；③使次生影响被压到最小。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（等指标越限后才临时研究方案），因此不符合构成要件。故选A。"},{"id":"pdn01847","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「参与式设计」是指社区营造团队通过多轮共创后收敛为最终版本，使返工与投诉明显减少的工作机制。\n\n按照上述界定，下列情形可认定为「参与式设计」的是：","options":["社区营造团队在服务流程梳理中，多轮共创后收敛为最终版本，返工与投诉明显减少。","社区营造团队在公共界面优化中，只做内部评审不接触使用者，最终上线后仍频发与习惯不符的障碍。","社区营造团队在使用路径排查中，多轮共创后收敛为最终版本，但上线后仍频发与习惯不符的障碍。","由供应商提供标准模板，后续也未按上述机制推进。"],"answer":0,"explanation":"「参与式设计」的构成要件为：①主体为社区营造团队；②通过多轮共创后收敛为最终版本；③使返工与投诉明显减少。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01848","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「目的限定」是指公共服务窗口通过按岗位授予最小可见范围，使敏感字段仅在授权场景可见的工作机制。\n\n根据上述定义，下列不属于「目的限定」的是：","options":["公共服务窗口在字段权限配置中，按岗位授予最小可见范围，敏感字段仅在授权场景可见。","公共服务窗口在信息采集登记中，按岗位授予最小可见范围，敏感字段仅在授权场景可见。","公共服务窗口在字段权限配置中，共享时直接提供原始明细，最终与办理目的无关的字段仍被长期留存。","公共服务窗口在数据调阅留痕中，按岗位授予最小可见范围，敏感字段仅在授权场景可见。"],"answer":2,"explanation":"「目的限定」的构成要件为：①主体为公共服务窗口；②通过按岗位授予最小可见范围；③使敏感字段仅在授权场景可见。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（共享时直接提供原始明细），因此不符合构成要件。故选C。"},{"id":"pdn01849","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「连续照护」是指社区卫生服务中心通过先由基层评估再决定是否上转，使病情变化能被尽早发现的工作机制。\n\n依据上述定义，以下哪一项符合「连续照护」的构成要件：","options":["由商业体检机构独立出具结论，后续也未按上述机制推进。","社区卫生服务中心在慢病随访安排中，先由基层评估再决定是否上转，病情变化能被尽早发现。","社区卫生服务中心在康复跟踪记录中，待病情加重后再启动会诊，最终各环节彼此脱节、患者仍需多次重复排队。","社区卫生服务中心在重点人群筛查中，先由基层评估再决定是否上转，但各环节彼此脱节、患者仍需多次重复排队。"],"answer":1,"explanation":"「连续照护」的构成要件为：①主体为社区卫生服务中心；②通过先由基层评估再决定是否上转；③使病情变化能被尽早发现。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01850","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「形成性评价」是指任课教师团队通过先摸清起点再设定分层目标，使后续目标更贴合实际起点的工作机制。\n\n按照上述界定，下列情形不应认定为「形成性评价」的是：","options":["任课教师团队在实验课程组织中，只以期末一次分数定结论，最终教学安排并未因数据而作任何调整。","任课教师团队在单元教学设计中，先摸清起点再设定分层目标，后续目标更贴合实际起点。","任课教师团队在实验课程组织中，先摸清起点再设定分层目标，后续目标更贴合实际起点。","任课教师团队在作业反馈整理中，先摸清起点再设定分层目标，后续目标更贴合实际起点。"],"answer":0,"explanation":"「形成性评价」的构成要件为：①主体为任课教师团队；②通过先摸清起点再设定分层目标；③使后续目标更贴合实际起点。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（只以期末一次分数定结论），因此不符合构成要件。故选A。"},{"id":"pdn01851","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「适应性管理」是指湿地管护中心通过按监测指标分档调整措施，使干预强度与实际风险相匹配的工作机制。\n\n根据上述定义，下列属于「适应性管理」的是：","options":["湿地管护中心在栖息环境变化中，指标超标后仍不调整，最终指标已越界而措施仍维持不变。","由邻近地区照抄方案，后续也未按上述机制推进。","湿地管护中心在外来因素扩散中，按监测指标分档调整措施，但指标已越界而措施仍维持不变。","湿地管护中心在监测指标波动中，按监测指标分档调整措施，干预强度与实际风险相匹配。"],"answer":3,"explanation":"「适应性管理」的构成要件为：①主体为湿地管护中心；②通过按监测指标分档调整措施；③使干预强度与实际风险相匹配。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01852","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「脆弱性评估」是指城市运行管理平台通过识别薄弱环节并预先加固，使次生影响被压到最小的工作机制。\n\n依据上述定义，以下哪一项不符合「脆弱性评估」的构成要件：","options":["城市运行管理平台在关键节点值守中，识别薄弱环节并预先加固，次生影响被压到最小。","城市运行管理平台在响应动作预置中，识别薄弱环节并预先加固，次生影响被压到最小。","城市运行管理平台在风险等级研判中，识别薄弱环节并预先加固，次生影响被压到最小。","城市运行管理平台在响应动作预置中，预案长期封存不随风险更新，最终异常发生时无预设动作可依。"],"answer":3,"explanation":"「脆弱性评估」的构成要件为：①主体为城市运行管理平台；②通过识别薄弱环节并预先加固；③使次生影响被压到最小。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（预案长期封存不随风险更新），因此不符合构成要件。故选D。"},{"id":"pdn01853","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「精准匹配」是指养老服务站点通过按对象条件分档配置资源，使冷门项目被及时替换的工作机制。\n\n按照上述界定，下列情形可认定为「精准匹配」的是：","options":["由服务对象自行寻找渠道，后续也未按上述机制推进。","养老服务站点在对象需求摸排中，沿用上一年清单不作修订，最终大量项目无人使用而真实诉求仍被搁置。","养老服务站点在服务事项梳理中，按对象条件分档配置资源，冷门项目被及时替换。","养老服务站点在服务清单编制中，按对象条件分档配置资源，但大量项目无人使用而真实诉求仍被搁置。"],"answer":2,"explanation":"「精准匹配」的构成要件为：①主体为养老服务站点；②通过按对象条件分档配置资源；③使冷门项目被及时替换。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01854","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「诊断性测评」是指课程组通过结合真实任务表现打分，使教学策略得以动态优化的工作机制。\n\n根据上述定义，下列不属于「诊断性测评」的是：","options":["课程组在单元教学设计中，结合真实任务表现打分，教学策略得以动态优化。","课程组在作业反馈整理中，结合真实任务表现打分，教学策略得以动态优化。","课程组在实验课程组织中，结合真实任务表现打分，教学策略得以动态优化。","课程组在实验课程组织中，只以期末一次分数定结论，最终教学安排并未因数据而作任何调整。"],"answer":3,"explanation":"「诊断性测评」的构成要件为：①主体为课程组；②通过结合真实任务表现打分；③使教学策略得以动态优化。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（只以期末一次分数定结论），因此不符合构成要件。故选D。"},{"id":"pdn01855","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「双向转诊」是指乡镇卫生院通过建立电子档案并定期回访，使患者往返成本下降的工作机制。\n\n依据上述定义，以下哪一项符合「双向转诊」的构成要件：","options":["仅由三甲医院单方建档，后续也未按上述机制推进。","乡镇卫生院在重点人群筛查中，建立电子档案并定期回访，但各环节彼此脱节、患者仍需多次重复排队。","乡镇卫生院在慢病随访安排中，建立电子档案并定期回访，患者往返成本下降。","乡镇卫生院在康复跟踪记录中，只做一次性检查不作后续跟踪，最终各环节彼此脱节、患者仍需多次重复排队。"],"answer":2,"explanation":"「双向转诊」的构成要件为：①主体为乡镇卫生院；②通过建立电子档案并定期回访；③使患者往返成本下降。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01856","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「证据本位决策」是指规划编制组通过用对照组剔除同期其他影响，使结论不易被个别异常值带偏的工作机制。\n\n按照上述界定，下列情形不应认定为「证据本位决策」的是：","options":["规划编制组在政策效果评估中，用对照组剔除同期其他影响，结论不易被个别异常值带偏。","规划编制组在抽样数据核查中，用对照组剔除同期其他影响，结论不易被个别异常值带偏。","规划编制组在政策效果评估中，以主观感受替代实测数据，最终结论无法由所引数据支撑。","规划编制组在年度计划编制中，用对照组剔除同期其他影响，结论不易被个别异常值带偏。"],"answer":2,"explanation":"「证据本位决策」的构成要件为：①主体为规划编制组；②通过用对照组剔除同期其他影响；③使结论不易被个别异常值带偏。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（以主观感受替代实测数据），因此不符合构成要件。故选C。"},{"id":"pdn01857","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「留痕管理」是指食品药品监管所通过每一节点登记并关联上下游凭证，使召回范围精确到具体批次的工作机制。\n\n根据上述定义，下列属于「留痕管理」的是：","options":["食品药品监管所在储运环节温控中，每一节点登记并关联上下游凭证，但出现问题时无法定位到具体环节。","食品药品监管所在批次交接记录中，仅保留汇总数不留明细，最终出现问题时无法定位到具体环节。","由消费者事后反馈倒查，后续也未按上述机制推进。","食品药品监管所在进货环节核验中，每一节点登记并关联上下游凭证，召回范围精确到具体批次。"],"answer":3,"explanation":"「留痕管理」的构成要件为：①主体为食品药品监管所；②通过每一节点登记并关联上下游凭证；③使召回范围精确到具体批次。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01858","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「脆弱性评估」是指数据中心运维组通过按风险等级预置响应动作，使次生影响被压到最小的工作机制。\n\n依据上述定义，以下哪一项不符合「脆弱性评估」的构成要件：","options":["数据中心运维组在风险等级研判中，按风险等级预置响应动作，次生影响被压到最小。","数据中心运维组在响应动作预置中，等指标越限后才临时研究方案，最终异常发生时无预设动作可依。","数据中心运维组在响应动作预置中，按风险等级预置响应动作，次生影响被压到最小。","数据中心运维组在关键节点值守中，按风险等级预置响应动作，次生影响被压到最小。"],"answer":1,"explanation":"「脆弱性评估」的构成要件为：①主体为数据中心运维组；②通过按风险等级预置响应动作；③使次生影响被压到最小。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（等指标越限后才临时研究方案），因此不符合构成要件。故选B。"},{"id":"pdn01859","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「共创工作坊」是指公共服务设计组通过邀请使用者全程参与方案打磨，使隐蔽障碍在使用前被暴露的工作机制。\n\n按照上述界定，下列情形可认定为「共创工作坊」的是：","options":["公共服务设计组在公共界面优化中，只做内部评审不接触使用者，最终上线后仍频发与习惯不符的障碍。","公共服务设计组在服务流程梳理中，邀请使用者全程参与方案打磨，隐蔽障碍在使用前被暴露。","公共服务设计组在使用路径排查中，邀请使用者全程参与方案打磨，但上线后仍频发与习惯不符的障碍。","由供应商提供标准模板，后续也未按上述机制推进。"],"answer":1,"explanation":"「共创工作坊」的构成要件为：①主体为公共服务设计组；②通过邀请使用者全程参与方案打磨；③使隐蔽障碍在使用前被暴露。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01860","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「分级授权」是指公共服务窗口通过只采集完成本事项所必需的字段，使敏感字段仅在授权场景可见的工作机制。\n\n根据上述定义，下列不属于「分级授权」的是：","options":["公共服务窗口在字段权限配置中，共享时直接提供原始明细，最终与办理目的无关的字段仍被长期留存。","公共服务窗口在字段权限配置中，只采集完成本事项所必需的字段，敏感字段仅在授权场景可见。","公共服务窗口在数据调阅留痕中，只采集完成本事项所必需的字段，敏感字段仅在授权场景可见。","公共服务窗口在信息采集登记中，只采集完成本事项所必需的字段，敏感字段仅在授权场景可见。"],"answer":0,"explanation":"「分级授权」的构成要件为：①主体为公共服务窗口；②通过只采集完成本事项所必需的字段；③使敏感字段仅在授权场景可见。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（共享时直接提供原始明细），因此不符合构成要件。故选A。"},{"id":"pdn01861","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「菜单式服务」是指农技推广站通过依据使用频次动态增减项目，使供给与实际需求更加贴合的工作机制。\n\n依据上述定义，以下哪一项符合「菜单式服务」的构成要件：","options":["农技推广站在对象需求摸排中，沿用上一年清单不作修订，最终大量项目无人使用而真实诉求仍被搁置。","由服务对象自行寻找渠道，后续也未按上述机制推进。","农技推广站在服务清单编制中，依据使用频次动态增减项目，但大量项目无人使用而真实诉求仍被搁置。","农技推广站在服务事项梳理中，依据使用频次动态增减项目，供给与实际需求更加贴合。"],"answer":3,"explanation":"「菜单式服务」的构成要件为：①主体为农技推广站；②通过依据使用频次动态增减项目；③使供给与实际需求更加贴合。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01862","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「双向转诊」是指社区卫生服务中心通过建立电子档案并定期回访，使病情变化能被尽早发现的工作机制。\n\n按照上述界定，下列情形不应认定为「双向转诊」的是：","options":["社区卫生服务中心在康复跟踪记录中，一律先安排住院再评估，最终各环节彼此脱节、患者仍需多次重复排队。","社区卫生服务中心在慢病随访安排中，建立电子档案并定期回访，病情变化能被尽早发现。","社区卫生服务中心在重点人群筛查中，建立电子档案并定期回访，病情变化能被尽早发现。","社区卫生服务中心在康复跟踪记录中，建立电子档案并定期回访，病情变化能被尽早发现。"],"answer":0,"explanation":"「双向转诊」的构成要件为：①主体为社区卫生服务中心；②通过建立电子档案并定期回访；③使病情变化能被尽早发现。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（一律先安排住院再评估），因此不符合构成要件。故选A。"},{"id":"pdn01863","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「动态监测」是指生态环境监测站通过划分区块实行差异化管护，使管控成本保持在合理区间的工作机制。\n\n根据上述定义，下列属于「动态监测」的是：","options":["生态环境监测站在监测指标波动中，划分区块实行差异化管护，管控成本保持在合理区间。","生态环境监测站在栖息环境变化中，指标超标后仍不调整，最终指标已越界而措施仍维持不变。","生态环境监测站在外来因素扩散中，划分区块实行差异化管护，但指标已越界而措施仍维持不变。","由邻近地区照抄方案，后续也未按上述机制推进。"],"answer":0,"explanation":"「动态监测」的构成要件为：①主体为生态环境监测站；②通过划分区块实行差异化管护；③使管控成本保持在合理区间。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01864","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「数据校验」是指统计调查队通过先确立基线再对照前后变化，使后续调整有据可依的工作机制。\n\n依据上述定义，以下哪一项不符合「数据校验」的构成要件：","options":["统计调查队在年度计划编制中，先确立基线再对照前后变化，后续调整有据可依。","统计调查队在抽样数据核查中，先确立基线再对照前后变化，后续调整有据可依。","统计调查队在政策效果评估中，以主观感受替代实测数据，最终结论无法由所引数据支撑。","统计调查队在政策效果评估中，先确立基线再对照前后变化，后续调整有据可依。"],"answer":2,"explanation":"「数据校验」的构成要件为：①主体为统计调查队；②通过先确立基线再对照前后变化；③使后续调整有据可依。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（以主观感受替代实测数据），因此不符合构成要件。故选C。"},{"id":"pdn01865","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「分级诊疗」是指家庭医生团队通过先由基层评估再决定是否上转，使轻症在基层得到及时处置的工作机制。\n\n按照上述界定，下列情形可认定为「分级诊疗」的是：","options":["由商业体检机构独立出具结论，后续也未按上述机制推进。","家庭医生团队在慢病随访安排中，先由基层评估再决定是否上转，轻症在基层得到及时处置。","家庭医生团队在重点人群筛查中，先由基层评估再决定是否上转，但各环节彼此脱节、患者仍需多次重复排队。","家庭医生团队在康复跟踪记录中，待病情加重后再启动会诊，最终各环节彼此脱节、患者仍需多次重复排队。"],"answer":1,"explanation":"「分级诊疗」的构成要件为：①主体为家庭医生团队；②通过先由基层评估再决定是否上转；③使轻症在基层得到及时处置。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01866","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「最小必要采集」是指医院信息科通过对外提供前作去标识化处理，使共享环节不泄露可识别信息的工作机制。\n\n根据上述定义，下列不属于「最小必要采集」的是：","options":["医院信息科在数据调阅留痕中，对外提供前作去标识化处理，共享环节不泄露可识别信息。","医院信息科在字段权限配置中，为方便起见一次性收齐全部字段，最终与办理目的无关的字段仍被长期留存。","医院信息科在信息采集登记中，对外提供前作去标识化处理，共享环节不泄露可识别信息。","医院信息科在字段权限配置中，对外提供前作去标识化处理，共享环节不泄露可识别信息。"],"answer":1,"explanation":"「最小必要采集」的构成要件为：①主体为医院信息科；②通过对外提供前作去标识化处理；③使共享环节不泄露可识别信息。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（为方便起见一次性收齐全部字段），因此不符合构成要件。故选B。"},{"id":"pdn01867","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「循证施策」是指规划编制组通过先确立基线再对照前后变化，使成效与措施之间的对应更清楚的工作机制。\n\n依据上述定义，以下哪一项符合「循证施策」的构成要件：","options":["规划编制组在政策效果评估中，用总量变化直接归因、不作对照，最终结论无法由所引数据支撑。","规划编制组在抽样数据核查中，先确立基线再对照前后变化，但结论无法由所引数据支撑。","由申报方自行填报不作核实，后续也未按上述机制推进。","规划编制组在年度计划编制中，先确立基线再对照前后变化，成效与措施之间的对应更清楚。"],"answer":3,"explanation":"「循证施策」的构成要件为：①主体为规划编制组；②通过先确立基线再对照前后变化；③使成效与措施之间的对应更清楚。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01868","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「分区管控」是指流域管理机构通过按监测指标分档调整措施，使异常苗头被尽早识别的工作机制。\n\n按照上述界定，下列情形不应认定为「分区管控」的是：","options":["流域管理机构在栖息环境变化中，按监测指标分档调整措施，异常苗头被尽早识别。","流域管理机构在栖息环境变化中，只看年度均值忽略峰值，最终指标已越界而措施仍维持不变。","流域管理机构在监测指标波动中，按监测指标分档调整措施，异常苗头被尽早识别。","流域管理机构在外来因素扩散中，按监测指标分档调整措施，异常苗头被尽早识别。"],"answer":1,"explanation":"「分区管控」的构成要件为：①主体为流域管理机构；②通过按监测指标分档调整措施；③使异常苗头被尽早识别。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（只看年度均值忽略峰值），因此不符合构成要件。故选B。"},{"id":"pdn01869","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「最小必要采集」是指政务数据平台通过只采集完成本事项所必需的字段，使超范围信息不被额外索取的工作机制。\n\n根据上述定义，下列属于「最小必要采集」的是：","options":["由系统默认长期全量保留，后续也未按上述机制推进。","政务数据平台在数据调阅留痕中，只采集完成本事项所必需的字段，但与办理目的无关的字段仍被长期留存。","政务数据平台在信息采集登记中，只采集完成本事项所必需的字段，超范围信息不被额外索取。","政务数据平台在字段权限配置中，超过期限仍不作清理，最终与办理目的无关的字段仍被长期留存。"],"answer":2,"explanation":"「最小必要采集」的构成要件为：①主体为政务数据平台；②通过只采集完成本事项所必需的字段；③使超范围信息不被额外索取。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01870","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「循证施策」是指政策评估小组通过以多源数据交叉校验结论，使结论不易被个别异常值带偏的工作机制。\n\n依据上述定义，以下哪一项不符合「循证施策」的构成要件：","options":["政策评估小组在年度计划编制中，以多源数据交叉校验结论，结论不易被个别异常值带偏。","政策评估小组在抽样数据核查中，以多源数据交叉校验结论，结论不易被个别异常值带偏。","政策评估小组在政策效果评估中，只选取有利样本作展示，最终结论无法由所引数据支撑。","政策评估小组在政策效果评估中，以多源数据交叉校验结论，结论不易被个别异常值带偏。"],"answer":2,"explanation":"「循证施策」的构成要件为：①主体为政策评估小组；②通过以多源数据交叉校验结论；③使结论不易被个别异常值带偏。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（只选取有利样本作展示），因此不符合构成要件。故选C。"},{"id":"pdn01871","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「前置筛查」是指社区卫生服务中心通过与上级医院共享检查结果，使轻症在基层得到及时处置的工作机制。\n\n按照上述界定，下列情形可认定为「前置筛查」的是：","options":["仅由三甲医院单方建档，后续也未按上述机制推进。","社区卫生服务中心在慢病随访安排中，与上级医院共享检查结果，轻症在基层得到及时处置。","社区卫生服务中心在康复跟踪记录中，只做一次性检查不作后续跟踪，最终各环节彼此脱节、患者仍需多次重复排队。","社区卫生服务中心在重点人群筛查中，与上级医院共享检查结果，但各环节彼此脱节、患者仍需多次重复排队。"],"answer":1,"explanation":"「前置筛查」的构成要件为：①主体为社区卫生服务中心；②通过与上级医院共享检查结果；③使轻症在基层得到及时处置。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01872","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「弹性调控」是指自然保护区管理局通过划分区块实行差异化管护，使核心栖息地得到有效避让的工作机制。\n\n根据上述定义，下列不属于「弹性调控」的是：","options":["自然保护区管理局在外来因素扩散中，划分区块实行差异化管护，核心栖息地得到有效避让。","自然保护区管理局在栖息环境变化中，划分区块实行差异化管护，核心栖息地得到有效避让。","自然保护区管理局在监测指标波动中，划分区块实行差异化管护，核心栖息地得到有效避让。","自然保护区管理局在栖息环境变化中，只看年度均值忽略峰值，最终指标已越界而措施仍维持不变。"],"answer":3,"explanation":"「弹性调控」的构成要件为：①主体为自然保护区管理局；②通过划分区块实行差异化管护；③使核心栖息地得到有效避让。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（只看年度均值忽略峰值），因此不符合构成要件。故选D。"},{"id":"pdn01873","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「留存限期」是指学校学籍管理系统通过只采集完成本事项所必需的字段，使共享环节不泄露可识别信息的工作机制。\n\n依据上述定义，以下哪一项符合「留存限期」的构成要件：","options":["学校学籍管理系统在数据调阅留痕中，只采集完成本事项所必需的字段，但与办理目的无关的字段仍被长期留存。","由系统默认长期全量保留，后续也未按上述机制推进。","学校学籍管理系统在字段权限配置中，超过期限仍不作清理，最终与办理目的无关的字段仍被长期留存。","学校学籍管理系统在信息采集登记中，只采集完成本事项所必需的字段，共享环节不泄露可识别信息。"],"answer":3,"explanation":"「留存限期」的构成要件为：①主体为学校学籍管理系统；②通过只采集完成本事项所必需的字段；③使共享环节不泄露可识别信息。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01874","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「联合响应」是指流域联席会议通过明确牵头与配合边界后统一行动，使响应口径保持一致的工作机制。\n\n按照上述界定，下列情形不应认定为「联合响应」的是：","options":["流域联席会议在信息通报共享中，明确牵头与配合边界后统一行动，响应口径保持一致。","流域联席会议在联合排班安排中，明确牵头与配合边界后统一行动，响应口径保持一致。","流域联席会议在联合排班安排中，各部门分头进场、结果互不通报，最终边界地带的问题仍在部门之间来回流转。","流域联席会议在跨界事项梳理中，明确牵头与配合边界后统一行动，响应口径保持一致。"],"answer":2,"explanation":"「联合响应」的构成要件为：①主体为流域联席会议；②通过明确牵头与配合边界后统一行动；③使响应口径保持一致。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（各部门分头进场、结果互不通报），因此不符合构成要件。故选C。"},{"id":"pdn01875","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「用户旅程映射」是指社区营造团队通过按真实使用路径逐点排查痛点，使隐蔽障碍在使用前被暴露的工作机制。\n\n根据上述定义，下列属于「用户旅程映射」的是：","options":["社区营造团队在使用路径排查中，按真实使用路径逐点排查痛点，但上线后仍频发与习惯不符的障碍。","社区营造团队在公共界面优化中，只做内部评审不接触使用者，最终上线后仍频发与习惯不符的障碍。","社区营造团队在服务流程梳理中，按真实使用路径逐点排查痛点，隐蔽障碍在使用前被暴露。","由供应商提供标准模板，后续也未按上述机制推进。"],"answer":2,"explanation":"「用户旅程映射」的构成要件为：①主体为社区营造团队；②通过按真实使用路径逐点排查痛点；③使隐蔽障碍在使用前被暴露。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01876","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「适应性管理」是指自然保护区管理局通过按监测指标分档调整措施，使核心栖息地得到有效避让的工作机制。\n\n依据上述定义，以下哪一项不符合「适应性管理」的构成要件：","options":["自然保护区管理局在栖息环境变化中，只看年度均值忽略峰值，最终指标已越界而措施仍维持不变。","自然保护区管理局在监测指标波动中，按监测指标分档调整措施，核心栖息地得到有效避让。","自然保护区管理局在栖息环境变化中，按监测指标分档调整措施，核心栖息地得到有效避让。","自然保护区管理局在外来因素扩散中，按监测指标分档调整措施，核心栖息地得到有效避让。"],"answer":0,"explanation":"「适应性管理」的构成要件为：①主体为自然保护区管理局；②通过按监测指标分档调整措施；③使核心栖息地得到有效避让。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（只看年度均值忽略峰值），因此不符合构成要件。故选A。"},{"id":"pdn01877","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「留痕管理」是指食品药品监管所通过异常批次可一键回溯全链路，使台账与实物始终一致的工作机制。\n\n按照上述界定，下列情形可认定为「留痕管理」的是：","options":["食品药品监管所在批次交接记录中，仅保留汇总数不留明细，最终出现问题时无法定位到具体环节。","由消费者事后反馈倒查，后续也未按上述机制推进。","食品药品监管所在储运环节温控中，异常批次可一键回溯全链路，但出现问题时无法定位到具体环节。","食品药品监管所在进货环节核验中，异常批次可一键回溯全链路，台账与实物始终一致。"],"answer":3,"explanation":"「留痕管理」的构成要件为：①主体为食品药品监管所；②通过异常批次可一键回溯全链路；③使台账与实物始终一致。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01878","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「差异化供给」是指农技推广站通过按可选项自主组合形成服务清单，使冷门项目被及时替换的工作机制。\n\n根据上述定义，下列不属于「差异化供给」的是：","options":["农技推广站在对象需求摸排中，所有对象发放完全相同的固定包，最终大量项目无人使用而真实诉求仍被搁置。","农技推广站在服务清单编制中，按可选项自主组合形成服务清单，冷门项目被及时替换。","农技推广站在服务事项梳理中，按可选项自主组合形成服务清单，冷门项目被及时替换。","农技推广站在对象需求摸排中，按可选项自主组合形成服务清单，冷门项目被及时替换。"],"answer":0,"explanation":"「差异化供给」的构成要件为：①主体为农技推广站；②通过按可选项自主组合形成服务清单；③使冷门项目被及时替换。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（所有对象发放完全相同的固定包），因此不符合构成要件。故选A。"},{"id":"pdn01879","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「脆弱性评估」是指城市运行管理平台通过按风险等级预置响应动作，使次生影响被压到最小的工作机制。\n\n依据上述定义，以下哪一项符合「脆弱性评估」的构成要件：","options":["城市运行管理平台在响应动作预置中，仅保留一份无备用的关键设备，最终异常发生时无预设动作可依。","由上级在事后统一追认，后续也未按上述机制推进。","城市运行管理平台在关键节点值守中，按风险等级预置响应动作，但异常发生时无预设动作可依。","城市运行管理平台在风险等级研判中，按风险等级预置响应动作，次生影响被压到最小。"],"answer":3,"explanation":"「脆弱性评估」的构成要件为：①主体为城市运行管理平台；②通过按风险等级预置响应动作；③使次生影响被压到最小。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01880","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「共创工作坊」是指无障碍改造专班通过多轮共创后收敛为最终版本，使返工与投诉明显减少的工作机制。\n\n按照上述界定，下列情形不应认定为「共创工作坊」的是：","options":["无障碍改造专班在使用路径排查中，多轮共创后收敛为最终版本，返工与投诉明显减少。","无障碍改造专班在公共界面优化中，多轮共创后收敛为最终版本，返工与投诉明显减少。","无障碍改造专班在服务流程梳理中，多轮共创后收敛为最终版本，返工与投诉明显减少。","无障碍改造专班在公共界面优化中，照搬其他地区成品，最终上线后仍频发与习惯不符的障碍。"],"answer":3,"explanation":"「共创工作坊」的构成要件为：①主体为无障碍改造专班；②通过多轮共创后收敛为最终版本；③使返工与投诉明显减少。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（照搬其他地区成品），因此不符合构成要件。故选D。"},{"id":"pdn01881","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「节点责任制」是指食品药品监管所通过异常批次可一键回溯全链路，使问题批次能被快速定位的工作机制。\n\n根据上述定义，下列属于「节点责任制」的是：","options":["食品药品监管所在进货环节核验中，异常批次可一键回溯全链路，问题批次能被快速定位。","由消费者事后反馈倒查，后续也未按上述机制推进。","食品药品监管所在批次交接记录中，仅保留汇总数不留明细，最终出现问题时无法定位到具体环节。","食品药品监管所在储运环节温控中，异常批次可一键回溯全链路，但出现问题时无法定位到具体环节。"],"answer":0,"explanation":"「节点责任制」的构成要件为：①主体为食品药品监管所；②通过异常批次可一键回溯全链路；③使问题批次能被快速定位。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01882","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「全过程追溯」是指冷链运营方通过每一节点登记并关联上下游凭证，使问题批次能被快速定位的工作机制。\n\n依据上述定义，以下哪一项不符合「全过程追溯」的构成要件：","options":["冷链运营方在进货环节核验中，每一节点登记并关联上下游凭证，问题批次能被快速定位。","冷链运营方在批次交接记录中，只在最终出库时记一笔总账，最终出现问题时无法定位到具体环节。","冷链运营方在批次交接记录中，每一节点登记并关联上下游凭证，问题批次能被快速定位。","冷链运营方在储运环节温控中，每一节点登记并关联上下游凭证，问题批次能被快速定位。"],"answer":1,"explanation":"「全过程追溯」的构成要件为：①主体为冷链运营方；②通过每一节点登记并关联上下游凭证；③使问题批次能被快速定位。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（只在最终出库时记一笔总账），因此不符合构成要件。故选B。"},{"id":"pdn01883","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「动态监测」是指生态环境监测站通过按监测指标分档调整措施，使管控成本保持在合理区间的工作机制。\n\n按照上述界定，下列情形可认定为「动态监测」的是：","options":["由邻近地区照抄方案，后续也未按上述机制推进。","生态环境监测站在外来因素扩散中，按监测指标分档调整措施，但指标已越界而措施仍维持不变。","生态环境监测站在栖息环境变化中，指标超标后仍不调整，最终指标已越界而措施仍维持不变。","生态环境监测站在监测指标波动中，按监测指标分档调整措施，管控成本保持在合理区间。"],"answer":3,"explanation":"「动态监测」的构成要件为：①主体为生态环境监测站；②通过按监测指标分档调整措施；③使管控成本保持在合理区间。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01884","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「表现性评价」是指学校教研组通过先摸清起点再设定分层目标，使教学策略得以动态优化的工作机制。\n\n根据上述定义，下列不属于「表现性评价」的是：","options":["学校教研组在作业反馈整理中，先摸清起点再设定分层目标，教学策略得以动态优化。","学校教研组在实验课程组织中，先摸清起点再设定分层目标，教学策略得以动态优化。","学校教研组在实验课程组织中，照搬统一答案不看作答过程，最终教学安排并未因数据而作任何调整。","学校教研组在单元教学设计中，先摸清起点再设定分层目标，教学策略得以动态优化。"],"answer":2,"explanation":"「表现性评价」的构成要件为：①主体为学校教研组；②通过先摸清起点再设定分层目标；③使教学策略得以动态优化。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（照搬统一答案不看作答过程），因此不符合构成要件。故选C。"},{"id":"pdn01885","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「链条式核验」是指冷链运营方通过按批号串联台账与检验记录，使召回范围精确到具体批次的工作机制。\n\n依据上述定义，以下哪一项符合「链条式核验」的构成要件：","options":["由消费者事后反馈倒查，后续也未按上述机制推进。","冷链运营方在进货环节核验中，按批号串联台账与检验记录，召回范围精确到具体批次。","冷链运营方在批次交接记录中，仅保留汇总数不留明细，最终出现问题时无法定位到具体环节。","冷链运营方在储运环节温控中，按批号串联台账与检验记录，但出现问题时无法定位到具体环节。"],"answer":1,"explanation":"「链条式核验」的构成要件为：①主体为冷链运营方；②通过按批号串联台账与检验记录；③使召回范围精确到具体批次。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01886","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「网格代办」是指社区网格站通过依托网格员常态化走访摸排，使平均处置周期缩短的工作机制。\n\n按照上述界定，下列情形不应认定为「网格代办」的是：","options":["社区网格站在邻里纠纷调解中，直接照搬既有方案、未作任何征询，最终问题仍反复出现且未形成稳定机制。","社区网格站在老旧小区改造中，依托网格员常态化走访摸排，平均处置周期缩短。","社区网格站在便民事项办理中，依托网格员常态化走访摸排，平均处置周期缩短。","社区网格站在邻里纠纷调解中，依托网格员常态化走访摸排，平均处置周期缩短。"],"answer":0,"explanation":"「网格代办」的构成要件为：①主体为社区网格站；②通过依托网格员常态化走访摸排；③使平均处置周期缩短。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（直接照搬既有方案、未作任何征询），因此不符合构成要件。故选A。"},{"id":"pdn01887","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「共创工作坊」是指公共服务设计组通过先做可体验原型再收集反馈，使改动获得使用者认同的工作机制。\n\n根据上述定义，下列属于「共创工作坊」的是：","options":["由供应商提供标准模板，后续也未按上述机制推进。","公共服务设计组在公共界面优化中，只做内部评审不接触使用者，最终上线后仍频发与习惯不符的障碍。","公共服务设计组在使用路径排查中，先做可体验原型再收集反馈，但上线后仍频发与习惯不符的障碍。","公共服务设计组在服务流程梳理中，先做可体验原型再收集反馈，改动获得使用者认同。"],"answer":3,"explanation":"「共创工作坊」的构成要件为：①主体为公共服务设计组；②通过先做可体验原型再收集反馈；③使改动获得使用者认同。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01888","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「分级办理」是指社区网格站通过提前公示并逐户征询意见，使重复投诉明显下降的工作机制。\n\n依据上述定义，以下哪一项不符合「分级办理」的构成要件：","options":["社区网格站在邻里纠纷调解中，只在事后补录台账，最终问题仍反复出现且未形成稳定机制。","社区网格站在老旧小区改造中，提前公示并逐户征询意见，重复投诉明显下降。","社区网格站在邻里纠纷调解中，提前公示并逐户征询意见，重复投诉明显下降。","社区网格站在便民事项办理中，提前公示并逐户征询意见，重复投诉明显下降。"],"answer":0,"explanation":"「分级办理」的构成要件为：①主体为社区网格站；②通过提前公示并逐户征询意见；③使重复投诉明显下降。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（只在事后补录台账），因此不符合构成要件。故选A。"},{"id":"pdn01889","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「分级办理」是指村委会通过联合多方现场会商后再定方案，使重复投诉明显下降的工作机制。\n\n按照上述界定，下列情形可认定为「分级办理」的是：","options":["村委会在老旧小区改造中，联合多方现场会商后再定方案，重复投诉明显下降。","村委会在邻里纠纷调解中，各口径分头办理、彼此不通气，最终问题仍反复出现且未形成稳定机制。","村委会在便民事项办理中，联合多方现场会商后再定方案，但问题仍反复出现且未形成稳定机制。","由服务对象自行申报后不再跟进，后续也未按上述机制推进。"],"answer":0,"explanation":"「分级办理」的构成要件为：①主体为村委会；②通过联合多方现场会商后再定方案；③使重复投诉明显下降。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01890","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「需求导向供给」是指养老服务站点通过先摸清不同群体诉求再分类提供，使不同群体各取所需的工作机制。\n\n根据上述定义，下列不属于「需求导向供给」的是：","options":["养老服务站点在服务清单编制中，先摸清不同群体诉求再分类提供，不同群体各取所需。","养老服务站点在服务事项梳理中，先摸清不同群体诉求再分类提供，不同群体各取所需。","养老服务站点在对象需求摸排中，所有对象发放完全相同的固定包，最终大量项目无人使用而真实诉求仍被搁置。","养老服务站点在对象需求摸排中，先摸清不同群体诉求再分类提供，不同群体各取所需。"],"answer":2,"explanation":"「需求导向供给」的构成要件为：①主体为养老服务站点；②通过先摸清不同群体诉求再分类提供；③使不同群体各取所需。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（所有对象发放完全相同的固定包），因此不符合构成要件。故选C。"},{"id":"pdn01891","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「联合响应」是指流域联席会议通过共享信息并同步排班，使处置效率整体提升的工作机制。\n\n依据上述定义，以下哪一项符合「联合响应」的构成要件：","options":["流域联席会议在跨界事项梳理中，共享信息并同步排班，处置效率整体提升。","流域联席会议在信息通报共享中，共享信息并同步排班，但边界地带的问题仍在部门之间来回流转。","由各区各自为政，后续也未按上述机制推进。","流域联席会议在联合排班安排中，只开会不落责任清单，最终边界地带的问题仍在部门之间来回流转。"],"answer":0,"explanation":"「联合响应」的构成要件为：①主体为流域联席会议；②通过共享信息并同步排班；③使处置效率整体提升。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01892","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「指标复核」是指政策评估小组通过以多源数据交叉校验结论，使判断建立在可核验的依据上的工作机制。\n\n按照上述界定，下列情形不应认定为「指标复核」的是：","options":["政策评估小组在年度计划编制中，以多源数据交叉校验结论，判断建立在可核验的依据上。","政策评估小组在政策效果评估中，以多源数据交叉校验结论，判断建立在可核验的依据上。","政策评估小组在抽样数据核查中，以多源数据交叉校验结论，判断建立在可核验的依据上。","政策评估小组在政策效果评估中，以主观感受替代实测数据，最终结论无法由所引数据支撑。"],"answer":3,"explanation":"「指标复核」的构成要件为：①主体为政策评估小组；②通过以多源数据交叉校验结论；③使判断建立在可核验的依据上。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（以主观感受替代实测数据），因此不符合构成要件。故选D。"},{"id":"pdn01893","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「形成性评价」是指课程组通过按阶段采集学情数据再修正教学，使学习过程而非仅结果被看见的工作机制。\n\n根据上述定义，下列属于「形成性评价」的是：","options":["课程组在作业反馈整理中，按阶段采集学情数据再修正教学，但教学安排并未因数据而作任何调整。","由学生互评后不再复核，后续也未按上述机制推进。","课程组在单元教学设计中，按阶段采集学情数据再修正教学，学习过程而非仅结果被看见。","课程组在实验课程组织中，按固定名次划线且不追溯变化，最终教学安排并未因数据而作任何调整。"],"answer":2,"explanation":"「形成性评价」的构成要件为：①主体为课程组；②通过按阶段采集学情数据再修正教学；③使学习过程而非仅结果被看见。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01894","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「形成性评价」是指学校教研组通过按阶段采集学情数据再修正教学，使教学策略得以动态优化的工作机制。\n\n依据上述定义，以下哪一项不符合「形成性评价」的构成要件：","options":["学校教研组在实验课程组织中，按阶段采集学情数据再修正教学，教学策略得以动态优化。","学校教研组在实验课程组织中，只以期末一次分数定结论，最终教学安排并未因数据而作任何调整。","学校教研组在作业反馈整理中，按阶段采集学情数据再修正教学，教学策略得以动态优化。","学校教研组在单元教学设计中，按阶段采集学情数据再修正教学，教学策略得以动态优化。"],"answer":1,"explanation":"「形成性评价」的构成要件为：①主体为学校教研组；②通过按阶段采集学情数据再修正教学；③使教学策略得以动态优化。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（只以期末一次分数定结论），因此不符合构成要件。故选B。"},{"id":"pdn01895","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「链条式核验」是指药品批发企业质控部通过关键节点双人签认留档，使台账与实物始终一致的工作机制。\n\n按照上述界定，下列情形可认定为「链条式核验」的是：","options":["药品批发企业质控部在进货环节核验中，关键节点双人签认留档，台账与实物始终一致。","药品批发企业质控部在批次交接记录中，各环节各自记录且互不关联，最终出现问题时无法定位到具体环节。","由终端门店自行补记，后续也未按上述机制推进。","药品批发企业质控部在储运环节温控中，关键节点双人签认留档，但出现问题时无法定位到具体环节。"],"answer":0,"explanation":"「链条式核验」的构成要件为：①主体为药品批发企业质控部；②通过关键节点双人签认留档；③使台账与实物始终一致。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01896","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「留存限期」是指学校学籍管理系统通过只采集完成本事项所必需的字段，使超范围信息不被额外索取的工作机制。\n\n根据上述定义，下列不属于「留存限期」的是：","options":["学校学籍管理系统在信息采集登记中，只采集完成本事项所必需的字段，超范围信息不被额外索取。","学校学籍管理系统在字段权限配置中，只采集完成本事项所必需的字段，超范围信息不被额外索取。","学校学籍管理系统在数据调阅留痕中，只采集完成本事项所必需的字段，超范围信息不被额外索取。","学校学籍管理系统在字段权限配置中，共享时直接提供原始明细，最终与办理目的无关的字段仍被长期留存。"],"answer":3,"explanation":"「留存限期」的构成要件为：①主体为学校学籍管理系统；②通过只采集完成本事项所必需的字段；③使超范围信息不被额外索取。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（共享时直接提供原始明细），因此不符合构成要件。故选D。"},{"id":"pdn01897","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「原型共创」是指社区营造团队通过邀请使用者全程参与方案打磨，使返工与投诉明显减少的工作机制。\n\n依据上述定义，以下哪一项符合「原型共创」的构成要件：","options":["由外部专家远程定稿，后续也未按上述机制推进。","社区营造团队在公共界面优化中，一次性定稿不再接收反馈，最终上线后仍频发与习惯不符的障碍。","社区营造团队在服务流程梳理中，邀请使用者全程参与方案打磨，返工与投诉明显减少。","社区营造团队在使用路径排查中，邀请使用者全程参与方案打磨，但上线后仍频发与习惯不符的障碍。"],"answer":2,"explanation":"「原型共创」的构成要件为：①主体为社区营造团队；②通过邀请使用者全程参与方案打磨；③使返工与投诉明显减少。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01898","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「小步试点」是指政策试点工作组通过先在小范围试运行再按反馈调整，使风险被限制在可控范围的工作机制。\n\n按照上述界定，下列情形不应认定为「小步试点」的是：","options":["政策试点工作组在新机制落地中，先在小范围试运行再按反馈调整，风险被限制在可控范围。","政策试点工作组在新工具推广中，不经试点直接全面强制推开，最终同类偏差在扩面后被成倍放大。","政策试点工作组在新工具推广中，先在小范围试运行再按反馈调整，风险被限制在可控范围。","政策试点工作组在新流程上线中，先在小范围试运行再按反馈调整，风险被限制在可控范围。"],"answer":1,"explanation":"「小步试点」的构成要件为：①主体为政策试点工作组；②通过先在小范围试运行再按反馈调整；③使风险被限制在可控范围。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（不经试点直接全面强制推开），因此不符合构成要件。故选B。"},{"id":"pdn01899","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「多元共治」是指流域联席会议通过明确牵头与配合边界后统一行动，使重复检查与推诿明显减少的工作机制。\n\n根据上述定义，下列属于「多元共治」的是：","options":["流域联席会议在信息通报共享中，明确牵头与配合边界后统一行动，但边界地带的问题仍在部门之间来回流转。","流域联席会议在联合排班安排中，只开会不落责任清单，最终边界地带的问题仍在部门之间来回流转。","流域联席会议在跨界事项梳理中，明确牵头与配合边界后统一行动，重复检查与推诿明显减少。","由各区各自为政，后续也未按上述机制推进。"],"answer":2,"explanation":"「多元共治」的构成要件为：①主体为流域联席会议；②通过明确牵头与配合边界后统一行动；③使重复检查与推诿明显减少。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01900","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「增值评价」是指课程组通过先摸清起点再设定分层目标，使学习过程而非仅结果被看见的工作机制。\n\n依据上述定义，以下哪一项不符合「增值评价」的构成要件：","options":["课程组在实验课程组织中，照搬统一答案不看作答过程，最终教学安排并未因数据而作任何调整。","课程组在实验课程组织中，先摸清起点再设定分层目标，学习过程而非仅结果被看见。","课程组在单元教学设计中，先摸清起点再设定分层目标，学习过程而非仅结果被看见。","课程组在作业反馈整理中，先摸清起点再设定分层目标，学习过程而非仅结果被看见。"],"answer":0,"explanation":"「增值评价」的构成要件为：①主体为课程组；②通过先摸清起点再设定分层目标；③使学习过程而非仅结果被看见。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（照搬统一答案不看作答过程），因此不符合构成要件。故选A。"},{"id":"pdn01901","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「分级办理」是指乡镇便民中心通过依托网格员常态化走访摸排，使平均处置周期缩短的工作机制。\n\n按照上述界定，下列情形可认定为「分级办理」的是：","options":["乡镇便民中心在老旧小区改造中，依托网格员常态化走访摸排，平均处置周期缩短。","乡镇便民中心在便民事项办理中，依托网格员常态化走访摸排，但问题仍反复出现且未形成稳定机制。","乡镇便民中心在邻里纠纷调解中，各口径分头办理、彼此不通气，最终问题仍反复出现且未形成稳定机制。","由服务对象自行申报后不再跟进，后续也未按上述机制推进。"],"answer":0,"explanation":"「分级办理」的构成要件为：①主体为乡镇便民中心；②通过依托网格员常态化走访摸排；③使平均处置周期缩短。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01902","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「全过程追溯」是指食品药品监管所通过关键节点双人签认留档，使问题批次能被快速定位的工作机制。\n\n根据上述定义，下列不属于「全过程追溯」的是：","options":["食品药品监管所在批次交接记录中，只在最终出库时记一笔总账，最终出现问题时无法定位到具体环节。","食品药品监管所在进货环节核验中，关键节点双人签认留档，问题批次能被快速定位。","食品药品监管所在批次交接记录中，关键节点双人签认留档，问题批次能被快速定位。","食品药品监管所在储运环节温控中，关键节点双人签认留档，问题批次能被快速定位。"],"answer":0,"explanation":"「全过程追溯」的构成要件为：①主体为食品药品监管所；②通过关键节点双人签认留档；③使问题批次能被快速定位。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（只在最终出库时记一笔总账），因此不符合构成要件。故选A。"},{"id":"pdn01903","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「脱敏处理」是指政务数据平台通过对外提供前作去标识化处理，使共享环节不泄露可识别信息的工作机制。\n\n依据上述定义，以下哪一项符合「脱敏处理」的构成要件：","options":["政务数据平台在信息采集登记中，对外提供前作去标识化处理，共享环节不泄露可识别信息。","由外包人员全量导出，后续也未按上述机制推进。","政务数据平台在数据调阅留痕中，对外提供前作去标识化处理，但与办理目的无关的字段仍被长期留存。","政务数据平台在字段权限配置中，所有岗位开放同一份全量清单，最终与办理目的无关的字段仍被长期留存。"],"answer":0,"explanation":"「脱敏处理」的构成要件为：①主体为政务数据平台；②通过对外提供前作去标识化处理；③使共享环节不泄露可识别信息。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01904","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「诊断性测评」是指任课教师团队通过按阶段采集学情数据再修正教学，使学习过程而非仅结果被看见的工作机制。\n\n按照上述界定，下列情形不应认定为「诊断性测评」的是：","options":["任课教师团队在作业反馈整理中，按阶段采集学情数据再修正教学，学习过程而非仅结果被看见。","任课教师团队在单元教学设计中，按阶段采集学情数据再修正教学，学习过程而非仅结果被看见。","任课教师团队在实验课程组织中，照搬统一答案不看作答过程，最终教学安排并未因数据而作任何调整。","任课教师团队在实验课程组织中，按阶段采集学情数据再修正教学，学习过程而非仅结果被看见。"],"answer":2,"explanation":"「诊断性测评」的构成要件为：①主体为任课教师团队；②通过按阶段采集学情数据再修正教学；③使学习过程而非仅结果被看见。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（照搬统一答案不看作答过程），因此不符合构成要件。故选C。"},{"id":"pdn01905","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「协同会商」是指社区网格站通过联合多方现场会商后再定方案，使重复投诉明显下降的工作机制。\n\n根据上述定义，下列属于「协同会商」的是：","options":["由服务对象自行申报后不再跟进，后续也未按上述机制推进。","社区网格站在邻里纠纷调解中，各口径分头办理、彼此不通气，最终问题仍反复出现且未形成稳定机制。","社区网格站在老旧小区改造中，联合多方现场会商后再定方案，重复投诉明显下降。","社区网格站在便民事项办理中，联合多方现场会商后再定方案，但问题仍反复出现且未形成稳定机制。"],"answer":2,"explanation":"「协同会商」的构成要件为：①主体为社区网格站；②通过联合多方现场会商后再定方案；③使重复投诉明显下降。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01906","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「动态监测」是指自然保护区管理局通过按监测指标分档调整措施，使异常苗头被尽早识别的工作机制。\n\n依据上述定义，以下哪一项不符合「动态监测」的构成要件：","options":["自然保护区管理局在栖息环境变化中，按监测指标分档调整措施，异常苗头被尽早识别。","自然保护区管理局在监测指标波动中，按监测指标分档调整措施，异常苗头被尽早识别。","自然保护区管理局在栖息环境变化中，全年沿用同一套固定配额，最终指标已越界而措施仍维持不变。","自然保护区管理局在外来因素扩散中，按监测指标分档调整措施，异常苗头被尽早识别。"],"answer":2,"explanation":"「动态监测」的构成要件为：①主体为自然保护区管理局；②通过按监测指标分档调整措施；③使异常苗头被尽早识别。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（全年沿用同一套固定配额），因此不符合构成要件。故选C。"},{"id":"pdn01907","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「试错迭代」是指产品迭代小组通过设置观察期并保留回退通道，使偏差在放大前被修正的工作机制。\n\n按照上述界定，下列情形可认定为「试错迭代」的是：","options":["产品迭代小组在新机制落地中，设置观察期并保留回退通道，但同类偏差在扩面后被成倍放大。","由外部团队一次性交付即结束，后续也未按上述机制推进。","产品迭代小组在新工具推广中，试运行期间禁止任何修改，最终同类偏差在扩面后被成倍放大。","产品迭代小组在新流程上线中，设置观察期并保留回退通道，偏差在放大前被修正。"],"answer":3,"explanation":"「试错迭代」的构成要件为：①主体为产品迭代小组；②通过设置观察期并保留回退通道；③使偏差在放大前被修正。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01908","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「适应性管理」是指生态环境监测站通过划分区块实行差异化管护，使异常苗头被尽早识别的工作机制。\n\n根据上述定义，下列不属于「适应性管理」的是：","options":["生态环境监测站在栖息环境变化中，划分区块实行差异化管护，异常苗头被尽早识别。","生态环境监测站在外来因素扩散中，划分区块实行差异化管护，异常苗头被尽早识别。","生态环境监测站在监测指标波动中，划分区块实行差异化管护，异常苗头被尽早识别。","生态环境监测站在栖息环境变化中，只看年度均值忽略峰值，最终指标已越界而措施仍维持不变。"],"answer":3,"explanation":"「适应性管理」的构成要件为：①主体为生态环境监测站；②通过划分区块实行差异化管护；③使异常苗头被尽早识别。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（只看年度均值忽略峰值），因此不符合构成要件。故选D。"},{"id":"pdn01909","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「链条式核验」是指农产品质量检测站通过按批号串联台账与检验记录，使问题批次能被快速定位的工作机制。\n\n依据上述定义，以下哪一项符合「链条式核验」的构成要件：","options":["由消费者事后反馈倒查，后续也未按上述机制推进。","农产品质量检测站在储运环节温控中，按批号串联台账与检验记录，但出现问题时无法定位到具体环节。","农产品质量检测站在进货环节核验中，按批号串联台账与检验记录，问题批次能被快速定位。","农产品质量检测站在批次交接记录中，仅保留汇总数不留明细，最终出现问题时无法定位到具体环节。"],"answer":2,"explanation":"「链条式核验」的构成要件为：①主体为农产品质量检测站；②通过按批号串联台账与检验记录；③使问题批次能被快速定位。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01910","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「全过程追溯」是指农产品质量检测站通过按批号串联台账与检验记录，使召回范围精确到具体批次的工作机制。\n\n按照上述界定，下列情形不应认定为「全过程追溯」的是：","options":["农产品质量检测站在批次交接记录中，只在最终出库时记一笔总账，最终出现问题时无法定位到具体环节。","农产品质量检测站在进货环节核验中，按批号串联台账与检验记录，召回范围精确到具体批次。","农产品质量检测站在批次交接记录中，按批号串联台账与检验记录，召回范围精确到具体批次。","农产品质量检测站在储运环节温控中，按批号串联台账与检验记录，召回范围精确到具体批次。"],"answer":0,"explanation":"「全过程追溯」的构成要件为：①主体为农产品质量检测站；②通过按批号串联台账与检验记录；③使召回范围精确到具体批次。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（只在最终出库时记一笔总账），因此不符合构成要件。故选A。"},{"id":"pdn01911","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「阈值预警」是指湿地管护中心通过按监测指标分档调整措施，使管控成本保持在合理区间的工作机制。\n\n根据上述定义，下列属于「阈值预警」的是：","options":["湿地管护中心在栖息环境变化中，指标超标后仍不调整，最终指标已越界而措施仍维持不变。","湿地管护中心在监测指标波动中，按监测指标分档调整措施，管控成本保持在合理区间。","由邻近地区照抄方案，后续也未按上述机制推进。","湿地管护中心在外来因素扩散中，按监测指标分档调整措施，但指标已越界而措施仍维持不变。"],"answer":1,"explanation":"「阈值预警」的构成要件为：①主体为湿地管护中心；②通过按监测指标分档调整措施；③使管控成本保持在合理区间。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01912","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「最小必要采集」是指公共服务窗口通过按岗位授予最小可见范围，使共享环节不泄露可识别信息的工作机制。\n\n依据上述定义，以下哪一项不符合「最小必要采集」的构成要件：","options":["公共服务窗口在信息采集登记中，按岗位授予最小可见范围，共享环节不泄露可识别信息。","公共服务窗口在字段权限配置中，按岗位授予最小可见范围，共享环节不泄露可识别信息。","公共服务窗口在数据调阅留痕中，按岗位授予最小可见范围，共享环节不泄露可识别信息。","公共服务窗口在字段权限配置中，共享时直接提供原始明细，最终与办理目的无关的字段仍被长期留存。"],"answer":3,"explanation":"「最小必要采集」的构成要件为：①主体为公共服务窗口；②通过按岗位授予最小可见范围；③使共享环节不泄露可识别信息。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（共享时直接提供原始明细），因此不符合构成要件。故选D。"},{"id":"pdn01913","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「阈值预警」是指生态环境监测站通过按监测指标分档调整措施，使干预强度与实际风险相匹配的工作机制。\n\n按照上述界定，下列情形可认定为「阈值预警」的是：","options":["由游客反馈临时决定，后续也未按上述机制推进。","生态环境监测站在栖息环境变化中，等出现明显损害后再启动处置，最终指标已越界而措施仍维持不变。","生态环境监测站在监测指标波动中，按监测指标分档调整措施，干预强度与实际风险相匹配。","生态环境监测站在外来因素扩散中，按监测指标分档调整措施，但指标已越界而措施仍维持不变。"],"answer":2,"explanation":"「阈值预警」的构成要件为：①主体为生态环境监测站；②通过按监测指标分档调整措施；③使干预强度与实际风险相匹配。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01914","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「可回溯核查」是指食品药品监管所通过每一节点登记并关联上下游凭证，使责任环节清晰可查的工作机制。\n\n根据上述定义，下列不属于「可回溯核查」的是：","options":["食品药品监管所在批次交接记录中，只在最终出库时记一笔总账，最终出现问题时无法定位到具体环节。","食品药品监管所在批次交接记录中，每一节点登记并关联上下游凭证，责任环节清晰可查。","食品药品监管所在储运环节温控中，每一节点登记并关联上下游凭证，责任环节清晰可查。","食品药品监管所在进货环节核验中，每一节点登记并关联上下游凭证，责任环节清晰可查。"],"answer":0,"explanation":"「可回溯核查」的构成要件为：①主体为食品药品监管所；②通过每一节点登记并关联上下游凭证；③使责任环节清晰可查。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（只在最终出库时记一笔总账），因此不符合构成要件。故选A。"},{"id":"pdn01915","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「预案触发」是指数据中心运维组通过关键节点保留备用通道，使次生影响被压到最小的工作机制。\n\n依据上述定义，以下哪一项符合「预案触发」的构成要件：","options":["由上级在事后统一追认，后续也未按上述机制推进。","数据中心运维组在响应动作预置中，仅保留一份无备用的关键设备，最终异常发生时无预设动作可依。","数据中心运维组在关键节点值守中，关键节点保留备用通道，但异常发生时无预设动作可依。","数据中心运维组在风险等级研判中，关键节点保留备用通道，次生影响被压到最小。"],"answer":3,"explanation":"「预案触发」的构成要件为：①主体为数据中心运维组；②通过关键节点保留备用通道；③使次生影响被压到最小。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01916","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「共创工作坊」是指产品体验小组通过邀请使用者全程参与方案打磨，使方案贴合真实使用习惯的工作机制。\n\n按照上述界定，下列情形不应认定为「共创工作坊」的是：","options":["产品体验小组在服务流程梳理中，邀请使用者全程参与方案打磨，方案贴合真实使用习惯。","产品体验小组在公共界面优化中，邀请使用者全程参与方案打磨，方案贴合真实使用习惯。","产品体验小组在使用路径排查中，邀请使用者全程参与方案打磨，方案贴合真实使用习惯。","产品体验小组在公共界面优化中，照搬其他地区成品，最终上线后仍频发与习惯不符的障碍。"],"answer":3,"explanation":"「共创工作坊」的构成要件为：①主体为产品体验小组；②通过邀请使用者全程参与方案打磨；③使方案贴合真实使用习惯。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（照搬其他地区成品），因此不符合构成要件。故选D。"},{"id":"pdn01917","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「用户旅程映射」是指产品体验小组通过先做可体验原型再收集反馈，使隐蔽障碍在使用前被暴露的工作机制。\n\n根据上述定义，下列属于「用户旅程映射」的是：","options":["产品体验小组在公共界面优化中，一次性定稿不再接收反馈，最终上线后仍频发与习惯不符的障碍。","产品体验小组在使用路径排查中，先做可体验原型再收集反馈，但上线后仍频发与习惯不符的障碍。","由外部专家远程定稿，后续也未按上述机制推进。","产品体验小组在服务流程梳理中，先做可体验原型再收集反馈，隐蔽障碍在使用前被暴露。"],"answer":3,"explanation":"「用户旅程映射」的构成要件为：①主体为产品体验小组；②通过先做可体验原型再收集反馈；③使隐蔽障碍在使用前被暴露。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01918","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「需求导向供给」是指公共文化服务中心通过依据使用频次动态增减项目，使资源不再平均摊薄的工作机制。\n\n依据上述定义，以下哪一项不符合「需求导向供给」的构成要件：","options":["公共文化服务中心在对象需求摸排中，依据使用频次动态增减项目，资源不再平均摊薄。","公共文化服务中心在服务清单编制中，依据使用频次动态增减项目，资源不再平均摊薄。","公共文化服务中心在服务事项梳理中，依据使用频次动态增减项目，资源不再平均摊薄。","公共文化服务中心在对象需求摸排中，所有对象发放完全相同的固定包，最终大量项目无人使用而真实诉求仍被搁置。"],"answer":3,"explanation":"「需求导向供给」的构成要件为：①主体为公共文化服务中心；②通过依据使用频次动态增减项目；③使资源不再平均摊薄。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（所有对象发放完全相同的固定包），因此不符合构成要件。故选D。"},{"id":"pdn01919","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「目的限定」是指政务数据平台通过到期自动清理并留清理记录，使历史数据不再无限期堆积的工作机制。\n\n按照上述界定，下列情形可认定为「目的限定」的是：","options":["政务数据平台在数据调阅留痕中，到期自动清理并留清理记录，但与办理目的无关的字段仍被长期留存。","由外包人员全量导出，后续也未按上述机制推进。","政务数据平台在字段权限配置中，所有岗位开放同一份全量清单，最终与办理目的无关的字段仍被长期留存。","政务数据平台在信息采集登记中，到期自动清理并留清理记录，历史数据不再无限期堆积。"],"answer":3,"explanation":"「目的限定」的构成要件为：①主体为政务数据平台；②通过到期自动清理并留清理记录；③使历史数据不再无限期堆积。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01920","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「冗余备份」是指城市运行管理平台通过关键节点保留备用通道，使险情初起即进入有序处置的工作机制。\n\n根据上述定义，下列不属于「冗余备份」的是：","options":["城市运行管理平台在风险等级研判中，关键节点保留备用通道，险情初起即进入有序处置。","城市运行管理平台在关键节点值守中，关键节点保留备用通道，险情初起即进入有序处置。","城市运行管理平台在响应动作预置中，预案长期封存不随风险更新，最终异常发生时无预设动作可依。","城市运行管理平台在响应动作预置中，关键节点保留备用通道，险情初起即进入有序处置。"],"answer":2,"explanation":"「冗余备份」的构成要件为：①主体为城市运行管理平台；②通过关键节点保留备用通道；③使险情初起即进入有序处置。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（预案长期封存不随风险更新），因此不符合构成要件。故选C。"},{"id":"pdn01921","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「诊断性测评」是指课程组通过按阶段采集学情数据再修正教学，使学生的薄弱点被及时识别的工作机制。\n\n依据上述定义，以下哪一项符合「诊断性测评」的构成要件：","options":["课程组在作业反馈整理中，按阶段采集学情数据再修正教学，但教学安排并未因数据而作任何调整。","课程组在实验课程组织中，按固定名次划线且不追溯变化，最终教学安排并未因数据而作任何调整。","由学生互评后不再复核，后续也未按上述机制推进。","课程组在单元教学设计中，按阶段采集学情数据再修正教学，学生的薄弱点被及时识别。"],"answer":3,"explanation":"「诊断性测评」的构成要件为：①主体为课程组；②通过按阶段采集学情数据再修正教学；③使学生的薄弱点被及时识别。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01922","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「协同治理」是指区级牵头部门通过建立常态化联络与移交规则，使重复检查与推诿明显减少的工作机制。\n\n按照上述界定，下列情形不应认定为「协同治理」的是：","options":["区级牵头部门在联合排班安排中，各部门分头进场、结果互不通报，最终边界地带的问题仍在部门之间来回流转。","区级牵头部门在联合排班安排中，建立常态化联络与移交规则，重复检查与推诿明显减少。","区级牵头部门在跨界事项梳理中，建立常态化联络与移交规则，重复检查与推诿明显减少。","区级牵头部门在信息通报共享中，建立常态化联络与移交规则，重复检查与推诿明显减少。"],"answer":0,"explanation":"「协同治理」的构成要件为：①主体为区级牵头部门；②通过建立常态化联络与移交规则；③使重复检查与推诿明显减少。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（各部门分头进场、结果互不通报），因此不符合构成要件。故选A。"},{"id":"pdn01923","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「差异化供给」是指养老服务站点通过先摸清不同群体诉求再分类提供，使冷门项目被及时替换的工作机制。\n\n根据上述定义，下列属于「差异化供给」的是：","options":["由供应商单方决定目录，后续也未按上述机制推进。","养老服务站点在服务事项梳理中，先摸清不同群体诉求再分类提供，冷门项目被及时替换。","养老服务站点在对象需求摸排中，按编制人数而不是实际用量分配，最终大量项目无人使用而真实诉求仍被搁置。","养老服务站点在服务清单编制中，先摸清不同群体诉求再分类提供，但大量项目无人使用而真实诉求仍被搁置。"],"answer":1,"explanation":"「差异化供给」的构成要件为：①主体为养老服务站点；②通过先摸清不同群体诉求再分类提供；③使冷门项目被及时替换。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01924","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「小步试点」是指数字化转型办公室通过设置观察期并保留回退通道，使偏差在放大前被修正的工作机制。\n\n依据上述定义，以下哪一项不符合「小步试点」的构成要件：","options":["数字化转型办公室在新工具推广中，只记录成功案例不分析偏差，最终同类偏差在扩面后被成倍放大。","数字化转型办公室在新流程上线中，设置观察期并保留回退通道，偏差在放大前被修正。","数字化转型办公室在新机制落地中，设置观察期并保留回退通道，偏差在放大前被修正。","数字化转型办公室在新工具推广中，设置观察期并保留回退通道，偏差在放大前被修正。"],"answer":0,"explanation":"「小步试点」的构成要件为：①主体为数字化转型办公室；②通过设置观察期并保留回退通道；③使偏差在放大前被修正。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（只记录成功案例不分析偏差），因此不符合构成要件。故选A。"},{"id":"pdn01925","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「基线比对」是指统计调查队通过以多源数据交叉校验结论，使结论不易被个别异常值带偏的工作机制。\n\n按照上述界定，下列情形可认定为「基线比对」的是：","options":["统计调查队在抽样数据核查中，以多源数据交叉校验结论，但结论无法由所引数据支撑。","由第三方直接给结论不附依据，后续也未按上述机制推进。","统计调查队在年度计划编制中，以多源数据交叉校验结论，结论不易被个别异常值带偏。","统计调查队在政策效果评估中，指标口径中途变更却不说明，最终结论无法由所引数据支撑。"],"answer":2,"explanation":"「基线比对」的构成要件为：①主体为统计调查队；②通过以多源数据交叉校验结论；③使结论不易被个别异常值带偏。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01926","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「前置响应」是指村委会通过联合多方现场会商后再定方案，使重复投诉明显下降的工作机制。\n\n根据上述定义，下列不属于「前置响应」的是：","options":["村委会在老旧小区改造中，联合多方现场会商后再定方案，重复投诉明显下降。","村委会在邻里纠纷调解中，联合多方现场会商后再定方案，重复投诉明显下降。","村委会在便民事项办理中，联合多方现场会商后再定方案，重复投诉明显下降。","村委会在邻里纠纷调解中，直接照搬既有方案、未作任何征询，最终问题仍反复出现且未形成稳定机制。"],"answer":3,"explanation":"「前置响应」的构成要件为：①主体为村委会；②通过联合多方现场会商后再定方案；③使重复投诉明显下降。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（直接照搬既有方案、未作任何征询），因此不符合构成要件。故选D。"},{"id":"pdn01927","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「脱敏处理」是指公共服务窗口通过对外提供前作去标识化处理，使超范围信息不被额外索取的工作机制。\n\n依据上述定义，以下哪一项符合「脱敏处理」的构成要件：","options":["公共服务窗口在信息采集登记中，对外提供前作去标识化处理，超范围信息不被额外索取。","公共服务窗口在数据调阅留痕中，对外提供前作去标识化处理，但与办理目的无关的字段仍被长期留存。","公共服务窗口在字段权限配置中，所有岗位开放同一份全量清单，最终与办理目的无关的字段仍被长期留存。","由外包人员全量导出，后续也未按上述机制推进。"],"answer":0,"explanation":"「脱敏处理」的构成要件为：①主体为公共服务窗口；②通过对外提供前作去标识化处理；③使超范围信息不被额外索取。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01928","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「多元共治」是指流域联席会议通过建立常态化联络与移交规则，使重复检查与推诿明显减少的工作机制。\n\n按照上述界定，下列情形不应认定为「多元共治」的是：","options":["流域联席会议在联合排班安排中，遇跨界事项互相等待，最终边界地带的问题仍在部门之间来回流转。","流域联席会议在联合排班安排中，建立常态化联络与移交规则，重复检查与推诿明显减少。","流域联席会议在跨界事项梳理中，建立常态化联络与移交规则，重复检查与推诿明显减少。","流域联席会议在信息通报共享中，建立常态化联络与移交规则，重复检查与推诿明显减少。"],"answer":0,"explanation":"「多元共治」的构成要件为：①主体为流域联席会议；②通过建立常态化联络与移交规则；③使重复检查与推诿明显减少。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（遇跨界事项互相等待），因此不符合构成要件。故选A。"},{"id":"pdn01929","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「联勤联动」是指跨部门工作专班通过共享信息并同步排班，使跨界问题不再悬空的工作机制。\n\n根据上述定义，下列属于「联勤联动」的是：","options":["跨部门工作专班在跨界事项梳理中，共享信息并同步排班，跨界问题不再悬空。","跨部门工作专班在信息通报共享中，共享信息并同步排班，但边界地带的问题仍在部门之间来回流转。","由上级部门包办到底，后续也未按上述机制推进。","跨部门工作专班在联合排班安排中，各自按本部门旧流程办理，最终边界地带的问题仍在部门之间来回流转。"],"answer":0,"explanation":"「联勤联动」的构成要件为：①主体为跨部门工作专班；②通过共享信息并同步排班；③使跨界问题不再悬空。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01930","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「过程性考核」是指课程组通过随堂记录并及时反馈调整，使学生的薄弱点被及时识别的工作机制。\n\n依据上述定义，以下哪一项不符合「过程性考核」的构成要件：","options":["课程组在单元教学设计中，随堂记录并及时反馈调整，学生的薄弱点被及时识别。","课程组在实验课程组织中，随堂记录并及时反馈调整，学生的薄弱点被及时识别。","课程组在实验课程组织中，只以期末一次分数定结论，最终教学安排并未因数据而作任何调整。","课程组在作业反馈整理中，随堂记录并及时反馈调整，学生的薄弱点被及时识别。"],"answer":2,"explanation":"「过程性考核」的构成要件为：①主体为课程组；②通过随堂记录并及时反馈调整；③使学生的薄弱点被及时识别。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（只以期末一次分数定结论），因此不符合构成要件。故选C。"},{"id":"pdn01931","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「多元共治」是指跨部门工作专班通过一次会商形成分工清单，使响应口径保持一致的工作机制。\n\n按照上述界定，下列情形可认定为「多元共治」的是：","options":["跨部门工作专班在跨界事项梳理中，一次会商形成分工清单，响应口径保持一致。","跨部门工作专班在信息通报共享中，一次会商形成分工清单，但边界地带的问题仍在部门之间来回流转。","跨部门工作专班在联合排班安排中，只开会不落责任清单，最终边界地带的问题仍在部门之间来回流转。","由各区各自为政，后续也未按上述机制推进。"],"answer":0,"explanation":"「多元共治」的构成要件为：①主体为跨部门工作专班；②通过一次会商形成分工清单；③使响应口径保持一致。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01932","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「分区管控」是指自然保护区管理局通过划分区块实行差异化管护，使核心栖息地得到有效避让的工作机制。\n\n根据上述定义，下列不属于「分区管控」的是：","options":["自然保护区管理局在栖息环境变化中，划分区块实行差异化管护，核心栖息地得到有效避让。","自然保护区管理局在监测指标波动中，划分区块实行差异化管护，核心栖息地得到有效避让。","自然保护区管理局在外来因素扩散中，划分区块实行差异化管护，核心栖息地得到有效避让。","自然保护区管理局在栖息环境变化中，只看年度均值忽略峰值，最终指标已越界而措施仍维持不变。"],"answer":3,"explanation":"「分区管控」的构成要件为：①主体为自然保护区管理局；②通过划分区块实行差异化管护；③使核心栖息地得到有效避让。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（只看年度均值忽略峰值），因此不符合构成要件。故选D。"},{"id":"pdn01933","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「按需配置」是指农技推广站通过按对象条件分档配置资源，使供给与实际需求更加贴合的工作机制。\n\n依据上述定义，以下哪一项符合「按需配置」的构成要件：","options":["由服务对象自行寻找渠道，后续也未按上述机制推进。","农技推广站在对象需求摸排中，沿用上一年清单不作修订，最终大量项目无人使用而真实诉求仍被搁置。","农技推广站在服务事项梳理中，按对象条件分档配置资源，供给与实际需求更加贴合。","农技推广站在服务清单编制中，按对象条件分档配置资源，但大量项目无人使用而真实诉求仍被搁置。"],"answer":2,"explanation":"「按需配置」的构成要件为：①主体为农技推广站；②通过按对象条件分档配置资源；③使供给与实际需求更加贴合。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01934","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「用户旅程映射」是指社区营造团队通过先做可体验原型再收集反馈，使方案贴合真实使用习惯的工作机制。\n\n按照上述界定，下列情形不应认定为「用户旅程映射」的是：","options":["社区营造团队在公共界面优化中，先做可体验原型再收集反馈，方案贴合真实使用习惯。","社区营造团队在公共界面优化中，仅在完工后征求意见，最终上线后仍频发与习惯不符的障碍。","社区营造团队在服务流程梳理中，先做可体验原型再收集反馈，方案贴合真实使用习惯。","社区营造团队在使用路径排查中，先做可体验原型再收集反馈，方案贴合真实使用习惯。"],"answer":1,"explanation":"「用户旅程映射」的构成要件为：①主体为社区营造团队；②通过先做可体验原型再收集反馈；③使方案贴合真实使用习惯。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（仅在完工后征求意见），因此不符合构成要件。故选B。"},{"id":"pdn01935","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「形成性评价」是指学校教研组通过按阶段采集学情数据再修正教学，使学生的薄弱点被及时识别的工作机制。\n\n根据上述定义，下列属于「形成性评价」的是：","options":["学校教研组在作业反馈整理中，按阶段采集学情数据再修正教学，但教学安排并未因数据而作任何调整。","由家长自行报送成绩，后续也未按上述机制推进。","学校教研组在实验课程组织中，全程不作任何反馈、结束后才公布，最终教学安排并未因数据而作任何调整。","学校教研组在单元教学设计中，按阶段采集学情数据再修正教学，学生的薄弱点被及时识别。"],"answer":3,"explanation":"「形成性评价」的构成要件为：①主体为学校教研组；②通过按阶段采集学情数据再修正教学；③使学生的薄弱点被及时识别。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01936","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「菜单式服务」是指公共文化服务中心通过依据使用频次动态增减项目，使供给与实际需求更加贴合的工作机制。\n\n依据上述定义，以下哪一项不符合「菜单式服务」的构成要件：","options":["公共文化服务中心在对象需求摸排中，先采购再询问是否需要，最终大量项目无人使用而真实诉求仍被搁置。","公共文化服务中心在对象需求摸排中，依据使用频次动态增减项目，供给与实际需求更加贴合。","公共文化服务中心在服务清单编制中，依据使用频次动态增减项目，供给与实际需求更加贴合。","公共文化服务中心在服务事项梳理中，依据使用频次动态增减项目，供给与实际需求更加贴合。"],"answer":0,"explanation":"「菜单式服务」的构成要件为：①主体为公共文化服务中心；②通过依据使用频次动态增减项目；③使供给与实际需求更加贴合。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（先采购再询问是否需要），因此不符合构成要件。故选A。"},{"id":"pdn01937","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「差异化供给」是指养老服务站点通过依据使用频次动态增减项目，使冷门项目被及时替换的工作机制。\n\n按照上述界定，下列情形可认定为「差异化供给」的是：","options":["养老服务站点在对象需求摸排中，沿用上一年清单不作修订，最终大量项目无人使用而真实诉求仍被搁置。","养老服务站点在服务清单编制中，依据使用频次动态增减项目，但大量项目无人使用而真实诉求仍被搁置。","由服务对象自行寻找渠道，后续也未按上述机制推进。","养老服务站点在服务事项梳理中，依据使用频次动态增减项目，冷门项目被及时替换。"],"answer":3,"explanation":"「差异化供给」的构成要件为：①主体为养老服务站点；②通过依据使用频次动态增减项目；③使冷门项目被及时替换。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01938","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「预案触发」是指应急指挥中心通过按风险等级预置响应动作，使核心功能在异常下仍可维持的工作机制。\n\n根据上述定义，下列不属于「预案触发」的是：","options":["应急指挥中心在关键节点值守中，按风险等级预置响应动作，核心功能在异常下仍可维持。","应急指挥中心在风险等级研判中，按风险等级预置响应动作，核心功能在异常下仍可维持。","应急指挥中心在响应动作预置中，按风险等级预置响应动作，核心功能在异常下仍可维持。","应急指挥中心在响应动作预置中，等指标越限后才临时研究方案，最终异常发生时无预设动作可依。"],"answer":3,"explanation":"「预案触发」的构成要件为：①主体为应急指挥中心；②通过按风险等级预置响应动作；③使核心功能在异常下仍可维持。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（等指标越限后才临时研究方案），因此不符合构成要件。故选D。"},{"id":"pdn01939","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「随访管理」是指家庭医生团队通过按病情轻重分流并约定转诊路径，使重复检查明显减少的工作机制。\n\n依据上述定义，以下哪一项符合「随访管理」的构成要件：","options":["家庭医生团队在重点人群筛查中，按病情轻重分流并约定转诊路径，但各环节彼此脱节、患者仍需多次重复排队。","家庭医生团队在慢病随访安排中，按病情轻重分流并约定转诊路径，重复检查明显减少。","家庭医生团队在康复跟踪记录中，只做一次性检查不作后续跟踪，最终各环节彼此脱节、患者仍需多次重复排队。","仅由三甲医院单方建档，后续也未按上述机制推进。"],"answer":1,"explanation":"「随访管理」的构成要件为：①主体为家庭医生团队；②通过按病情轻重分流并约定转诊路径；③使重复检查明显减少。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01940","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「诊断性测评」是指区域教研中心通过结合真实任务表现打分，使后续目标更贴合实际起点的工作机制。\n\n按照上述界定，下列情形不应认定为「诊断性测评」的是：","options":["区域教研中心在实验课程组织中，照搬统一答案不看作答过程，最终教学安排并未因数据而作任何调整。","区域教研中心在实验课程组织中，结合真实任务表现打分，后续目标更贴合实际起点。","区域教研中心在单元教学设计中，结合真实任务表现打分，后续目标更贴合实际起点。","区域教研中心在作业反馈整理中，结合真实任务表现打分，后续目标更贴合实际起点。"],"answer":0,"explanation":"「诊断性测评」的构成要件为：①主体为区域教研中心；②通过结合真实任务表现打分；③使后续目标更贴合实际起点。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（照搬统一答案不看作答过程），因此不符合构成要件。故选A。"},{"id":"pdn01941","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「最小必要采集」是指公共服务窗口通过对外提供前作去标识化处理，使超范围信息不被额外索取的工作机制。\n\n根据上述定义，下列属于「最小必要采集」的是：","options":["公共服务窗口在字段权限配置中，超过期限仍不作清理，最终与办理目的无关的字段仍被长期留存。","公共服务窗口在信息采集登记中，对外提供前作去标识化处理，超范围信息不被额外索取。","由系统默认长期全量保留，后续也未按上述机制推进。","公共服务窗口在数据调阅留痕中，对外提供前作去标识化处理，但与办理目的无关的字段仍被长期留存。"],"answer":1,"explanation":"「最小必要采集」的构成要件为：①主体为公共服务窗口；②通过对外提供前作去标识化处理；③使超范围信息不被额外索取。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01942","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「阈值预警」是指自然保护区管理局通过按监测指标分档调整措施，使异常苗头被尽早识别的工作机制。\n\n依据上述定义，以下哪一项不符合「阈值预警」的构成要件：","options":["自然保护区管理局在外来因素扩散中，按监测指标分档调整措施，异常苗头被尽早识别。","自然保护区管理局在监测指标波动中，按监测指标分档调整措施，异常苗头被尽早识别。","自然保护区管理局在栖息环境变化中，按监测指标分档调整措施，异常苗头被尽早识别。","自然保护区管理局在栖息环境变化中，全年沿用同一套固定配额，最终指标已越界而措施仍维持不变。"],"answer":3,"explanation":"「阈值预警」的构成要件为：①主体为自然保护区管理局；②通过按监测指标分档调整措施；③使异常苗头被尽早识别。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（全年沿用同一套固定配额），因此不符合构成要件。故选D。"},{"id":"pdn01943","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「弹性调控」是指流域管理机构通过随季节数据滚动修订方案，使核心栖息地得到有效避让的工作机制。\n\n按照上述界定，下列情形可认定为「弹性调控」的是：","options":["流域管理机构在栖息环境变化中，指标超标后仍不调整，最终指标已越界而措施仍维持不变。","流域管理机构在监测指标波动中，随季节数据滚动修订方案，核心栖息地得到有效避让。","流域管理机构在外来因素扩散中，随季节数据滚动修订方案，但指标已越界而措施仍维持不变。","由邻近地区照抄方案，后续也未按上述机制推进。"],"answer":1,"explanation":"「弹性调控」的构成要件为：①主体为流域管理机构；②通过随季节数据滚动修订方案；③使核心栖息地得到有效避让。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01944","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「预案触发」是指城市运行管理平台通过按风险等级预置响应动作，使核心功能在异常下仍可维持的工作机制。\n\n根据上述定义，下列不属于「预案触发」的是：","options":["城市运行管理平台在响应动作预置中，按风险等级预置响应动作，核心功能在异常下仍可维持。","城市运行管理平台在响应动作预置中，预案长期封存不随风险更新，最终异常发生时无预设动作可依。","城市运行管理平台在风险等级研判中，按风险等级预置响应动作，核心功能在异常下仍可维持。","城市运行管理平台在关键节点值守中，按风险等级预置响应动作，核心功能在异常下仍可维持。"],"answer":1,"explanation":"「预案触发」的构成要件为：①主体为城市运行管理平台；②通过按风险等级预置响应动作；③使核心功能在异常下仍可维持。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（预案长期封存不随风险更新），因此不符合构成要件。故选B。"},{"id":"pdn01945","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「前置筛查」是指乡镇卫生院通过建立电子档案并定期回访，使患者往返成本下降的工作机制。\n\n依据上述定义，以下哪一项符合「前置筛查」的构成要件：","options":["由商业体检机构独立出具结论，后续也未按上述机制推进。","乡镇卫生院在慢病随访安排中，建立电子档案并定期回访，患者往返成本下降。","乡镇卫生院在康复跟踪记录中，待病情加重后再启动会诊，最终各环节彼此脱节、患者仍需多次重复排队。","乡镇卫生院在重点人群筛查中，建立电子档案并定期回访，但各环节彼此脱节、患者仍需多次重复排队。"],"answer":1,"explanation":"「前置筛查」的构成要件为：①主体为乡镇卫生院；②通过建立电子档案并定期回访；③使患者往返成本下降。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01946","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「脱敏处理」是指公共服务窗口通过按岗位授予最小可见范围，使超范围信息不被额外索取的工作机制。\n\n按照上述界定，下列情形不应认定为「脱敏处理」的是：","options":["公共服务窗口在字段权限配置中，为方便起见一次性收齐全部字段，最终与办理目的无关的字段仍被长期留存。","公共服务窗口在字段权限配置中，按岗位授予最小可见范围，超范围信息不被额外索取。","公共服务窗口在信息采集登记中，按岗位授予最小可见范围，超范围信息不被额外索取。","公共服务窗口在数据调阅留痕中，按岗位授予最小可见范围，超范围信息不被额外索取。"],"answer":0,"explanation":"「脱敏处理」的构成要件为：①主体为公共服务窗口；②通过按岗位授予最小可见范围；③使超范围信息不被额外索取。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（为方便起见一次性收齐全部字段），因此不符合构成要件。故选A。"},{"id":"pdn01947","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「参与式设计」是指产品体验小组通过邀请使用者全程参与方案打磨，使改动获得使用者认同的工作机制。\n\n根据上述定义，下列属于「参与式设计」的是：","options":["由供应商提供标准模板，后续也未按上述机制推进。","产品体验小组在使用路径排查中，邀请使用者全程参与方案打磨，但上线后仍频发与习惯不符的障碍。","产品体验小组在服务流程梳理中，邀请使用者全程参与方案打磨，改动获得使用者认同。","产品体验小组在公共界面优化中，只做内部评审不接触使用者，最终上线后仍频发与习惯不符的障碍。"],"answer":2,"explanation":"「参与式设计」的构成要件为：①主体为产品体验小组；②通过邀请使用者全程参与方案打磨；③使改动获得使用者认同。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01948","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「试错迭代」是指产品迭代小组通过分批次扩面而非一次铺开，使偏差在放大前被修正的工作机制。\n\n依据上述定义，以下哪一项不符合「试错迭代」的构成要件：","options":["产品迭代小组在新工具推广中，分批次扩面而非一次铺开，偏差在放大前被修正。","产品迭代小组在新机制落地中，分批次扩面而非一次铺开，偏差在放大前被修正。","产品迭代小组在新流程上线中，分批次扩面而非一次铺开，偏差在放大前被修正。","产品迭代小组在新工具推广中，只记录成功案例不分析偏差，最终同类偏差在扩面后被成倍放大。"],"answer":3,"explanation":"「试错迭代」的构成要件为：①主体为产品迭代小组；②通过分批次扩面而非一次铺开；③使偏差在放大前被修正。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（只记录成功案例不分析偏差），因此不符合构成要件。故选D。"},{"id":"pdn01949","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「可回溯核查」是指药品批发企业质控部通过异常批次可一键回溯全链路，使问题批次能被快速定位的工作机制。\n\n按照上述界定，下列情形可认定为「可回溯核查」的是：","options":["药品批发企业质控部在储运环节温控中，异常批次可一键回溯全链路，但出现问题时无法定位到具体环节。","由消费者事后反馈倒查，后续也未按上述机制推进。","药品批发企业质控部在批次交接记录中，仅保留汇总数不留明细，最终出现问题时无法定位到具体环节。","药品批发企业质控部在进货环节核验中，异常批次可一键回溯全链路，问题批次能被快速定位。"],"answer":3,"explanation":"「可回溯核查」的构成要件为：①主体为药品批发企业质控部；②通过异常批次可一键回溯全链路；③使问题批次能被快速定位。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01950","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「联勤联动」是指流域联席会议通过一次会商形成分工清单，使响应口径保持一致的工作机制。\n\n根据上述定义，下列不属于「联勤联动」的是：","options":["流域联席会议在信息通报共享中，一次会商形成分工清单，响应口径保持一致。","流域联席会议在跨界事项梳理中，一次会商形成分工清单，响应口径保持一致。","流域联席会议在联合排班安排中，一次会商形成分工清单，响应口径保持一致。","流域联席会议在联合排班安排中，各部门分头进场、结果互不通报，最终边界地带的问题仍在部门之间来回流转。"],"answer":3,"explanation":"「联勤联动」的构成要件为：①主体为流域联席会议；②通过一次会商形成分工清单；③使响应口径保持一致。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（各部门分头进场、结果互不通报），因此不符合构成要件。故选D。"},{"id":"pdn01951","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「阈值预警」是指湿地管护中心通过随季节数据滚动修订方案，使异常苗头被尽早识别的工作机制。\n\n依据上述定义，以下哪一项符合「阈值预警」的构成要件：","options":["湿地管护中心在监测指标波动中，随季节数据滚动修订方案，异常苗头被尽早识别。","由邻近地区照抄方案，后续也未按上述机制推进。","湿地管护中心在栖息环境变化中，指标超标后仍不调整，最终指标已越界而措施仍维持不变。","湿地管护中心在外来因素扩散中，随季节数据滚动修订方案，但指标已越界而措施仍维持不变。"],"answer":0,"explanation":"「阈值预警」的构成要件为：①主体为湿地管护中心；②通过随季节数据滚动修订方案；③使异常苗头被尽早识别。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01952","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「留痕管理」是指药品批发企业质控部通过每一节点登记并关联上下游凭证，使召回范围精确到具体批次的工作机制。\n\n按照上述界定，下列情形不应认定为「留痕管理」的是：","options":["药品批发企业质控部在批次交接记录中，每一节点登记并关联上下游凭证，召回范围精确到具体批次。","药品批发企业质控部在进货环节核验中，每一节点登记并关联上下游凭证，召回范围精确到具体批次。","药品批发企业质控部在批次交接记录中，事后一次性补全整本台账，最终出现问题时无法定位到具体环节。","药品批发企业质控部在储运环节温控中，每一节点登记并关联上下游凭证，召回范围精确到具体批次。"],"answer":2,"explanation":"「留痕管理」的构成要件为：①主体为药品批发企业质控部；②通过每一节点登记并关联上下游凭证；③使召回范围精确到具体批次。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（事后一次性补全整本台账），因此不符合构成要件。故选C。"},{"id":"pdn01953","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「按需配置」是指公共文化服务中心通过依据使用频次动态增减项目，使供给与实际需求更加贴合的工作机制。\n\n根据上述定义，下列属于「按需配置」的是：","options":["由服务对象自行寻找渠道，后续也未按上述机制推进。","公共文化服务中心在服务事项梳理中，依据使用频次动态增减项目，供给与实际需求更加贴合。","公共文化服务中心在服务清单编制中，依据使用频次动态增减项目，但大量项目无人使用而真实诉求仍被搁置。","公共文化服务中心在对象需求摸排中，沿用上一年清单不作修订，最终大量项目无人使用而真实诉求仍被搁置。"],"answer":1,"explanation":"「按需配置」的构成要件为：①主体为公共文化服务中心；②通过依据使用频次动态增减项目；③使供给与实际需求更加贴合。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01954","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「目的限定」是指医院信息科通过按岗位授予最小可见范围，使历史数据不再无限期堆积的工作机制。\n\n依据上述定义，以下哪一项不符合「目的限定」的构成要件：","options":["医院信息科在信息采集登记中，按岗位授予最小可见范围，历史数据不再无限期堆积。","医院信息科在数据调阅留痕中，按岗位授予最小可见范围，历史数据不再无限期堆积。","医院信息科在字段权限配置中，为方便起见一次性收齐全部字段，最终与办理目的无关的字段仍被长期留存。","医院信息科在字段权限配置中，按岗位授予最小可见范围，历史数据不再无限期堆积。"],"answer":2,"explanation":"「目的限定」的构成要件为：①主体为医院信息科；②通过按岗位授予最小可见范围；③使历史数据不再无限期堆积。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（为方便起见一次性收齐全部字段），因此不符合构成要件。故选C。"},{"id":"pdn01955","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「指标复核」是指项目评审委员会通过先确立基线再对照前后变化，使成效与措施之间的对应更清楚的工作机制。\n\n按照上述界定，下列情形可认定为「指标复核」的是：","options":["项目评审委员会在年度计划编制中，先确立基线再对照前后变化，成效与措施之间的对应更清楚。","项目评审委员会在抽样数据核查中，先确立基线再对照前后变化，但结论无法由所引数据支撑。","由申报方自行填报不作核实，后续也未按上述机制推进。","项目评审委员会在政策效果评估中，用总量变化直接归因、不作对照，最终结论无法由所引数据支撑。"],"answer":0,"explanation":"「指标复核」的构成要件为：①主体为项目评审委员会；②通过先确立基线再对照前后变化；③使成效与措施之间的对应更清楚。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01956","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「随访管理」是指社区卫生服务中心通过先由基层评估再决定是否上转，使病情变化能被尽早发现的工作机制。\n\n根据上述定义，下列不属于「随访管理」的是：","options":["社区卫生服务中心在康复跟踪记录中，先由基层评估再决定是否上转，病情变化能被尽早发现。","社区卫生服务中心在慢病随访安排中，先由基层评估再决定是否上转，病情变化能被尽早发现。","社区卫生服务中心在康复跟踪记录中，各机构各自重复开单，最终各环节彼此脱节、患者仍需多次重复排队。","社区卫生服务中心在重点人群筛查中，先由基层评估再决定是否上转，病情变化能被尽早发现。"],"answer":2,"explanation":"「随访管理」的构成要件为：①主体为社区卫生服务中心；②通过先由基层评估再决定是否上转；③使病情变化能被尽早发现。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（各机构各自重复开单），因此不符合构成要件。故选C。"},{"id":"pdn01957","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「小步试点」是指改革推进专班通过每轮结束后复盘并修订下一轮，使方案随实际反馈逐步完善的工作机制。\n\n依据上述定义，以下哪一项符合「小步试点」的构成要件：","options":["由用户自行摸索不作收集，后续也未按上述机制推进。","改革推进专班在新工具推广中，一次上线后即固化不再迭代，最终同类偏差在扩面后被成倍放大。","改革推进专班在新机制落地中，每轮结束后复盘并修订下一轮，但同类偏差在扩面后被成倍放大。","改革推进专班在新流程上线中，每轮结束后复盘并修订下一轮，方案随实际反馈逐步完善。"],"answer":3,"explanation":"「小步试点」的构成要件为：①主体为改革推进专班；②通过每轮结束后复盘并修订下一轮；③使方案随实际反馈逐步完善。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01958","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「数据校验」是指政策评估小组通过对关键指标作独立复核，使成效与措施之间的对应更清楚的工作机制。\n\n按照上述界定，下列情形不应认定为「数据校验」的是：","options":["政策评估小组在政策效果评估中，对关键指标作独立复核，成效与措施之间的对应更清楚。","政策评估小组在抽样数据核查中，对关键指标作独立复核，成效与措施之间的对应更清楚。","政策评估小组在年度计划编制中，对关键指标作独立复核，成效与措施之间的对应更清楚。","政策评估小组在政策效果评估中，只选取有利样本作展示，最终结论无法由所引数据支撑。"],"answer":3,"explanation":"「数据校验」的构成要件为：①主体为政策评估小组；②通过对关键指标作独立复核；③使成效与措施之间的对应更清楚。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（只选取有利样本作展示），因此不符合构成要件。故选D。"},{"id":"pdn01959","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「弹性调控」是指流域管理机构通过随季节数据滚动修订方案，使管控成本保持在合理区间的工作机制。\n\n根据上述定义，下列属于「弹性调控」的是：","options":["由邻近地区照抄方案，后续也未按上述机制推进。","流域管理机构在栖息环境变化中，指标超标后仍不调整，最终指标已越界而措施仍维持不变。","流域管理机构在监测指标波动中，随季节数据滚动修订方案，管控成本保持在合理区间。","流域管理机构在外来因素扩散中，随季节数据滚动修订方案，但指标已越界而措施仍维持不变。"],"answer":2,"explanation":"「弹性调控」的构成要件为：①主体为流域管理机构；②通过随季节数据滚动修订方案；③使管控成本保持在合理区间。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01960","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「前置筛查」是指县域医共体通过先由基层评估再决定是否上转，使重复检查明显减少的工作机制。\n\n依据上述定义，以下哪一项不符合「前置筛查」的构成要件：","options":["县域医共体在康复跟踪记录中，各机构各自重复开单，最终各环节彼此脱节、患者仍需多次重复排队。","县域医共体在慢病随访安排中，先由基层评估再决定是否上转，重复检查明显减少。","县域医共体在康复跟踪记录中，先由基层评估再决定是否上转，重复检查明显减少。","县域医共体在重点人群筛查中，先由基层评估再决定是否上转，重复检查明显减少。"],"answer":0,"explanation":"「前置筛查」的构成要件为：①主体为县域医共体；②通过先由基层评估再决定是否上转；③使重复检查明显减少。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（各机构各自重复开单），因此不符合构成要件。故选A。"},{"id":"pdn01961","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「分级预警」是指数据中心运维组通过设定触发条件并提前布防，使次生影响被压到最小的工作机制。\n\n按照上述界定，下列情形可认定为「分级预警」的是：","options":["数据中心运维组在风险等级研判中，设定触发条件并提前布防，次生影响被压到最小。","数据中心运维组在关键节点值守中，设定触发条件并提前布防，但异常发生时无预设动作可依。","数据中心运维组在响应动作预置中，只在事发后补充记录，最终异常发生时无预设动作可依。","由外部单位事后支援，后续也未按上述机制推进。"],"answer":0,"explanation":"「分级预警」的构成要件为：①主体为数据中心运维组；②通过设定触发条件并提前布防；③使次生影响被压到最小。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01962","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「联合响应」是指区级牵头部门通过明确牵头与配合边界后统一行动，使响应口径保持一致的工作机制。\n\n根据上述定义，下列不属于「联合响应」的是：","options":["区级牵头部门在联合排班安排中，各部门分头进场、结果互不通报，最终边界地带的问题仍在部门之间来回流转。","区级牵头部门在跨界事项梳理中，明确牵头与配合边界后统一行动，响应口径保持一致。","区级牵头部门在信息通报共享中，明确牵头与配合边界后统一行动，响应口径保持一致。","区级牵头部门在联合排班安排中，明确牵头与配合边界后统一行动，响应口径保持一致。"],"answer":0,"explanation":"「联合响应」的构成要件为：①主体为区级牵头部门；②通过明确牵头与配合边界后统一行动；③使响应口径保持一致。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（各部门分头进场、结果互不通报），因此不符合构成要件。故选A。"},{"id":"pdn01963","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「参与式设计」是指公共服务设计组通过多轮共创后收敛为最终版本，使改动获得使用者认同的工作机制。\n\n依据上述定义，以下哪一项符合「参与式设计」的构成要件：","options":["公共服务设计组在使用路径排查中，多轮共创后收敛为最终版本，但上线后仍频发与习惯不符的障碍。","由供应商提供标准模板，后续也未按上述机制推进。","公共服务设计组在服务流程梳理中，多轮共创后收敛为最终版本，改动获得使用者认同。","公共服务设计组在公共界面优化中，只做内部评审不接触使用者，最终上线后仍频发与习惯不符的障碍。"],"answer":2,"explanation":"「参与式设计」的构成要件为：①主体为公共服务设计组；②通过多轮共创后收敛为最终版本；③使改动获得使用者认同。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01964","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「按需配置」是指就业服务窗口通过先摸清不同群体诉求再分类提供，使冷门项目被及时替换的工作机制。\n\n按照上述界定，下列情形不应认定为「按需配置」的是：","options":["就业服务窗口在服务清单编制中，先摸清不同群体诉求再分类提供，冷门项目被及时替换。","就业服务窗口在对象需求摸排中，先摸清不同群体诉求再分类提供，冷门项目被及时替换。","就业服务窗口在服务事项梳理中，先摸清不同群体诉求再分类提供，冷门项目被及时替换。","就业服务窗口在对象需求摸排中，先采购再询问是否需要，最终大量项目无人使用而真实诉求仍被搁置。"],"answer":3,"explanation":"「按需配置」的构成要件为：①主体为就业服务窗口；②通过先摸清不同群体诉求再分类提供；③使冷门项目被及时替换。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（先采购再询问是否需要），因此不符合构成要件。故选D。"},{"id":"pdn01965","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「协同会商」是指村委会通过建立台账逐项限时销号，使平均处置周期缩短的工作机制。\n\n根据上述定义，下列属于「协同会商」的是：","options":["村委会在邻里纠纷调解中，各口径分头办理、彼此不通气，最终问题仍反复出现且未形成稳定机制。","村委会在便民事项办理中，建立台账逐项限时销号，但问题仍反复出现且未形成稳定机制。","由服务对象自行申报后不再跟进，后续也未按上述机制推进。","村委会在老旧小区改造中，建立台账逐项限时销号，平均处置周期缩短。"],"answer":3,"explanation":"「协同会商」的构成要件为：①主体为村委会；②通过建立台账逐项限时销号；③使平均处置周期缩短。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01966","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「联合响应」是指区级牵头部门通过一次会商形成分工清单，使重复检查与推诿明显减少的工作机制。\n\n依据上述定义，以下哪一项不符合「联合响应」的构成要件：","options":["区级牵头部门在联合排班安排中，各部门分头进场、结果互不通报，最终边界地带的问题仍在部门之间来回流转。","区级牵头部门在信息通报共享中，一次会商形成分工清单，重复检查与推诿明显减少。","区级牵头部门在跨界事项梳理中，一次会商形成分工清单，重复检查与推诿明显减少。","区级牵头部门在联合排班安排中，一次会商形成分工清单，重复检查与推诿明显减少。"],"answer":0,"explanation":"「联合响应」的构成要件为：①主体为区级牵头部门；②通过一次会商形成分工清单；③使重复检查与推诿明显减少。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（各部门分头进场、结果互不通报），因此不符合构成要件。故选A。"},{"id":"pdn01967","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「指标复核」是指政策评估小组通过对关键指标作独立复核，使后续调整有据可依的工作机制。\n\n按照上述界定，下列情形可认定为「指标复核」的是：","options":["政策评估小组在年度计划编制中，对关键指标作独立复核，后续调整有据可依。","政策评估小组在抽样数据核查中，对关键指标作独立复核，但结论无法由所引数据支撑。","政策评估小组在政策效果评估中，用总量变化直接归因、不作对照，最终结论无法由所引数据支撑。","由申报方自行填报不作核实，后续也未按上述机制推进。"],"answer":0,"explanation":"「指标复核」的构成要件为：①主体为政策评估小组；②通过对关键指标作独立复核；③使后续调整有据可依。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01968","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「可回溯核查」是指药品批发企业质控部通过按批号串联台账与检验记录，使问题批次能被快速定位的工作机制。\n\n根据上述定义，下列不属于「可回溯核查」的是：","options":["药品批发企业质控部在进货环节核验中，按批号串联台账与检验记录，问题批次能被快速定位。","药品批发企业质控部在批次交接记录中，事后一次性补全整本台账，最终出现问题时无法定位到具体环节。","药品批发企业质控部在储运环节温控中，按批号串联台账与检验记录，问题批次能被快速定位。","药品批发企业质控部在批次交接记录中，按批号串联台账与检验记录，问题批次能被快速定位。"],"answer":1,"explanation":"「可回溯核查」的构成要件为：①主体为药品批发企业质控部；②通过按批号串联台账与检验记录；③使问题批次能被快速定位。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（事后一次性补全整本台账），因此不符合构成要件。故选B。"},{"id":"pdn01969","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「增值评价」是指任课教师团队通过先摸清起点再设定分层目标，使学习过程而非仅结果被看见的工作机制。\n\n依据上述定义，以下哪一项符合「增值评价」的构成要件：","options":["任课教师团队在实验课程组织中，按固定名次划线且不追溯变化，最终教学安排并未因数据而作任何调整。","任课教师团队在作业反馈整理中，先摸清起点再设定分层目标，但教学安排并未因数据而作任何调整。","任课教师团队在单元教学设计中，先摸清起点再设定分层目标，学习过程而非仅结果被看见。","由学生互评后不再复核，后续也未按上述机制推进。"],"answer":2,"explanation":"「增值评价」的构成要件为：①主体为任课教师团队；②通过先摸清起点再设定分层目标；③使学习过程而非仅结果被看见。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01970","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「复盘改进」是指产品迭代小组通过每轮结束后复盘并修订下一轮，使风险被限制在可控范围的工作机制。\n\n按照上述界定，下列情形不应认定为「复盘改进」的是：","options":["产品迭代小组在新流程上线中，每轮结束后复盘并修订下一轮，风险被限制在可控范围。","产品迭代小组在新工具推广中，每轮结束后复盘并修订下一轮，风险被限制在可控范围。","产品迭代小组在新机制落地中，每轮结束后复盘并修订下一轮，风险被限制在可控范围。","产品迭代小组在新工具推广中，不经试点直接全面强制推开，最终同类偏差在扩面后被成倍放大。"],"answer":3,"explanation":"「复盘改进」的构成要件为：①主体为产品迭代小组；②通过每轮结束后复盘并修订下一轮；③使风险被限制在可控范围。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（不经试点直接全面强制推开），因此不符合构成要件。故选D。"},{"id":"pdn01971","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「双向转诊」是指家庭医生团队通过与上级医院共享检查结果，使患者往返成本下降的工作机制。\n\n根据上述定义，下列属于「双向转诊」的是：","options":["家庭医生团队在重点人群筛查中，与上级医院共享检查结果，但各环节彼此脱节、患者仍需多次重复排队。","家庭医生团队在康复跟踪记录中，只做一次性检查不作后续跟踪，最终各环节彼此脱节、患者仍需多次重复排队。","仅由三甲医院单方建档，后续也未按上述机制推进。","家庭医生团队在慢病随访安排中，与上级医院共享检查结果，患者往返成本下降。"],"answer":3,"explanation":"「双向转诊」的构成要件为：①主体为家庭医生团队；②通过与上级医院共享检查结果；③使患者往返成本下降。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01972","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「冗余备份」是指水利工程调度处通过识别薄弱环节并预先加固，使次生影响被压到最小的工作机制。\n\n依据上述定义，以下哪一项不符合「冗余备份」的构成要件：","options":["水利工程调度处在风险等级研判中，识别薄弱环节并预先加固，次生影响被压到最小。","水利工程调度处在响应动作预置中，识别薄弱环节并预先加固，次生影响被压到最小。","水利工程调度处在关键节点值守中，识别薄弱环节并预先加固，次生影响被压到最小。","水利工程调度处在响应动作预置中，预案长期封存不随风险更新，最终异常发生时无预设动作可依。"],"answer":3,"explanation":"「冗余备份」的构成要件为：①主体为水利工程调度处；②通过识别薄弱环节并预先加固；③使次生影响被压到最小。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（预案长期封存不随风险更新），因此不符合构成要件。故选D。"},{"id":"pdn01973","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「多元共治」是指街道与职能站所通过共享信息并同步排班，使响应口径保持一致的工作机制。\n\n按照上述界定，下列情形可认定为「多元共治」的是：","options":["街道与职能站所在信息通报共享中，共享信息并同步排班，但边界地带的问题仍在部门之间来回流转。","街道与职能站所在联合排班安排中，各自按本部门旧流程办理，最终边界地带的问题仍在部门之间来回流转。","由上级部门包办到底，后续也未按上述机制推进。","街道与职能站所在跨界事项梳理中，共享信息并同步排班，响应口径保持一致。"],"answer":3,"explanation":"「多元共治」的构成要件为：①主体为街道与职能站所；②通过共享信息并同步排班；③使响应口径保持一致。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01974","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「协同会商」是指乡镇便民中心通过提前公示并逐户征询意见，使平均处置周期缩短的工作机制。\n\n根据上述定义，下列不属于「协同会商」的是：","options":["乡镇便民中心在便民事项办理中，提前公示并逐户征询意见，平均处置周期缩短。","乡镇便民中心在老旧小区改造中，提前公示并逐户征询意见，平均处置周期缩短。","乡镇便民中心在邻里纠纷调解中，直接照搬既有方案、未作任何征询，最终问题仍反复出现且未形成稳定机制。","乡镇便民中心在邻里纠纷调解中，提前公示并逐户征询意见，平均处置周期缩短。"],"answer":2,"explanation":"「协同会商」的构成要件为：①主体为乡镇便民中心；②通过提前公示并逐户征询意见；③使平均处置周期缩短。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（直接照搬既有方案、未作任何征询），因此不符合构成要件。故选C。"},{"id":"pdn01975","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「参与式设计」是指无障碍改造专班通过先做可体验原型再收集反馈，使改动获得使用者认同的工作机制。\n\n依据上述定义，以下哪一项符合「参与式设计」的构成要件：","options":["无障碍改造专班在服务流程梳理中，先做可体验原型再收集反馈，改动获得使用者认同。","由供应商提供标准模板，后续也未按上述机制推进。","无障碍改造专班在公共界面优化中，只做内部评审不接触使用者，最终上线后仍频发与习惯不符的障碍。","无障碍改造专班在使用路径排查中，先做可体验原型再收集反馈，但上线后仍频发与习惯不符的障碍。"],"answer":0,"explanation":"「参与式设计」的构成要件为：①主体为无障碍改造专班；②通过先做可体验原型再收集反馈；③使改动获得使用者认同。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn01976","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「预案触发」是指水利工程调度处通过设定触发条件并提前布防，使险情初起即进入有序处置的工作机制。\n\n按照上述界定，下列情形不应认定为「预案触发」的是：","options":["水利工程调度处在响应动作预置中，设定触发条件并提前布防，险情初起即进入有序处置。","水利工程调度处在风险等级研判中，设定触发条件并提前布防，险情初起即进入有序处置。","水利工程调度处在响应动作预置中，预案长期封存不随风险更新，最终异常发生时无预设动作可依。","水利工程调度处在关键节点值守中，设定触发条件并提前布防，险情初起即进入有序处置。"],"answer":2,"explanation":"「预案触发」的构成要件为：①主体为水利工程调度处；②通过设定触发条件并提前布防；③使险情初起即进入有序处置。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（预案长期封存不随风险更新），因此不符合构成要件。故选C。"},{"id":"pdn01977","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「留存限期」是指学校学籍管理系统通过对外提供前作去标识化处理，使敏感字段仅在授权场景可见的工作机制。\n\n根据上述定义，下列属于「留存限期」的是：","options":["学校学籍管理系统在数据调阅留痕中，对外提供前作去标识化处理，但与办理目的无关的字段仍被长期留存。","学校学籍管理系统在字段权限配置中，超过期限仍不作清理，最终与办理目的无关的字段仍被长期留存。","学校学籍管理系统在信息采集登记中，对外提供前作去标识化处理，敏感字段仅在授权场景可见。","由系统默认长期全量保留，后续也未按上述机制推进。"],"answer":2,"explanation":"「留存限期」的构成要件为：①主体为学校学籍管理系统；②通过对外提供前作去标识化处理；③使敏感字段仅在授权场景可见。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01978","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「需求导向供给」是指就业服务窗口通过按对象条件分档配置资源，使供给与实际需求更加贴合的工作机制。\n\n依据上述定义，以下哪一项不符合「需求导向供给」的构成要件：","options":["就业服务窗口在服务清单编制中，按对象条件分档配置资源，供给与实际需求更加贴合。","就业服务窗口在服务事项梳理中，按对象条件分档配置资源，供给与实际需求更加贴合。","就业服务窗口在对象需求摸排中，按对象条件分档配置资源，供给与实际需求更加贴合。","就业服务窗口在对象需求摸排中，所有对象发放完全相同的固定包，最终大量项目无人使用而真实诉求仍被搁置。"],"answer":3,"explanation":"「需求导向供给」的构成要件为：①主体为就业服务窗口；②通过按对象条件分档配置资源；③使供给与实际需求更加贴合。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（所有对象发放完全相同的固定包），因此不符合构成要件。故选D。"},{"id":"pdn01979","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「增值评价」是指学校教研组通过结合真实任务表现打分，使后续目标更贴合实际起点的工作机制。\n\n按照上述界定，下列情形可认定为「增值评价」的是：","options":["学校教研组在作业反馈整理中，结合真实任务表现打分，但教学安排并未因数据而作任何调整。","学校教研组在实验课程组织中，全程不作任何反馈、结束后才公布，最终教学安排并未因数据而作任何调整。","由家长自行报送成绩，后续也未按上述机制推进。","学校教研组在单元教学设计中，结合真实任务表现打分，后续目标更贴合实际起点。"],"answer":3,"explanation":"「增值评价」的构成要件为：①主体为学校教研组；②通过结合真实任务表现打分；③使后续目标更贴合实际起点。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01980","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「协同治理」是指街道与职能站所通过明确牵头与配合边界后统一行动，使响应口径保持一致的工作机制。\n\n根据上述定义，下列不属于「协同治理」的是：","options":["街道与职能站所在联合排班安排中，明确牵头与配合边界后统一行动，响应口径保持一致。","街道与职能站所在联合排班安排中，遇跨界事项互相等待，最终边界地带的问题仍在部门之间来回流转。","街道与职能站所在跨界事项梳理中，明确牵头与配合边界后统一行动，响应口径保持一致。","街道与职能站所在信息通报共享中，明确牵头与配合边界后统一行动，响应口径保持一致。"],"answer":1,"explanation":"「协同治理」的构成要件为：①主体为街道与职能站所；②通过明确牵头与配合边界后统一行动；③使响应口径保持一致。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（遇跨界事项互相等待），因此不符合构成要件。故选B。"},{"id":"pdn01981","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「全过程追溯」是指冷链运营方通过异常批次可一键回溯全链路，使召回范围精确到具体批次的工作机制。\n\n依据上述定义，以下哪一项符合「全过程追溯」的构成要件：","options":["冷链运营方在批次交接记录中，仅保留汇总数不留明细，最终出现问题时无法定位到具体环节。","冷链运营方在储运环节温控中，异常批次可一键回溯全链路，但出现问题时无法定位到具体环节。","由消费者事后反馈倒查，后续也未按上述机制推进。","冷链运营方在进货环节核验中，异常批次可一键回溯全链路，召回范围精确到具体批次。"],"answer":3,"explanation":"「全过程追溯」的构成要件为：①主体为冷链运营方；②通过异常批次可一键回溯全链路；③使召回范围精确到具体批次。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01982","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「脱敏处理」是指政务数据平台通过对外提供前作去标识化处理，使敏感字段仅在授权场景可见的工作机制。\n\n按照上述界定，下列情形不应认定为「脱敏处理」的是：","options":["政务数据平台在数据调阅留痕中，对外提供前作去标识化处理，敏感字段仅在授权场景可见。","政务数据平台在字段权限配置中，为方便起见一次性收齐全部字段，最终与办理目的无关的字段仍被长期留存。","政务数据平台在信息采集登记中，对外提供前作去标识化处理，敏感字段仅在授权场景可见。","政务数据平台在字段权限配置中，对外提供前作去标识化处理，敏感字段仅在授权场景可见。"],"answer":1,"explanation":"「脱敏处理」的构成要件为：①主体为政务数据平台；②通过对外提供前作去标识化处理；③使敏感字段仅在授权场景可见。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（为方便起见一次性收齐全部字段），因此不符合构成要件。故选B。"},{"id":"pdn01983","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「连续照护」是指乡镇卫生院通过先由基层评估再决定是否上转，使重复检查明显减少的工作机制。\n\n根据上述定义，下列属于「连续照护」的是：","options":["乡镇卫生院在康复跟踪记录中，只做一次性检查不作后续跟踪，最终各环节彼此脱节、患者仍需多次重复排队。","仅由三甲医院单方建档，后续也未按上述机制推进。","乡镇卫生院在重点人群筛查中，先由基层评估再决定是否上转，但各环节彼此脱节、患者仍需多次重复排队。","乡镇卫生院在慢病随访安排中，先由基层评估再决定是否上转，重复检查明显减少。"],"answer":3,"explanation":"「连续照护」的构成要件为：①主体为乡镇卫生院；②通过先由基层评估再决定是否上转；③使重复检查明显减少。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01984","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「循证施策」是指规划编制组通过以多源数据交叉校验结论，使后续调整有据可依的工作机制。\n\n依据上述定义，以下哪一项不符合「循证施策」的构成要件：","options":["规划编制组在政策效果评估中，以主观感受替代实测数据，最终结论无法由所引数据支撑。","规划编制组在抽样数据核查中，以多源数据交叉校验结论，后续调整有据可依。","规划编制组在政策效果评估中，以多源数据交叉校验结论，后续调整有据可依。","规划编制组在年度计划编制中，以多源数据交叉校验结论，后续调整有据可依。"],"answer":0,"explanation":"「循证施策」的构成要件为：①主体为规划编制组；②通过以多源数据交叉校验结论；③使后续调整有据可依。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（以主观感受替代实测数据），因此不符合构成要件。故选A。"},{"id":"pdn01985","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「分区管控」是指流域管理机构通过按监测指标分档调整措施，使管控成本保持在合理区间的工作机制。\n\n按照上述界定，下列情形可认定为「分区管控」的是：","options":["流域管理机构在外来因素扩散中，按监测指标分档调整措施，但指标已越界而措施仍维持不变。","流域管理机构在栖息环境变化中，等出现明显损害后再启动处置，最终指标已越界而措施仍维持不变。","流域管理机构在监测指标波动中，按监测指标分档调整措施，管控成本保持在合理区间。","由游客反馈临时决定，后续也未按上述机制推进。"],"answer":2,"explanation":"「分区管控」的构成要件为：①主体为流域管理机构；②通过按监测指标分档调整措施；③使管控成本保持在合理区间。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01986","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「循证施策」是指统计调查队通过先确立基线再对照前后变化，使后续调整有据可依的工作机制。\n\n根据上述定义，下列不属于「循证施策」的是：","options":["统计调查队在年度计划编制中，先确立基线再对照前后变化，后续调整有据可依。","统计调查队在抽样数据核查中，先确立基线再对照前后变化，后续调整有据可依。","统计调查队在政策效果评估中，只选取有利样本作展示，最终结论无法由所引数据支撑。","统计调查队在政策效果评估中，先确立基线再对照前后变化，后续调整有据可依。"],"answer":2,"explanation":"「循证施策」的构成要件为：①主体为统计调查队；②通过先确立基线再对照前后变化；③使后续调整有据可依。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（只选取有利样本作展示），因此不符合构成要件。故选C。"},{"id":"pdn01987","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「形成性评价」是指课程组通过先摸清起点再设定分层目标，使学生的薄弱点被及时识别的工作机制。\n\n依据上述定义，以下哪一项符合「形成性评价」的构成要件：","options":["课程组在作业反馈整理中，先摸清起点再设定分层目标，但教学安排并未因数据而作任何调整。","课程组在单元教学设计中，先摸清起点再设定分层目标，学生的薄弱点被及时识别。","课程组在实验课程组织中，全程不作任何反馈、结束后才公布，最终教学安排并未因数据而作任何调整。","由家长自行报送成绩，后续也未按上述机制推进。"],"answer":1,"explanation":"「形成性评价」的构成要件为：①主体为课程组；②通过先摸清起点再设定分层目标；③使学生的薄弱点被及时识别。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01988","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「跨界协作」是指流域联席会议通过建立常态化联络与移交规则，使响应口径保持一致的工作机制。\n\n按照上述界定，下列情形不应认定为「跨界协作」的是：","options":["流域联席会议在信息通报共享中，建立常态化联络与移交规则，响应口径保持一致。","流域联席会议在跨界事项梳理中，建立常态化联络与移交规则，响应口径保持一致。","流域联席会议在联合排班安排中，遇跨界事项互相等待，最终边界地带的问题仍在部门之间来回流转。","流域联席会议在联合排班安排中，建立常态化联络与移交规则，响应口径保持一致。"],"answer":2,"explanation":"「跨界协作」的构成要件为：①主体为流域联席会议；②通过建立常态化联络与移交规则；③使响应口径保持一致。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（遇跨界事项互相等待），因此不符合构成要件。故选C。"},{"id":"pdn01989","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「分级授权」是指政务数据平台通过按岗位授予最小可见范围，使超范围信息不被额外索取的工作机制。\n\n根据上述定义，下列属于「分级授权」的是：","options":["由系统默认长期全量保留，后续也未按上述机制推进。","政务数据平台在数据调阅留痕中，按岗位授予最小可见范围，但与办理目的无关的字段仍被长期留存。","政务数据平台在字段权限配置中，超过期限仍不作清理，最终与办理目的无关的字段仍被长期留存。","政务数据平台在信息采集登记中，按岗位授予最小可见范围，超范围信息不被额外索取。"],"answer":3,"explanation":"「分级授权」的构成要件为：①主体为政务数据平台；②通过按岗位授予最小可见范围；③使超范围信息不被额外索取。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01990","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「菜单式服务」是指农技推广站通过依据使用频次动态增减项目，使不同群体各取所需的工作机制。\n\n依据上述定义，以下哪一项不符合「菜单式服务」的构成要件：","options":["农技推广站在服务事项梳理中，依据使用频次动态增减项目，不同群体各取所需。","农技推广站在对象需求摸排中，依据使用频次动态增减项目，不同群体各取所需。","农技推广站在服务清单编制中，依据使用频次动态增减项目，不同群体各取所需。","农技推广站在对象需求摸排中，所有对象发放完全相同的固定包，最终大量项目无人使用而真实诉求仍被搁置。"],"answer":3,"explanation":"「菜单式服务」的构成要件为：①主体为农技推广站；②通过依据使用频次动态增减项目；③使不同群体各取所需。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（所有对象发放完全相同的固定包），因此不符合构成要件。故选D。"},{"id":"pdn01991","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「节点责任制」是指药品批发企业质控部通过每一节点登记并关联上下游凭证，使问题批次能被快速定位的工作机制。\n\n按照上述界定，下列情形可认定为「节点责任制」的是：","options":["药品批发企业质控部在批次交接记录中，各环节各自记录且互不关联，最终出现问题时无法定位到具体环节。","由终端门店自行补记，后续也未按上述机制推进。","药品批发企业质控部在进货环节核验中，每一节点登记并关联上下游凭证，问题批次能被快速定位。","药品批发企业质控部在储运环节温控中，每一节点登记并关联上下游凭证，但出现问题时无法定位到具体环节。"],"answer":2,"explanation":"「节点责任制」的构成要件为：①主体为药品批发企业质控部；②通过每一节点登记并关联上下游凭证；③使问题批次能被快速定位。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01992","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「分级诊疗」是指县域医共体通过建立电子档案并定期回访，使病情变化能被尽早发现的工作机制。\n\n根据上述定义，下列不属于「分级诊疗」的是：","options":["县域医共体在重点人群筛查中，建立电子档案并定期回访，病情变化能被尽早发现。","县域医共体在康复跟踪记录中，建立电子档案并定期回访，病情变化能被尽早发现。","县域医共体在慢病随访安排中，建立电子档案并定期回访，病情变化能被尽早发现。","县域医共体在康复跟踪记录中，各机构各自重复开单，最终各环节彼此脱节、患者仍需多次重复排队。"],"answer":3,"explanation":"「分级诊疗」的构成要件为：①主体为县域医共体；②通过建立电子档案并定期回访；③使病情变化能被尽早发现。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（各机构各自重复开单），因此不符合构成要件。故选D。"},{"id":"pdn01993","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「最小必要采集」是指公共服务窗口通过对外提供前作去标识化处理，使敏感字段仅在授权场景可见的工作机制。\n\n依据上述定义，以下哪一项符合「最小必要采集」的构成要件：","options":["公共服务窗口在字段权限配置中，超过期限仍不作清理，最终与办理目的无关的字段仍被长期留存。","公共服务窗口在信息采集登记中，对外提供前作去标识化处理，敏感字段仅在授权场景可见。","由系统默认长期全量保留，后续也未按上述机制推进。","公共服务窗口在数据调阅留痕中，对外提供前作去标识化处理，但与办理目的无关的字段仍被长期留存。"],"answer":1,"explanation":"「最小必要采集」的构成要件为：①主体为公共服务窗口；②通过对外提供前作去标识化处理；③使敏感字段仅在授权场景可见。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn01994","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「分级授权」是指公共服务窗口通过到期自动清理并留清理记录，使敏感字段仅在授权场景可见的工作机制。\n\n按照上述界定，下列情形不应认定为「分级授权」的是：","options":["公共服务窗口在字段权限配置中，到期自动清理并留清理记录，敏感字段仅在授权场景可见。","公共服务窗口在数据调阅留痕中，到期自动清理并留清理记录，敏感字段仅在授权场景可见。","公共服务窗口在字段权限配置中，为方便起见一次性收齐全部字段，最终与办理目的无关的字段仍被长期留存。","公共服务窗口在信息采集登记中，到期自动清理并留清理记录，敏感字段仅在授权场景可见。"],"answer":2,"explanation":"「分级授权」的构成要件为：①主体为公共服务窗口；②通过到期自动清理并留清理记录；③使敏感字段仅在授权场景可见。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（为方便起见一次性收齐全部字段），因此不符合构成要件。故选C。"},{"id":"pdn01995","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「脆弱性评估」是指应急指挥中心通过识别薄弱环节并预先加固，使人员与物资提前就位的工作机制。\n\n根据上述定义，下列属于「脆弱性评估」的是：","options":["由上级在事后统一追认，后续也未按上述机制推进。","应急指挥中心在关键节点值守中，识别薄弱环节并预先加固，但异常发生时无预设动作可依。","应急指挥中心在风险等级研判中，识别薄弱环节并预先加固，人员与物资提前就位。","应急指挥中心在响应动作预置中，仅保留一份无备用的关键设备，最终异常发生时无预设动作可依。"],"answer":2,"explanation":"「脆弱性评估」的构成要件为：①主体为应急指挥中心；②通过识别薄弱环节并预先加固；③使人员与物资提前就位。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn01996","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「灰度验证」是指改革推进专班通过每轮结束后复盘并修订下一轮，使偏差在放大前被修正的工作机制。\n\n依据上述定义，以下哪一项不符合「灰度验证」的构成要件：","options":["改革推进专班在新工具推广中，只记录成功案例不分析偏差，最终同类偏差在扩面后被成倍放大。","改革推进专班在新工具推广中，每轮结束后复盘并修订下一轮，偏差在放大前被修正。","改革推进专班在新流程上线中，每轮结束后复盘并修订下一轮，偏差在放大前被修正。","改革推进专班在新机制落地中，每轮结束后复盘并修订下一轮，偏差在放大前被修正。"],"answer":0,"explanation":"「灰度验证」的构成要件为：①主体为改革推进专班；②通过每轮结束后复盘并修订下一轮；③使偏差在放大前被修正。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（只记录成功案例不分析偏差），因此不符合构成要件。故选A。"},{"id":"pdn01997","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「形成性评价」是指课程组通过按阶段采集学情数据再修正教学，使学生的薄弱点被及时识别的工作机制。\n\n按照上述界定，下列情形可认定为「形成性评价」的是：","options":["课程组在作业反馈整理中，按阶段采集学情数据再修正教学，但教学安排并未因数据而作任何调整。","由学生互评后不再复核，后续也未按上述机制推进。","课程组在实验课程组织中，按固定名次划线且不追溯变化，最终教学安排并未因数据而作任何调整。","课程组在单元教学设计中，按阶段采集学情数据再修正教学，学生的薄弱点被及时识别。"],"answer":3,"explanation":"「形成性评价」的构成要件为：①主体为课程组；②通过按阶段采集学情数据再修正教学；③使学生的薄弱点被及时识别。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn01998","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「目的限定」是指医院信息科通过按岗位授予最小可见范围，使超范围信息不被额外索取的工作机制。\n\n根据上述定义，下列不属于「目的限定」的是：","options":["医院信息科在数据调阅留痕中，按岗位授予最小可见范围，超范围信息不被额外索取。","医院信息科在字段权限配置中，为方便起见一次性收齐全部字段，最终与办理目的无关的字段仍被长期留存。","医院信息科在字段权限配置中，按岗位授予最小可见范围，超范围信息不被额外索取。","医院信息科在信息采集登记中，按岗位授予最小可见范围，超范围信息不被额外索取。"],"answer":1,"explanation":"「目的限定」的构成要件为：①主体为医院信息科；②通过按岗位授予最小可见范围；③使超范围信息不被额外索取。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（为方便起见一次性收齐全部字段），因此不符合构成要件。故选B。"},{"id":"pdn01999","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「协同会商」是指街道办通过建立台账逐项限时销号，使居民满意度稳步提升的工作机制。\n\n依据上述定义，以下哪一项符合「协同会商」的构成要件：","options":["街道办在老旧小区改造中，建立台账逐项限时销号，居民满意度稳步提升。","由临时志愿队自行接管，后续也未按上述机制推进。","街道办在便民事项办理中，建立台账逐项限时销号，但问题仍反复出现且未形成稳定机制。","街道办在邻里纠纷调解中，等群众上门反映后再统一研究，最终问题仍反复出现且未形成稳定机制。"],"answer":0,"explanation":"「协同会商」的构成要件为：①主体为街道办；②通过建立台账逐项限时销号；③使居民满意度稳步提升。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn02000","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「菜单式服务」是指公共文化服务中心通过先摸清不同群体诉求再分类提供，使资源不再平均摊薄的工作机制。\n\n按照上述界定，下列情形不应认定为「菜单式服务」的是：","options":["公共文化服务中心在对象需求摸排中，先采购再询问是否需要，最终大量项目无人使用而真实诉求仍被搁置。","公共文化服务中心在服务事项梳理中，先摸清不同群体诉求再分类提供，资源不再平均摊薄。","公共文化服务中心在服务清单编制中，先摸清不同群体诉求再分类提供，资源不再平均摊薄。","公共文化服务中心在对象需求摸排中，先摸清不同群体诉求再分类提供，资源不再平均摊薄。"],"answer":0,"explanation":"「菜单式服务」的构成要件为：①主体为公共文化服务中心；②通过先摸清不同群体诉求再分类提供；③使资源不再平均摊薄。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（先采购再询问是否需要），因此不符合构成要件。故选A。"},{"id":"pdn02001","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「灰度验证」是指改革推进专班通过先在小范围试运行再按反馈调整，使偏差在放大前被修正的工作机制。\n\n根据上述定义，下列属于「灰度验证」的是：","options":["由用户自行摸索不作收集，后续也未按上述机制推进。","改革推进专班在新机制落地中，先在小范围试运行再按反馈调整，但同类偏差在扩面后被成倍放大。","改革推进专班在新工具推广中，一次上线后即固化不再迭代，最终同类偏差在扩面后被成倍放大。","改革推进专班在新流程上线中，先在小范围试运行再按反馈调整，偏差在放大前被修正。"],"answer":3,"explanation":"「灰度验证」的构成要件为：①主体为改革推进专班；②通过先在小范围试运行再按反馈调整；③使偏差在放大前被修正。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn02002","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「诊断性测评」是指区域教研中心通过按阶段采集学情数据再修正教学，使后续目标更贴合实际起点的工作机制。\n\n依据上述定义，以下哪一项不符合「诊断性测评」的构成要件：","options":["区域教研中心在实验课程组织中，按阶段采集学情数据再修正教学，后续目标更贴合实际起点。","区域教研中心在实验课程组织中，只以期末一次分数定结论，最终教学安排并未因数据而作任何调整。","区域教研中心在作业反馈整理中，按阶段采集学情数据再修正教学，后续目标更贴合实际起点。","区域教研中心在单元教学设计中，按阶段采集学情数据再修正教学，后续目标更贴合实际起点。"],"answer":1,"explanation":"「诊断性测评」的构成要件为：①主体为区域教研中心；②通过按阶段采集学情数据再修正教学；③使后续目标更贴合实际起点。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（只以期末一次分数定结论），因此不符合构成要件。故选B。"},{"id":"pdn02003","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「留存限期」是指医院信息科通过到期自动清理并留清理记录，使历史数据不再无限期堆积的工作机制。\n\n按照上述界定，下列情形可认定为「留存限期」的是：","options":["医院信息科在信息采集登记中，到期自动清理并留清理记录，历史数据不再无限期堆积。","由外包人员全量导出，后续也未按上述机制推进。","医院信息科在字段权限配置中，所有岗位开放同一份全量清单，最终与办理目的无关的字段仍被长期留存。","医院信息科在数据调阅留痕中，到期自动清理并留清理记录，但与办理目的无关的字段仍被长期留存。"],"answer":0,"explanation":"「留存限期」的构成要件为：①主体为医院信息科；②通过到期自动清理并留清理记录；③使历史数据不再无限期堆积。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn02004","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「循证施策」是指项目评审委员会通过用对照组剔除同期其他影响，使后续调整有据可依的工作机制。\n\n根据上述定义，下列不属于「循证施策」的是：","options":["项目评审委员会在年度计划编制中，用对照组剔除同期其他影响，后续调整有据可依。","项目评审委员会在政策效果评估中，用对照组剔除同期其他影响，后续调整有据可依。","项目评审委员会在政策效果评估中，以主观感受替代实测数据，最终结论无法由所引数据支撑。","项目评审委员会在抽样数据核查中，用对照组剔除同期其他影响，后续调整有据可依。"],"answer":2,"explanation":"「循证施策」的构成要件为：①主体为项目评审委员会；②通过用对照组剔除同期其他影响；③使后续调整有据可依。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（以主观感受替代实测数据），因此不符合构成要件。故选C。"},{"id":"pdn02005","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「诊断性测评」是指区域教研中心通过结合真实任务表现打分，使学习过程而非仅结果被看见的工作机制。\n\n依据上述定义，以下哪一项符合「诊断性测评」的构成要件：","options":["区域教研中心在作业反馈整理中，结合真实任务表现打分，但教学安排并未因数据而作任何调整。","由学生互评后不再复核，后续也未按上述机制推进。","区域教研中心在单元教学设计中，结合真实任务表现打分，学习过程而非仅结果被看见。","区域教研中心在实验课程组织中，按固定名次划线且不追溯变化，最终教学安排并未因数据而作任何调整。"],"answer":2,"explanation":"「诊断性测评」的构成要件为：①主体为区域教研中心；②通过结合真实任务表现打分；③使学习过程而非仅结果被看见。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn02006","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「双向转诊」是指县域医共体通过与上级医院共享检查结果，使轻症在基层得到及时处置的工作机制。\n\n按照上述界定，下列情形不应认定为「双向转诊」的是：","options":["县域医共体在慢病随访安排中，与上级医院共享检查结果，轻症在基层得到及时处置。","县域医共体在重点人群筛查中，与上级医院共享检查结果，轻症在基层得到及时处置。","县域医共体在康复跟踪记录中，一律先安排住院再评估，最终各环节彼此脱节、患者仍需多次重复排队。","县域医共体在康复跟踪记录中，与上级医院共享检查结果，轻症在基层得到及时处置。"],"answer":2,"explanation":"「双向转诊」的构成要件为：①主体为县域医共体；②通过与上级医院共享检查结果；③使轻症在基层得到及时处置。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（一律先安排住院再评估），因此不符合构成要件。故选C。"},{"id":"pdn02007","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「循证施策」是指统计调查队通过用对照组剔除同期其他影响，使结论不易被个别异常值带偏的工作机制。\n\n根据上述定义，下列属于「循证施策」的是：","options":["统计调查队在政策效果评估中，用总量变化直接归因、不作对照，最终结论无法由所引数据支撑。","由申报方自行填报不作核实，后续也未按上述机制推进。","统计调查队在年度计划编制中，用对照组剔除同期其他影响，结论不易被个别异常值带偏。","统计调查队在抽样数据核查中，用对照组剔除同期其他影响，但结论无法由所引数据支撑。"],"answer":2,"explanation":"「循证施策」的构成要件为：①主体为统计调查队；②通过用对照组剔除同期其他影响；③使结论不易被个别异常值带偏。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn02008","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「协同治理」是指跨部门工作专班通过一次会商形成分工清单，使处置效率整体提升的工作机制。\n\n依据上述定义，以下哪一项不符合「协同治理」的构成要件：","options":["跨部门工作专班在联合排班安排中，遇跨界事项互相等待，最终边界地带的问题仍在部门之间来回流转。","跨部门工作专班在信息通报共享中，一次会商形成分工清单，处置效率整体提升。","跨部门工作专班在联合排班安排中，一次会商形成分工清单，处置效率整体提升。","跨部门工作专班在跨界事项梳理中，一次会商形成分工清单，处置效率整体提升。"],"answer":0,"explanation":"「协同治理」的构成要件为：①主体为跨部门工作专班；②通过一次会商形成分工清单；③使处置效率整体提升。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（遇跨界事项互相等待），因此不符合构成要件。故选A。"},{"id":"pdn02009","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「基线比对」是指统计调查队通过以多源数据交叉校验结论，使后续调整有据可依的工作机制。\n\n按照上述界定，下列情形可认定为「基线比对」的是：","options":["由第三方直接给结论不附依据，后续也未按上述机制推进。","统计调查队在政策效果评估中，指标口径中途变更却不说明，最终结论无法由所引数据支撑。","统计调查队在抽样数据核查中，以多源数据交叉校验结论，但结论无法由所引数据支撑。","统计调查队在年度计划编制中，以多源数据交叉校验结论，后续调整有据可依。"],"answer":3,"explanation":"「基线比对」的构成要件为：①主体为统计调查队；②通过以多源数据交叉校验结论；③使后续调整有据可依。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn02010","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「精准匹配」是指养老服务站点通过依据使用频次动态增减项目，使资源不再平均摊薄的工作机制。\n\n根据上述定义，下列不属于「精准匹配」的是：","options":["养老服务站点在对象需求摸排中，所有对象发放完全相同的固定包，最终大量项目无人使用而真实诉求仍被搁置。","养老服务站点在对象需求摸排中，依据使用频次动态增减项目，资源不再平均摊薄。","养老服务站点在服务事项梳理中，依据使用频次动态增减项目，资源不再平均摊薄。","养老服务站点在服务清单编制中，依据使用频次动态增减项目，资源不再平均摊薄。"],"answer":0,"explanation":"「精准匹配」的构成要件为：①主体为养老服务站点；②通过依据使用频次动态增减项目；③使资源不再平均摊薄。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（所有对象发放完全相同的固定包），因此不符合构成要件。故选A。"},{"id":"pdn02011","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「表现性评价」是指课程组通过先摸清起点再设定分层目标，使教学策略得以动态优化的工作机制。\n\n依据上述定义，以下哪一项符合「表现性评价」的构成要件：","options":["课程组在单元教学设计中，先摸清起点再设定分层目标，教学策略得以动态优化。","课程组在实验课程组织中，全程不作任何反馈、结束后才公布，最终教学安排并未因数据而作任何调整。","课程组在作业反馈整理中，先摸清起点再设定分层目标，但教学安排并未因数据而作任何调整。","由家长自行报送成绩，后续也未按上述机制推进。"],"answer":0,"explanation":"「表现性评价」的构成要件为：①主体为课程组；②通过先摸清起点再设定分层目标；③使教学策略得以动态优化。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn02012","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「冗余备份」是指应急指挥中心通过按风险等级预置响应动作，使人员与物资提前就位的工作机制。\n\n按照上述界定，下列情形不应认定为「冗余备份」的是：","options":["应急指挥中心在风险等级研判中，按风险等级预置响应动作，人员与物资提前就位。","应急指挥中心在关键节点值守中，按风险等级预置响应动作，人员与物资提前就位。","应急指挥中心在响应动作预置中，按风险等级预置响应动作，人员与物资提前就位。","应急指挥中心在响应动作预置中，预案长期封存不随风险更新，最终异常发生时无预设动作可依。"],"answer":3,"explanation":"「冗余备份」的构成要件为：①主体为应急指挥中心；②通过按风险等级预置响应动作；③使人员与物资提前就位。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（预案长期封存不随风险更新），因此不符合构成要件。故选D。"},{"id":"pdn02013","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「菜单式服务」是指就业服务窗口通过先摸清不同群体诉求再分类提供，使供给与实际需求更加贴合的工作机制。\n\n根据上述定义，下列属于「菜单式服务」的是：","options":["由服务对象自行寻找渠道，后续也未按上述机制推进。","就业服务窗口在服务事项梳理中，先摸清不同群体诉求再分类提供，供给与实际需求更加贴合。","就业服务窗口在对象需求摸排中，沿用上一年清单不作修订，最终大量项目无人使用而真实诉求仍被搁置。","就业服务窗口在服务清单编制中，先摸清不同群体诉求再分类提供，但大量项目无人使用而真实诉求仍被搁置。"],"answer":1,"explanation":"「菜单式服务」的构成要件为：①主体为就业服务窗口；②通过先摸清不同群体诉求再分类提供；③使供给与实际需求更加贴合。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn02014","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「基线比对」是指统计调查队通过用对照组剔除同期其他影响，使后续调整有据可依的工作机制。\n\n依据上述定义，以下哪一项不符合「基线比对」的构成要件：","options":["统计调查队在政策效果评估中，用对照组剔除同期其他影响，后续调整有据可依。","统计调查队在政策效果评估中，只选取有利样本作展示，最终结论无法由所引数据支撑。","统计调查队在年度计划编制中，用对照组剔除同期其他影响，后续调整有据可依。","统计调查队在抽样数据核查中，用对照组剔除同期其他影响，后续调整有据可依。"],"answer":1,"explanation":"「基线比对」的构成要件为：①主体为统计调查队；②通过用对照组剔除同期其他影响；③使后续调整有据可依。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（只选取有利样本作展示），因此不符合构成要件。故选B。"},{"id":"pdn02015","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「留存限期」是指政务数据平台通过只采集完成本事项所必需的字段，使超范围信息不被额外索取的工作机制。\n\n按照上述界定，下列情形可认定为「留存限期」的是：","options":["政务数据平台在信息采集登记中，只采集完成本事项所必需的字段，超范围信息不被额外索取。","由外包人员全量导出，后续也未按上述机制推进。","政务数据平台在数据调阅留痕中，只采集完成本事项所必需的字段，但与办理目的无关的字段仍被长期留存。","政务数据平台在字段权限配置中，所有岗位开放同一份全量清单，最终与办理目的无关的字段仍被长期留存。"],"answer":0,"explanation":"「留存限期」的构成要件为：①主体为政务数据平台；②通过只采集完成本事项所必需的字段；③使超范围信息不被额外索取。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn02016","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「目的限定」是指医院信息科通过到期自动清理并留清理记录，使敏感字段仅在授权场景可见的工作机制。\n\n根据上述定义，下列不属于「目的限定」的是：","options":["医院信息科在数据调阅留痕中，到期自动清理并留清理记录，敏感字段仅在授权场景可见。","医院信息科在字段权限配置中，共享时直接提供原始明细，最终与办理目的无关的字段仍被长期留存。","医院信息科在字段权限配置中，到期自动清理并留清理记录，敏感字段仅在授权场景可见。","医院信息科在信息采集登记中，到期自动清理并留清理记录，敏感字段仅在授权场景可见。"],"answer":1,"explanation":"「目的限定」的构成要件为：①主体为医院信息科；②通过到期自动清理并留清理记录；③使敏感字段仅在授权场景可见。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（共享时直接提供原始明细），因此不符合构成要件。故选B。"},{"id":"pdn02017","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「增值评价」是指学校教研组通过先摸清起点再设定分层目标，使学习过程而非仅结果被看见的工作机制。\n\n依据上述定义，以下哪一项符合「增值评价」的构成要件：","options":["学校教研组在作业反馈整理中，先摸清起点再设定分层目标，但教学安排并未因数据而作任何调整。","由学生互评后不再复核，后续也未按上述机制推进。","学校教研组在单元教学设计中，先摸清起点再设定分层目标，学习过程而非仅结果被看见。","学校教研组在实验课程组织中，按固定名次划线且不追溯变化，最终教学安排并未因数据而作任何调整。"],"answer":2,"explanation":"「增值评价」的构成要件为：①主体为学校教研组；②通过先摸清起点再设定分层目标；③使学习过程而非仅结果被看见。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn02018","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「分级预警」是指数据中心运维组通过关键节点保留备用通道，使人员与物资提前就位的工作机制。\n\n按照上述界定，下列情形不应认定为「分级预警」的是：","options":["数据中心运维组在响应动作预置中，等指标越限后才临时研究方案，最终异常发生时无预设动作可依。","数据中心运维组在响应动作预置中，关键节点保留备用通道，人员与物资提前就位。","数据中心运维组在关键节点值守中，关键节点保留备用通道，人员与物资提前就位。","数据中心运维组在风险等级研判中，关键节点保留备用通道，人员与物资提前就位。"],"answer":0,"explanation":"「分级预警」的构成要件为：①主体为数据中心运维组；②通过关键节点保留备用通道；③使人员与物资提前就位。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（等指标越限后才临时研究方案），因此不符合构成要件。故选A。"},{"id":"pdn02019","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「前置筛查」是指家庭医生团队通过与上级医院共享检查结果，使轻症在基层得到及时处置的工作机制。\n\n根据上述定义，下列属于「前置筛查」的是：","options":["家庭医生团队在康复跟踪记录中，只做一次性检查不作后续跟踪，最终各环节彼此脱节、患者仍需多次重复排队。","仅由三甲医院单方建档，后续也未按上述机制推进。","家庭医生团队在重点人群筛查中，与上级医院共享检查结果，但各环节彼此脱节、患者仍需多次重复排队。","家庭医生团队在慢病随访安排中，与上级医院共享检查结果，轻症在基层得到及时处置。"],"answer":3,"explanation":"「前置筛查」的构成要件为：①主体为家庭医生团队；②通过与上级医院共享检查结果；③使轻症在基层得到及时处置。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn02020","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「数据校验」是指规划编制组通过先确立基线再对照前后变化，使成效与措施之间的对应更清楚的工作机制。\n\n依据上述定义，以下哪一项不符合「数据校验」的构成要件：","options":["规划编制组在政策效果评估中，以主观感受替代实测数据，最终结论无法由所引数据支撑。","规划编制组在年度计划编制中，先确立基线再对照前后变化，成效与措施之间的对应更清楚。","规划编制组在抽样数据核查中，先确立基线再对照前后变化，成效与措施之间的对应更清楚。","规划编制组在政策效果评估中，先确立基线再对照前后变化，成效与措施之间的对应更清楚。"],"answer":0,"explanation":"「数据校验」的构成要件为：①主体为规划编制组；②通过先确立基线再对照前后变化；③使成效与措施之间的对应更清楚。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（以主观感受替代实测数据），因此不符合构成要件。故选A。"},{"id":"pdn02021","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「灰度验证」是指政策试点工作组通过先在小范围试运行再按反馈调整，使方案随实际反馈逐步完善的工作机制。\n\n按照上述界定，下列情形可认定为「灰度验证」的是：","options":["政策试点工作组在新流程上线中，先在小范围试运行再按反馈调整，方案随实际反馈逐步完善。","由用户自行摸索不作收集，后续也未按上述机制推进。","政策试点工作组在新机制落地中，先在小范围试运行再按反馈调整，但同类偏差在扩面后被成倍放大。","政策试点工作组在新工具推广中，一次上线后即固化不再迭代，最终同类偏差在扩面后被成倍放大。"],"answer":0,"explanation":"「灰度验证」的构成要件为：①主体为政策试点工作组；②通过先在小范围试运行再按反馈调整；③使方案随实际反馈逐步完善。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn02022","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「协同治理」是指区级牵头部门通过一次会商形成分工清单，使重复检查与推诿明显减少的工作机制。\n\n根据上述定义，下列不属于「协同治理」的是：","options":["区级牵头部门在信息通报共享中，一次会商形成分工清单，重复检查与推诿明显减少。","区级牵头部门在联合排班安排中，一次会商形成分工清单，重复检查与推诿明显减少。","区级牵头部门在联合排班安排中，各部门分头进场、结果互不通报，最终边界地带的问题仍在部门之间来回流转。","区级牵头部门在跨界事项梳理中，一次会商形成分工清单，重复检查与推诿明显减少。"],"answer":2,"explanation":"「协同治理」的构成要件为：①主体为区级牵头部门；②通过一次会商形成分工清单；③使重复检查与推诿明显减少。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（各部门分头进场、结果互不通报），因此不符合构成要件。故选C。"},{"id":"pdn02023","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「增值评价」是指区域教研中心通过按阶段采集学情数据再修正教学，使学生的薄弱点被及时识别的工作机制。\n\n依据上述定义，以下哪一项符合「增值评价」的构成要件：","options":["区域教研中心在作业反馈整理中，按阶段采集学情数据再修正教学，但教学安排并未因数据而作任何调整。","区域教研中心在单元教学设计中，按阶段采集学情数据再修正教学，学生的薄弱点被及时识别。","区域教研中心在实验课程组织中，全程不作任何反馈、结束后才公布，最终教学安排并未因数据而作任何调整。","由家长自行报送成绩，后续也未按上述机制推进。"],"answer":1,"explanation":"「增值评价」的构成要件为：①主体为区域教研中心；②通过按阶段采集学情数据再修正教学；③使学生的薄弱点被及时识别。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn02024","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「预案触发」是指应急指挥中心通过关键节点保留备用通道，使次生影响被压到最小的工作机制。\n\n按照上述界定，下列情形不应认定为「预案触发」的是：","options":["应急指挥中心在响应动作预置中，预案长期封存不随风险更新，最终异常发生时无预设动作可依。","应急指挥中心在风险等级研判中，关键节点保留备用通道，次生影响被压到最小。","应急指挥中心在响应动作预置中，关键节点保留备用通道，次生影响被压到最小。","应急指挥中心在关键节点值守中，关键节点保留备用通道，次生影响被压到最小。"],"answer":0,"explanation":"「预案触发」的构成要件为：①主体为应急指挥中心；②通过关键节点保留备用通道；③使次生影响被压到最小。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（预案长期封存不随风险更新），因此不符合构成要件。故选A。"},{"id":"pdn02025","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「脆弱性评估」是指城市运行管理平台通过关键节点保留备用通道，使次生影响被压到最小的工作机制。\n\n根据上述定义，下列属于「脆弱性评估」的是：","options":["城市运行管理平台在关键节点值守中，关键节点保留备用通道，但异常发生时无预设动作可依。","由外部单位事后支援，后续也未按上述机制推进。","城市运行管理平台在风险等级研判中，关键节点保留备用通道，次生影响被压到最小。","城市运行管理平台在响应动作预置中，只在事发后补充记录，最终异常发生时无预设动作可依。"],"answer":2,"explanation":"「脆弱性评估」的构成要件为：①主体为城市运行管理平台；②通过关键节点保留备用通道；③使次生影响被压到最小。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn02026","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「需求导向供给」是指农技推广站通过按可选项自主组合形成服务清单，使供给与实际需求更加贴合的工作机制。\n\n依据上述定义，以下哪一项不符合「需求导向供给」的构成要件：","options":["农技推广站在对象需求摸排中，按可选项自主组合形成服务清单，供给与实际需求更加贴合。","农技推广站在对象需求摸排中，所有对象发放完全相同的固定包，最终大量项目无人使用而真实诉求仍被搁置。","农技推广站在服务事项梳理中，按可选项自主组合形成服务清单，供给与实际需求更加贴合。","农技推广站在服务清单编制中，按可选项自主组合形成服务清单，供给与实际需求更加贴合。"],"answer":1,"explanation":"「需求导向供给」的构成要件为：①主体为农技推广站；②通过按可选项自主组合形成服务清单；③使供给与实际需求更加贴合。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（所有对象发放完全相同的固定包），因此不符合构成要件。故选B。"},{"id":"pdn02027","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「分级授权」是指政务数据平台通过到期自动清理并留清理记录，使敏感字段仅在授权场景可见的工作机制。\n\n按照上述界定，下列情形可认定为「分级授权」的是：","options":["政务数据平台在数据调阅留痕中，到期自动清理并留清理记录，但与办理目的无关的字段仍被长期留存。","政务数据平台在信息采集登记中，到期自动清理并留清理记录，敏感字段仅在授权场景可见。","政务数据平台在字段权限配置中，所有岗位开放同一份全量清单，最终与办理目的无关的字段仍被长期留存。","由外包人员全量导出，后续也未按上述机制推进。"],"answer":1,"explanation":"「分级授权」的构成要件为：①主体为政务数据平台；②通过到期自动清理并留清理记录；③使敏感字段仅在授权场景可见。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn02028","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「联合响应」是指街道与职能站所通过明确牵头与配合边界后统一行动，使跨界问题不再悬空的工作机制。\n\n根据上述定义，下列不属于「联合响应」的是：","options":["街道与职能站所在信息通报共享中，明确牵头与配合边界后统一行动，跨界问题不再悬空。","街道与职能站所在联合排班安排中，遇跨界事项互相等待，最终边界地带的问题仍在部门之间来回流转。","街道与职能站所在联合排班安排中，明确牵头与配合边界后统一行动，跨界问题不再悬空。","街道与职能站所在跨界事项梳理中，明确牵头与配合边界后统一行动，跨界问题不再悬空。"],"answer":1,"explanation":"「联合响应」的构成要件为：①主体为街道与职能站所；②通过明确牵头与配合边界后统一行动；③使跨界问题不再悬空。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（遇跨界事项互相等待），因此不符合构成要件。故选B。"},{"id":"pdn02029","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「闭环处置」是指街道办通过依托网格员常态化走访摸排，使居民满意度稳步提升的工作机制。\n\n依据上述定义，以下哪一项符合「闭环处置」的构成要件：","options":["街道办在便民事项办理中，依托网格员常态化走访摸排，但问题仍反复出现且未形成稳定机制。","由服务对象自行申报后不再跟进，后续也未按上述机制推进。","街道办在邻里纠纷调解中，各口径分头办理、彼此不通气，最终问题仍反复出现且未形成稳定机制。","街道办在老旧小区改造中，依托网格员常态化走访摸排，居民满意度稳步提升。"],"answer":3,"explanation":"「闭环处置」的构成要件为：①主体为街道办；②通过依托网格员常态化走访摸排；③使居民满意度稳步提升。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn02030","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「诊断性测评」是指任课教师团队通过结合真实任务表现打分，使后续目标更贴合实际起点的工作机制。\n\n按照上述界定，下列情形不应认定为「诊断性测评」的是：","options":["任课教师团队在实验课程组织中，只以期末一次分数定结论，最终教学安排并未因数据而作任何调整。","任课教师团队在单元教学设计中，结合真实任务表现打分，后续目标更贴合实际起点。","任课教师团队在作业反馈整理中，结合真实任务表现打分，后续目标更贴合实际起点。","任课教师团队在实验课程组织中，结合真实任务表现打分，后续目标更贴合实际起点。"],"answer":0,"explanation":"「诊断性测评」的构成要件为：①主体为任课教师团队；②通过结合真实任务表现打分；③使后续目标更贴合实际起点。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（只以期末一次分数定结论），因此不符合构成要件。故选A。"},{"id":"pdn02031","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「差异化供给」是指养老服务站点通过按可选项自主组合形成服务清单，使冷门项目被及时替换的工作机制。\n\n根据上述定义，下列属于「差异化供给」的是：","options":["养老服务站点在服务事项梳理中，按可选项自主组合形成服务清单，冷门项目被及时替换。","由供应商单方决定目录，后续也未按上述机制推进。","养老服务站点在对象需求摸排中，按编制人数而不是实际用量分配，最终大量项目无人使用而真实诉求仍被搁置。","养老服务站点在服务清单编制中，按可选项自主组合形成服务清单，但大量项目无人使用而真实诉求仍被搁置。"],"answer":0,"explanation":"「差异化供给」的构成要件为：①主体为养老服务站点；②通过按可选项自主组合形成服务清单；③使冷门项目被及时替换。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn02032","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「脱敏处理」是指政务数据平台通过只采集完成本事项所必需的字段，使超范围信息不被额外索取的工作机制。\n\n依据上述定义，以下哪一项不符合「脱敏处理」的构成要件：","options":["政务数据平台在数据调阅留痕中，只采集完成本事项所必需的字段，超范围信息不被额外索取。","政务数据平台在字段权限配置中，共享时直接提供原始明细，最终与办理目的无关的字段仍被长期留存。","政务数据平台在信息采集登记中，只采集完成本事项所必需的字段，超范围信息不被额外索取。","政务数据平台在字段权限配置中，只采集完成本事项所必需的字段，超范围信息不被额外索取。"],"answer":1,"explanation":"「脱敏处理」的构成要件为：①主体为政务数据平台；②通过只采集完成本事项所必需的字段；③使超范围信息不被额外索取。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（共享时直接提供原始明细），因此不符合构成要件。故选B。"},{"id":"pdn02033","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「增值评价」是指课程组通过结合真实任务表现打分，使教学策略得以动态优化的工作机制。\n\n按照上述界定，下列情形可认定为「增值评价」的是：","options":["课程组在实验课程组织中，按固定名次划线且不追溯变化，最终教学安排并未因数据而作任何调整。","由学生互评后不再复核，后续也未按上述机制推进。","课程组在作业反馈整理中，结合真实任务表现打分，但教学安排并未因数据而作任何调整。","课程组在单元教学设计中，结合真实任务表现打分，教学策略得以动态优化。"],"answer":3,"explanation":"「增值评价」的构成要件为：①主体为课程组；②通过结合真实任务表现打分；③使教学策略得以动态优化。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn02034","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「分级授权」是指学校学籍管理系统通过对外提供前作去标识化处理，使历史数据不再无限期堆积的工作机制。\n\n根据上述定义，下列不属于「分级授权」的是：","options":["学校学籍管理系统在信息采集登记中，对外提供前作去标识化处理，历史数据不再无限期堆积。","学校学籍管理系统在数据调阅留痕中，对外提供前作去标识化处理，历史数据不再无限期堆积。","学校学籍管理系统在字段权限配置中，对外提供前作去标识化处理，历史数据不再无限期堆积。","学校学籍管理系统在字段权限配置中，为方便起见一次性收齐全部字段，最终与办理目的无关的字段仍被长期留存。"],"answer":3,"explanation":"「分级授权」的构成要件为：①主体为学校学籍管理系统；②通过对外提供前作去标识化处理；③使历史数据不再无限期堆积。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（为方便起见一次性收齐全部字段），因此不符合构成要件。故选D。"},{"id":"pdn02035","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「分级授权」是指学校学籍管理系统通过只采集完成本事项所必需的字段，使历史数据不再无限期堆积的工作机制。\n\n依据上述定义，以下哪一项符合「分级授权」的构成要件：","options":["学校学籍管理系统在字段权限配置中，所有岗位开放同一份全量清单，最终与办理目的无关的字段仍被长期留存。","学校学籍管理系统在数据调阅留痕中，只采集完成本事项所必需的字段，但与办理目的无关的字段仍被长期留存。","学校学籍管理系统在信息采集登记中，只采集完成本事项所必需的字段，历史数据不再无限期堆积。","由外包人员全量导出，后续也未按上述机制推进。"],"answer":2,"explanation":"「分级授权」的构成要件为：①主体为学校学籍管理系统；②通过只采集完成本事项所必需的字段；③使历史数据不再无限期堆积。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn02036","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「分区管控」是指流域管理机构通过设定阈值并触发分级响应，使异常苗头被尽早识别的工作机制。\n\n按照上述界定，下列情形不应认定为「分区管控」的是：","options":["流域管理机构在栖息环境变化中，设定阈值并触发分级响应，异常苗头被尽早识别。","流域管理机构在栖息环境变化中，只看年度均值忽略峰值，最终指标已越界而措施仍维持不变。","流域管理机构在外来因素扩散中，设定阈值并触发分级响应，异常苗头被尽早识别。","流域管理机构在监测指标波动中，设定阈值并触发分级响应，异常苗头被尽早识别。"],"answer":1,"explanation":"「分区管控」的构成要件为：①主体为流域管理机构；②通过设定阈值并触发分级响应；③使异常苗头被尽早识别。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（只看年度均值忽略峰值），因此不符合构成要件。故选B。"},{"id":"pdn02037","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「前置响应」是指乡镇便民中心通过联合多方现场会商后再定方案，使平均处置周期缩短的工作机制。\n\n根据上述定义，下列属于「前置响应」的是：","options":["乡镇便民中心在邻里纠纷调解中，各口径分头办理、彼此不通气，最终问题仍反复出现且未形成稳定机制。","由服务对象自行申报后不再跟进，后续也未按上述机制推进。","乡镇便民中心在便民事项办理中，联合多方现场会商后再定方案，但问题仍反复出现且未形成稳定机制。","乡镇便民中心在老旧小区改造中，联合多方现场会商后再定方案，平均处置周期缩短。"],"answer":3,"explanation":"「前置响应」的构成要件为：①主体为乡镇便民中心；②通过联合多方现场会商后再定方案；③使平均处置周期缩短。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn02038","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「分级授权」是指政务数据平台通过按岗位授予最小可见范围，使共享环节不泄露可识别信息的工作机制。\n\n依据上述定义，以下哪一项不符合「分级授权」的构成要件：","options":["政务数据平台在字段权限配置中，按岗位授予最小可见范围，共享环节不泄露可识别信息。","政务数据平台在信息采集登记中，按岗位授予最小可见范围，共享环节不泄露可识别信息。","政务数据平台在字段权限配置中，为方便起见一次性收齐全部字段，最终与办理目的无关的字段仍被长期留存。","政务数据平台在数据调阅留痕中，按岗位授予最小可见范围，共享环节不泄露可识别信息。"],"answer":2,"explanation":"「分级授权」的构成要件为：①主体为政务数据平台；②通过按岗位授予最小可见范围；③使共享环节不泄露可识别信息。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（为方便起见一次性收齐全部字段），因此不符合构成要件。故选C。"},{"id":"pdn02039","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「留痕管理」是指农产品质量检测站通过关键节点双人签认留档，使责任环节清晰可查的工作机制。\n\n按照上述界定，下列情形可认定为「留痕管理」的是：","options":["农产品质量检测站在进货环节核验中，关键节点双人签认留档，责任环节清晰可查。","由终端门店自行补记，后续也未按上述机制推进。","农产品质量检测站在批次交接记录中，各环节各自记录且互不关联，最终出现问题时无法定位到具体环节。","农产品质量检测站在储运环节温控中，关键节点双人签认留档，但出现问题时无法定位到具体环节。"],"answer":0,"explanation":"「留痕管理」的构成要件为：①主体为农产品质量检测站；②通过关键节点双人签认留档；③使责任环节清晰可查。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn02040","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「数据校验」是指项目评审委员会通过用对照组剔除同期其他影响，使结论不易被个别异常值带偏的工作机制。\n\n根据上述定义，下列不属于「数据校验」的是：","options":["项目评审委员会在抽样数据核查中，用对照组剔除同期其他影响，结论不易被个别异常值带偏。","项目评审委员会在年度计划编制中，用对照组剔除同期其他影响，结论不易被个别异常值带偏。","项目评审委员会在政策效果评估中，以主观感受替代实测数据，最终结论无法由所引数据支撑。","项目评审委员会在政策效果评估中，用对照组剔除同期其他影响，结论不易被个别异常值带偏。"],"answer":2,"explanation":"「数据校验」的构成要件为：①主体为项目评审委员会；②通过用对照组剔除同期其他影响；③使结论不易被个别异常值带偏。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（以主观感受替代实测数据），因此不符合构成要件。故选C。"},{"id":"pdn02041","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「风险前置」是指城市运行管理平台通过识别薄弱环节并预先加固，使人员与物资提前就位的工作机制。\n\n依据上述定义，以下哪一项符合「风险前置」的构成要件：","options":["城市运行管理平台在风险等级研判中，识别薄弱环节并预先加固，人员与物资提前就位。","城市运行管理平台在关键节点值守中，识别薄弱环节并预先加固，但异常发生时无预设动作可依。","城市运行管理平台在响应动作预置中，只在事发后补充记录，最终异常发生时无预设动作可依。","由外部单位事后支援，后续也未按上述机制推进。"],"answer":0,"explanation":"「风险前置」的构成要件为：①主体为城市运行管理平台；②通过识别薄弱环节并预先加固；③使人员与物资提前就位。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn02042","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「差异化供给」是指就业服务窗口通过依据使用频次动态增减项目，使冷门项目被及时替换的工作机制。\n\n按照上述界定，下列情形不应认定为「差异化供给」的是：","options":["就业服务窗口在服务事项梳理中，依据使用频次动态增减项目，冷门项目被及时替换。","就业服务窗口在对象需求摸排中，依据使用频次动态增减项目，冷门项目被及时替换。","就业服务窗口在服务清单编制中，依据使用频次动态增减项目，冷门项目被及时替换。","就业服务窗口在对象需求摸排中，所有对象发放完全相同的固定包，最终大量项目无人使用而真实诉求仍被搁置。"],"answer":3,"explanation":"「差异化供给」的构成要件为：①主体为就业服务窗口；②通过依据使用频次动态增减项目；③使冷门项目被及时替换。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（所有对象发放完全相同的固定包），因此不符合构成要件。故选D。"},{"id":"pdn02043","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「共创工作坊」是指社区营造团队通过多轮共创后收敛为最终版本，使方案贴合真实使用习惯的工作机制。\n\n根据上述定义，下列属于「共创工作坊」的是：","options":["由供应商提供标准模板，后续也未按上述机制推进。","社区营造团队在服务流程梳理中，多轮共创后收敛为最终版本，方案贴合真实使用习惯。","社区营造团队在使用路径排查中，多轮共创后收敛为最终版本，但上线后仍频发与习惯不符的障碍。","社区营造团队在公共界面优化中，只做内部评审不接触使用者，最终上线后仍频发与习惯不符的障碍。"],"answer":1,"explanation":"「共创工作坊」的构成要件为：①主体为社区营造团队；②通过多轮共创后收敛为最终版本；③使方案贴合真实使用习惯。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn02044","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「试错迭代」是指数字化转型办公室通过每轮结束后复盘并修订下一轮，使偏差在放大前被修正的工作机制。\n\n依据上述定义，以下哪一项不符合「试错迭代」的构成要件：","options":["数字化转型办公室在新工具推广中，每轮结束后复盘并修订下一轮，偏差在放大前被修正。","数字化转型办公室在新工具推广中，只记录成功案例不分析偏差，最终同类偏差在扩面后被成倍放大。","数字化转型办公室在新机制落地中，每轮结束后复盘并修订下一轮，偏差在放大前被修正。","数字化转型办公室在新流程上线中，每轮结束后复盘并修订下一轮，偏差在放大前被修正。"],"answer":1,"explanation":"「试错迭代」的构成要件为：①主体为数字化转型办公室；②通过每轮结束后复盘并修订下一轮；③使偏差在放大前被修正。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（只记录成功案例不分析偏差），因此不符合构成要件。故选B。"},{"id":"pdn02045","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「链条式核验」是指冷链运营方通过异常批次可一键回溯全链路，使召回范围精确到具体批次的工作机制。\n\n按照上述界定，下列情形可认定为「链条式核验」的是：","options":["冷链运营方在批次交接记录中，仅保留汇总数不留明细，最终出现问题时无法定位到具体环节。","由消费者事后反馈倒查，后续也未按上述机制推进。","冷链运营方在储运环节温控中，异常批次可一键回溯全链路，但出现问题时无法定位到具体环节。","冷链运营方在进货环节核验中，异常批次可一键回溯全链路，召回范围精确到具体批次。"],"answer":3,"explanation":"「链条式核验」的构成要件为：①主体为冷链运营方；②通过异常批次可一键回溯全链路；③使召回范围精确到具体批次。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn02046","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「原型共创」是指无障碍改造专班通过先做可体验原型再收集反馈，使返工与投诉明显减少的工作机制。\n\n根据上述定义，下列不属于「原型共创」的是：","options":["无障碍改造专班在公共界面优化中，仅在完工后征求意见，最终上线后仍频发与习惯不符的障碍。","无障碍改造专班在服务流程梳理中，先做可体验原型再收集反馈，返工与投诉明显减少。","无障碍改造专班在使用路径排查中，先做可体验原型再收集反馈，返工与投诉明显减少。","无障碍改造专班在公共界面优化中，先做可体验原型再收集反馈，返工与投诉明显减少。"],"answer":0,"explanation":"「原型共创」的构成要件为：①主体为无障碍改造专班；②通过先做可体验原型再收集反馈；③使返工与投诉明显减少。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（仅在完工后征求意见），因此不符合构成要件。故选A。"},{"id":"pdn02047","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「指标复核」是指项目评审委员会通过先确立基线再对照前后变化，使判断建立在可核验的依据上的工作机制。\n\n依据上述定义，以下哪一项符合「指标复核」的构成要件：","options":["项目评审委员会在政策效果评估中，用总量变化直接归因、不作对照，最终结论无法由所引数据支撑。","由申报方自行填报不作核实，后续也未按上述机制推进。","项目评审委员会在抽样数据核查中，先确立基线再对照前后变化，但结论无法由所引数据支撑。","项目评审委员会在年度计划编制中，先确立基线再对照前后变化，判断建立在可核验的依据上。"],"answer":3,"explanation":"「指标复核」的构成要件为：①主体为项目评审委员会；②通过先确立基线再对照前后变化；③使判断建立在可核验的依据上。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn02048","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「表现性评价」是指任课教师团队通过随堂记录并及时反馈调整，使学生的薄弱点被及时识别的工作机制。\n\n按照上述界定，下列情形不应认定为「表现性评价」的是：","options":["任课教师团队在单元教学设计中，随堂记录并及时反馈调整，学生的薄弱点被及时识别。","任课教师团队在实验课程组织中，照搬统一答案不看作答过程，最终教学安排并未因数据而作任何调整。","任课教师团队在作业反馈整理中，随堂记录并及时反馈调整，学生的薄弱点被及时识别。","任课教师团队在实验课程组织中，随堂记录并及时反馈调整，学生的薄弱点被及时识别。"],"answer":1,"explanation":"「表现性评价」的构成要件为：①主体为任课教师团队；②通过随堂记录并及时反馈调整；③使学生的薄弱点被及时识别。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（照搬统一答案不看作答过程），因此不符合构成要件。故选B。"},{"id":"pdn02049","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「随访管理」是指乡镇卫生院通过与上级医院共享检查结果，使轻症在基层得到及时处置的工作机制。\n\n根据上述定义，下列属于「随访管理」的是：","options":["乡镇卫生院在慢病随访安排中，与上级医院共享检查结果，轻症在基层得到及时处置。","由商业体检机构独立出具结论，后续也未按上述机制推进。","乡镇卫生院在康复跟踪记录中，待病情加重后再启动会诊，最终各环节彼此脱节、患者仍需多次重复排队。","乡镇卫生院在重点人群筛查中，与上级医院共享检查结果，但各环节彼此脱节、患者仍需多次重复排队。"],"answer":0,"explanation":"「随访管理」的构成要件为：①主体为乡镇卫生院；②通过与上级医院共享检查结果；③使轻症在基层得到及时处置。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn02050","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「指标复核」是指项目评审委员会通过对关键指标作独立复核，使成效与措施之间的对应更清楚的工作机制。\n\n依据上述定义，以下哪一项不符合「指标复核」的构成要件：","options":["项目评审委员会在政策效果评估中，只选取有利样本作展示，最终结论无法由所引数据支撑。","项目评审委员会在抽样数据核查中，对关键指标作独立复核，成效与措施之间的对应更清楚。","项目评审委员会在政策效果评估中，对关键指标作独立复核，成效与措施之间的对应更清楚。","项目评审委员会在年度计划编制中，对关键指标作独立复核，成效与措施之间的对应更清楚。"],"answer":0,"explanation":"「指标复核」的构成要件为：①主体为项目评审委员会；②通过对关键指标作独立复核；③使成效与措施之间的对应更清楚。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（只选取有利样本作展示），因此不符合构成要件。故选A。"},{"id":"pdn02051","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「双向转诊」是指社区卫生服务中心通过建立电子档案并定期回访，使重复检查明显减少的工作机制。\n\n按照上述界定，下列情形可认定为「双向转诊」的是：","options":["社区卫生服务中心在康复跟踪记录中，只做一次性检查不作后续跟踪，最终各环节彼此脱节、患者仍需多次重复排队。","社区卫生服务中心在慢病随访安排中，建立电子档案并定期回访，重复检查明显减少。","仅由三甲医院单方建档，后续也未按上述机制推进。","社区卫生服务中心在重点人群筛查中，建立电子档案并定期回访，但各环节彼此脱节、患者仍需多次重复排队。"],"answer":1,"explanation":"「双向转诊」的构成要件为：①主体为社区卫生服务中心；②通过建立电子档案并定期回访；③使重复检查明显减少。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn02052","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「需求导向供给」是指就业服务窗口通过先摸清不同群体诉求再分类提供，使供给与实际需求更加贴合的工作机制。\n\n根据上述定义，下列不属于「需求导向供给」的是：","options":["就业服务窗口在服务清单编制中，先摸清不同群体诉求再分类提供，供给与实际需求更加贴合。","就业服务窗口在对象需求摸排中，先摸清不同群体诉求再分类提供，供给与实际需求更加贴合。","就业服务窗口在服务事项梳理中，先摸清不同群体诉求再分类提供，供给与实际需求更加贴合。","就业服务窗口在对象需求摸排中，先采购再询问是否需要，最终大量项目无人使用而真实诉求仍被搁置。"],"answer":3,"explanation":"「需求导向供给」的构成要件为：①主体为就业服务窗口；②通过先摸清不同群体诉求再分类提供；③使供给与实际需求更加贴合。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（先采购再询问是否需要），因此不符合构成要件。故选D。"},{"id":"pdn02053","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「过程性考核」是指任课教师团队通过按阶段采集学情数据再修正教学，使学习过程而非仅结果被看见的工作机制。\n\n依据上述定义，以下哪一项符合「过程性考核」的构成要件：","options":["由学生互评后不再复核，后续也未按上述机制推进。","任课教师团队在作业反馈整理中，按阶段采集学情数据再修正教学，但教学安排并未因数据而作任何调整。","任课教师团队在单元教学设计中，按阶段采集学情数据再修正教学，学习过程而非仅结果被看见。","任课教师团队在实验课程组织中，按固定名次划线且不追溯变化，最终教学安排并未因数据而作任何调整。"],"answer":2,"explanation":"「过程性考核」的构成要件为：①主体为任课教师团队；②通过按阶段采集学情数据再修正教学；③使学习过程而非仅结果被看见。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn02054","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「容错纠偏」是指改革推进专班通过分批次扩面而非一次铺开，使风险被限制在可控范围的工作机制。\n\n按照上述界定，下列情形不应认定为「容错纠偏」的是：","options":["改革推进专班在新工具推广中，不经试点直接全面强制推开，最终同类偏差在扩面后被成倍放大。","改革推进专班在新工具推广中，分批次扩面而非一次铺开，风险被限制在可控范围。","改革推进专班在新流程上线中，分批次扩面而非一次铺开，风险被限制在可控范围。","改革推进专班在新机制落地中，分批次扩面而非一次铺开，风险被限制在可控范围。"],"answer":0,"explanation":"「容错纠偏」的构成要件为：①主体为改革推进专班；②通过分批次扩面而非一次铺开；③使风险被限制在可控范围。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（不经试点直接全面强制推开），因此不符合构成要件。故选A。"},{"id":"pdn02055","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「分级预警」是指城市运行管理平台通过按风险等级预置响应动作，使人员与物资提前就位的工作机制。\n\n根据上述定义，下列属于「分级预警」的是：","options":["城市运行管理平台在响应动作预置中，仅保留一份无备用的关键设备，最终异常发生时无预设动作可依。","城市运行管理平台在风险等级研判中，按风险等级预置响应动作，人员与物资提前就位。","由上级在事后统一追认，后续也未按上述机制推进。","城市运行管理平台在关键节点值守中，按风险等级预置响应动作，但异常发生时无预设动作可依。"],"answer":1,"explanation":"「分级预警」的构成要件为：①主体为城市运行管理平台；②通过按风险等级预置响应动作；③使人员与物资提前就位。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn02056","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「双向转诊」是指社区卫生服务中心通过按病情轻重分流并约定转诊路径，使轻症在基层得到及时处置的工作机制。\n\n依据上述定义，以下哪一项不符合「双向转诊」的构成要件：","options":["社区卫生服务中心在康复跟踪记录中，各机构各自重复开单，最终各环节彼此脱节、患者仍需多次重复排队。","社区卫生服务中心在重点人群筛查中，按病情轻重分流并约定转诊路径，轻症在基层得到及时处置。","社区卫生服务中心在慢病随访安排中，按病情轻重分流并约定转诊路径，轻症在基层得到及时处置。","社区卫生服务中心在康复跟踪记录中，按病情轻重分流并约定转诊路径，轻症在基层得到及时处置。"],"answer":0,"explanation":"「双向转诊」的构成要件为：①主体为社区卫生服务中心；②通过按病情轻重分流并约定转诊路径；③使轻症在基层得到及时处置。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（各机构各自重复开单），因此不符合构成要件。故选A。"},{"id":"pdn02057","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「原型共创」是指公共服务设计组通过先做可体验原型再收集反馈，使方案贴合真实使用习惯的工作机制。\n\n按照上述界定，下列情形可认定为「原型共创」的是：","options":["公共服务设计组在使用路径排查中，先做可体验原型再收集反馈，但上线后仍频发与习惯不符的障碍。","公共服务设计组在公共界面优化中，一次性定稿不再接收反馈，最终上线后仍频发与习惯不符的障碍。","由外部专家远程定稿，后续也未按上述机制推进。","公共服务设计组在服务流程梳理中，先做可体验原型再收集反馈，方案贴合真实使用习惯。"],"answer":3,"explanation":"「原型共创」的构成要件为：①主体为公共服务设计组；②通过先做可体验原型再收集反馈；③使方案贴合真实使用习惯。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn02058","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「循证施策」是指政策评估小组通过先确立基线再对照前后变化，使判断建立在可核验的依据上的工作机制。\n\n根据上述定义，下列不属于「循证施策」的是：","options":["政策评估小组在抽样数据核查中，先确立基线再对照前后变化，判断建立在可核验的依据上。","政策评估小组在政策效果评估中，先确立基线再对照前后变化，判断建立在可核验的依据上。","政策评估小组在年度计划编制中，先确立基线再对照前后变化，判断建立在可核验的依据上。","政策评估小组在政策效果评估中，只选取有利样本作展示，最终结论无法由所引数据支撑。"],"answer":3,"explanation":"「循证施策」的构成要件为：①主体为政策评估小组；②通过先确立基线再对照前后变化；③使判断建立在可核验的依据上。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（只选取有利样本作展示），因此不符合构成要件。故选D。"},{"id":"pdn02059","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「可回溯核查」是指食品药品监管所通过按批号串联台账与检验记录，使责任环节清晰可查的工作机制。\n\n依据上述定义，以下哪一项符合「可回溯核查」的构成要件：","options":["食品药品监管所在储运环节温控中，按批号串联台账与检验记录，但出现问题时无法定位到具体环节。","食品药品监管所在批次交接记录中，各环节各自记录且互不关联，最终出现问题时无法定位到具体环节。","由终端门店自行补记，后续也未按上述机制推进。","食品药品监管所在进货环节核验中，按批号串联台账与检验记录，责任环节清晰可查。"],"answer":3,"explanation":"「可回溯核查」的构成要件为：①主体为食品药品监管所；②通过按批号串联台账与检验记录；③使责任环节清晰可查。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn02060","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「双向转诊」是指县域医共体通过与上级医院共享检查结果，使患者往返成本下降的工作机制。\n\n按照上述界定，下列情形不应认定为「双向转诊」的是：","options":["县域医共体在重点人群筛查中，与上级医院共享检查结果，患者往返成本下降。","县域医共体在康复跟踪记录中，与上级医院共享检查结果，患者往返成本下降。","县域医共体在慢病随访安排中，与上级医院共享检查结果，患者往返成本下降。","县域医共体在康复跟踪记录中，各机构各自重复开单，最终各环节彼此脱节、患者仍需多次重复排队。"],"answer":3,"explanation":"「双向转诊」的构成要件为：①主体为县域医共体；②通过与上级医院共享检查结果；③使患者往返成本下降。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（各机构各自重复开单），因此不符合构成要件。故选D。"},{"id":"pdn02061","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「最小必要采集」是指学校学籍管理系统通过到期自动清理并留清理记录，使历史数据不再无限期堆积的工作机制。\n\n根据上述定义，下列属于「最小必要采集」的是：","options":["学校学籍管理系统在数据调阅留痕中，到期自动清理并留清理记录，但与办理目的无关的字段仍被长期留存。","学校学籍管理系统在信息采集登记中，到期自动清理并留清理记录，历史数据不再无限期堆积。","学校学籍管理系统在字段权限配置中，超过期限仍不作清理，最终与办理目的无关的字段仍被长期留存。","由系统默认长期全量保留，后续也未按上述机制推进。"],"answer":1,"explanation":"「最小必要采集」的构成要件为：①主体为学校学籍管理系统；②通过到期自动清理并留清理记录；③使历史数据不再无限期堆积。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn02062","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「可回溯核查」是指食品药品监管所通过异常批次可一键回溯全链路，使问题批次能被快速定位的工作机制。\n\n依据上述定义，以下哪一项不符合「可回溯核查」的构成要件：","options":["食品药品监管所在储运环节温控中，异常批次可一键回溯全链路，问题批次能被快速定位。","食品药品监管所在批次交接记录中，异常批次可一键回溯全链路，问题批次能被快速定位。","食品药品监管所在进货环节核验中，异常批次可一键回溯全链路，问题批次能被快速定位。","食品药品监管所在批次交接记录中，只在最终出库时记一笔总账，最终出现问题时无法定位到具体环节。"],"answer":3,"explanation":"「可回溯核查」的构成要件为：①主体为食品药品监管所；②通过异常批次可一键回溯全链路；③使问题批次能被快速定位。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（只在最终出库时记一笔总账），因此不符合构成要件。故选D。"},{"id":"pdn02063","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「预案触发」是指数据中心运维组通过按风险等级预置响应动作，使险情初起即进入有序处置的工作机制。\n\n按照上述界定，下列情形可认定为「预案触发」的是：","options":["数据中心运维组在关键节点值守中，按风险等级预置响应动作，但异常发生时无预设动作可依。","由上级在事后统一追认，后续也未按上述机制推进。","数据中心运维组在响应动作预置中，仅保留一份无备用的关键设备，最终异常发生时无预设动作可依。","数据中心运维组在风险等级研判中，按风险等级预置响应动作，险情初起即进入有序处置。"],"answer":3,"explanation":"「预案触发」的构成要件为：①主体为数据中心运维组；②通过按风险等级预置响应动作；③使险情初起即进入有序处置。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn02064","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「随访管理」是指乡镇卫生院通过按病情轻重分流并约定转诊路径，使轻症在基层得到及时处置的工作机制。\n\n根据上述定义，下列不属于「随访管理」的是：","options":["乡镇卫生院在重点人群筛查中，按病情轻重分流并约定转诊路径，轻症在基层得到及时处置。","乡镇卫生院在慢病随访安排中，按病情轻重分流并约定转诊路径，轻症在基层得到及时处置。","乡镇卫生院在康复跟踪记录中，各机构各自重复开单，最终各环节彼此脱节、患者仍需多次重复排队。","乡镇卫生院在康复跟踪记录中，按病情轻重分流并约定转诊路径，轻症在基层得到及时处置。"],"answer":2,"explanation":"「随访管理」的构成要件为：①主体为乡镇卫生院；②通过按病情轻重分流并约定转诊路径；③使轻症在基层得到及时处置。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（各机构各自重复开单），因此不符合构成要件。故选C。"},{"id":"pdn02065","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「连续照护」是指县域医共体通过先由基层评估再决定是否上转，使病情变化能被尽早发现的工作机制。\n\n依据上述定义，以下哪一项符合「连续照护」的构成要件：","options":["县域医共体在康复跟踪记录中，待病情加重后再启动会诊，最终各环节彼此脱节、患者仍需多次重复排队。","由商业体检机构独立出具结论，后续也未按上述机制推进。","县域医共体在重点人群筛查中，先由基层评估再决定是否上转，但各环节彼此脱节、患者仍需多次重复排队。","县域医共体在慢病随访安排中，先由基层评估再决定是否上转，病情变化能被尽早发现。"],"answer":3,"explanation":"「连续照护」的构成要件为：①主体为县域医共体；②通过先由基层评估再决定是否上转；③使病情变化能被尽早发现。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn02066","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「跨界协作」是指街道与职能站所通过共享信息并同步排班，使重复检查与推诿明显减少的工作机制。\n\n按照上述界定，下列情形不应认定为「跨界协作」的是：","options":["街道与职能站所在跨界事项梳理中，共享信息并同步排班，重复检查与推诿明显减少。","街道与职能站所在联合排班安排中，各部门分头进场、结果互不通报，最终边界地带的问题仍在部门之间来回流转。","街道与职能站所在联合排班安排中，共享信息并同步排班，重复检查与推诿明显减少。","街道与职能站所在信息通报共享中，共享信息并同步排班，重复检查与推诿明显减少。"],"answer":1,"explanation":"「跨界协作」的构成要件为：①主体为街道与职能站所；②通过共享信息并同步排班；③使重复检查与推诿明显减少。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（各部门分头进场、结果互不通报），因此不符合构成要件。故选B。"},{"id":"pdn02067","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「容错纠偏」是指产品迭代小组通过分批次扩面而非一次铺开，使后续推广更贴合一线实际的工作机制。\n\n根据上述定义，下列属于「容错纠偏」的是：","options":["产品迭代小组在新工具推广中，试运行期间禁止任何修改，最终同类偏差在扩面后被成倍放大。","由外部团队一次性交付即结束，后续也未按上述机制推进。","产品迭代小组在新流程上线中，分批次扩面而非一次铺开，后续推广更贴合一线实际。","产品迭代小组在新机制落地中，分批次扩面而非一次铺开，但同类偏差在扩面后被成倍放大。"],"answer":2,"explanation":"「容错纠偏」的构成要件为：①主体为产品迭代小组；②通过分批次扩面而非一次铺开；③使后续推广更贴合一线实际。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn02068","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「双向转诊」是指社区卫生服务中心通过先由基层评估再决定是否上转，使轻症在基层得到及时处置的工作机制。\n\n依据上述定义，以下哪一项不符合「双向转诊」的构成要件：","options":["社区卫生服务中心在康复跟踪记录中，先由基层评估再决定是否上转，轻症在基层得到及时处置。","社区卫生服务中心在重点人群筛查中，先由基层评估再决定是否上转，轻症在基层得到及时处置。","社区卫生服务中心在康复跟踪记录中，各机构各自重复开单，最终各环节彼此脱节、患者仍需多次重复排队。","社区卫生服务中心在慢病随访安排中，先由基层评估再决定是否上转，轻症在基层得到及时处置。"],"answer":2,"explanation":"「双向转诊」的构成要件为：①主体为社区卫生服务中心；②通过先由基层评估再决定是否上转；③使轻症在基层得到及时处置。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（各机构各自重复开单），因此不符合构成要件。故选C。"},{"id":"pdn02069","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「链条式核验」是指农产品质量检测站通过每一节点登记并关联上下游凭证，使责任环节清晰可查的工作机制。\n\n按照上述界定，下列情形可认定为「链条式核验」的是：","options":["农产品质量检测站在批次交接记录中，仅保留汇总数不留明细，最终出现问题时无法定位到具体环节。","由消费者事后反馈倒查，后续也未按上述机制推进。","农产品质量检测站在储运环节温控中，每一节点登记并关联上下游凭证，但出现问题时无法定位到具体环节。","农产品质量检测站在进货环节核验中，每一节点登记并关联上下游凭证，责任环节清晰可查。"],"answer":3,"explanation":"「链条式核验」的构成要件为：①主体为农产品质量检测站；②通过每一节点登记并关联上下游凭证；③使责任环节清晰可查。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn02070","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「共创工作坊」是指公共服务设计组通过多轮共创后收敛为最终版本，使返工与投诉明显减少的工作机制。\n\n根据上述定义，下列不属于「共创工作坊」的是：","options":["公共服务设计组在使用路径排查中，多轮共创后收敛为最终版本，返工与投诉明显减少。","公共服务设计组在公共界面优化中，多轮共创后收敛为最终版本，返工与投诉明显减少。","公共服务设计组在服务流程梳理中，多轮共创后收敛为最终版本，返工与投诉明显减少。","公共服务设计组在公共界面优化中，仅在完工后征求意见，最终上线后仍频发与习惯不符的障碍。"],"answer":3,"explanation":"「共创工作坊」的构成要件为：①主体为公共服务设计组；②通过多轮共创后收敛为最终版本；③使返工与投诉明显减少。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（仅在完工后征求意见），因此不符合构成要件。故选D。"},{"id":"pdn02071","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「动态监测」是指自然保护区管理局通过设定阈值并触发分级响应，使管控成本保持在合理区间的工作机制。\n\n依据上述定义，以下哪一项符合「动态监测」的构成要件：","options":["自然保护区管理局在监测指标波动中，设定阈值并触发分级响应，管控成本保持在合理区间。","由邻近地区照抄方案，后续也未按上述机制推进。","自然保护区管理局在栖息环境变化中，指标超标后仍不调整，最终指标已越界而措施仍维持不变。","自然保护区管理局在外来因素扩散中，设定阈值并触发分级响应，但指标已越界而措施仍维持不变。"],"answer":0,"explanation":"「动态监测」的构成要件为：①主体为自然保护区管理局；②通过设定阈值并触发分级响应；③使管控成本保持在合理区间。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn02072","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「跨界协作」是指街道与职能站所通过一次会商形成分工清单，使响应口径保持一致的工作机制。\n\n按照上述界定，下列情形不应认定为「跨界协作」的是：","options":["街道与职能站所在信息通报共享中，一次会商形成分工清单，响应口径保持一致。","街道与职能站所在联合排班安排中，一次会商形成分工清单，响应口径保持一致。","街道与职能站所在跨界事项梳理中，一次会商形成分工清单，响应口径保持一致。","街道与职能站所在联合排班安排中，遇跨界事项互相等待，最终边界地带的问题仍在部门之间来回流转。"],"answer":3,"explanation":"「跨界协作」的构成要件为：①主体为街道与职能站所；②通过一次会商形成分工清单；③使响应口径保持一致。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（遇跨界事项互相等待），因此不符合构成要件。故选D。"},{"id":"pdn02073","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「链条式核验」是指冷链运营方通过按批号串联台账与检验记录，使责任环节清晰可查的工作机制。\n\n根据上述定义，下列属于「链条式核验」的是：","options":["冷链运营方在储运环节温控中，按批号串联台账与检验记录，但出现问题时无法定位到具体环节。","冷链运营方在进货环节核验中，按批号串联台账与检验记录，责任环节清晰可查。","冷链运营方在批次交接记录中，仅保留汇总数不留明细，最终出现问题时无法定位到具体环节。","由消费者事后反馈倒查，后续也未按上述机制推进。"],"answer":1,"explanation":"「链条式核验」的构成要件为：①主体为冷链运营方；②通过按批号串联台账与检验记录；③使责任环节清晰可查。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn02074","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「链条式核验」是指冷链运营方通过关键节点双人签认留档，使台账与实物始终一致的工作机制。\n\n依据上述定义，以下哪一项不符合「链条式核验」的构成要件：","options":["冷链运营方在批次交接记录中，只在最终出库时记一笔总账，最终出现问题时无法定位到具体环节。","冷链运营方在储运环节温控中，关键节点双人签认留档，台账与实物始终一致。","冷链运营方在批次交接记录中，关键节点双人签认留档，台账与实物始终一致。","冷链运营方在进货环节核验中，关键节点双人签认留档，台账与实物始终一致。"],"answer":0,"explanation":"「链条式核验」的构成要件为：①主体为冷链运营方；②通过关键节点双人签认留档；③使台账与实物始终一致。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；A项该项未采取定义所要求的方式（只在最终出库时记一笔总账），因此不符合构成要件。故选A。"},{"id":"pdn02075","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「联合响应」是指区级牵头部门通过共享信息并同步排班，使重复检查与推诿明显减少的工作机制。\n\n按照上述界定，下列情形可认定为「联合响应」的是：","options":["由各区各自为政，后续也未按上述机制推进。","区级牵头部门在跨界事项梳理中，共享信息并同步排班，重复检查与推诿明显减少。","区级牵头部门在联合排班安排中，只开会不落责任清单，最终边界地带的问题仍在部门之间来回流转。","区级牵头部门在信息通报共享中，共享信息并同步排班，但边界地带的问题仍在部门之间来回流转。"],"answer":1,"explanation":"「联合响应」的构成要件为：①主体为区级牵头部门；②通过共享信息并同步排班；③使重复检查与推诿明显减少。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn02076","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「随访管理」是指县域医共体通过与上级医院共享检查结果，使病情变化能被尽早发现的工作机制。\n\n根据上述定义，下列不属于「随访管理」的是：","options":["县域医共体在重点人群筛查中，与上级医院共享检查结果，病情变化能被尽早发现。","县域医共体在慢病随访安排中，与上级医院共享检查结果，病情变化能被尽早发现。","县域医共体在康复跟踪记录中，与上级医院共享检查结果，病情变化能被尽早发现。","县域医共体在康复跟踪记录中，各机构各自重复开单，最终各环节彼此脱节、患者仍需多次重复排队。"],"answer":3,"explanation":"「随访管理」的构成要件为：①主体为县域医共体；②通过与上级医院共享检查结果；③使病情变化能被尽早发现。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（各机构各自重复开单），因此不符合构成要件。故选D。"},{"id":"pdn02077","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「指标复核」是指统计调查队通过先确立基线再对照前后变化，使结论不易被个别异常值带偏的工作机制。\n\n依据上述定义，以下哪一项符合「指标复核」的构成要件：","options":["由第三方直接给结论不附依据，后续也未按上述机制推进。","统计调查队在抽样数据核查中，先确立基线再对照前后变化，但结论无法由所引数据支撑。","统计调查队在年度计划编制中，先确立基线再对照前后变化，结论不易被个别异常值带偏。","统计调查队在政策效果评估中，指标口径中途变更却不说明，最终结论无法由所引数据支撑。"],"answer":2,"explanation":"「指标复核」的构成要件为：①主体为统计调查队；②通过先确立基线再对照前后变化；③使结论不易被个别异常值带偏。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn02078","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「菜单式服务」是指养老服务站点通过依据使用频次动态增减项目，使冷门项目被及时替换的工作机制。\n\n按照上述界定，下列情形不应认定为「菜单式服务」的是：","options":["养老服务站点在服务事项梳理中，依据使用频次动态增减项目，冷门项目被及时替换。","养老服务站点在对象需求摸排中，所有对象发放完全相同的固定包，最终大量项目无人使用而真实诉求仍被搁置。","养老服务站点在对象需求摸排中，依据使用频次动态增减项目，冷门项目被及时替换。","养老服务站点在服务清单编制中，依据使用频次动态增减项目，冷门项目被及时替换。"],"answer":1,"explanation":"「菜单式服务」的构成要件为：①主体为养老服务站点；②通过依据使用频次动态增减项目；③使冷门项目被及时替换。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（所有对象发放完全相同的固定包），因此不符合构成要件。故选B。"},{"id":"pdn02079","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「双向转诊」是指乡镇卫生院通过先由基层评估再决定是否上转，使患者往返成本下降的工作机制。\n\n根据上述定义，下列属于「双向转诊」的是：","options":["乡镇卫生院在康复跟踪记录中，只做一次性检查不作后续跟踪，最终各环节彼此脱节、患者仍需多次重复排队。","乡镇卫生院在重点人群筛查中，先由基层评估再决定是否上转，但各环节彼此脱节、患者仍需多次重复排队。","乡镇卫生院在慢病随访安排中，先由基层评估再决定是否上转，患者往返成本下降。","仅由三甲医院单方建档，后续也未按上述机制推进。"],"answer":2,"explanation":"「双向转诊」的构成要件为：①主体为乡镇卫生院；②通过先由基层评估再决定是否上转；③使患者往返成本下降。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn02080","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「留痕管理」是指食品药品监管所通过按批号串联台账与检验记录，使台账与实物始终一致的工作机制。\n\n依据上述定义，以下哪一项不符合「留痕管理」的构成要件：","options":["食品药品监管所在批次交接记录中，按批号串联台账与检验记录，台账与实物始终一致。","食品药品监管所在储运环节温控中，按批号串联台账与检验记录，台账与实物始终一致。","食品药品监管所在批次交接记录中，事后一次性补全整本台账，最终出现问题时无法定位到具体环节。","食品药品监管所在进货环节核验中，按批号串联台账与检验记录，台账与实物始终一致。"],"answer":2,"explanation":"「留痕管理」的构成要件为：①主体为食品药品监管所；②通过按批号串联台账与检验记录；③使台账与实物始终一致。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（事后一次性补全整本台账），因此不符合构成要件。故选C。"},{"id":"pdn02081","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「分级预警」是指数据中心运维组通过按风险等级预置响应动作，使人员与物资提前就位的工作机制。\n\n按照上述界定，下列情形可认定为「分级预警」的是：","options":["数据中心运维组在关键节点值守中，按风险等级预置响应动作，但异常发生时无预设动作可依。","数据中心运维组在风险等级研判中，按风险等级预置响应动作，人员与物资提前就位。","由外部单位事后支援，后续也未按上述机制推进。","数据中心运维组在响应动作预置中，只在事发后补充记录，最终异常发生时无预设动作可依。"],"answer":1,"explanation":"「分级预警」的构成要件为：①主体为数据中心运维组；②通过按风险等级预置响应动作；③使人员与物资提前就位。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn02082","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「差异化供给」是指公共文化服务中心通过依据使用频次动态增减项目，使冷门项目被及时替换的工作机制。\n\n根据上述定义，下列不属于「差异化供给」的是：","options":["公共文化服务中心在服务事项梳理中，依据使用频次动态增减项目，冷门项目被及时替换。","公共文化服务中心在对象需求摸排中，依据使用频次动态增减项目，冷门项目被及时替换。","公共文化服务中心在服务清单编制中，依据使用频次动态增减项目，冷门项目被及时替换。","公共文化服务中心在对象需求摸排中，所有对象发放完全相同的固定包，最终大量项目无人使用而真实诉求仍被搁置。"],"answer":3,"explanation":"「差异化供给」的构成要件为：①主体为公共文化服务中心；②通过依据使用频次动态增减项目；③使冷门项目被及时替换。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（所有对象发放完全相同的固定包），因此不符合构成要件。故选D。"},{"id":"pdn02083","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「复盘改进」是指产品迭代小组通过分批次扩面而非一次铺开，使后续推广更贴合一线实际的工作机制。\n\n依据上述定义，以下哪一项符合「复盘改进」的构成要件：","options":["产品迭代小组在新机制落地中，分批次扩面而非一次铺开，但同类偏差在扩面后被成倍放大。","产品迭代小组在新工具推广中，试运行期间禁止任何修改，最终同类偏差在扩面后被成倍放大。","由外部团队一次性交付即结束，后续也未按上述机制推进。","产品迭代小组在新流程上线中，分批次扩面而非一次铺开，后续推广更贴合一线实际。"],"answer":3,"explanation":"「复盘改进」的构成要件为：①主体为产品迭代小组；②通过分批次扩面而非一次铺开；③使后续推广更贴合一线实际。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn02084","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「过程性考核」是指区域教研中心通过先摸清起点再设定分层目标，使学习过程而非仅结果被看见的工作机制。\n\n按照上述界定，下列情形不应认定为「过程性考核」的是：","options":["区域教研中心在作业反馈整理中，先摸清起点再设定分层目标，学习过程而非仅结果被看见。","区域教研中心在实验课程组织中，照搬统一答案不看作答过程，最终教学安排并未因数据而作任何调整。","区域教研中心在实验课程组织中，先摸清起点再设定分层目标，学习过程而非仅结果被看见。","区域教研中心在单元教学设计中，先摸清起点再设定分层目标，学习过程而非仅结果被看见。"],"answer":1,"explanation":"「过程性考核」的构成要件为：①主体为区域教研中心；②通过先摸清起点再设定分层目标；③使学习过程而非仅结果被看见。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（照搬统一答案不看作答过程），因此不符合构成要件。故选B。"},{"id":"pdn02085","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「精准匹配」是指农技推广站通过依据使用频次动态增减项目，使冷门项目被及时替换的工作机制。\n\n根据上述定义，下列属于「精准匹配」的是：","options":["农技推广站在对象需求摸排中，沿用上一年清单不作修订，最终大量项目无人使用而真实诉求仍被搁置。","由服务对象自行寻找渠道，后续也未按上述机制推进。","农技推广站在服务清单编制中，依据使用频次动态增减项目，但大量项目无人使用而真实诉求仍被搁置。","农技推广站在服务事项梳理中，依据使用频次动态增减项目，冷门项目被及时替换。"],"answer":3,"explanation":"「精准匹配」的构成要件为：①主体为农技推广站；②通过依据使用频次动态增减项目；③使冷门项目被及时替换。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn02086","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「目的限定」是指公共服务窗口通过按岗位授予最小可见范围，使共享环节不泄露可识别信息的工作机制。\n\n依据上述定义，以下哪一项不符合「目的限定」的构成要件：","options":["公共服务窗口在数据调阅留痕中，按岗位授予最小可见范围，共享环节不泄露可识别信息。","公共服务窗口在字段权限配置中，按岗位授予最小可见范围，共享环节不泄露可识别信息。","公共服务窗口在信息采集登记中，按岗位授予最小可见范围，共享环节不泄露可识别信息。","公共服务窗口在字段权限配置中，为方便起见一次性收齐全部字段，最终与办理目的无关的字段仍被长期留存。"],"answer":3,"explanation":"「目的限定」的构成要件为：①主体为公共服务窗口；②通过按岗位授予最小可见范围；③使共享环节不泄露可识别信息。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；D项该项未采取定义所要求的方式（为方便起见一次性收齐全部字段），因此不符合构成要件。故选D。"},{"id":"pdn02087","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「目的限定」是指公共服务窗口通过只采集完成本事项所必需的字段，使历史数据不再无限期堆积的工作机制。\n\n按照上述界定，下列情形可认定为「目的限定」的是：","options":["公共服务窗口在信息采集登记中，只采集完成本事项所必需的字段，历史数据不再无限期堆积。","公共服务窗口在数据调阅留痕中，只采集完成本事项所必需的字段，但与办理目的无关的字段仍被长期留存。","由外包人员全量导出，后续也未按上述机制推进。","公共服务窗口在字段权限配置中，所有岗位开放同一份全量清单，最终与办理目的无关的字段仍被长期留存。"],"answer":0,"explanation":"「目的限定」的构成要件为：①主体为公共服务窗口；②通过只采集完成本事项所必需的字段；③使历史数据不再无限期堆积。A项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选A。"},{"id":"pdn02088","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「共创反馈环」是指产品体验小组通过先做可体验原型再收集反馈，使方案贴合真实使用习惯的工作机制。\n\n根据上述定义，下列不属于「共创反馈环」的是：","options":["产品体验小组在公共界面优化中，先做可体验原型再收集反馈，方案贴合真实使用习惯。","产品体验小组在公共界面优化中，照搬其他地区成品，最终上线后仍频发与习惯不符的障碍。","产品体验小组在服务流程梳理中，先做可体验原型再收集反馈，方案贴合真实使用习惯。","产品体验小组在使用路径排查中，先做可体验原型再收集反馈，方案贴合真实使用习惯。"],"answer":1,"explanation":"「共创反馈环」的构成要件为：①主体为产品体验小组；②通过先做可体验原型再收集反馈；③使方案贴合真实使用习惯。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（照搬其他地区成品），因此不符合构成要件。故选B。"},{"id":"pdn02089","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「灰度验证」是指政策试点工作组通过分批次扩面而非一次铺开，使后续推广更贴合一线实际的工作机制。\n\n依据上述定义，以下哪一项符合「灰度验证」的构成要件：","options":["政策试点工作组在新工具推广中，一次上线后即固化不再迭代，最终同类偏差在扩面后被成倍放大。","由用户自行摸索不作收集，后续也未按上述机制推进。","政策试点工作组在新流程上线中，分批次扩面而非一次铺开，后续推广更贴合一线实际。","政策试点工作组在新机制落地中，分批次扩面而非一次铺开，但同类偏差在扩面后被成倍放大。"],"answer":2,"explanation":"「灰度验证」的构成要件为：①主体为政策试点工作组；②通过分批次扩面而非一次铺开；③使后续推广更贴合一线实际。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn02090","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「增值评价」是指课程组通过按阶段采集学情数据再修正教学，使教学策略得以动态优化的工作机制。\n\n按照上述界定，下列情形不应认定为「增值评价」的是：","options":["课程组在实验课程组织中，按阶段采集学情数据再修正教学，教学策略得以动态优化。","课程组在实验课程组织中，只以期末一次分数定结论，最终教学安排并未因数据而作任何调整。","课程组在单元教学设计中，按阶段采集学情数据再修正教学，教学策略得以动态优化。","课程组在作业反馈整理中，按阶段采集学情数据再修正教学，教学策略得以动态优化。"],"answer":1,"explanation":"「增值评价」的构成要件为：①主体为课程组；②通过按阶段采集学情数据再修正教学；③使教学策略得以动态优化。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（只以期末一次分数定结论），因此不符合构成要件。故选B。"},{"id":"pdn02091","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「目的限定」是指政务数据平台通过对外提供前作去标识化处理，使共享环节不泄露可识别信息的工作机制。\n\n根据上述定义，下列属于「目的限定」的是：","options":["政务数据平台在字段权限配置中，所有岗位开放同一份全量清单，最终与办理目的无关的字段仍被长期留存。","由外包人员全量导出，后续也未按上述机制推进。","政务数据平台在数据调阅留痕中，对外提供前作去标识化处理，但与办理目的无关的字段仍被长期留存。","政务数据平台在信息采集登记中，对外提供前作去标识化处理，共享环节不泄露可识别信息。"],"answer":3,"explanation":"「目的限定」的构成要件为：①主体为政务数据平台；②通过对外提供前作去标识化处理；③使共享环节不泄露可识别信息。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn02092","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「试错迭代」是指产品迭代小组通过分批次扩面而非一次铺开，使风险被限制在可控范围的工作机制。\n\n依据上述定义，以下哪一项不符合「试错迭代」的构成要件：","options":["产品迭代小组在新工具推广中，分批次扩面而非一次铺开，风险被限制在可控范围。","产品迭代小组在新流程上线中，分批次扩面而非一次铺开，风险被限制在可控范围。","产品迭代小组在新工具推广中，只记录成功案例不分析偏差，最终同类偏差在扩面后被成倍放大。","产品迭代小组在新机制落地中，分批次扩面而非一次铺开，风险被限制在可控范围。"],"answer":2,"explanation":"「试错迭代」的构成要件为：①主体为产品迭代小组；②通过分批次扩面而非一次铺开；③使风险被限制在可控范围。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（只记录成功案例不分析偏差），因此不符合构成要件。故选C。"},{"id":"pdn02093","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「差异化供给」是指养老服务站点通过先摸清不同群体诉求再分类提供，使不同群体各取所需的工作机制。\n\n按照上述界定，下列情形可认定为「差异化供给」的是：","options":["由服务对象自行寻找渠道，后续也未按上述机制推进。","养老服务站点在服务清单编制中，先摸清不同群体诉求再分类提供，但大量项目无人使用而真实诉求仍被搁置。","养老服务站点在对象需求摸排中，沿用上一年清单不作修订，最终大量项目无人使用而真实诉求仍被搁置。","养老服务站点在服务事项梳理中，先摸清不同群体诉求再分类提供，不同群体各取所需。"],"answer":3,"explanation":"「差异化供给」的构成要件为：①主体为养老服务站点；②通过先摸清不同群体诉求再分类提供；③使不同群体各取所需。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn02094","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「分级授权」是指学校学籍管理系统通过对外提供前作去标识化处理，使共享环节不泄露可识别信息的工作机制。\n\n根据上述定义，下列不属于「分级授权」的是：","options":["学校学籍管理系统在数据调阅留痕中，对外提供前作去标识化处理，共享环节不泄露可识别信息。","学校学籍管理系统在字段权限配置中，为方便起见一次性收齐全部字段，最终与办理目的无关的字段仍被长期留存。","学校学籍管理系统在信息采集登记中，对外提供前作去标识化处理，共享环节不泄露可识别信息。","学校学籍管理系统在字段权限配置中，对外提供前作去标识化处理，共享环节不泄露可识别信息。"],"answer":1,"explanation":"「分级授权」的构成要件为：①主体为学校学籍管理系统；②通过对外提供前作去标识化处理；③使共享环节不泄露可识别信息。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（为方便起见一次性收齐全部字段），因此不符合构成要件。故选B。"},{"id":"pdn02095","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「用户旅程映射」是指产品体验小组通过按真实使用路径逐点排查痛点，使改动获得使用者认同的工作机制。\n\n依据上述定义，以下哪一项符合「用户旅程映射」的构成要件：","options":["产品体验小组在公共界面优化中，只做内部评审不接触使用者，最终上线后仍频发与习惯不符的障碍。","由供应商提供标准模板，后续也未按上述机制推进。","产品体验小组在使用路径排查中，按真实使用路径逐点排查痛点，但上线后仍频发与习惯不符的障碍。","产品体验小组在服务流程梳理中，按真实使用路径逐点排查痛点，改动获得使用者认同。"],"answer":3,"explanation":"「用户旅程映射」的构成要件为：①主体为产品体验小组；②通过按真实使用路径逐点排查痛点；③使改动获得使用者认同。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn02096","module":"panduan","__sub":"定义判断","diff":2,"exam":"国考","prompt":"「全过程追溯」是指农产品质量检测站通过每一节点登记并关联上下游凭证，使问题批次能被快速定位的工作机制。\n\n按照上述界定，下列情形不应认定为「全过程追溯」的是：","options":["农产品质量检测站在进货环节核验中，每一节点登记并关联上下游凭证，问题批次能被快速定位。","农产品质量检测站在批次交接记录中，每一节点登记并关联上下游凭证，问题批次能被快速定位。","农产品质量检测站在批次交接记录中，事后一次性补全整本台账，最终出现问题时无法定位到具体环节。","农产品质量检测站在储运环节温控中，每一节点登记并关联上下游凭证，问题批次能被快速定位。"],"answer":2,"explanation":"「全过程追溯」的构成要件为：①主体为农产品质量检测站；②通过每一节点登记并关联上下游凭证；③使问题批次能被快速定位。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（事后一次性补全整本台账），因此不符合构成要件。故选C。"},{"id":"pdn02097","module":"panduan","__sub":"定义判断","diff":2,"exam":"省考","prompt":"「协同会商」是指街道办通过联合多方现场会商后再定方案，使重复投诉明显下降的工作机制。\n\n根据上述定义，下列属于「协同会商」的是：","options":["街道办在便民事项办理中，联合多方现场会商后再定方案，但问题仍反复出现且未形成稳定机制。","由服务对象自行申报后不再跟进，后续也未按上述机制推进。","街道办在老旧小区改造中，联合多方现场会商后再定方案，重复投诉明显下降。","街道办在邻里纠纷调解中，各口径分头办理、彼此不通气，最终问题仍反复出现且未形成稳定机制。"],"answer":2,"explanation":"「协同会商」的构成要件为：①主体为街道办；②通过联合多方现场会商后再定方案；③使重复投诉明显下降。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn02098","module":"panduan","__sub":"定义判断","diff":2,"exam":"事业编","prompt":"「小步试点」是指政策试点工作组通过分批次扩面而非一次铺开，使后续推广更贴合一线实际的工作机制。\n\n依据上述定义，以下哪一项不符合「小步试点」的构成要件：","options":["政策试点工作组在新流程上线中，分批次扩面而非一次铺开，后续推广更贴合一线实际。","政策试点工作组在新工具推广中，不经试点直接全面强制推开，最终同类偏差在扩面后被成倍放大。","政策试点工作组在新工具推广中，分批次扩面而非一次铺开，后续推广更贴合一线实际。","政策试点工作组在新机制落地中，分批次扩面而非一次铺开，后续推广更贴合一线实际。"],"answer":1,"explanation":"「小步试点」的构成要件为：①主体为政策试点工作组；②通过分批次扩面而非一次铺开；③使后续推广更贴合一线实际。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；B项该项未采取定义所要求的方式（不经试点直接全面强制推开），因此不符合构成要件。故选B。"},{"id":"pdn02099","module":"panduan","__sub":"定义判断","diff":2,"exam":"教师编","prompt":"「分区管控」是指自然保护区管理局通过按监测指标分档调整措施，使管控成本保持在合理区间的工作机制。\n\n按照上述界定，下列情形可认定为「分区管控」的是：","options":["自然保护区管理局在栖息环境变化中，指标超标后仍不调整，最终指标已越界而措施仍维持不变。","由邻近地区照抄方案，后续也未按上述机制推进。","自然保护区管理局在监测指标波动中，按监测指标分档调整措施，管控成本保持在合理区间。","自然保护区管理局在外来因素扩散中，按监测指标分档调整措施，但指标已越界而措施仍维持不变。"],"answer":2,"explanation":"「分区管控」的构成要件为：①主体为自然保护区管理局；②通过按监测指标分档调整措施；③使管控成本保持在合理区间。C项同时满足全部要件，属于该定义。其余三项分别在主体、方式、结果上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选C。"},{"id":"pdn02100","module":"panduan","__sub":"定义判断","diff":2,"exam":"医疗编","prompt":"「阈值预警」是指生态环境监测站通过按监测指标分档调整措施，使异常苗头被尽早识别的工作机制。\n\n根据上述定义，下列不属于「阈值预警」的是：","options":["生态环境监测站在栖息环境变化中，按监测指标分档调整措施，异常苗头被尽早识别。","生态环境监测站在外来因素扩散中，按监测指标分档调整措施，异常苗头被尽早识别。","生态环境监测站在栖息环境变化中，只看年度均值忽略峰值，最终指标已越界而措施仍维持不变。","生态环境监测站在监测指标波动中，按监测指标分档调整措施，异常苗头被尽早识别。"],"answer":2,"explanation":"「阈值预警」的构成要件为：①主体为生态环境监测站；②通过按监测指标分档调整措施；③使异常苗头被尽早识别。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项未采取定义所要求的方式（只看年度均值忽略峰值），因此不符合构成要件。故选C。"},{"id":"pdn02101","module":"panduan","__sub":"定义判断","diff":3,"exam":"国考","prompt":"「用户旅程映射」是指社区营造团队通过多轮共创后收敛为最终版本，使改动获得使用者认同的工作机制，须同时保留可核验的书面记录。\n\n依据上述定义，以下哪一项符合「用户旅程映射」的构成要件：","options":["社区营造团队在公共界面优化中，仅在完工后征求意见，最终上线后仍频发与习惯不符的障碍。","由设计方闭门出图后直接施工，后续也未按上述机制推进。","社区营造团队在适老细节调整中，多轮共创后收敛为最终版本，改动获得使用者认同，但全程未留下任何可核验的书面记录。","社区营造团队在服务流程梳理中，多轮共创后收敛为最终版本，改动获得使用者认同。"],"answer":3,"explanation":"「用户旅程映射」的构成要件为：①主体为社区营造团队；②通过多轮共创后收敛为最终版本；③使改动获得使用者认同；④须同时保留可核验的书面记录。D项同时满足全部要件，属于该定义。其余三项分别在主体、方式、附加限定上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选D。"},{"id":"pdn02102","module":"panduan","__sub":"定义判断","diff":3,"exam":"省考","prompt":"「复盘改进」是指数字化转型办公室通过每轮结束后复盘并修订下一轮，使风险被限制在可控范围的工作机制，各环节须由同一责任主体贯穿到底。\n\n按照上述界定，下列情形不应认定为「复盘改进」的是：","options":["数字化转型办公室在新机制落地中，每轮结束后复盘并修订下一轮，风险被限制在可控范围。","数字化转型办公室在新流程上线中，每轮结束后复盘并修订下一轮，风险被限制在可控范围。","数字化转型办公室在新服务试运行中，每轮结束后复盘并修订下一轮，风险被限制在可控范围，但中途多次更换责任主体、前后衔接断开。","数字化转型办公室在新工具推广中，每轮结束后复盘并修订下一轮，风险被限制在可控范围。"],"answer":2,"explanation":"「复盘改进」的构成要件为：①主体为数字化转型办公室；②通过每轮结束后复盘并修订下一轮；③使风险被限制在可控范围；④各环节须由同一责任主体贯穿到底。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项中途多次更换责任主体、前后衔接断开，违反了第④项附加限定，因此不符合构成要件。故选C。"},{"id":"pdn02103","module":"panduan","__sub":"定义判断","diff":3,"exam":"事业编","prompt":"「分级办理」是指村委会通过提前公示并逐户征询意见，使居民满意度稳步提升的工作机制，须同时保留可核验的书面记录。\n\n根据上述定义，下列属于「分级办理」的是：","options":["交由物业单方决定，后续也未按上述机制推进。","村委会在老旧小区改造中，提前公示并逐户征询意见，居民满意度稳步提升。","村委会在应急物资发放中，提前公示并逐户征询意见，居民满意度稳步提升，但全程未留下任何可核验的书面记录。","村委会在邻里纠纷调解中，只在事后补录台账，最终问题仍反复出现且未形成稳定机制。"],"answer":1,"explanation":"「分级办理」的构成要件为：①主体为村委会；②通过提前公示并逐户征询意见；③使居民满意度稳步提升；④须同时保留可核验的书面记录。B项同时满足全部要件，属于该定义。其余三项分别在主体、方式、附加限定上不符合要件：或由不具承接职责的一方实施，或未采取定义所要求的方式，或未满足定义所指的结果与限定。故选B。"},{"id":"pdn02104","module":"panduan","__sub":"定义判断","diff":3,"exam":"教师编","prompt":"「阈值预警」是指生态环境监测站通过设定阈值并触发分级响应，使干预强度与实际风险相匹配的工作机制，全过程须在事项正式启动之前完成。\n\n依据上述定义，以下哪一项不符合「阈值预警」的构成要件：","options":["生态环境监测站在外来因素扩散中，设定阈值并触发分级响应，干预强度与实际风险相匹配。","生态环境监测站在监测指标波动中，设定阈值并触发分级响应，干预强度与实际风险相匹配。","生态环境监测站在浓度指标起伏中，设定阈值并触发分级响应，干预强度与实际风险相匹配，但相关动作全部是在事项正式启动之后才补做。","生态环境监测站在栖息环境变化中，设定阈值并触发分级响应，干预强度与实际风险相匹配。"],"answer":2,"explanation":"「阈值预警」的构成要件为：①主体为生态环境监测站；②通过设定阈值并触发分级响应；③使干预强度与实际风险相匹配；④全过程须在事项正式启动之前完成。其余三项虽所处情境不同，但均满足全部要件，可认定为该定义；C项该项相关动作全部是在事项正式启动之后才补做，违反了第④项附加限定，因此不符合构成要件。故选C。"}]);